INSERT IGNORE INTO versions
(code, name, language, copyright, license, license_status, source_url, active) VALUES
('sbl', 'Santa Biblia Libre Latinoamericano', 'es', 'Dominio público', 'public_domain', 'open', 'https://ebible.org/spabll/', 1);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'En el principio , Dios creó los cielos y la tierra.',NULL),
(@vid,@bid,1,2,'La tierra no tenía forma y estaba vacía. Las tinieblas cubrían el abismo y el Espíritu de Dios se movía sobre la superficie de las aguas .',NULL),
(@vid,@bid,1,3,'Dios dijo: “ Que se haga la luz”, y se hizo la luz.',NULL),
(@vid,@bid,1,4,'Dios vio que la luz era buena y separó la luz de las tinieblas .',NULL),
(@vid,@bid,1,5,'Dios llamó a la luz “ día ”, y a las tinieblas las llamó “ noche ”. Hubo tarde y hubo mañana : el primer día .',NULL),
(@vid,@bid,1,6,'Dios dijo: “ Que haya una bóveda en medio de las aguas , para que separe unas aguas de otras”.',NULL),
(@vid,@bid,1,7,'Dios hizo la bóveda y separó las aguas que estaban debajo de la bóveda de las que estaban arriba de ella ; y así fue .',NULL),
(@vid,@bid,1,8,'Dios llamó a la bóveda “ cielo ”. Hubo tarde y hubo mañana : el segundo día .',NULL),
(@vid,@bid,1,9,'Dios dijo: “ Que las aguas que están debajo del cielo se junten en un solo lugar , y que aparezca lo seco”; y así fue .',NULL),
(@vid,@bid,1,10,'Dios llamó a lo seco “ tierra ”, y a la reunión de las aguas la llamó “ mares ”. Y vio Dios que era bueno .',NULL),
(@vid,@bid,1,11,'Luego Dios dijo: “ Que la tierra produzca vegetación: plantas que den semilla y árboles frutales que den fruto sobre la tierra, según su especie y con su semilla en él ”; y así fue .',NULL),
(@vid,@bid,1,12,'La tierra produjo vegetación: plantas que dan semilla según su especie , y árboles que dan fruto con su semilla en él , según su especie . Y vio Dios que era bueno .',NULL),
(@vid,@bid,1,13,'Hubo tarde y hubo mañana : el tercer día .',NULL),
(@vid,@bid,1,14,'Dios dijo: “ Que haya luces en la bóveda del cielo para separar el día de la noche ; que sirvan como señales para las estaciones, los días y los años ,',NULL),
(@vid,@bid,1,15,'y que brillen en la bóveda del cielo para iluminar la tierra”; y así fue .',NULL),
(@vid,@bid,1,16,'Dios hizo las dos grandes luces: la luz mayor para dominar el día y la luz menor para dominar la noche . También hizo las estrellas .',NULL),
(@vid,@bid,1,17,'Dios las puso en la bóveda del cielo para iluminar la tierra,',NULL),
(@vid,@bid,1,18,'para dominar el día y la noche , y para separar la luz de las tinieblas . Y vio Dios que era bueno .',NULL),
(@vid,@bid,1,19,'Hubo tarde y hubo mañana : el cuarto día .',NULL),
(@vid,@bid,1,20,'Dios dijo: “ Que las aguas se llenen de seres vivos , y que las aves vuelen sobre la tierra en la abierta expansión del cielo ”.',NULL),
(@vid,@bid,1,21,'Dios creó las grandes criaturas marinas y todos los seres vivos que se mueven y pululan en las aguas , según su especie , y toda ave alada según su especie . Y vio Dios que era bueno .',NULL),
(@vid,@bid,1,22,'Dios los bendijo diciendo: “Sean fecundos y multiplíquense; llenen las aguas de los mares y que las aves se multipliquen en la tierra”.',NULL),
(@vid,@bid,1,23,'Hubo tarde y hubo mañana : el quinto día .',NULL),
(@vid,@bid,1,24,'Dios dijo: “ Que la tierra produzca seres vivos según su especie : ganado, reptiles y animales salvajes según su especie ”; y así fue .',NULL),
(@vid,@bid,1,25,'Dios hizo los animales de la tierra según su especie , el ganado según su especie y todo lo que se arrastra por el suelo según su especie . Y vio Dios que era bueno .',NULL),
(@vid,@bid,1,26,'Entonces Dios dijo: “ Hagamos al hombre a nuestra imagen , conforme a nuestra semejanza . Que tenga dominio sobre los peces del mar , las aves del cielo , el ganado, sobre toda la tierra y sobre todo animal que se arrastra por ella ”.',NULL),
(@vid,@bid,1,27,'Y Dios creó al hombre a su imagen , a imagen de Dios lo creó; hombre y mujer los creó.',NULL),
(@vid,@bid,1,28,'Dios los bendijo y les dijo: “Sean fecundos y multiplíquense; llenen la tierra y sométanla. Dominen a los peces del mar , a las aves del cielo y a todos los seres vivos que se mueven sobre la tierra”.',NULL),
(@vid,@bid,1,29,'También dijo Dios: “Miren, les he dado toda planta que da semilla, que está sobre la superficie de toda la tierra, y todo árbol que da fruto con semilla. Esto les servirá de alimento.',NULL),
(@vid,@bid,1,30,'A todos los animales de la tierra, a todas las aves del cielo y a todo lo que se arrastra sobre la tierra y tiene vida , les doy toda planta verde como alimento”; y así fue .',NULL),
(@vid,@bid,1,31,'Dios vio todo lo que había hecho , y todo era muy bueno . Hubo tarde y hubo mañana : el sexto día .',NULL),
(@vid,@bid,2,1,'Así quedaron terminados los cielos y la tierra, y todo lo que hay en ellos .',NULL),
(@vid,@bid,2,2,'Al llegar el séptimo día , Dios terminó la obra que había estado haciendo , y descansó de toda su labor .',NULL),
(@vid,@bid,2,3,'Dios bendijo el séptimo día y lo declaró santo , porque en ese día descansó de toda su obra de creación.',NULL),
(@vid,@bid,2,4,'Ésta es la historia de la creación de los cielos y de la tierra. Cuando Yahvé Dios hizo la tierra y los cielos ,',NULL),
(@vid,@bid,2,5,'aún no había en la tierra ningún arbusto del campo , ni había brotado ninguna hierba , porque Yahvé Dios todavía no había hecho llover sobre la tierra, ni había nadie que la cultivara.',NULL),
(@vid,@bid,2,6,'En lugar de eso, subía de la tierra un vapor que regaba toda la superficie del suelo.',NULL),
(@vid,@bid,2,7,'Entonces Yahvé Dios formó al hombre del polvo de la tierra , sopló en su nariz aliento de vida , y el hombre se convirtió en un ser viviente .',NULL),
(@vid,@bid,2,8,'Yahvé Dios plantó un jardín en una región llamada Edén, en el oriente , y allí puso al hombre que había formado.',NULL),
(@vid,@bid,2,9,'Yahvé Dios hizo que de la tierra creciera toda clase de árboles hermosos y buenos para comer. En medio del jardín estaban también el árbol de la vida y el árbol del conocimiento del bien y del mal .',NULL),
(@vid,@bid,2,10,'Del Edén salía un río que regaba el jardín, y de allí se dividía en cuatro brazos.',NULL),
(@vid,@bid,2,11,'El primero se llama Pisón, y es el que rodea toda la tierra de Javilá, donde hay oro .',NULL),
(@vid,@bid,2,12,'El oro de esa tierra es de muy buena calidad; también hay allí resina aromática y piedras de ónice.',NULL),
(@vid,@bid,2,13,'El segundo río se llama Guijón, y es el que rodea toda la tierra de Cus.',NULL),
(@vid,@bid,2,14,'El tercer río se llama Tigris, y es el que corre al oriente de Asiria. El cuarto río es el Éufrates .',NULL),
(@vid,@bid,2,15,'Yahvé Dios tomó al hombre y lo puso en el jardín del Edén para que lo cultivara y lo cuidara.',NULL),
(@vid,@bid,2,16,'Y Yahvé Dios le dio al hombre esta orden : “Puedes comer de todos los árboles del jardín,',NULL),
(@vid,@bid,2,17,'pero no comas del árbol del conocimiento del bien y del mal , porque el día que comas de él , de cierto morirás ”.',NULL),
(@vid,@bid,2,18,'Luego Yahvé Dios dijo: “ No es bueno que el hombre esté solo. Voy a hacerle una ayuda adecuada”.',NULL),
(@vid,@bid,2,19,'Yahvé Dios formó de la tierra todos los animales del campo y todas las aves del cielo , y se los llevó al hombre para ver qué nombre les ponía. El nombre que el hombre le dio a cada ser viviente , ése se le quedó.',NULL),
(@vid,@bid,2,20,'Así el hombre les puso nombre a todos los animales domésticos, a las aves del cielo y a todos los animales salvajes. Sin embargo, no se encontró entre ellos una ayuda adecuada para el hombre.',NULL),
(@vid,@bid,2,21,'Entonces Yahvé Dios hizo que el hombre cayera en un sueño profundo y , mientras dormía , le sacó una de sus costillas y cerró la carne en ese lugar .',NULL),
(@vid,@bid,2,22,'De esa costilla Yahvé Dios hizo una mujer, y se la presentó al hombre.',NULL),
(@vid,@bid,2,23,'Al verla, el hombre exclamó: “¡ Ésta sí es hueso de mis huesos y carne de mi carne ! Se llamará ‘mujer’, porque del hombre fue sacada”.',NULL),
(@vid,@bid,2,24,'Por eso el hombre deja a su padre y a su madre, y se une a su mujer, y los dos se funden en un solo ser.',NULL),
(@vid,@bid,2,25,'Tanto el hombre como su mujer estaban desnudos , pero ninguno de los dos sentía vergüenza.',NULL),
(@vid,@bid,3,1,'La serpiente era más astuta que todos los animales salvajes que Yahvé Dios había creado. Ella le preguntó a la mujer: “¿ De veras Dios les dijo que no comieran de ningún árbol del jardín?”',NULL),
(@vid,@bid,3,2,'La mujer le respondió: “Podemos comer del fruto de los árboles del jardín.',NULL),
(@vid,@bid,3,3,'Pero en cuanto al fruto del árbol que está en medio del jardín, Dios nos dijo: ‘ No coman de él, ni lo toquen , para que no mueran ’”.',NULL),
(@vid,@bid,3,4,'Pero la serpiente le dijo a la mujer: “¡ No es cierto , no morirán !',NULL),
(@vid,@bid,3,5,'Dios sabe muy bien que , cuando ustedes coman de ese árbol, se les abrirán los ojos y serán como Dios, conocedores del bien y del mal ”.',NULL),
(@vid,@bid,3,6,'La mujer vio que el fruto del árbol era bueno para comer, y que tenía un aspecto encantador y era deseable para alcanzar sabiduría. Así que tomó un fruto y se lo comió. Luego le dio a su esposo, que estaba con ella , y él también comió.',NULL),
(@vid,@bid,3,7,'En ese momento se les abrirán los ojos y se dieron cuenta de que estaban desnudos. Entonces cosieron hojas de higuera para cubrirse.',NULL),
(@vid,@bid,3,8,'Cuando oyeron que Yahvé Dios se paseaba por el jardín a la hora en que sopla el viento de la tarde, el hombre y su mujer se escondieron de su presencia entre los árboles del jardín.',NULL),
(@vid,@bid,3,9,'Pero Yahvé Dios llamó al hombre y le preguntó: “¿Dónde estás?”',NULL),
(@vid,@bid,3,10,'El hombre respondió: “ Oí tus pasos por el jardín y tuve miedo porque estoy desnudo; por eso me escondí ”.',NULL),
(@vid,@bid,3,11,'“¿ Y quién te dijo que estás desnudo? le preguntó Dios. ¿Acaso has comido del árbol que te prohibí comer?”',NULL),
(@vid,@bid,3,12,'El hombre contestó: “ La mujer que me diste por compañera me dio del fruto de ese árbol , y yo comí”.',NULL),
(@vid,@bid,3,13,'Entonces Yahvé Dios le preguntó a la mujer: “¿ Qué es lo que has hecho ?” “ La serpiente me engañó, y yo comí” respondió ella.',NULL),
(@vid,@bid,3,14,'Entonces Yahvé Dios le dijo a la serpiente : “ Por haber hecho esto , maldita serás entre todos los animales domésticos y entre todos los animales salvajes. Te arrastrarás sobre tu vientre, y comerás polvo todos los días de tu vida .',NULL),
(@vid,@bid,3,15,'Pondré enemistad entre ti y la mujer, y entre tu descendencia y la suya . Él te aplastará la cabeza , y tú le herirás el talón”.',NULL),
(@vid,@bid,3,16,'A la mujer le dijo: “Aumentaré mucho tus dolores de parto; con dolor darás a luz a tus hijos . Tu deseo te llevará a tu esposo, y él te dominará”.',NULL),
(@vid,@bid,3,17,'Al hombre le dijo: “ Como le hiciste caso a tu mujer y comiste del árbol que te prohibí, la tierra estará maldita por tu culpa. Con mucho esfuerzo comerás de ella todos los días de tu vida .',NULL),
(@vid,@bid,3,18,'La tierra te producirá espinos y cardos, y comerás hierbas del campo .',NULL),
(@vid,@bid,3,19,'Te ganarás el pan con el sudor de tu frente, hasta que vuelvas a la tierra de donde fuiste sacado. Porque eres polvo , y al polvo volverás ”.',NULL),
(@vid,@bid,3,20,'El hombre llamó a su mujer Eva , porque ella sería la madre de todos los vivientes .',NULL),
(@vid,@bid,3,21,'Yahvé Dios les hizo ropa de piel al hombre y a su mujer, y los vistió .',NULL),
(@vid,@bid,3,22,'Luego Yahvé Dios dijo: “ Ahora el hombre se ha vuelto como uno de nosotros, pues conoce el bien y el mal . No vaya a ser que extienda su mano y tome también del árbol de la vida , y coma de él y viva para siempre ”.',NULL),
(@vid,@bid,3,23,'Así que Yahvé Dios expulsó al hombre del jardín del Edén, para que cultivara la tierra de la cual había sido formado.',NULL),
(@vid,@bid,3,24,'Después de expulsar al hombre, puso al oriente del jardín del Edén querubines y una espada llameante que giraba en todas direcciones para vigilar el camino que conducía al árbol de la vida .',NULL),
(@vid,@bid,4,1,'El hombre tuvo relaciones con su mujer Eva . Ella quedó embarazada y dio a luz a Caín , y dijo: “Con la ayuda de Yahvé, he tenido un hijo varón”.',NULL),
(@vid,@bid,4,2,'Después dio a luz a Abel , el hermano de Caín . Abel se dedicó a pastorear ovejas , mientras que Caín se dedicó a cultivar la tierra.',NULL),
(@vid,@bid,4,3,'Tiempo después , Caín le presentó a Yahvé una ofrenda del fruto de la tierra.',NULL),
(@vid,@bid,4,4,'Por su parte, Abel le presentó lo mejor de las primeras crías de su rebaño . Yahvé miró con agrado a Abel y a su ofrenda ,',NULL),
(@vid,@bid,4,5,'pero no miró así a Caín ni a su ofrenda . Por eso Caín se enfureció y andaba muy cabizbajo.',NULL),
(@vid,@bid,4,6,'Yahvé le preguntó a Caín : “¿ Por qué estás tan enojado ? ¿ Por qué andas cabizbajo?',NULL),
(@vid,@bid,4,7,'Si hicieras lo bueno, podrías andar con la frente en alto. Pero, si haces lo malo, el pecado te acecha como una fiera lista para atraparte. No obstante, tú puedes dominarlo”.',NULL),
(@vid,@bid,4,8,'Caín le dijo a su hermano Abel : “Vamos al campo ”. Y sucedió que , mientras estaban en el campo , Caín atacó a su hermano Abel y lo mató .',NULL),
(@vid,@bid,4,9,'Entonces Yahvé le preguntó a Caín : “¿Dónde está tu hermano Abel ?” “ No lo sé respondió él. ¿Acaso soy yo el guardián de mi hermano?”',NULL),
(@vid,@bid,4,10,'“¿ Qué has hecho ? le dijo Yahvé. La sangre de tu hermano clama a mí desde la tierra.',NULL),
(@vid,@bid,4,11,'Por eso, ahora quedas bajo la maldición de la tierra, que abrió su boca para recibir de tus manos la sangre de tu hermano.',NULL),
(@vid,@bid,4,12,'Cuando cultives la tierra, ella no te dará sus frutos. Andarás por la tierra como un fugitivo y un vagabundo”.',NULL),
(@vid,@bid,4,13,'Caín le dijo a Yahvé: “ Mi castigo es más de lo que puedo soportar.',NULL),
(@vid,@bid,4,14,'Hoy me estás expulsando de la tierra, y tendré que esconderme de tu presencia . Andaré por el mundo como un fugitivo y un vagabundo, y cualquiera que me encuentre me matará ”.',NULL),
(@vid,@bid,4,15,'Pero Yahvé le respondió: “ No será así . El que mate a Caín será castigado siete veces”. Entonces Yahvé le puso una señal a Caín para que el que lo encontrara no lo matara .',NULL),
(@vid,@bid,4,16,'Así Caín se alejó de la presencia de Yahvé y se fue a vivir a la región de Nod, al oriente del Edén.',NULL),
(@vid,@bid,4,17,'Caín tuvo relaciones con su mujer, y ella quedó embarazada y dio a luz a Enoc. Caín estaba construyendo una ciudad , a la que le puso el nombre de su hijo , Enoc.',NULL),
(@vid,@bid,4,18,'Enoc fue el padre de Irad , Irad fue el padre de Mejuyael, Mejuyael fue el padre de Metusael, y Metusael fue el padre de Lamec.',NULL),
(@vid,@bid,4,19,'Lamec tuvo dos mujeres. Una se llamaba Adá y la otra Zilá.',NULL),
(@vid,@bid,4,20,'Adá dio a luz a Jabal, que fue el antepasado de los que viven en tiendas y crían ganado .',NULL),
(@vid,@bid,4,21,'Jabal tuvo un hermano llamado Jubal , que fue el antepasado de los que tocan el arpa y la flauta.',NULL),
(@vid,@bid,4,22,'Por su parte, Zilá dio a luz a Tubal Caín, que fue herrero y forjador de toda clase de herramientas de bronce y de hierro . Tubal Caín tuvo una hermana que se llamaba Noamá.',NULL),
(@vid,@bid,4,23,'Lamec les dijo a sus mujeres: “ Adá y Zilá, escuchen bien mi voz ; mujeres de Lamec, presten atención a mis palabras: maté a un hombre por haberme herido, y a un joven por haberme golpeado.',NULL),
(@vid,@bid,4,24,'Si a Caín lo vengarán siete veces , a Lamec lo vengarán setenta y siete veces ”.',NULL),
(@vid,@bid,4,25,'Adán volvió a tener relaciones con su mujer, y ella dio a luz un hijo al que llamó Set, pues dijo: “Dios me ha concedido otro hijo en lugar de Abel , a quien Caín mató ”.',NULL),
(@vid,@bid,4,26,'También Set tuvo un hijo , al que llamó Enós. Fue entonces cuando los hombres comenzaron a invocar el nombre de Yahvé.',NULL),
(@vid,@bid,5,1,'Ésta es la lista de los descendientes de Adán. Cuando Dios creó al hombre, lo hizo a su semejanza .',NULL),
(@vid,@bid,5,2,'Hombre y mujer los creó, y los bendijo . El día que fueron creados, los llamó “Humanidad”.',NULL),
(@vid,@bid,5,3,'Adán tenía ciento treinta años cuando tuvo un hijo a su imagen y semejanza , al que llamó Set.',NULL),
(@vid,@bid,5,4,'Después del nacimiento de Set, Adán vivió ochocientos años más, y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,5,'Adán murió a los novecientos treinta años de edad .',NULL),
(@vid,@bid,5,6,'Set tenía ciento cinco años cuando fue padre de Enós.',NULL),
(@vid,@bid,5,7,'Después del nacimiento de Enós, Set vivió ochocientos siete años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,8,'Set murió a los novecientos doce años de edad .',NULL),
(@vid,@bid,5,9,'Enós tenía noventa años cuando fue padre de Cainán .',NULL),
(@vid,@bid,5,10,'Después del nacimiento de Cainán , Enós vivió ochocientos quince años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,11,'Enós murió a los novecientos cinco años de edad .',NULL),
(@vid,@bid,5,12,'Cainán tenía setenta años cuando fue padre de Mejalalel.',NULL),
(@vid,@bid,5,13,'Después del nacimiento de Mejalalel, Cainán vivió ochocientos cuarenta años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,14,'Cainán murió a los novecientos diez años de edad .',NULL),
(@vid,@bid,5,15,'Mejalalel tenía sesenta y cinco años cuando fue padre de Jared .',NULL),
(@vid,@bid,5,16,'Después del nacimiento de Jared , Mejalalel vivió ochocientos treinta años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,17,'Mejalalel murió a los ochocientos noventa y cinco años de edad .',NULL),
(@vid,@bid,5,18,'Jared tenía ciento sesenta y dos años cuando fue padre de Enoc.',NULL),
(@vid,@bid,5,19,'Después del nacimiento de Enoc, Jared vivió ochocientos años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,20,'Jared murió a los novecientos sesenta y dos años de edad .',NULL),
(@vid,@bid,5,21,'Enoc tenía sesenta y cinco años cuando fue padre de Matusalén.',NULL),
(@vid,@bid,5,22,'Después del nacimiento de Matusalén, Enoc vivió en íntima comunión con Dios trescientos años más, y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,23,'En total, Enoc vivió trescientos sesenta y cinco años .',NULL),
(@vid,@bid,5,24,'Enoc vivió en íntima comunión con Dios, y un día desapareció porque Dios se lo llevó .',NULL),
(@vid,@bid,5,25,'Matusalén tenía ciento ochenta y siete años cuando fue padre de Lamec.',NULL),
(@vid,@bid,5,26,'Después del nacimiento de Lamec, Matusalén vivió setecientos ochenta y dos años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,27,'Matusalén murió a los novecientos sesenta y nueve años de edad .',NULL),
(@vid,@bid,5,28,'Lamec tenía ciento ochenta y dos años cuando tuvo un hijo .',NULL),
(@vid,@bid,5,29,'Lo llamó Noé , pues dijo: “ Éste nos aliviará de nuestro trabajo y de la fatiga de nuestras manos , causados por la tierra que Yahvé maldijo”.',NULL),
(@vid,@bid,5,30,'Después del nacimiento de Noé , Lamec vivió quinientos noventa y cinco años , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,5,31,'Lamec murió a los setecientos setenta y siete años de edad .',NULL),
(@vid,@bid,5,32,'Noé tenía quinientos años cuando fue padre de Sem , Cam y Jafet.',NULL),
(@vid,@bid,6,1,'Cuando los seres humanos comenzaron a multiplicarse sobre la tierra y tuvieron hijas ,',NULL),
(@vid,@bid,6,2,'los hijos de Dios vieron que las hijas de los hombres eran hermosas , y tomaron por esposas a las que más les gustaron.',NULL),
(@vid,@bid,6,3,'Entonces Yahvé dijo: “ Mi Espíritu no permanecerá en el hombre para siempre , porque él no es más que carne mortal. Por eso , el hombre no vivirá más de ciento veinte años ”.',NULL),
(@vid,@bid,6,4,'En aquellos días , y aun después , había gigantes en la tierra. Éstos eran los hijos que los hijos de Dios tuvieron con las hijas de los hombres . Fueron los héroes famosos de la antigüedad.',NULL),
(@vid,@bid,6,5,'Al ver Yahvé que la maldad del ser humano en la tierra era muy grande , y que todos sus pensamientos tendían siempre hacia el mal ,',NULL),
(@vid,@bid,6,6,'se arrepintió de haber hecho al hombre en la tierra, y le dolió en el corazón .',NULL),
(@vid,@bid,6,7,'Por eso dijo Yahvé: “Voy a borrar de la superficie de la tierra a estos hombres que he creado, y también a los animales, a los reptiles y a las aves del cielo . ¡ Me pesa haberlos hecho !”',NULL),
(@vid,@bid,6,8,'Pero Noé contaba con el favor de Yahvé.',NULL),
(@vid,@bid,6,9,'Ésta es la historia de Noé . Noé era un hombre justo y honrado entre sus contemporáneos. Siempre vivió en íntima comunión con Dios.',NULL),
(@vid,@bid,6,10,'Noé tuvo tres hijos : Sem , Cam y Jafet.',NULL),
(@vid,@bid,6,11,'Para ese entonces, la tierra estaba corrompida a los ojos de Dios y llena de violencia .',NULL),
(@vid,@bid,6,12,'Al ver Dios tanta corrupción en la tierra, pues todos los seres humanos se habían corrompido ,',NULL),
(@vid,@bid,6,13,'le dijo a Noé : “He decidido poner fin a toda la humanidad, porque la tierra está llena de violencia por culpa de ellos . ¡Voy a destruirlos junto con la tierra!',NULL),
(@vid,@bid,6,14,'Así que hazte un arca de madera de ciprés, con compartimentos, y recúbrela con brea por dentro y por fuera .',NULL),
(@vid,@bid,6,15,'Hazla de estas medidas: ciento treinta y ocho metros de largo, veintitrés metros de ancho y catorce metros de alto.',NULL),
(@vid,@bid,6,16,'Hazle un techo, dejando una abertura de medio metro entre el techo y los costados . Pon la puerta en uno de sus lados , y construye tres pisos en el arca .',NULL),
(@vid,@bid,6,17,'Yo voy a enviar un diluvio sobre la tierra, para destruir a todos los seres que tienen aliento de vida bajo el cielo . ¡ Todo lo que hay en la tierra morirá !',NULL),
(@vid,@bid,6,18,'Pero contigo estableceré mi pacto . Tú entrarás en el arca , y contigo tus hijos , tu mujer y tus nueras.',NULL),
(@vid,@bid,6,19,'También meterás en el arca una pareja de cada especie de todos los seres vivos , para que sobrevivan contigo; tienen que ser macho y hembra .',NULL),
(@vid,@bid,6,20,'De cada especie de aves , de animales y de reptiles , entrará contigo una pareja para que sobrevivan.',NULL),
(@vid,@bid,6,21,'Asegúrate de llevar toda clase de alimentos y de almacenarlos, para que tú y ellos tengan qué comer”.',NULL),
(@vid,@bid,6,22,'Noé lo hizo así ; cumplió al pie de la letra con todo lo que Dios le había ordenado .',NULL),
(@vid,@bid,7,1,'Después Yahvé le dijo a Noé : “Entra en el arca con toda tu familia , porque he visto que tú eres el único hombre justo de este tiempo.',NULL),
(@vid,@bid,7,2,'De todos los animales puros, toma siete parejas, macho y hembra; pero de los animales impuros, toma sólo una pareja, macho y hembra.',NULL),
(@vid,@bid,7,3,'También de las aves del cielo , toma siete parejas, macho y hembra , para conservar su especie sobre la tierra.',NULL),
(@vid,@bid,7,4,'Porque dentro de siete días enviaré una lluvia sobre la tierra que durará cuarenta días y cuarenta noches , y borraré de la superficie de la tierra a todos los seres vivos que he creado”.',NULL),
(@vid,@bid,7,5,'Noé hizo todo tal como Yahvé se lo había ordenado .',NULL),
(@vid,@bid,7,6,'Noé tenía seiscientos años cuando el diluvio inundó la tierra.',NULL),
(@vid,@bid,7,7,'Él entró en el arca , junto con sus hijos , su mujer y sus nueras, para salvarse del diluvio .',NULL),
(@vid,@bid,7,8,'De los animales puros e impuros, de las aves y de todos los seres que se arrastran por el suelo,',NULL),
(@vid,@bid,7,9,'entraron con Noé en el arca parejas de macho y hembra , tal como Dios se lo había ordenado .',NULL),
(@vid,@bid,7,10,'Siete días después , las aguas del diluvio comenzaron a caer sobre la tierra.',NULL),
(@vid,@bid,7,11,'Cuando Noé tenía seiscientos años , el día diecisiete del segundo mes , se reventaron todas las fuentes del gran abismo y se abrieron las compuertas del cielo .',NULL),
(@vid,@bid,7,12,'Estuvo lloviendo sobre la tierra cuarenta días y cuarenta noches .',NULL),
(@vid,@bid,7,13,'Ese mismo día , Noé y sus hijos Sem , Cam y Jafet, junto con su mujer y sus tres nueras, entraron en el arca .',NULL),
(@vid,@bid,7,14,'Con ellos entraron todos los animales salvajes y domésticos según su especie , todos los reptiles que se arrastran por el suelo según su especie , y todas las aves y todos los seres alados según su especie .',NULL),
(@vid,@bid,7,15,'De todos los seres que tienen aliento de vida , entraron con Noé en el arca de dos en dos .',NULL),
(@vid,@bid,7,16,'Los animales que entraron eran macho y hembra de cada especie, tal como Dios se lo había ordenado a Noé. Luego Yahvé cerró la puerta.',NULL),
(@vid,@bid,7,17,'El diluvio duró cuarenta días sobre la tierra. Al crecer las aguas , el arca se levantó y comenzó a flotar.',NULL),
(@vid,@bid,7,18,'Las aguas crecieron y aumentaron muchísimo, pero el arca se mantenía a flote sobre ellas .',NULL),
(@vid,@bid,7,19,'Tanto subieron las aguas que cubrieron las montañas más altas que hay bajo el cielo .',NULL),
(@vid,@bid,7,20,'El nivel del agua subió casi siete metros por encima de las montañas.',NULL),
(@vid,@bid,7,21,'Y murieron todos los seres que se movían sobre la tierra: las aves , los animales domésticos y salvajes, todos los reptiles y toda la humanidad.',NULL),
(@vid,@bid,7,22,'Todo lo que tenía aliento de vida y vivía en la tierra firme, murió .',NULL),
(@vid,@bid,7,23,'Así Dios borró de la superficie de la tierra a todos los seres vivos, desde el hombre hasta los animales, los reptiles y las aves del cielo . ¡ Todos fueron borrados de la tierra! Sólo sobrevivieron Noé y los que estaban con él en el arca .',NULL),
(@vid,@bid,7,24,'Y las aguas cubrieron la tierra durante ciento cincuenta días .',NULL),
(@vid,@bid,8,1,'Pero Dios se acordó de Noé y de todos los animales salvajes y domésticos que estaban con él en el arca . Entonces hizo que soplara un viento fuerte sobre la tierra, y las aguas comenzaron a bajar.',NULL),
(@vid,@bid,8,2,'Se cerraron las fuentes del abismo y las compuertas del cielo , y dejó de llover.',NULL),
(@vid,@bid,8,3,'Poco a poco las aguas se fueron retirando de la tierra. Al cabo de ciento cincuenta días , el nivel del agua había bajado.',NULL),
(@vid,@bid,8,4,'El día diecisiete del séptimo mes , el arca quedó encallada en los montes de Ararat.',NULL),
(@vid,@bid,8,5,'Las aguas siguieron bajando hasta que el primer día del décimo mes pudieron verse las cimas de las montañas.',NULL),
(@vid,@bid,8,6,'Pasados otros cuarenta días , Noé abrió la ventana que le había hecho al arca',NULL),
(@vid,@bid,8,7,'y soltó un cuervo , el cual estuvo volando de un lado a otro hasta que se secó la tierra.',NULL),
(@vid,@bid,8,8,'Luego soltó una paloma para ver si las aguas ya se habían retirado de la superficie.',NULL),
(@vid,@bid,8,9,'Pero la paloma no encontró dónde posarse, así que volvió al arca porque el agua todavía cubría toda la tierra. Noé extendió la mano , la tomó y la metió de nuevo en el arca .',NULL),
(@vid,@bid,8,10,'Esperó siete días más y volvió a soltar la paloma .',NULL),
(@vid,@bid,8,11,'Al anochecer, la paloma regresó con una hoja de olivo recién arrancada en el pico. Así Noé se dio cuenta de que las aguas ya habían bajado.',NULL),
(@vid,@bid,8,12,'Esperó otros siete días y volvió a soltar la paloma , pero ésta ya no regresó.',NULL),
(@vid,@bid,8,13,'Cuando Noé tenía seiscientos un años , el primer día del primer mes , las aguas se habían secado. Noé quitó el techo del arca y vio que la superficie del suelo ya estaba seca.',NULL),
(@vid,@bid,8,14,'El día veintisiete del segundo mes , la tierra ya estaba completamente seca .',NULL),
(@vid,@bid,8,15,'Entonces Dios le dijo a Noé :',NULL),
(@vid,@bid,8,16,'“ Sal del arca junto con tu mujer, tus hijos y tus nueras.',NULL),
(@vid,@bid,8,17,'Saca también a todos los animales que están contigo , tanto aves como fieras y reptiles , para que se multipliquen y sean fecundos sobre la tierra”.',NULL),
(@vid,@bid,8,18,'Noé salió del arca con sus hijos , su mujer y sus nueras.',NULL),
(@vid,@bid,8,19,'También salieron todos los animales , reptiles y aves , según su especie.',NULL),
(@vid,@bid,8,20,'Luego Noé construyó un altar a Yahvé y, tomando de todos los animales y aves puros, ofreció un sacrificio en el altar .',NULL),
(@vid,@bid,8,21,'El aroma del sacrificio le agradó a Yahvé, quien pensó: “ Nunca más volveré a maldecir la tierra por culpa del hombre, aunque desde su juventud sus intenciones sean malas . Tampoco volveré a destruir a todos los seres vivos , como acabo de hacerlo.',NULL),
(@vid,@bid,8,22,'Mientras la tierra exista, no faltarán la siembra ni la cosecha, ni el frío ni el calor, ni el verano ni el invierno, ni el día ni la noche ”.',NULL),
(@vid,@bid,9,1,'Dios bendijo a Noé y a sus hijos , y les dijo: “Sean fecundos, multiplíquense y llenen la tierra.',NULL),
(@vid,@bid,9,2,'Todos los animales de la tierra y todas las aves del cielo , todos los reptiles que se arrastran por el suelo y todos los peces del mar tendrán miedo de ustedes. Todos ellos quedan bajo su dominio.',NULL),
(@vid,@bid,9,3,'Todo lo que se mueve y tiene vida les servirá de alimento. Yo les doy todo esto , tal como antes les di las plantas verdes.',NULL),
(@vid,@bid,9,4,'Pero no deben comer carne con sangre , porque la sangre es la vida .',NULL),
(@vid,@bid,9,5,'Yo pediré cuentas de la sangre de cada uno de ustedes. Se las pediré a cualquier animal , y también a cualquier hombre por la vida de su semejante.',NULL),
(@vid,@bid,9,6,'El que derrame sangre humana, por otro hombre su sangre será derramada; porque Dios creó al hombre a su propia imagen .',NULL),
(@vid,@bid,9,7,'Pero ustedes, sean fecundos y multiplíquense; pueblen la tierra en abundancia y multiplíquense en ella”.',NULL),
(@vid,@bid,9,8,'Dios también les dijo a Noé y a sus hijos :',NULL),
(@vid,@bid,9,9,'“Miren, yo establezco mi pacto con ustedes, con sus descendientes',NULL),
(@vid,@bid,9,10,'y con todos los seres vivos que están con ustedes: aves , animales domésticos y salvajes, y todos los que salieron del arca .',NULL),
(@vid,@bid,9,11,'Éste es mi pacto : Nunca más volverán a ser exterminados los seres vivos por un diluvio , ni habrá otro diluvio que destruya la tierra”.',NULL),
(@vid,@bid,9,12,'Y añadió Dios: “ Ésta es la señal del pacto que establezco para siempre con ustedes y con todos los seres vivos :',NULL),
(@vid,@bid,9,13,'He puesto mi arco iris en las nubes . Ésa será la señal de mi pacto con la tierra.',NULL),
(@vid,@bid,9,14,'Cuando yo cubra la tierra de nubes y aparezca el arco iris,',NULL),
(@vid,@bid,9,15,'me acordaré del pacto que hice con ustedes y con todos los seres vivos , y nunca más las aguas del diluvio volverán a destruir a los seres vivos .',NULL),
(@vid,@bid,9,16,'Cuando el arco iris esté en las nubes , yo lo veré y me acordaré del pacto eterno que hay entre Dios y todos los seres vivos de la tierra”.',NULL),
(@vid,@bid,9,17,'Así le dijo Dios a Noé : “ Ésta es la señal del pacto que he establecido con todos los seres vivos de la tierra”.',NULL),
(@vid,@bid,9,18,'Los hijos de Noé que salieron del arca fueron Sem , Cam y Jafet. Cam fue el padre de Canaán .',NULL),
(@vid,@bid,9,19,'A partir de estos tres hijos de Noé se pobló toda la tierra.',NULL),
(@vid,@bid,9,20,'Noé se dedicó a la agricultura y plantó una viña .',NULL),
(@vid,@bid,9,21,'Un día bebió vino , se emborrachó y se quedó desnudo dentro de su tienda.',NULL),
(@vid,@bid,9,22,'Cam, el padre de Canaán , vio la desnudez de su padre y salió a contárselo a sus dos hermanos.',NULL),
(@vid,@bid,9,23,'Entonces Sem y Jafet tomaron un manto y , poniéndoselo sobre los hombros , entraron caminando de espaldas para no ver la desnudez de su padre, y lo cubrieron . Como caminaban de espaldas, no lo vieron desnudo.',NULL),
(@vid,@bid,9,24,'Cuando a Noé se le pasó la borrachera y se enteró de lo que su hijo menor le había hecho ,',NULL),
(@vid,@bid,9,25,'exclamó: “¡Maldito sea Canaán ! Será el último de los esclavos de sus hermanos”.',NULL),
(@vid,@bid,9,26,'Y añadió: “¡ Bendito sea Yahvé, Dios de Sem ! ¡ Que Canaán sea esclavo de Sem !',NULL),
(@vid,@bid,9,27,'¡ Que Dios extienda el territorio de Jafet! ¡ Que Jafet viva en las tiendas de Sem , y que Canaán sea su esclavo!”',NULL),
(@vid,@bid,9,28,'Después del diluvio , Noé vivió trescientos cincuenta años más .',NULL),
(@vid,@bid,9,29,'Murió a los novecientos cincuenta años de edad .',NULL),
(@vid,@bid,10,1,'Éstos son los descendientes de Sem , Cam y Jafet, los hijos de Noé , que tuvieron hijos después del diluvio .',NULL),
(@vid,@bid,10,2,'Los hijos de Jafet fueron: Gómer , Magog , Maday, Javán , Tubal , Mésec y Tirás.',NULL),
(@vid,@bid,10,3,'Los hijos de Gómer fueron: Asquenaz, Rifat y Togarma.',NULL),
(@vid,@bid,10,4,'Los hijos de Javán fueron: Elisá, Tarsis , Quitín y Dodanín.',NULL),
(@vid,@bid,10,5,'De ellos descendieron los que poblaron las costas y las islas, cada uno según su lengua , sus familias y sus naciones .',NULL),
(@vid,@bid,10,6,'Los hijos de Cam fueron: Cus, Mizrayín, Fut y Canaán .',NULL),
(@vid,@bid,10,7,'Los hijos de Cus fueron: Seba , Javilá, Sabtá, Raamá y Sabteca. Los hijos de Raamá fueron: Sabá y Dedán .',NULL),
(@vid,@bid,10,8,'Cus fue el padre de Nimrod, el primer hombre poderoso que hubo en la tierra.',NULL),
(@vid,@bid,10,9,'Nimrod fue un gran cazador ante Yahvé; por eso se dice: “ Como Nimrod, gran cazador ante Yahvé”.',NULL),
(@vid,@bid,10,10,'Las ciudades principales de su reino fueron Babel, Érec, Acad y Calné, en la tierra de Sinar.',NULL),
(@vid,@bid,10,11,'De esa tierra pasó a Asiria, donde construyó Nínive , Rehobot Ir, Cálaj',NULL),
(@vid,@bid,10,12,'y Resén, la gran ciudad que está entre Nínive y Cálaj.',NULL),
(@vid,@bid,10,13,'Mizrayín fue el antepasado de los ludeos, los anameos, los lejabeos, los naftujeos,',NULL),
(@vid,@bid,10,14,'los patrusim, los caslujeos (de donde descendieron los filisteos ) y los caftoreos.',NULL),
(@vid,@bid,10,15,'Canaán fue el padre de Sidón , su primogénito , y de Het.',NULL),
(@vid,@bid,10,16,'También fue el antepasado de los jebuseos , los amorreos, los gergeseos ,',NULL),
(@vid,@bid,10,17,'los heveos , los araceos, los sineos,',NULL),
(@vid,@bid,10,18,'los arvadeos, los zemareos y los jamateos. Después las familias cananeas se dispersaron.',NULL),
(@vid,@bid,10,19,'El territorio de los cananeos se extendía desde Sidón , en dirección a Gerar , hasta Gaza , y en dirección a Sodoma , Gomorra , Admá y Zeboín, hasta Lasa .',NULL),
(@vid,@bid,10,20,'Éstos fueron los descendientes de Cam, según sus familias y sus lenguas, en sus tierras y sus naciones .',NULL),
(@vid,@bid,10,21,'También Sem , el hermano mayor de Jafet, tuvo hijos . Sem fue el antepasado de todos los hijos de Héber .',NULL),
(@vid,@bid,10,22,'Los hijos de Sem fueron: Elam , Asur, Arfaxad, Lud y Aram.',NULL),
(@vid,@bid,10,23,'Los hijos de Aram fueron: Uz , Hul , Guéter y Mas.',NULL),
(@vid,@bid,10,24,'Arfaxad fue el padre de Selá , y Selá fue el padre de Héber .',NULL),
(@vid,@bid,10,25,'Héber tuvo dos hijos . Uno se llamaba Péleg , porque en su tiempo se dividió la tierra; su hermano se llamaba Joctán .',NULL),
(@vid,@bid,10,26,'Joctán fue el padre de Almodad, Sélef, Jazarmávet, Jera,',NULL),
(@vid,@bid,10,27,'Adorán, Uzal, Diclá ,',NULL),
(@vid,@bid,10,28,'Obal, Abimael, Sabá,',NULL),
(@vid,@bid,10,29,'Ofir, Javilá y Jobab . Todos éstos fueron hijos de Joctán .',NULL),
(@vid,@bid,10,30,'Su territorio se extendía desde Mesá, en dirección a Sefar, en la región montañosa del oriente .',NULL),
(@vid,@bid,10,31,'Éstos fueron los descendientes de Sem , según sus familias y sus lenguas, en sus tierras y sus naciones .',NULL),
(@vid,@bid,10,32,'Éstas son las familias de los hijos de Noé , según sus descendientes y sus naciones . A partir de ellas se dispersaron las naciones por toda la tierra después del diluvio .',NULL),
(@vid,@bid,11,1,'En ese tiempo, todo el mundo hablaba un mismo idioma y usaba las mismas palabras .',NULL),
(@vid,@bid,11,2,'Al emigrar desde el oriente , la gente encontró una llanura en la tierra de Sinar y se estableció allí .',NULL),
(@vid,@bid,11,3,'Un día se dijeron unos a otros: “Vengan, vamos a fabricar ladrillos y a cocerlos al fuego”. Así, usaron ladrillos en vez de piedras, y asfalto en vez de mezcla.',NULL),
(@vid,@bid,11,4,'Luego dijeron: “Vengan, vamos a construir una ciudad y una torre que llegue hasta el cielo . Así nos haremos famosos y no andaremos dispersos por todo el mundo”.',NULL),
(@vid,@bid,11,5,'Pero Yahvé bajó para ver la ciudad y la torre que los hombres estaban construyendo.',NULL),
(@vid,@bid,11,6,'Y dijo Yahvé: “Miren, todos ellos forman un solo pueblo y hablan un solo idioma; ¡y esto es sólo el comienzo de sus obras! Ahora nada de lo que se propongan les será imposible.',NULL),
(@vid,@bid,11,7,'Será mejor que bajemos y confundamos su idioma, para que no se entiendan entre ellos”.',NULL),
(@vid,@bid,11,8,'Así Yahvé los dispersó por toda la tierra, y ellos dejaron de construir la ciudad .',NULL),
(@vid,@bid,11,9,'Por eso la ciudad se llamó Babel, porque allí confundió Yahvé el idioma de todo el mundo, y desde allí los dispersó por toda la tierra.',NULL),
(@vid,@bid,11,10,'Ésta es la historia de los descendientes de Sem . Dos años después del diluvio , cuando Sem tenía cien años , fue padre de Arfaxad.',NULL),
(@vid,@bid,11,11,'Después del nacimiento de Arfaxad, Sem vivió quinientos años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,12,'Arfaxad tenía treinta y cinco años cuando fue padre de Selá .',NULL),
(@vid,@bid,11,13,'Después del nacimiento de Selá , Arfaxad vivió cuatrocientos tres años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,14,'Selá tenía treinta años cuando fue padre de Héber .',NULL),
(@vid,@bid,11,15,'Después del nacimiento de Héber , Selá vivió cuatrocientos tres años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,16,'Héber tenía treinta y cuatro años cuando fue padre de Péleg .',NULL),
(@vid,@bid,11,17,'Después del nacimiento de Péleg , Héber vivió cuatrocientos treinta años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,18,'Péleg tenía treinta años cuando fue padre de Reu .',NULL),
(@vid,@bid,11,19,'Después del nacimiento de Reu , Péleg vivió doscientos nueve años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,20,'Reu tenía treinta y dos años cuando fue padre de Serug .',NULL),
(@vid,@bid,11,21,'Después del nacimiento de Serug , Reu vivió doscientos siete años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,22,'Serug tenía treinta años cuando fue padre de Nacor.',NULL),
(@vid,@bid,11,23,'Después del nacimiento de Nacor, Serug vivió doscientos años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,24,'Nacor tenía veintinueve años cuando fue padre de Taré.',NULL),
(@vid,@bid,11,25,'Después del nacimiento de Taré, Nacor vivió ciento diecinueve años más , y tuvo otros hijos e hijas .',NULL),
(@vid,@bid,11,26,'Taré tenía setenta años cuando fue padre de Abram, Nacor y Harán .',NULL),
(@vid,@bid,11,27,'Éstos son los descendientes de Taré. Taré fue el padre de Abram, Nacor y Harán . Harán fue el padre de Lot .',NULL),
(@vid,@bid,11,28,'Harán murió en Ur de los caldeos , su tierra natal, mientras su padre Taré aún vivía.',NULL),
(@vid,@bid,11,29,'Abram y Nacor se casaron. La esposa de Abram se llamaba Saray. La esposa de Nacor se llamaba Milca , y era hija de Harán , el padre de Milca e Iscá.',NULL),
(@vid,@bid,11,30,'Pero Saray era estéril y no podía tener hijos.',NULL),
(@vid,@bid,11,31,'Taré tomó a su hijo Abram, a su nieto Lot , hijo de Harán , y a su nuera Saray, la esposa de Abram, y salieron de Ur de los caldeos para ir a la tierra de Canaán . Al llegar a la ciudad de Jarán, se quedaron a vivir allí .',NULL),
(@vid,@bid,11,32,'Taré vivió doscientos cinco años , y murió en Jarán.',NULL),
(@vid,@bid,12,1,'Yahvé le dijo a Abram: “ Vete de tu tierra, de tu parentela y de la casa de tu padre a la tierra que yo te mostraré .',NULL),
(@vid,@bid,12,2,'Haré de ti una nación grande , y te bendeciré ; haré famoso tu nombre , y serás una bendición .',NULL),
(@vid,@bid,12,3,'Bendeciré a los que te bendigan y maldeciré a los que te maldigan ; ¡por medio de ti serán benditas todas las familias de la tierra!”',NULL),
(@vid,@bid,12,4,'Abram partió , tal como Yahvé se lo había ordenado, y Lot se fue con él . Abram tenía setenta y cinco años cuando salió de Jarán.',NULL),
(@vid,@bid,12,5,'Tomó a su esposa Saray, a su nieto Lot , y todos los bienes y las personas que habían adquirido en Jarán, y se pusieron en camino hacia la tierra de Canaán . Cuando llegaron a Canaán ,',NULL),
(@vid,@bid,12,6,'Abram atravesó la tierra hasta llegar al lugar de Siquén, donde está la encina de Moré. En aquel tiempo, los cananeos vivían en esa región.',NULL),
(@vid,@bid,12,7,'Allí Yahvé se le apareció a Abram y le dijo: “Yo le daré esta tierra a tu descendencia ”. Entonces Abram construyó allí un altar a Yahvé, quien se le había aparecido.',NULL),
(@vid,@bid,12,8,'De allí pasó a la región montañosa que está al oriente de Betel, donde plantó su tienda, entre Betel al occidente y Ay al oriente . También allí construyó un altar a Yahvé e invocó su nombre .',NULL),
(@vid,@bid,12,9,'Después Abram siguió su camino por etapas hacia el Néguev.',NULL),
(@vid,@bid,12,10,'Hubo entonces una gran escasez de comida en la tierra, por lo que Abram bajó a Egipto para vivir allí por un tiempo, pues el hambre era terrible.',NULL),
(@vid,@bid,12,11,'Cuando estaba por entrar en Egipto , le dijo a su esposa Saray: “Escúchame; yo sé muy bien que eres una mujer hermosa .',NULL),
(@vid,@bid,12,12,'Cuando los egipcios te vean , dirán: ‘ Ésta es su esposa’, y a mí me matarán , pero a ti te dejarán con vida .',NULL),
(@vid,@bid,12,13,'Por favor, di que eres mi hermana, para que me traten bien por tu culpa y me dejen vivir gracias a ti”.',NULL),
(@vid,@bid,12,14,'En efecto, cuando Abram entró en Egipto , los egipcios vieron que Saray era muy hermosa .',NULL),
(@vid,@bid,12,15,'También la vieron los funcionarios del faraón y le hablaron de ella a su soberano, por lo que Saray fue llevada al palacio.',NULL),
(@vid,@bid,12,16,'Gracias a ella, el faraón trató muy bien a Abram, quien llegó a tener ovejas , vacas , burros y burras, siervos y siervas , y camellos .',NULL),
(@vid,@bid,12,17,'Pero por causa de Saray, la esposa de Abram, Yahvé envió terribles plagas sobre el faraón y su familia .',NULL),
(@vid,@bid,12,18,'Entonces el faraón llamó a Abram y le reclamó: “¿ Qué es lo que me has hecho ? ¿ Por qué no me dijiste que era tu esposa?',NULL),
(@vid,@bid,12,19,'¿ Por qué dijiste: ‘ Es mi hermana’? ¡ Yo pude haberla tomado por esposa! ¡ Aquí tienes a tu mujer; tómala y vete !”',NULL),
(@vid,@bid,12,20,'Entonces el faraón les dio órdenes a sus hombres acerca de Abram, y ellos lo despidieron junto con su mujer y todo lo que tenía.',NULL),
(@vid,@bid,13,1,'Abram salió de Egipto y se fue al Néguev, junto con su mujer y todo lo que tenía . Lot también iba con él .',NULL),
(@vid,@bid,13,2,'Abram ya era muy rico en ganado , plata y oro .',NULL),
(@vid,@bid,13,3,'Del Néguev, Abram volvió por etapas hasta llegar a Betel, al lugar donde antes había plantado su tienda, entre Betel y Ay.',NULL),
(@vid,@bid,13,4,'Allí estaba el altar que antes había construido, y allí Abram invocó el nombre de Yahvé.',NULL),
(@vid,@bid,13,5,'También Lot , que acompañaba a Abram, tenía sus propias ovejas , vacas y tiendas.',NULL),
(@vid,@bid,13,6,'Pero la región no bastaba para que los dos vivieran juntos , porque tenían demasiadas posesiones.',NULL),
(@vid,@bid,13,7,'Por eso hubo pleitos entre los pastores de Abram y los de Lot . En aquel tiempo, los cananeos y los ferezeos también vivían en esa región.',NULL),
(@vid,@bid,13,8,'Entonces Abram le dijo a Lot : “ No debe haber pleitos entre nosotros, ni entre tus pastores y los míos, porque somos parientes.',NULL),
(@vid,@bid,13,9,'¿Acaso no tienes toda la tierra ante tus ojos? Por favor, sepárate de mí . Si te vas a la izquierda , yo me iré a la derecha ; y si te vas a la derecha , yo me iré a la izquierda ”.',NULL),
(@vid,@bid,13,10,'Lot miró a su alrededor y vio que todo el valle del Jordán , hasta llegar a Zoar , era tierra de regadío, como el jardín de Yahvé o como la tierra de Egipto . Esto fue antes de que Yahvé destruyera a Sodoma y Gomorra .',NULL),
(@vid,@bid,13,11,'Entonces Lot escogió para sí todo el valle del Jordán y partió hacia el oriente . Así fue como se separaron el uno del otro.',NULL),
(@vid,@bid,13,12,'Abram se quedó a vivir en la tierra de Canaán , mientras que Lot se estableció entre las ciudades del valle y fue plantando sus tiendas cerca de Sodoma .',NULL),
(@vid,@bid,13,13,'Pero los habitantes de Sodoma eran muy malos y cometían grandes pecados contra Yahvé.',NULL),
(@vid,@bid,13,14,'Después de que Lot se separó de él , Yahvé le dijo a Abram: “ Levanta los ojos y, desde donde estás, mira hacia el norte y el sur, hacia el oriente y el occidente.',NULL),
(@vid,@bid,13,15,'Yo te daré a ti y a tu descendencia , para siempre , toda la tierra que alcanzas a ver .',NULL),
(@vid,@bid,13,16,'Haré que tu descendencia sea como el polvo de la tierra ; ¡ si alguien puede contar el polvo de la tierra , también podrá contar a tus descendientes!',NULL),
(@vid,@bid,13,17,'¡ Levántate y recorre la tierra a lo largo y a lo ancho, porque yo te la doy a ti!”',NULL),
(@vid,@bid,13,18,'Entonces Abram levantó su campamento y se fue a vivir cerca del encinar de Mamre , en Hebrón , donde construyó un altar a Yahvé.',NULL),
(@vid,@bid,14,1,'En aquel tiempo , Amrafel era rey de Sinar; Arioc, rey de Elasar; Quedorlaomer, rey de Elam ; y Tidal, rey de Goyín.',NULL),
(@vid,@bid,14,2,'Estos reyes le declararon la guerra a Bera , rey de Sodoma ; a Birsá, rey de Gomorra ; a Sinab, rey de Admá; a Semeber, rey de Zeboín; y al rey de Bela , que es Zoar .',NULL),
(@vid,@bid,14,3,'Todos estos últimos se aliaron en el valle de Sidín, donde ahora está el Mar Muerto.',NULL),
(@vid,@bid,14,4,'Durante doce años habían estado bajo el dominio de Quedorlaomer, pero en el año trece se rebelaron.',NULL),
(@vid,@bid,14,5,'Al año siguiente, Quedorlaomer y los reyes que estaban con él marcharon y derrotaron a los refaítas en Asterot Carnayín, a los zuzitas en Jan, a los emitas en Savé Quiriataín',NULL),
(@vid,@bid,14,6,'y a los horeos en los montes de Seir , hasta El Parán, que está cerca del desierto .',NULL),
(@vid,@bid,14,7,'De regreso, pasaron por En Mispat, que es Cades , y conquistaron todo el territorio de los amalecitas, y también derrotaron a los amorreos que vivían en Jazezón Tamar.',NULL),
(@vid,@bid,14,8,'Entonces salieron los reyes de Sodoma , de Gomorra , de Admá, de Zeboín y de Bela ( que es Zoar ), y en el valle de Sidín presentaron batalla',NULL),
(@vid,@bid,14,9,'contra Quedorlaomer, rey de Elam ; Tidal, rey de Goyín; Amrafel, rey de Sinar; y Arioc, rey de Elasar. Eran cuatro reyes contra cinco .',NULL),
(@vid,@bid,14,10,'Como el valle de Sidín estaba lleno de pozos de asfalto, cuando los reyes de Sodoma y de Gomorra huyeron , cayeron en ellos, y los demás escaparon hacia los montes .',NULL),
(@vid,@bid,14,11,'Los vencedores se llevaron todas las riquezas de Sodoma y de Gomorra , y todas sus provisiones.',NULL),
(@vid,@bid,14,12,'También se llevaron a Lot , el sobrino de Abram, junto con todas sus posesiones, ya que él vivía en Sodoma .',NULL),
(@vid,@bid,14,13,'Uno de los que escaparon fue a contarle todo esto a Abram el hebreo , que vivía cerca del encinar de Mamre el amorreo. Mamre era hermano de Escol y de Aner , los cuales eran aliados de Abram.',NULL),
(@vid,@bid,14,14,'Cuando Abram se enteró de que su sobrino estaba cautivo , organizó a trescientos dieciocho hombres de confianza, nacidos en su casa , y persiguió a los reyes hasta Dan .',NULL),
(@vid,@bid,14,15,'Durante la noche , Abram y sus hombres se dividieron para atacarlos, y los derrotaron y persiguieron hasta Hobá, que está al norte de Damasco .',NULL),
(@vid,@bid,14,16,'Así recuperó todas las riquezas , y también a su sobrino Lot con sus posesiones, y a las mujeres y a la demás gente .',NULL),
(@vid,@bid,14,17,'Cuando Abram volvía de derrotar a Quedorlaomer y a los reyes que lo acompañaban, el rey de Sodoma salió a recibirlo al valle de Savé, que es el Valle del Rey .',NULL),
(@vid,@bid,14,18,'Entonces Melquisedec, rey de Salén y sacerdote del Dios Altísimo , sacó pan y vino ;',NULL),
(@vid,@bid,14,19,'bendijo a Abram con estas palabras: “¡Que te bendiga el Dios Altísimo , creador del cielo y de la tierra!',NULL),
(@vid,@bid,14,20,'¡ Y bendito sea el Dios Altísimo , que entregó a tus enemigos en tus manos !” Entonces Abram le dio a Melquisedec la décima parte de todo lo que había recuperado.',NULL),
(@vid,@bid,14,21,'El rey de Sodoma le dijo a Abram: “ Dame a las personas y quédate con las riquezas ”.',NULL),
(@vid,@bid,14,22,'Pero Abram le respondió al rey de Sodoma : “He jurado por Yahvé, el Dios Altísimo , creador del cielo y de la tierra,',NULL),
(@vid,@bid,14,23,'que no tomaré nada de lo que es tuyo, ni siquiera un hilo o la correa de una sandalia, para que no digas: ‘Yo enriquecí a Abram’.',NULL),
(@vid,@bid,14,24,'No quiero nada para mí, fuera de lo que mis hombres ya han comido. En cuanto a la parte que les corresponde a los hombres que me acompañaron, es decir, Aner , Escol y Mamre , que se queden ellos con su parte ”.',NULL),
(@vid,@bid,15,1,'Después de esto , la palabra de Yahvé vino a Abram en una visión : “ No tengas miedo , Abram. Yo soy tu escudo ; tu recompensa será muy grande ”.',NULL),
(@vid,@bid,15,2,'Pero Abram le respondió: “Señor Yahvé, ¿ qué me puedes dar , si no tengo hijos , y el heredero de mis bienes será Eliezer de Damasco ?”',NULL),
(@vid,@bid,15,3,'Y Abram añadió: “Como no me has dado ningún hijo , el heredero de todo será un siervo nacido en mi casa ”.',NULL),
(@vid,@bid,15,4,'Entonces la palabra de Yahvé vino a él y le dijo: “ Ese hombre no será tu heredero ; tu heredero será tu propio hijo”.',NULL),
(@vid,@bid,15,5,'Luego Yahvé lo llevó afuera y le dijo: “ Mira al cielo y cuenta las estrellas , a ver si puedes contarlas”. Y añadió: “ Así de numerosa será tu descendencia ”.',NULL),
(@vid,@bid,15,6,'Abram le creyó a Yahvé, y el Señor se lo reconoció como justicia .',NULL),
(@vid,@bid,15,7,'Además, le dijo: “Yo soy Yahvé, que te saqué de Ur de los caldeos para darte esta tierra como herencia”.',NULL),
(@vid,@bid,15,8,'Pero Abram le preguntó: “Señor Yahvé, ¿ cómo sabré que esta tierra va a ser mía?”',NULL),
(@vid,@bid,15,9,'Yahvé le respondió: “Tráeme una ternera, una cabra y un carnero, todos de tres años, y también una tórtola y un pichón de paloma”.',NULL),
(@vid,@bid,15,10,'Abram le trajo todos estos animales, los partió por la mitad y puso cada mitad frente a la otra, pero no partió las aves.',NULL),
(@vid,@bid,15,11,'Cuando las aves de rapiña bajaron sobre los animales muertos , Abram las espantó.',NULL),
(@vid,@bid,15,12,'Al atardecer, Abram cayó en un sueño profundo, y lo invadió un temor y una gran oscuridad.',NULL),
(@vid,@bid,15,13,'Entonces Yahvé le dijo: “ Ten por seguro que tus descendientes vivirán como extranjeros en un país que no será el suyo. Allí serán esclavos, y los maltratarán durante cuatrocientos años .',NULL),
(@vid,@bid,15,14,'Pero yo también castigaré a la nación de la que serán esclavos, y después saldrán de allí con grandes riquezas .',NULL),
(@vid,@bid,15,15,'Tú, por tu parte, morirás en paz y serás enterrado a una edad muy avanzada.',NULL),
(@vid,@bid,15,16,'En la cuarta generación tus descendientes volverán a este lugar, porque la maldad de los amorreos aún no ha llegado a su límite”.',NULL),
(@vid,@bid,15,17,'Cuando el sol se puso y todo quedó a oscuras, aparecieron un horno humeante y una antorcha encendida, los cuales pasaron por en medio de los animales descuartizados.',NULL),
(@vid,@bid,15,18,'Aquel día Yahvé hizo un pacto con Abram, diciendo: “ A tu descendencia le he dado esta tierra, desde el río de Egipto hasta el gran río Éufrates :',NULL),
(@vid,@bid,15,19,'la tierra de los quenitas, de los quenizitas, de los cadmonitas,',NULL),
(@vid,@bid,15,20,'de los hititas, de los ferezeos, de los refaítas,',NULL),
(@vid,@bid,15,21,'de los amorreos, de los cananeos , de los gergeseos y de los jebuseos ”.',NULL),
(@vid,@bid,16,1,'Sarai , la esposa de Abram, no le había dado hijos. Pero tenía una esclava egipcia que se llamaba Agar .',NULL),
(@vid,@bid,16,2,'Entonces Sarai le dijo a Abram: “ Mira , Yahvé no me ha permitido tener hijos. Por favor, ten relaciones con mi esclava; tal vez pueda formar una familia por medio de ella ”. Y Abram aceptó la propuesta de Sarai .',NULL),
(@vid,@bid,16,3,'Así que Sarai , la esposa de Abram, tomó a su esclava Agar la egipcia y se la dio a su esposo por mujer. Esto ocurrió cuando Abram ya llevaba diez años viviendo en la tierra de Canaán .',NULL),
(@vid,@bid,16,4,'Abram tuvo relaciones con Agar , y ella quedó embarazada . Al darse cuenta de que estaba embarazada , Agar comenzó a mirar a su señora con desprecio.',NULL),
(@vid,@bid,16,5,'Entonces Sarai le reclamó a Abram: “¡ Tú tienes la culpa de este problema! Yo misma te entregué a mi esclava, pero desde que se dio cuenta de que está embarazada , me mira con desprecio. ¡ Que Yahvé juzgue entre tú y yo !”',NULL),
(@vid,@bid,16,6,'Abram le respondió a Sarai : “ Tu esclava está en tus manos ; haz con ella lo que mejor te parezca”. Entonces Sarai la trató tan mal que Agar huyó de ella.',NULL),
(@vid,@bid,16,7,'El ángel de Yahvé la encontró en el desierto , junto a un manantial de agua ; es el manantial que está en el camino a Shur .',NULL),
(@vid,@bid,16,8,'Y le preguntó: “ Agar , esclava de Sarai , ¿ de dónde vienes y a dónde vas ?” Ella le respondió: “Estoy huyendo de mi señora Sarai ”.',NULL),
(@vid,@bid,16,9,'El ángel de Yahvé le ordenó: “Regresa con tu señora y sométete a su autoridad”.',NULL),
(@vid,@bid,16,10,'El ángel de Yahvé también le dijo: “ Multiplicaré tanto tu descendencia que será imposible contarla”.',NULL),
(@vid,@bid,16,11,'Además , el ángel de Yahvé le dijo: “Estás embarazada y darás a luz un hijo , y le pondrás por nombre Ismael , porque Yahvé ha escuchado tu aflicción .',NULL),
(@vid,@bid,16,12,'Será un hombre indomable como un burro salvaje. Luchará contra todos , y todos lucharán contra él ; y vivirá en conflicto con todos sus hermanos”.',NULL),
(@vid,@bid,16,13,'Como Yahvé le había hablado , ella lo llamó : “Tú eres el Dios que me ve ”, pues se dijo : “¿Acaso he visto a Dios y sigo con vida?”',NULL),
(@vid,@bid,16,14,'Por eso el pozo fue llamado Beer Lahai Roi. Este pozo se encuentra entre Cades y Bered .',NULL),
(@vid,@bid,16,15,'Agar le dio un hijo a Abram, y Abram le puso por nombre Ismael al hijo que ella le dio.',NULL),
(@vid,@bid,16,16,'Abram tenía ochenta y seis años cuando Agar dio a luz a Ismael .',NULL),
(@vid,@bid,17,1,'Cuando Abram tenía noventa y nueve años , Yahvé se le apareció y le dijo: “Yo soy el Dios Todopoderoso . Vive en mi presencia y sé intachable.',NULL),
(@vid,@bid,17,2,'Estableceré mi pacto contigo, y multiplicaré tu descendencia en gran manera ”.',NULL),
(@vid,@bid,17,3,'Abram se inclinó hasta tocar el suelo con la frente, y Dios le dijo :',NULL),
(@vid,@bid,17,4,'“ Éste es mi pacto contigo: Serás el padre de muchas naciones .',NULL),
(@vid,@bid,17,5,'Ya no te llamarás Abram, sino que tu nombre será Abraham, porque te he constituido en padre de muchas naciones .',NULL),
(@vid,@bid,17,6,'Te haré muy fecundo; de ti formaré naciones , y de ti saldrán reyes .',NULL),
(@vid,@bid,17,7,'Estableceré mi pacto contigo y con tu descendencia por todas las generaciones venideras. Será un pacto eterno ; yo seré tu Dios y el Dios de tus descendientes.',NULL),
(@vid,@bid,17,8,'A ti y a tu descendencia les daré en posesión eterna toda la tierra de Canaán , donde ahora viven como extranjeros. Y yo seré su Dios”.',NULL),
(@vid,@bid,17,9,'Dios también le dijo a Abraham: “Tú, por tu parte, cumplirás mi pacto , tú y tus descendientes por todas las generaciones .',NULL),
(@vid,@bid,17,10,'Éste es el pacto que ustedes deberán cumplir, el pacto entre mí y ustedes y sus descendientes: Todos los varones entre ustedes deberán ser circuncidados.',NULL),
(@vid,@bid,17,11,'Se circuncidarán la carne del prepucio , y esto servirá como señal del pacto entre nosotros.',NULL),
(@vid,@bid,17,12,'Todo varón entre ustedes que tenga ocho días de nacido deberá ser circuncidado a lo largo de sus generaciones , ya sea que haya nacido en la casa o que haya sido comprado con dinero a cualquier extranjero que no sea de su sangre.',NULL),
(@vid,@bid,17,13,'Tanto el nacido en tu casa como el comprado con tu dinero debe ser circuncidado . Así mi pacto quedará marcado en su carne como un pacto eterno .',NULL),
(@vid,@bid,17,14,'El varón incircunciso , el que no haya sido circuncidado en la carne de su prepucio , será eliminado de su pueblo por haber roto mi pacto ”.',NULL),
(@vid,@bid,17,15,'Dios también le dijo a Abraham: “ A tu esposa Sarai ya no la llamarás Sarai , sino que su nombre será Sara .',NULL),
(@vid,@bid,17,16,'Yo la bendeciré y , por medio de ella , te daré un hijo . Sí , la bendeciré y será madre de naciones ; de ella saldrán reyes de pueblos ”.',NULL),
(@vid,@bid,17,17,'Entonces Abraham se inclinó hasta tocar el suelo con la frente, se rió y pensó: “¿Acaso puede un hombre de cien años tener un hijo ? ¿ Y podrá Sara dar a luz a los noventa años ?”',NULL),
(@vid,@bid,17,18,'Y le dijo a Dios: “¡ Ojalá que Ismael pueda vivir bajo tu bendición!”',NULL),
(@vid,@bid,17,19,'Pero Dios le respondió: “No, tu esposa Sara te dará un hijo , y lo llamarás Isaac . Yo estableceré mi pacto con él y con su descendencia , como un pacto eterno .',NULL),
(@vid,@bid,17,20,'En cuanto a Ismael , también te he escuchado. Yo lo bendeciré , lo haré muy fecundo y multiplicaré en gran manera su descendencia. Será el padre de doce príncipes , y haré de él una gran nación .',NULL),
(@vid,@bid,17,21,'Pero mi pacto lo estableceré con Isaac , el hijo que Sara te dará a luz por esta misma época el año que viene”.',NULL),
(@vid,@bid,17,22,'Cuando terminó de hablar con Abraham, Dios se retiró de él .',NULL),
(@vid,@bid,17,23,'Ese mismo día , Abraham tomó a su hijo Ismael , a todos los nacidos en su casa y a todos los comprados con su dinero ; a todos los varones de su casa , y les circuncidó la carne del prepucio , tal como Dios se lo había ordenado.',NULL),
(@vid,@bid,17,24,'Abraham tenía noventa y nueve años cuando fue circuncidado .',NULL),
(@vid,@bid,17,25,'Su hijo Ismael tenía trece años cuando fue circuncidado .',NULL),
(@vid,@bid,17,26,'Ese mismo día fueron circuncidados Abraham y su hijo Ismael .',NULL),
(@vid,@bid,17,27,'Y con él fueron circuncidados todos los varones de su casa , tanto los nacidos en ella como los que habían sido comprados a los extranjeros .',NULL),
(@vid,@bid,18,1,'Yahvé se le apareció a Abraham junto a los robles de Mamre , mientras él estaba sentado a la entrada de su tienda en la hora de más calor.',NULL),
(@vid,@bid,18,2,'Abraham levantó la vista y vio a tres hombres de pie cerca de él . Al verlos, corrió desde la entrada de la tienda a recibirlos, se inclinó hasta el suelo',NULL),
(@vid,@bid,18,3,'y dijo: “Señor mío , si he hallado gracia a tus ojos , te ruego que no pases de largo y te quedes con tu siervo .',NULL),
(@vid,@bid,18,4,'Haré que traigan un poco de agua para que se laven los pies y descansen bajo el árbol .',NULL),
(@vid,@bid,18,5,'Ya que han pasado por donde está su siervo , iré a buscar un pedazo de pan para que repongan sus fuerzas antes de seguir su camino”. Ellos respondieron : “ Está bien , haz lo que has dicho ”.',NULL),
(@vid,@bid,18,6,'Abraham entró corriendo a la tienda donde estaba Sara y le dijo: “¡Rápido! Toma tres medidas de la mejor harina , amásala y prepara unos panes ”.',NULL),
(@vid,@bid,18,7,'Luego Abraham corrió hacia donde estaba el ganado , escogió un ternero tierno y gordo, y se lo dio a un sirviente, quien se apresuró a prepararlo.',NULL),
(@vid,@bid,18,8,'También tomó cuajada, leche y el ternero recién preparado, y se lo sirvió. Mientras ellos comían, él se quedó de pie junto a ellos debajo del árbol .',NULL),
(@vid,@bid,18,9,'Entonces le preguntaron: “¿Dónde está tu esposa Sara ?” “Allí en la tienda”, respondió él.',NULL),
(@vid,@bid,18,10,'Y uno de ellos le dijo: “Te aseguro que para esta misma época, el año que viene, volveré a verte, y tu esposa Sara tendrá un hijo ”. Sara estaba escuchando a la entrada de la tienda, a espaldas de él .',NULL),
(@vid,@bid,18,11,'Abraham y Sara ya eran muy ancianos , y Sara había pasado la edad de tener hijos.',NULL),
(@vid,@bid,18,12,'Por eso Sara se rió por dentro , pensando: “¿Acaso voy a tener este placer, ahora que ya estoy vieja y mi esposo también es un anciano?”',NULL),
(@vid,@bid,18,13,'Pero Yahvé le dijo a Abraham: “¿ Por qué se ríe Sara ? ¿ Por qué dice: ‘¿De verdad voy a dar a luz ahora que soy vieja?’',NULL),
(@vid,@bid,18,14,'¿Acaso hay algo imposible para Yahvé? El año que viene, por esta misma época, volveré a visitarte, y Sara tendrá un hijo ”.',NULL),
(@vid,@bid,18,15,'Llena de miedo , Sara mintió y dijo: “ No me estaba riendo”. Pero él le replicó: “ No es cierto , sí te reíste”.',NULL),
(@vid,@bid,18,16,'Luego los hombres se levantaron de allí y miraron hacia Sodoma , y Abraham los acompañó para despedirlos.',NULL),
(@vid,@bid,18,17,'Yahvé pensó: “¿Debería ocultarle a Abraham lo que voy a hacer ?',NULL),
(@vid,@bid,18,18,'Después de todo , de Abraham saldrá una nación grande y poderosa, y por medio de él serán bendecidas todas las naciones de la tierra.',NULL),
(@vid,@bid,18,19,'Yo lo he elegido para que instruya a sus hijos y a su familia , a fin de que se mantengan en el camino de Yahvé y practiquen la justicia y el derecho . Así Yahvé cumplirá todo lo que le ha prometido a Abraham”.',NULL),
(@vid,@bid,18,20,'Entonces Yahvé le dijo: “Las quejas contra Sodoma y Gomorra son ya muchas , y su pecado es gravísimo.',NULL),
(@vid,@bid,18,21,'Voy a bajar a ver si realmente sus acciones son tan malas como los informes que me han llegado. Y si no es así, lo sabré”.',NULL),
(@vid,@bid,18,22,'Los hombres se alejaron de allí y se dirigieron a Sodoma , pero Abraham se quedó de pie delante de Yahvé.',NULL),
(@vid,@bid,18,23,'Abraham se acercó y le dijo: “¿ De veras vas a destruir al justo junto con el malvado?',NULL),
(@vid,@bid,18,24,'¿ Qué tal si hay cincuenta justos en la ciudad ? ¿Acaso no perdonarás el lugar por amor a esos cincuenta justos ?',NULL),
(@vid,@bid,18,25,'¡ Lejos de ti actuar de esa manera ! ¡ Tú no puedes matar al justo junto con el malvado, ni tratar al justo como al malvado! ¡ Lejos de ti hacer tal cosa ! El Juez de toda la tierra, ¿acaso no actuará con justicia ?”',NULL),
(@vid,@bid,18,26,'Yahvé le respondió: “Si encuentro cincuenta justos en Sodoma , por amor a ellos perdonaré a toda la ciudad ”.',NULL),
(@vid,@bid,18,27,'Pero Abraham volvió a hablar : “ Ya que he tenido el atrevimiento de hablarle a mi Señor, yo que no soy más que polvo y ceniza,',NULL),
(@vid,@bid,18,28,'¿ qué pasará si de esos cincuenta justos faltan cinco ? ¿ Destruirás toda la ciudad por esos cinco ?” “ Si encuentro allí cuarenta y cinco , no la destruiré ”, respondió él .',NULL),
(@vid,@bid,18,29,'Abraham insistió: “¿ Y si sólo se encuentran cuarenta?” “ Por amor a esos cuarenta, no lo haré ”, respondió él .',NULL),
(@vid,@bid,18,30,'Abraham volvió a decirle: “Por favor, que no se enoje mi Señor si sigo hablando . ¿ Qué pasará si sólo se encuentran treinta ?” “ Si encuentro treinta , tampoco lo haré ”, contestó.',NULL),
(@vid,@bid,18,31,'Abraham dijo : “Me he atrevido a hablarle a mi Señor. ¿ Y si se encuentran veinte ?” “ Por amor a esos veinte , no la destruiré ”, le respondió.',NULL),
(@vid,@bid,18,32,'Finalmente Abraham dijo : “Le ruego a mi Señor que no se enoje, y hablaré sólo una vez más . ¿ Y si sólo se encuentran diez ?” “ Por amor a esos diez , no la destruiré ”, contestó él.',NULL),
(@vid,@bid,18,33,'El Señor se fue en cuanto terminó de hablar con Abraham, y éste volvió a su lugar .',NULL),
(@vid,@bid,19,1,'Los dos ángeles llegaron a Sodoma al anochecer. Lot estaba sentado a la puerta de la ciudad. Al verlos, Lot se levantó a recibirlos, se inclinó hasta tocar el suelo con la frente ,',NULL),
(@vid,@bid,19,2,'y les dijo: “ Por favor, señores míos, vengan a la casa de este servidor suyo para pasar la noche y lavarse los pies ; mañana podrán levantarse temprano y seguir su camino ”. “ No respondieron ellos, pasaremos la noche en la plaza”.',NULL),
(@vid,@bid,19,3,'Pero Lot les insistió tanto que fueron con él y entraron en su casa . Allí les preparó una gran cena, horneó pan sin levadura, y ellos comieron.',NULL),
(@vid,@bid,19,4,'Aún no se habían acostado cuando los hombres de la ciudad , los hombres de Sodoma , rodearon la casa . Todo el pueblo , desde los más jóvenes hasta los más viejos , estaba allí.',NULL),
(@vid,@bid,19,5,'Llamaron a Lot y le dijeron: “¿Dónde están los hombres que entraron en tu casa esta noche ? ¡Sácalos, para que tengamos relaciones con ellos!”',NULL),
(@vid,@bid,19,6,'Lot salió a la puerta y, cerrándola detrás de sí,',NULL),
(@vid,@bid,19,7,'les dijo: “Por favor, hermanos míos, no cometan semejante maldad.',NULL),
(@vid,@bid,19,8,'Miren, tengo dos hijas que todavía son vírgenes. Voy a sacarlas para que hagan con ellas lo que quieran. Pero a estos hombres no les hagan nada , porque son mis invitados y están bajo mi protección”.',NULL),
(@vid,@bid,19,9,'“¡Hazte a un lado!” le gritaron. Y añadieron: “Éste no es más que un extranjero entre nosotros, ¡y ahora resulta que quiere ser nuestro juez ! Pues ahora te trataremos a ti peor que a ellos ”. Entonces se abalanzaron sobre Lot y se acercaron para derribar la puerta .',NULL),
(@vid,@bid,19,10,'Pero los hombres que estaban adentro extendieron los brazos, metieron a Lot en la casa y cerraron la puerta .',NULL),
(@vid,@bid,19,11,'Luego , a los hombres que estaban a la puerta de la casa , desde el más joven hasta el más viejo, los hirieron con ceguera, de modo que se cansaron de buscar la puerta .',NULL),
(@vid,@bid,19,12,'Entonces los dos visitantes le dijeron a Lot : “¿ Tienes a alguien más aquí ? Saca de este lugar a tus yernos , hijos , hijas y a todos los que tengas en la ciudad ,',NULL),
(@vid,@bid,19,13,'porque vamos a destruir este lugar . El clamor contra esta gente ha llegado hasta Yahvé, y él nos ha enviado a destruirlos ”.',NULL),
(@vid,@bid,19,14,'Lot salió y habló con sus futuros yernos , los que iban a casarse con sus hijas , y les dijo : “¡ Levántense y salgan de este lugar , porque Yahvé va a destruir la ciudad !” Pero sus yernos pensaron que estaba bromeando.',NULL),
(@vid,@bid,19,15,'Al amanecer, los ángeles apresuraron a Lot , diciéndole: “¡ Levántate ! Llévate a tu esposa y a tus dos hijas que están aquí, para que no mueran cuando la ciudad sea castigada”.',NULL),
(@vid,@bid,19,16,'Como Lot se demoraba, los hombres lo tomaron de la mano , lo mismo que a su esposa y a sus dos hijas , y los sacaron de la ciudad , porque Yahvé tuvo compasión de él .',NULL),
(@vid,@bid,19,17,'Una vez fuera de la ciudad, uno de los ángeles le dijo: “¡Huye para salvar tu vida ! No mires hacia atrás, ni te detengas en ninguna parte del valle. ¡Huye a las montañas, no sea que mueras!”',NULL),
(@vid,@bid,19,18,'Pero Lot les respondió: “¡No, por favor, señor mío!',NULL),
(@vid,@bid,19,19,'Tu servidor ha hallado gracia a tus ojos , y me has mostrado una gran bondad al salvarme la vida . Pero no puedo huir a las montañas; la desgracia me alcanzaría y moriría.',NULL),
(@vid,@bid,19,20,'Mira , aquí cerca hay una ciudad pequeña a la que puedo huir. ¡Déjame escapar allá y salvaré mi vida ! ¡Al fin y al cabo es una ciudad muy pequeña !”',NULL),
(@vid,@bid,19,21,'El ángel le contestó: “ Está bien, te concedo también esta petición: no destruiré la ciudad de la que hablas.',NULL),
(@vid,@bid,19,22,'¡ Pero date prisa, huye allá ! No puedo hacer nada hasta que llegues”. Por eso la ciudad recibió el nombre de Zoar .',NULL),
(@vid,@bid,19,23,'El sol ya había salido cuando Lot llegó a Zoar .',NULL),
(@vid,@bid,19,24,'Entonces Yahvé hizo llover desde el cielo fuego y azufre sobre Sodoma y Gomorra .',NULL),
(@vid,@bid,19,25,'Destruyó esas ciudades y todo el valle, junto con todos sus habitantes y la vegetación de la tierra.',NULL),
(@vid,@bid,19,26,'Pero la esposa de Lot miró hacia atrás, a espaldas de él, y se convirtió en una estatua de sal .',NULL),
(@vid,@bid,19,27,'A la mañana siguiente, Abraham se levantó muy temprano y fue al lugar donde había estado delante de Yahvé.',NULL),
(@vid,@bid,19,28,'Miró hacia Sodoma y Gomorra , y hacia todo el valle, y vio que de la tierra subía un humo muy denso, como el de un horno.',NULL),
(@vid,@bid,19,29,'Así que , cuando Dios destruyó las ciudades del valle donde vivía Lot , se acordó de Abraham y sacó a Lot de la destrucción.',NULL),
(@vid,@bid,19,30,'Lot tenía miedo de quedarse a vivir en Zoar ; por eso se fue a la montaña y se instaló en una cueva con sus dos hijas .',NULL),
(@vid,@bid,19,31,'Un día, la hija mayor le dijo a la menor : “Nuestro padre ya está viejo , y no queda ningún hombre en esta región para que se case con nosotras, como es la costumbre en todo el mundo.',NULL),
(@vid,@bid,19,32,'Ven , emborrachémoslo con vino y acostémonos con él , para que podamos conservar la descendencia de nuestro padre”.',NULL),
(@vid,@bid,19,33,'Esa misma noche le dieron a beber vino a su padre, y la hija mayor entró y se acostó con él . Pero él no se dio cuenta ni cuando ella se acostó ni cuando se levantó .',NULL),
(@vid,@bid,19,34,'Al día siguiente , la mayor le dijo a la menor : “Ayer por la noche yo me acosté con mi padre. Vamos a darle vino también esta noche ; luego entras tú y te acuestas con él . Así conservaremos la descendencia de nuestro padre”.',NULL),
(@vid,@bid,19,35,'Esa noche también le dieron a beber vino a su padre, y la menor entró y se acostó con él . Igual que la vez anterior, él no se dio cuenta ni cuando ella se acostó ni cuando se levantó .',NULL),
(@vid,@bid,19,36,'De este modo, las dos hijas de Lot quedaron embarazadas de su propio padre.',NULL),
(@vid,@bid,19,37,'La mayor tuvo un hijo , y lo llamó Moab . Éste es el antepasado de los actuales moabitas.',NULL),
(@vid,@bid,19,38,'La menor también tuvo un hijo , y lo llamó Ben Amí. Éste es el antepasado de los actuales amonitas.',NULL),
(@vid,@bid,20,1,'Abraham viajó desde allí hacia la región del Néguev, y se estableció entre Cades y Shur . Mientras vivía como extranjero en Gerar ,',NULL),
(@vid,@bid,20,2,'Abraham decía que su esposa Sara era su hermana. Entonces Abimelec, rey de Gerar , mandó a buscar a Sara y se la llevó .',NULL),
(@vid,@bid,20,3,'Pero Dios se le apareció a Abimelec en un sueño nocturno y le dijo: “Date por muerto a causa de la mujer que has tomado , porque es una mujer casada ”.',NULL),
(@vid,@bid,20,4,'Como Abimelec todavía no la había tocado, le respondió: “Señor, ¿acaso destruirías a una nación inocente?',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,20,5,'¿ No me dijo él mismo : ‘ Es mi hermana’? Y ella también afirmó: ‘ Es mi hermano’. Yo he hecho esto con buenas intenciones y con las manos limpias”.',NULL),
(@vid,@bid,20,6,'Dios le respondió en el sueño : “ Sí , yo sé que has actuado con buenas intenciones. Por eso yo mismo te impedí pecar contra mí y no te permití que la tocaras.',NULL),
(@vid,@bid,20,7,'Pero ahora , devuélvele su esposa a ese hombre. Él es profeta y orará por ti para que vivas. Pero si no se la devuelves, ten por seguro que morirás , tú y todos los tuyos”.',NULL),
(@vid,@bid,20,8,'Al día siguiente, Abimelec se levantó muy temprano, llamó a todos sus servidores y les contó todo lo que había pasado. Al oírlo, los hombres se llenaron de miedo .',NULL),
(@vid,@bid,20,9,'Luego Abimelec mandó llamar a Abraham y le reclamó: “¿ Qué nos has hecho ? ¿ En qué te he ofendido, para que hayas traído un pecado tan grande sobre mí y sobre mi reino ? ¡ Me has hecho cosas que no se le hacen a nadie !”',NULL),
(@vid,@bid,20,10,'Y añadió Abimelec: “¿ Qué pretendías al hacer esto ?”',NULL),
(@vid,@bid,20,11,'Abraham le respondió: “ Es que yo pensé: ‘Seguramente en este lugar no hay temor de Dios, y me matarán por causa de mi esposa’.',NULL),
(@vid,@bid,20,12,'Además , ella es en verdad mi hermana, pues es hija de mi padre, aunque no de mi madre; y llegó a ser mi esposa.',NULL),
(@vid,@bid,20,13,'Cuando Dios me hizo salir de la casa de mi padre para andar errante, yo le dije a ella : ‘ Hazme este favor: en cualquier lugar adonde vayamos, di siempre que soy tu hermano’”.',NULL),
(@vid,@bid,20,14,'Entonces Abimelec tomó ovejas y vacas , esclavos y esclavas, y se los regaló a Abraham; además, le devolvió a su esposa Sara .',NULL),
(@vid,@bid,20,15,'Y le dijo Abimelec: “ Mi tierra está a tu disposición; quédate a vivir donde más te guste”.',NULL),
(@vid,@bid,20,16,'A Sara le dijo: “ Mira , le he entregado a tu hermano mil monedas de plata . Esto servirá como compensación para ti ante todos los que están contigo; así quedarás libre de toda culpa”.',NULL),
(@vid,@bid,20,17,'Entonces Abraham oró a Dios, y Dios sanó a Abimelec, a su esposa y a sus esclavas, para que pudieran tener hijos,',NULL),
(@vid,@bid,20,18,'porque a causa de Sara , la esposa de Abraham, Yahvé había dejado estériles a todas las mujeres de la casa de Abimelec.',NULL),
(@vid,@bid,21,1,'Yahvé visitó a Sara tal como lo había dicho , y cumplió Yahvé su promesa con ella.',NULL),
(@vid,@bid,21,2,'Sara quedó embarazada y le dio un hijo a Abraham en su vejez, en el tiempo exacto que Dios le había indicado.',NULL),
(@vid,@bid,21,3,'Al hijo que Sara le dio, Abraham le puso por nombre Isaac .',NULL),
(@vid,@bid,21,4,'Y a los ocho días de nacido, Abraham circuncidó a su hijo Isaac , tal como Dios se lo había ordenado .',NULL),
(@vid,@bid,21,5,'Abraham tenía ya cien años cuando nació su hijo Isaac .',NULL),
(@vid,@bid,21,6,'Sara exclamó: “Dios me ha hecho reír, y todos los que se enteren se reirán conmigo ”.',NULL),
(@vid,@bid,21,7,'Y añadió: “¿ Quién le hubiera dicho a Abraham que Sara amamantaría hijos ? Sin embargo, le he dado un hijo en su vejez”.',NULL),
(@vid,@bid,21,8,'El niño creció y fue destetado. Ese mismo día , Abraham hizo una gran fiesta.',NULL),
(@vid,@bid,21,9,'Pero Sara vio que el hijo que Agar la egipcia le había dado a Abraham se burlaba de Isaac.',NULL),
(@vid,@bid,21,10,'Entonces le dijo a Abraham: “¡ Echa de aquí a esa esclava y a su hijo ! El hijo de esa esclava jamás compartirá la herencia con mi hijo Isaac ”.',NULL),
(@vid,@bid,21,11,'Esto le dolió muchísimo a Abraham, porque se trataba de su propio hijo .',NULL),
(@vid,@bid,21,12,'Pero Dios le dijo a Abraham: “ No te angusties por el muchacho ni por tu esclava. Hazle caso a Sara en todo lo que te pida, porque tu descendencia se establecerá por medio de Isaac .',NULL),
(@vid,@bid,21,13,'Pero también del hijo de la esclava haré una gran nación , porque él también es descendiente tuyo”.',NULL),
(@vid,@bid,21,14,'A la mañana siguiente, Abraham se levantó muy temprano, tomó pan y un odre de agua , y se los dio a Agar , poniéndoselos sobre el hombro . Luego le entregó al muchacho y la despidió . Agar se fue y anduvo vagando por el desierto de Beerseba.',NULL),
(@vid,@bid,21,15,'Cuando se le acabó el agua del odre , dejó al muchacho debajo de un matorral',NULL),
(@vid,@bid,21,16,'y se fue a sentar a cierta distancia, a la distancia de un tiro de arco , pues se decía: “ No quiero ver morir al muchacho”. Y mientras estaba allí sentada, comenzó a llorar a gritos.',NULL),
(@vid,@bid,21,17,'Pero Dios escuchó los sollozos del muchacho , y el ángel de Dios llamó a Agar desde el cielo y le dijo: “¿ Qué te pasa, Agar ? No tengas miedo , porque Dios ha escuchado los sollozos del muchacho allí donde está .',NULL),
(@vid,@bid,21,18,'¡ Levántate ! Toma al muchacho y tómalo de la mano , porque haré de él una gran nación ”.',NULL),
(@vid,@bid,21,19,'Entonces Dios le abrió los ojos , y ella vio un pozo de agua . Fue y llenó el odre de agua y le dio de beber al muchacho .',NULL),
(@vid,@bid,21,20,'Dios acompañó al muchacho , el cual creció , vivió en el desierto y se convirtió en un gran arquero.',NULL),
(@vid,@bid,21,21,'Vivió en el desierto de Parán , y su madre le consiguió una esposa de la tierra de Egipto .',NULL),
(@vid,@bid,21,22,'En aquel tiempo , Abimelec y Ficol, jefe de su ejército , le dijeron a Abraham: “Dios está contigo en todo lo que haces .',NULL),
(@vid,@bid,21,23,'Así que júrame ahora mismo, por Dios, que no me engañarás a mí, ni a mis hijos, ni a mis nietos. Júrame que así como yo te he tratado con bondad, tú también nos tratarás a mí y a este país donde has vivido como extranjero”.',NULL),
(@vid,@bid,21,24,'Abraham le respondió: “Te lo juro ”.',NULL),
(@vid,@bid,21,25,'Pero Abraham le reclamó a Abimelec por un pozo de agua que los siervos de Abimelec le habían quitado por la fuerza.',NULL),
(@vid,@bid,21,26,'Abimelec contestó: “ No sé quién pudo haber hecho esto . Tú no me lo habías informado, y yo me vengo a enterar apenas hoy ”.',NULL),
(@vid,@bid,21,27,'Entonces Abraham tomó ovejas y vacas , y se las dio a Abimelec, y los dos hicieron un pacto .',NULL),
(@vid,@bid,21,28,'Luego Abraham apartó siete corderas de su rebaño ,',NULL),
(@vid,@bid,21,29,'y Abimelec le preguntó: “¿ Qué significan estas siete corderas que has puesto aparte?”',NULL),
(@vid,@bid,21,30,'Abraham respondió: “Aceptarás estas siete corderas de mis manos como prueba de que yo mismo cavé este pozo”.',NULL),
(@vid,@bid,21,31,'Por eso a ese lugar se le llamó Beerseba, porque allí ambos hicieron un juramento.',NULL),
(@vid,@bid,21,32,'Después de hacer este pacto en Beerseba, Abimelec y Ficol, jefe de su ejército , regresaron a la tierra de los filisteos .',NULL),
(@vid,@bid,21,33,'Abraham plantó un árbol de tamarisco en Beerseba, y allí invocó el nombre de Yahvé, el Dios eterno .',NULL),
(@vid,@bid,21,34,'Y Abraham vivió mucho tiempo como extranjero en la tierra de los filisteos .',NULL),
(@vid,@bid,22,1,'Pasado algún tiempo, Dios puso a prueba a Abraham y le dijo: “¡Abraham!” “ Aquí estoy ”, respondió él.',NULL),
(@vid,@bid,22,2,'Y Dios le dijo: “ Toma ahora a tu hijo , a tu único hijo , Isaac , a quien tanto amas, y vete a la región de Moriah. Allí me lo ofrecerás en holocausto sobre la montaña que yo te indicaré”.',NULL),
(@vid,@bid,22,3,'Abraham se levantó de madrugada, ensilló su burro y se llevó consigo a dos de sus muchachos y a su hijo Isaac . Cortó leña para el holocausto y emprendió el viaje hacia el lugar que Dios le había indicado.',NULL),
(@vid,@bid,22,4,'Al tercer día , Abraham levantó la vista y vio el lugar a lo lejos .',NULL),
(@vid,@bid,22,5,'Entonces les dijo a sus muchachos: “Quédense aquí con el burro. El muchacho y yo seguiremos hasta allá. Adoraremos a Dios y luego regresaremos con ustedes”.',NULL),
(@vid,@bid,22,6,'Abraham tomó la leña para el holocausto y la puso sobre los hombros de su hijo Isaac ; él , por su parte, llevó el fuego y el cuchillo. Y los dos siguieron caminando juntos .',NULL),
(@vid,@bid,22,7,'De pronto, Isaac le dijo a su padre Abraham: “¿Padre mío?” “ Aquí estoy, hijo mío”, le respondió. “ Aquí tenemos el fuego y la leña dijo Isaac , pero ¿dónde está el cordero para el holocausto ?”',NULL),
(@vid,@bid,22,8,'Abraham le respondió: “Dios mismo proveerá el cordero para el holocausto , hijo mío”. Y continuaron caminando juntos .',NULL),
(@vid,@bid,22,9,'Cuando llegaron al lugar que Dios le había indicado, Abraham construyó un altar y acomodó la leña . Luego ató a su hijo Isaac y lo puso sobre el altar , encima de la leña .',NULL),
(@vid,@bid,22,10,'Entonces extendió la mano y tomó el cuchillo para sacrificar a su hijo .',NULL),
(@vid,@bid,22,11,'Pero el ángel de Yahvé lo llamó desde el cielo : “¡Abraham, Abraham!” “ Aquí estoy”, respondió él.',NULL),
(@vid,@bid,22,12,'“ No pongas tu mano sobre el muchacho ni le hagas ningún daño”, le dijo el ángel. “ Ahora sé que temes a Dios, porque no me has negado a tu hijo , tu único hijo ”.',NULL),
(@vid,@bid,22,13,'Abraham levantó la vista y vio a sus espaldas un carnero enredado por los cuernos en un matorral. Entonces fue , tomó el carnero y lo ofreció en holocausto en lugar de su hijo .',NULL),
(@vid,@bid,22,14,'Por eso Abraham llamó a aquel lugar “Yahvé proveerá ”. De allí viene el dicho de hoy : “En la montaña de Yahvé se proveerá ”.',NULL),
(@vid,@bid,22,15,'El ángel de Yahvé llamó a Abraham por segunda vez desde el cielo',NULL),
(@vid,@bid,22,16,'y le dijo : “He jurado por mí mismo, afirma Yahvé, que por haber hecho esto y no haberme negado a tu hijo , tu único hijo ,',NULL),
(@vid,@bid,22,17,'te bendeciré en gran manera . Multiplicaré tu descendencia como las estrellas del cielo y como la arena de la orilla del mar . Tu descendencia conquistará las ciudades de sus enemigos,',NULL),
(@vid,@bid,22,18,'y por medio de tu descendencia serán bendecidas todas las naciones de la tierra, porque has obedecido mi voz ”.',NULL),
(@vid,@bid,22,19,'Después de esto, Abraham regresó a donde estaban sus muchachos, y juntos partieron hacia Beerseba. Y Abraham se quedó a vivir en Beerseba.',NULL),
(@vid,@bid,22,20,'Pasado algún tiempo, le informaron a Abraham: “Tu cuñada Milca también le ha dado hijos a tu hermano Nacor:',NULL),
(@vid,@bid,22,21,'Uz el primogénito , Buz su hermano, Kemuel el padre de Aram,',NULL),
(@vid,@bid,22,22,'Quésed, Jazó, Pildás, Jidlaf y Betuel”.',NULL),
(@vid,@bid,22,23,'Y Betuel fue el padre de Rebeca . Estos ocho hijos le dio Milca a Nacor, el hermano de Abraham.',NULL),
(@vid,@bid,22,24,'Además , la concubina de Nacor, que se llamaba Reúma , le dio a luz a Tébah, Gaham, Tahas y Maaca.',NULL),
(@vid,@bid,23,1,'Sara vivió ciento veintisiete años ; esa fue la duración de su vida .',NULL),
(@vid,@bid,23,2,'Murió en Quiriat Arba ( es decir, en Hebrón ), en la tierra de Canaán . Y Abraham hizo duelo por Sara y la lloró .',NULL),
(@vid,@bid,23,3,'Luego Abraham se levantó de donde estaba el cuerpo de su esposa, y fue a hablar con los hititas, diciéndoles:',NULL),
(@vid,@bid,23,4,'“Yo no soy más que un extranjero de paso entre ustedes. Véndanme una propiedad para tener un lugar propio donde sepultar a mi esposa”.',NULL),
(@vid,@bid,23,5,'Los hititas le respondieron a Abraham:',NULL),
(@vid,@bid,23,6,'“Escúchenos, señor nuestro. Usted es un príncipe de Dios entre nosotros. Sepulte a su esposa en la mejor de nuestras tumbas. Ninguno de nosotros le negará su tumba para que sepulte a su esposa”.',NULL),
(@vid,@bid,23,7,'Abraham se levantó , se inclinó ante los hititas, que eran los habitantes del lugar,',NULL),
(@vid,@bid,23,8,'y les dijo : “ Si de veras están de acuerdo en que yo sepulte aquí a mi esposa, escúchenme y pídanle de mi parte a Efrón, el hijo de Zojar,',NULL),
(@vid,@bid,23,9,'que me venda la cueva de Macpela que le pertenece, la cual está en el extremo de su campo . Que me la venda por su precio exacto, para tener entre ustedes un lugar propio para sepulturas”.',NULL),
(@vid,@bid,23,10,'Efrón el hitita estaba sentado entre su gente, y le respondió a Abraham para que lo escucharan todos los que entraban por la puerta de la ciudad :',NULL),
(@vid,@bid,23,11,'“ No , señor mío , escúcheme bien . Yo le regalo el campo , y también le regalo la cueva que está en él . Se lo doy en presencia de mi pueblo . Sepulte a su esposa”.',NULL),
(@vid,@bid,23,12,'Abraham volvió a inclinarse ante la gente del lugar,',NULL),
(@vid,@bid,23,13,'y a la vista de todos ellos le dijo a Efrón: “ Por favor, escúcheme usted a mí. Le pagaré el precio del campo . Acéptelo, para que yo pueda sepultar allí a mi esposa”.',NULL),
(@vid,@bid,23,14,'Efrón le contestó a Abraham:',NULL),
(@vid,@bid,23,15,'“Señor mío, escúcheme: un terreno que vale cuatrocientas monedas de plata , ¿ qué significa entre usted y yo? Sepulte a su esposa”.',NULL),
(@vid,@bid,23,16,'Abraham aceptó la propuesta de Efrón, y a la vista de los hititas le pesó la cantidad de plata que Efrón había mencionado: cuatrocientas monedas de plata , de acuerdo con el peso de los comerciantes de la época.',NULL),
(@vid,@bid,23,17,'Fue así como el campo de Efrón en Macpela, frente a Mamre , es decir, el campo con la cueva y con todos los árboles que había dentro de sus límites,',NULL),
(@vid,@bid,23,18,'pasó a ser propiedad de Abraham, a la vista de los hititas y de todos los que entraban por la puerta de la ciudad .',NULL),
(@vid,@bid,23,19,'Después de esto , Abraham sepultó a su esposa Sara en la cueva del campo de Macpela, frente a Mamre ( es decir, Hebrón ), en la tierra de Canaán .',NULL),
(@vid,@bid,23,20,'Así fue como los hititas le cedieron a Abraham el campo y la cueva , como propiedad para sepultura .',NULL),
(@vid,@bid,24,1,'Abraham ya era viejo , de edad muy avanzada, y Yahvé lo había bendecido en todo .',NULL),
(@vid,@bid,24,2,'Un día, Abraham le dijo al sirviente más viejo de su casa , el que administraba todos sus bienes: “ Por favor, pon tu mano debajo de mi muslo',NULL),
(@vid,@bid,24,3,'y júrame por Yahvé, Dios del cielo y de la tierra, que no buscarás una esposa para mi hijo entre las hijas de los cananeos , con los cuales vivo.',NULL),
(@vid,@bid,24,4,'Júrame que irás a mi tierra, a mi propia familia, y de allí buscarás una esposa para mi hijo Isaac ”.',NULL),
(@vid,@bid,24,5,'El sirviente le preguntó: “¿ Y qué pasa si la mujer no quiere venir conmigo a esta tierra? ¿Debo llevar a tu hijo a la tierra de donde saliste ?”',NULL),
(@vid,@bid,24,6,'Abraham le advirtió: “¡Cuidado con llevar allá a mi hijo !',NULL),
(@vid,@bid,24,7,'Yahvé, el Dios del cielo , que me sacó de la casa de mi padre y de la tierra de mis familiares, me prometió y me juró : ‘ A tu descendencia le daré esta tierra’. Él enviará a su ángel delante de ti para que puedas traer de allá una esposa para mi hijo .',NULL),
(@vid,@bid,24,8,'Si la mujer no quiere seguirte, quedarás libre de este juramento . Pero por ningún motivo lleves allá a mi hijo ”.',NULL),
(@vid,@bid,24,9,'Entonces el sirviente puso su mano debajo del muslo de su amo Abraham, y le juró cumplir con este encargo.',NULL),
(@vid,@bid,24,10,'Luego tomó diez de los camellos de su amo, cargó toda clase de regalos valiosos de su amo, y se puso en camino hacia Aram Naharaim, la ciudad de Nacor.',NULL),
(@vid,@bid,24,11,'Hacia el atardecer, a la hora en que las mujeres salen a sacar agua , el sirviente hizo arrodillar a los camellos fuera de la ciudad , junto al pozo de agua .',NULL),
(@vid,@bid,24,12,'Y oró: “Yahvé, Dios de mi amo Abraham, te ruego que me concedas el éxito hoy y que le muestres bondad a mi amo Abraham.',NULL),
(@vid,@bid,24,13,'Aquí estoy , junto a este manantial, mientras las muchachas de la ciudad salen a sacar agua .',NULL),
(@vid,@bid,24,14,'Yo le diré a una de las muchachas: ‘ Por favor, baja tu cántaro para que yo beba’. Si ella me responde: ‘ Bebe , y también les daré de beber a tus camellos ’, que sea ella la que tú has elegido para tu siervo Isaac . Así sabré que has sido bondadoso con mi amo”.',NULL),
(@vid,@bid,24,15,'Aún no había terminado de orar, cuando vio que se acercaba Rebeca con su cántaro al hombro . Ella era hija de Betuel, el hijo de Milca y de Nacor, el hermano de Abraham.',NULL),
(@vid,@bid,24,16,'La joven era muy hermosa ; era virgen , ningún hombre la había tocado. Bajó hasta el manantial, llenó su cántaro y volvió a subir .',NULL),
(@vid,@bid,24,17,'El sirviente corrió a su encuentro y le dijo: “Por favor, dame a beber un poco de agua de tu cántaro ”.',NULL),
(@vid,@bid,24,18,'“Beba usted, señor mío ” respondió ella . Enseguida bajó su cántaro y se lo dio a beber .',NULL),
(@vid,@bid,24,19,'Cuando él terminó de beber , ella le dijo: “Ahora voy a sacar agua para sus camellos , hasta que terminen de beber ”.',NULL),
(@vid,@bid,24,20,'Rápidamente vació su cántaro en el bebedero y corrió de nuevo al pozo para sacar más agua, y les dio de beber a todos los camellos .',NULL),
(@vid,@bid,24,21,'El hombre la observaba en silencio, maravillado, tratando de saber si Yahvé había coronado con el éxito su viaje o no .',NULL),
(@vid,@bid,24,22,'Cuando los camellos terminaron de beber , el hombre tomó un anillo de oro que pesaba como seis gramos, y se lo puso a ella en la nariz. También le puso en los brazos dos pulseras de oro que pesaban más de cien gramos,',NULL),
(@vid,@bid,24,23,'y le preguntó: “Por favor, dime: ¿de quién eres hija ? ¿ Habrá lugar en la casa de tu padre para que mis hombres y yo pasemos la noche?”',NULL),
(@vid,@bid,24,24,'Ella le respondió: “Soy hija de Betuel, el hijo que Milca le dio a Nacor”.',NULL),
(@vid,@bid,24,25,'Y añadió: “Tenemos mucha paja y forraje , y también hay lugar para que pasen la noche”.',NULL),
(@vid,@bid,24,26,'Entonces el hombre se inclinó y adoró a Yahvé,',NULL),
(@vid,@bid,24,27,'diciendo: “¡ Bendito sea Yahvé, el Dios de mi amo Abraham, que no le ha negado su bondad y su verdad a mi amo! Yahvé me ha guiado en el camino hasta la casa de los familiares de mi amo”.',NULL),
(@vid,@bid,24,28,'La joven corrió a la casa de su madre para contar todo esto .',NULL),
(@vid,@bid,24,29,'Rebeca tenía un hermano llamado Labán , el cual salió corriendo hacia el manantial para encontrarse con el hombre.',NULL),
(@vid,@bid,24,30,'Cuando Labán vio el anillo en la nariz de su hermana y las pulseras en sus brazos, y escuchó que Rebeca decía: “ Así me habló aquel hombre”, fue a buscarlo. Lo encontró todavía de pie , junto a los camellos , cerca del manantial.',NULL),
(@vid,@bid,24,31,'Y le dijo: “¡Pase usted, bendito de Yahvé! ¿ Por qué se queda ahí afuera ? Ya he preparado la casa y un lugar para los camellos ”.',NULL),
(@vid,@bid,24,32,'Entonces el hombre entró en la casa . Labán descargó los camellos y les dio paja y forraje , y luego trajo agua para que el hombre y sus acompañantes se lavaran los pies .',NULL),
(@vid,@bid,24,33,'Le sirvieron comida, pero él dijo : “ No comeré hasta que haya dicho lo que tengo que decir”. “ Hable usted” le contestó Labán.',NULL),
(@vid,@bid,24,34,'Entonces el hombre dijo: “Soy sirviente de Abraham.',NULL),
(@vid,@bid,24,35,'Yahvé ha bendecido mucho a mi amo y lo ha hecho muy rico. Le ha dado ovejas y vacas , plata y oro , esclavos y esclavas, camellos y burros.',NULL),
(@vid,@bid,24,36,'Sara , la esposa de mi amo, le dio un hijo en su vejez, y mi amo le ha dejado a ese hijo todo lo que tiene.',NULL),
(@vid,@bid,24,37,'Además, mi amo me hizo jurar, diciendo: ‘ No buscarás una esposa para mi hijo entre las hijas de los cananeos , en cuya tierra vivo.',NULL),
(@vid,@bid,24,38,'Tienes que ir a la casa de mi padre y a mi propia familia , y de allí buscarás una esposa para mi hijo ’.',NULL),
(@vid,@bid,24,39,'Yo le pregunté a mi amo: ‘¿ Y si la mujer no quiere venir conmigo?’',NULL),
(@vid,@bid,24,40,'Pero él me respondió: ‘Yahvé, en cuya presencia he vivido, enviará su ángel contigo y hará que tu viaje sea un éxito. Así podrás traerle a mi hijo una esposa de mi propia familia , de la casa de mi padre.',NULL),
(@vid,@bid,24,41,'Sólo quedarás libre del juramento que me has hecho si llegas a mi familia y ellos no te la quieren dar . En ese caso, quedarás libre de mi juramento’.',NULL),
(@vid,@bid,24,42,'Hoy , cuando llegué al manantial, oré así: ‘Yahvé, Dios de mi amo Abraham, te ruego que corones con el éxito el viaje que he emprendido.',NULL),
(@vid,@bid,24,43,'Aquí estoy , junto a este manantial. Si una muchacha viene a sacar agua , yo le diré: “ Por favor, dame a beber un poco de agua de tu cántaro ”.',NULL),
(@vid,@bid,24,44,'Si ella me responde: “Beba usted, y también sacaré agua para sus camellos ”, que sea ella la mujer que Yahvé ha elegido para el hijo de mi amo’.',NULL),
(@vid,@bid,24,45,'Todavía no terminaba yo de orar en mi corazón , cuando vi a Rebeca que venía con su cántaro al hombro . Bajó al manantial y sacó agua. Entonces le pedí: ‘ Por favor, dame de beber ’.',NULL),
(@vid,@bid,24,46,'Ella enseguida bajó su cántaro del hombro y me dijo: ‘Beba usted, y también les daré de beber a sus camellos ’. Así que yo bebí , y ella también les dio agua a los camellos .',NULL),
(@vid,@bid,24,47,'Luego le pregunté : ‘¿ De quién eres hija ?’ Ella me respondió: ‘Soy hija de Betuel, el hijo que Milca le dio a Nacor’. Entonces le puse el anillo en la nariz y las pulseras en los brazos.',NULL),
(@vid,@bid,24,48,'Y me incliné y adoré a Yahvé, y bendije a Yahvé, el Dios de mi amo Abraham, que me había guiado por el camino correcto para llevarle al hijo de mi amo la hija de su hermano.',NULL),
(@vid,@bid,24,49,'Ahora bien, si ustedes están dispuestos a tratar a mi amo con bondad y lealtad, díganmelo; y si no , díganmelo también, para que yo sepa qué camino tomar”.',NULL),
(@vid,@bid,24,50,'Labán y Betuel respondieron : “ Esto viene de Yahvé; no podemos decirle a usted que sí ni que no .',NULL),
(@vid,@bid,24,51,'Aquí tiene a Rebeca ; llévesela, y que sea la esposa del hijo de su amo, tal como Yahvé lo ha dispuesto”.',NULL),
(@vid,@bid,24,52,'Al oír esto , el sirviente de Abraham se inclinó hasta el suelo para adorar a Yahvé.',NULL),
(@vid,@bid,24,53,'Luego sacó joyas de oro y de plata , y vestidos, y se los regaló a Rebeca . También les dio valiosos regalos a su hermano y a su madre.',NULL),
(@vid,@bid,24,54,'Después comieron y bebieron , él y los hombres que lo acompañaban, y pasaron la noche allí. Al levantarse por la mañana , el sirviente les dijo: “Déjenme regresar a la casa de mi amo”.',NULL),
(@vid,@bid,24,55,'Pero el hermano y la madre de la muchacha respondieron: “ Que la joven se quede con nosotros unos diez días más, y después se podrá ir ”.',NULL),
(@vid,@bid,24,56,'“ No me detengan es contestó él, ya que Yahvé ha coronado con el éxito mi viaje . Déjenme ir para que vuelva a la casa de mi amo”.',NULL),
(@vid,@bid,24,57,'“Llamaremos a la muchacha para ver qué opina ella” le dijeron.',NULL),
(@vid,@bid,24,58,'Así que llamaron a Rebeca y le preguntaron: “¿Quieres irte con este hombre?” “Sí, me iré con él ”, respondió ella.',NULL),
(@vid,@bid,24,59,'Entonces dejaron ir a su hermana Rebeca , junto con su nodriza, y al sirviente de Abraham y a sus hombres.',NULL),
(@vid,@bid,24,60,'Y bendijeron a Rebeca con estas palabras: “Hermana nuestra, ¡ que seas madre de millones! ¡ Que tus descendientes conquisten las ciudades de sus enemigos !”',NULL),
(@vid,@bid,24,61,'Rebeca y sus sirvientas se prepararon, montaron en los camellos y siguieron al hombre. Así fue como el sirviente tomó a Rebeca y emprendió el camino de regreso.',NULL),
(@vid,@bid,24,62,'Mientras tanto, Isaac había regresado del pozo del Viviente-que-me-ve, pues vivía en la región del Néguev.',NULL),
(@vid,@bid,24,63,'Al atardecer, Isaac salió a meditar al campo . Levantó la vista y vio que se acercaban unos camellos .',NULL),
(@vid,@bid,24,64,'También Rebeca levantó la vista, y al ver a Isaac se bajó del camello',NULL),
(@vid,@bid,24,65,'y le preguntó al sirviente: “¿ Quién es ese hombre que viene por el campo a nuestro encuentro?” “ Es mi amo” contestó el sirviente. Entonces ella tomó su velo y se cubrió el rostro.',NULL),
(@vid,@bid,24,66,'El sirviente le contó a Isaac todo lo que había hecho .',NULL),
(@vid,@bid,24,67,'Luego Isaac llevó a Rebeca a la tienda de su madre Sara , y la tomó por esposa. Isaac la amó mucho, y así se consoló tras la muerte de su madre.',NULL),
(@vid,@bid,25,1,'Abraham volvió a casarse. Su nueva esposa se llamaba Cetura,',NULL),
(@vid,@bid,25,2,'la cual le dio a luz a Zimrán, Jocsán , Medán , Madián , Isbac y Súa.',NULL),
(@vid,@bid,25,3,'Jocsán fue el padre de Seba y de Dedán . Los descendientes de Dedán fueron los asureos, los letuseos y los leumeos.',NULL),
(@vid,@bid,25,4,'Los hijos de Madián fueron Efá, Efer, Hanoc, Abida y Eldá. Todos ellos fueron descendientes de Cetura.',NULL),
(@vid,@bid,25,5,'Abraham le dejó todo lo que tenía a Isaac ,',NULL),
(@vid,@bid,25,6,'pero a los hijos que tuvo con sus concubinas les dio regalos mientras él aún vivía, y los envió hacia el oriente , lejos de su hijo Isaac .',NULL),
(@vid,@bid,25,7,'Abraham vivió en total ciento setenta y cinco años .',NULL),
(@vid,@bid,25,8,'Murió a una edad muy avanzada, anciano y satisfecho de la vida, y fue a reunirse con sus antepasados.',NULL),
(@vid,@bid,25,9,'Sus hijos Isaac e Ismael lo sepultaron en la cueva de Macpela, en el campo de Efrón, hijo de Zojar el hitita, que está al oriente de Mamre .',NULL),
(@vid,@bid,25,10,'Éste era el campo que Abraham les había comprado a los hititas. Allí fue sepultado Abraham, junto a su esposa Sara .',NULL),
(@vid,@bid,25,11,'Después de la muerte de Abraham, Dios bendijo a su hijo Isaac , quien se estableció cerca de Beer Lahai Roi.',NULL),
(@vid,@bid,25,12,'Ésta es la historia de Ismael , el hijo que Abraham tuvo con Agar la egipcia , la esclava de Sara .',NULL),
(@vid,@bid,25,13,'Éstos son los nombres de los hijos de Ismael , en orden de nacimiento: el primogénito fue Nebaiot; luego nacieron Cedar , Adbeel, Mibsam ,',NULL),
(@vid,@bid,25,14,'Mismá , Dumá , Masá,',NULL),
(@vid,@bid,25,15,'Hadad , Temá, Jetur , Nafis y Cedema.',NULL),
(@vid,@bid,25,16,'Éstos fueron los hijos de Ismael , y éstos son los nombres de sus poblados y campamentos . Fueron los doce jefes de sus respectivas tribus.',NULL),
(@vid,@bid,25,17,'Ismael vivió ciento treinta y siete años . Luego exhaló el último suspiro, murió y fue a reunirse con sus antepasados.',NULL),
(@vid,@bid,25,18,'Sus descendientes habitaron en la región que va desde Javilá hasta Shur , cerca de la frontera de Egipto , en dirección a Asiria. Ismael vivió en conflicto con todos sus parientes.',NULL),
(@vid,@bid,25,19,'Ésta es la historia de Isaac , el hijo de Abraham.',NULL),
(@vid,@bid,25,20,'Isaac tenía cuarenta años cuando se casó con Rebeca , que era hija de Betuel y hermana de Labán , los arameos de Padán Aram.',NULL),
(@vid,@bid,25,21,'Isaac oró a Yahvé en favor de su esposa, porque ella no podía tener hijos. Yahvé escuchó su oración, y Rebeca quedó embarazada .',NULL),
(@vid,@bid,25,22,'Pero como los niños luchaban dentro de su vientre, ella exclamó: “Si esto va a ser así , ¿para qué sigo viva?” Entonces fue a consultar a Yahvé,',NULL),
(@vid,@bid,25,23,'y Yahvé le contestó: “En tu vientre hay dos naciones , de tus entrañas saldrán dos pueblos divididos. Uno de los pueblos será más fuerte que el otro, y el mayor servirá al menor ”.',NULL),
(@vid,@bid,25,24,'Cuando llegó el momento de dar a luz, resultó que llevaba gemelos en el vientre.',NULL),
(@vid,@bid,25,25,'El primero en nacer era pelirrojo, y tenía el cuerpo tan cubierto de vello que parecía un abrigo de pieles; por eso le pusieron por nombre Esaú .',NULL),
(@vid,@bid,25,26,'Luego nació su hermano, agarrado del talón de Esaú con una mano ; por eso le pusieron por nombre Jacob . Isaac tenía sesenta años cuando nacieron .',NULL),
(@vid,@bid,25,27,'Los niños crecieron. Esaú se convirtió en un hábil cazador , un hombre de campo , mientras que Jacob era un hombre tranquilo que prefería quedarse en las tiendas.',NULL),
(@vid,@bid,25,28,'Isaac prefería a Esaú porque le gustaba comer de lo que él cazaba, pero Rebeca prefería a Jacob .',NULL),
(@vid,@bid,25,29,'Un día, Jacob estaba preparando un guiso. En eso llegó Esaú del campo , agotado por el hambre,',NULL),
(@vid,@bid,25,30,'y le dijo a Jacob : “ Por favor, dame un poco de ese guiso rojo, porque me muero de hambre”. Por eso a Esaú también se le conoció como Edom.',NULL),
(@vid,@bid,25,31,'Jacob le respondió: “Primero véndeme tus derechos de primogenitura”.',NULL),
(@vid,@bid,25,32,'Esaú dijo: “Me estoy muriendo de hambre, ¿de qué me sirven a mí los derechos de primogenitura?”',NULL),
(@vid,@bid,25,33,'Jacob insistió: “ Júramelo ahora mismo”. Esaú se lo juró , y de esa manera le vendió a Jacob sus derechos de primogenitura.',NULL),
(@vid,@bid,25,34,'Luego Jacob le dio a Esaú pan y guiso de lentejas . Esaú comió y bebió , luego se levantó y se fue . Así de poco le importaron a Esaú sus derechos de hijo mayor.',NULL),
(@vid,@bid,26,1,'Hubo otra época de hambre en la región, además de la primera que hubo en tiempos de Abraham. Por eso, Isaac se fue a Gerar , donde estaba Abimelec, rey de los filisteos .',NULL),
(@vid,@bid,26,2,'Allí Yahvé se le apareció y le dijo: “No bajes a Egipto . Quédate a vivir en la tierra que yo te indicaré.',NULL),
(@vid,@bid,26,3,'Quédate a vivir en esta tierra, y yo estaré contigo y te bendeciré . A ti y a tu descendencia les daré todas estas tierras, y así cumpliré el juramento que le hice a tu padre Abraham.',NULL),
(@vid,@bid,26,4,'Multiplicaré tu descendencia como las estrellas del cielo , y le daré todas estas tierras. Por medio de tu descendencia serán bendecidas todas las naciones de la tierra,',NULL),
(@vid,@bid,26,5,'porque Abraham me obedeció y cumplió mis preceptos, mis mandamientos , mis normas y mis leyes ”.',NULL),
(@vid,@bid,26,6,'Así que Isaac se quedó a vivir en Gerar .',NULL),
(@vid,@bid,26,7,'Cuando los hombres del lugar le preguntaban por su esposa, él respondía: “ Es mi hermana”. Tenía miedo de decir que era su esposa, pues pensaba: “ Los hombres de este lugar me matarán por causa de Rebeca , porque es muy hermosa ”.',NULL),
(@vid,@bid,26,8,'Isaac ya llevaba mucho tiempo allí cuando Abimelec, rey de los filisteos , se asomó a una ventana y lo vio acariciando a su esposa Rebeca .',NULL),
(@vid,@bid,26,9,'Abimelec mandó llamar a Isaac y le dijo: “¡ Así que ella es tu esposa! ¿ Por qué dijiste que era tu hermana?” Isaac le respondió: “ Porque pensé que me matarían por su culpa”.',NULL),
(@vid,@bid,26,10,'Abimelec le reclamó: “¿ Qué es lo que nos has hecho ? Cualquiera del pueblo podría haberse acostado con tu esposa, ¡ y tú nos habrías hecho culpables de un gran pecado!”',NULL),
(@vid,@bid,26,11,'Entonces Abimelec le dio esta orden a todo el pueblo : “ Cualquiera que toque a este hombre o a su esposa, será condenado a muerte ”.',NULL),
(@vid,@bid,26,12,'Isaac sembró en aquella región, y ese mismo año cosechó cien veces lo que había sembrado , porque Yahvé lo bendijo .',NULL),
(@vid,@bid,26,13,'Su riqueza fue aumentando, hasta que llegó a ser un hombre muy rico y poderoso .',NULL),
(@vid,@bid,26,14,'Llegó a tener tantas ovejas y vacas , y tantos sirvientes, que los filisteos le tuvieron envidia .',NULL),
(@vid,@bid,26,15,'Por eso, taparon con tierra todos los pozos que los sirvientes de su padre habían cavado en tiempos de Abraham.',NULL),
(@vid,@bid,26,16,'Incluso Abimelec le dijo a Isaac : “ Vete de aquí, porque te has vuelto mucho más poderoso que nosotros ”.',NULL),
(@vid,@bid,26,17,'Así que Isaac se fue de allí , acampó en el valle de Gerar y se quedó a vivir en ese lugar.',NULL),
(@vid,@bid,26,18,'Isaac volvió a abrir los pozos de agua que habían sido cavados en tiempos de su padre Abraham, y que los filisteos habían tapado después de su muerte . A estos pozos les puso los mismos nombres que su padre les había dado.',NULL),
(@vid,@bid,26,19,'Un día, los sirvientes de Isaac estaban cavando en el valle y encontraron un pozo de agua fresca.',NULL),
(@vid,@bid,26,20,'Pero los pastores de Gerar se pelearon con los pastores de Isaac , reclamando: “¡Esta agua es nuestra!” Por eso Isaac llamó a ese pozo Esek , porque se habían peleado con él .',NULL),
(@vid,@bid,26,21,'Luego cavaron otro pozo, y también se pelearon por él ; así que lo llamó Sitná.',NULL),
(@vid,@bid,26,22,'Se alejó de allí y cavó otro pozo, y por ese no se pelearon. A ese lo llamó Rejobot, pues dijo: “ Ahora Yahvé nos ha dado espacio, y prosperaremos en esta tierra”.',NULL),
(@vid,@bid,26,23,'De allí , Isaac subió a Beerseba.',NULL),
(@vid,@bid,26,24,'Esa misma noche Yahvé se le apareció y le dijo: “ Yo soy el Dios de tu padre Abraham. No tengas miedo , porque yo estoy contigo. Por amor a mi siervo Abraham, te bendeciré y multiplicaré tu descendencia ”.',NULL),
(@vid,@bid,26,25,'Isaac construyó allí un altar e invocó el nombre de Yahvé. Allí armó su campamento, y sus sirvientes cavaron un pozo.',NULL),
(@vid,@bid,26,26,'Abimelec fue a visitarlo desde Gerar , acompañado por su amigo Ajuzat y por Ficol, el jefe de su ejército .',NULL),
(@vid,@bid,26,27,'Isaac les preguntó: “¿ A qué vienen, si ustedes me odian y me echaron de su tierra?”',NULL),
(@vid,@bid,26,28,'Ellos le respondieron: “Hemos visto claramente que Yahvé está contigo . Por eso pensamos que debería haber un acuerdo bajo juramento entre nosotros y tú. Queremos hacer un pacto contigo :',NULL),
(@vid,@bid,26,29,'júranos que no nos harás ningún daño, así como nosotros no te hemos tocado, sino que te hemos tratado bien y te dejamos ir en paz . ¡ Tú eres el bendito de Yahvé!”',NULL),
(@vid,@bid,26,30,'Isaac les preparó un banquete , y comieron y bebieron .',NULL),
(@vid,@bid,26,31,'A la mañana siguiente se levantaron temprano y se hicieron un juramento mutuo. Luego Isaac los despidió , y ellos se fueron en paz .',NULL),
(@vid,@bid,26,32,'Ese mismo día llegaron los sirvientes de Isaac y le informaron acerca del pozo que habían estado cavando. “¡Encontramos agua !”, le dijeron.',NULL),
(@vid,@bid,26,33,'Isaac llamó a ese pozo Sibá. Por eso , hasta el día de hoy , la ciudad se llama Beerseba.',NULL),
(@vid,@bid,26,34,'Cuando Esaú tenía cuarenta años , se casó con Judit, hija de Beerí el hitita, y con Basemat, hija de Elón el hitita.',NULL),
(@vid,@bid,26,35,'Estas dos mujeres les causaron mucha amargura a Isaac y a Rebeca .',NULL),
(@vid,@bid,27,1,'Cuando Isaac envejeció y perdió la vista, llamó a Esaú , su hijo mayor , y le dijo: “¡ Hijo mío!” —“ Aquí estoy ” —respondió él .',NULL),
(@vid,@bid,27,2,'Entonces Isaac le dijo: “ Mira , ya soy viejo y no sé qué día voy a morir.',NULL),
(@vid,@bid,27,3,'Así que toma tus armas , tu arco y tus flechas, sal al campo y cázame algún animal.',NULL),
(@vid,@bid,27,4,'Prepárame un guiso sabroso, como a mí me gusta, y tráemelo para que coma. Así te daré mi bendición antes de morir ”.',NULL),
(@vid,@bid,27,5,'Rebeca estaba escuchando mientras Isaac hablaba con su hijo Esaú . Así que , cuando Esaú se fue al campo a cazar el animal para su padre,',NULL),
(@vid,@bid,27,6,'Rebeca le dijo a su hijo Jacob : “Acabo de escuchar a tu padre hablar con tu hermano Esaú . Le estaba diciendo :',NULL),
(@vid,@bid,27,7,'‘Cázame un animal y prepárame un guiso sabroso, para que yo coma y te bendiga en presencia de Yahvé antes de morir’.',NULL),
(@vid,@bid,27,8,'Ahora bien, hijo mío, escúchame y haz exactamente lo que te ordeno :',NULL),
(@vid,@bid,27,9,'ve al rebaño y tráeme dos de los mejores cabritos . Yo prepararé con ellos un guiso sabroso para tu padre, tal como a él le gusta.',NULL),
(@vid,@bid,27,10,'Luego se lo llevarás a tu padre para que coma, y así él te dará su bendición antes de morir”.',NULL),
(@vid,@bid,27,11,'Pero Jacob le dijo a su madre Rebeca : “ Mira que mi hermano Esaú es un hombre muy velludo, y yo no.',NULL),
(@vid,@bid,27,12,'¿ Qué pasa si mi padre me toca? Se dará cuenta de que lo estoy engañando, y en lugar de bendición , atraeré sobre mí una maldición ”.',NULL),
(@vid,@bid,27,13,'Su madre le respondió: “¡ Que esa maldición caiga sobre mí , hijo mío ! Tú sólo hazme caso , y ve a traerme los cabritos”.',NULL),
(@vid,@bid,27,14,'Entonces Jacob fue a buscarlos y se los llevó a su madre, y ella preparó un guiso sabroso, tal como le gustaba a su padre.',NULL),
(@vid,@bid,27,15,'Luego Rebeca sacó la mejor ropa de su hijo mayor Esaú , la cual tenía guardada en casa , y con ella vistió a su hijo menor Jacob .',NULL),
(@vid,@bid,27,16,'Con las pieles de los cabritos le cubrió las manos y la parte sin vello del cuello .',NULL),
(@vid,@bid,27,17,'Finalmente, le entregó a Jacob el guiso sabroso y el pan que había preparado.',NULL),
(@vid,@bid,27,18,'Jacob se acercó a su padre y le dijo: “¡Padre mío!” “ Aquí estoy respondió Isaac. ¿ Quién eres, hijo mío?”',NULL),
(@vid,@bid,27,19,'Jacob le contestó: “Soy Esaú , tu hijo mayor. Ya hice lo que me pediste. Por favor, siéntate y come de lo que he cazado, para que puedas darme tu bendición ”.',NULL),
(@vid,@bid,27,20,'Isaac le preguntó a su hijo : “¿ Cómo es que lo encontraste tan rápido, hijo mío?” “ Porque Yahvé tu Dios me ayudó a encontrarlo”, respondió él .',NULL),
(@vid,@bid,27,21,'Entonces Isaac le dijo a Jacob : “ Acércate , hijo mío, para que pueda tocarte y saber si realmente eres mi hijo Esaú o no ”.',NULL),
(@vid,@bid,27,22,'Jacob se acercó a su padre Isaac . Al tocarlo, Isaac dijo: “La voz es la de Jacob , pero las manos son las de Esaú ”.',NULL),
(@vid,@bid,27,23,'Así que no lo reconoció, porque sus manos estaban velludas como las de su hermano Esaú , y lo bendijo .',NULL),
(@vid,@bid,27,24,'Sin embargo, volvió a preguntarle: “¿ De verdad eres mi hijo Esaú ?” “Sí, lo soy” respondió Jacob.',NULL),
(@vid,@bid,27,25,'Entonces Isaac le dijo: “Sírveme, para que coma de la caza de mi hijo y te dé mi bendición ”. Jacob le sirvió, e Isaac comió; también le trajo vino , y él bebió .',NULL),
(@vid,@bid,27,26,'Luego su padre Isaac le dijo: “ Acércate y bésame, hijo mío”.',NULL),
(@vid,@bid,27,27,'Jacob se acercó y lo besó . Cuando Isaac sintió el olor de su ropa, lo bendijo con estas palabras: “Miren, el olor de mi hijo es como el olor de un campo bendecido por Yahvé.',NULL),
(@vid,@bid,27,28,'¡Que Dios te conceda el rocío del cielo , la riqueza de la tierra, y abundancia de trigo y de vino nuevo!',NULL),
(@vid,@bid,27,29,'Que los pueblos te sirvan, y que las naciones se inclinen ante ti. Sé el señor de tus hermanos, y que los hijos de tu madre se inclinen ante ti. ¡Maldito sea el que te maldiga, y bendito sea el que te bendiga !”',NULL),
(@vid,@bid,27,30,'Isaac acababa de bendecir a Jacob , y apenas había salido Jacob de la presencia de su padre, cuando su hermano Esaú llegó de cazar.',NULL),
(@vid,@bid,27,31,'También él preparó un guiso sabroso, se lo llevó a su padre y le dijo: “ Levántate , padre mío, y come de lo que tu hijo ha cazado, para que me des tu bendición ”.',NULL),
(@vid,@bid,27,32,'Su padre Isaac le preguntó: “¿ Y tú quién eres?” “Soy tu hijo mayor, Esaú ” respondió él .',NULL),
(@vid,@bid,27,33,'Isaac se asustó muchísimo y , temblando, le dijo: “ Entonces , ¿ quién fue el que cazó un animal y me lo trajo? Yo comí de todo antes de que tú llegaras. Ya le he dado mi bendición , y bendito quedará ”.',NULL),
(@vid,@bid,27,34,'Al escuchar las palabras de su padre, Esaú dio un grito lleno de amargura y le suplicó: “¡ Bendíceme también a mí, padre mío!”',NULL),
(@vid,@bid,27,35,'Pero Isaac le respondió: “Tu hermano vino y me engañó , y se llevó tu bendición ”.',NULL),
(@vid,@bid,27,36,'Esaú exclamó: “¡ Con razón le pusieron por nombre Jacob ! Ya me ha engañado dos veces : primero me quitó mis derechos de hijo mayor , y ahora me ha quitado mi bendición ”. Y le preguntó a su padre: “¿ No has guardado ninguna bendición para mí ?”',NULL),
(@vid,@bid,27,37,'Isaac le contestó a Esaú : “ Ya lo he puesto como señor tuyo, y a todos sus parientes los he puesto como sus servidores; lo he provisto de trigo y de vino . ¿ Qué puedo hacer ahora por ti, hijo mío?”',NULL),
(@vid,@bid,27,38,'Esaú le rogó a su padre: “¿Acaso tienes una sola bendición , padre mío? ¡ Bendíceme también a mí !” Y Esaú se puso a llorar a gritos.',NULL),
(@vid,@bid,27,39,'Entonces su padre Isaac le dijo: “Vivirás lejos de las riquezas de la tierra y lejos del rocío que cae del cielo .',NULL),
(@vid,@bid,27,40,'Vivirás de tu espada y servirás a tu hermano. Pero cuando no lo soportes más , te arrancarás su yugo del cuello ”.',NULL),
(@vid,@bid,27,41,'A partir de ese momento, Esaú guardó un profundo rencor contra Jacob por la bendición que su padre le había dado, y pensó: “ Ya se acercan los días de guardar luto por mi padre. En cuanto muera, mataré a mi hermano Jacob ”.',NULL),
(@vid,@bid,27,42,'Pero alguien le contó a Rebeca lo que estaba planeando su hijo mayor . Entonces mandó llamar a su hijo menor Jacob y le dijo : “ Mira , tu hermano Esaú se está consolando con la idea de matarte.',NULL),
(@vid,@bid,27,43,'Así que , hijo mío, escúchame bien: prepárate y huye de inmediato a Jarán, a la casa de mi hermano Labán .',NULL),
(@vid,@bid,27,44,'Quédate con él un tiempo , hasta que se le pase el enojo a tu hermano.',NULL),
(@vid,@bid,27,45,'Cuando se calme su ira y olvide lo que le has hecho , yo mandaré a buscarte. ¿ Por qué habría de perderlos a los dos en un solo día ?”',NULL),
(@vid,@bid,27,46,'Luego Rebeca le dijo a Isaac : “ Ya no aguanto la vida por culpa de estas mujeres hititas. Si Jacob llega a casarse con una hitita, con una de las mujeres de esta tierra, ¡más me valdría morir!”',NULL),
(@vid,@bid,28,1,'Entonces Isaac llamó a Jacob , lo bendijo y le dio esta orden : “ No te cases con ninguna de las mujeres de Canaán .',NULL),
(@vid,@bid,28,2,'Prepárate y ve a Padán Aram, a la casa de tu abuelo Betuel. Cásate allá con una de las hijas de Labán , el hermano de tu madre.',NULL),
(@vid,@bid,28,3,'Que el Dios Todopoderoso te bendiga , te haga muy fecundo y multiplique tu descendencia, hasta que llegues a formar una multitud de naciones.',NULL),
(@vid,@bid,28,4,'Que también te dé la bendición de Abraham, a ti y a tus descendientes, para que tomes posesión de esta tierra donde ahora vives como extranjero, la cual Dios le dio a Abraham”.',NULL),
(@vid,@bid,28,5,'Así fue como Isaac despidió a Jacob , quien se dirigió a Padán Aram, a la casa de Labán , que era hijo de Betuel el arameo y hermano de Rebeca , la madre de Jacob y Esaú .',NULL),
(@vid,@bid,28,6,'Esaú se dio cuenta de que Isaac había bendecido a Jacob y lo había enviado a Padán Aram para buscar esposa allí , y que al bendecirlo le había ordenado : “ No te cases con ninguna mujer de Canaán ”.',NULL),
(@vid,@bid,28,7,'También supo que Jacob había obedecido a su padre y a su madre, y que se había ido a Padán Aram.',NULL),
(@vid,@bid,28,8,'Al ver Esaú que a su padre Isaac no le agradaban las mujeres cananeas,',NULL),
(@vid,@bid,28,9,'fue a ver a Ismael , el hijo de Abraham, y además de las esposas que ya tenía, se casó con Majalat, que era hija de Ismael y hermana de Nebaiot.',NULL),
(@vid,@bid,28,10,'Jacob salió de Beerseba y emprendió el viaje hacia Jarán.',NULL),
(@vid,@bid,28,11,'Al llegar a cierto lugar , se detuvo para pasar la noche, porque el sol ya se había puesto . Tomó una de las piedras del lugar , la usó como almohada y se acostó a dormir allí .',NULL),
(@vid,@bid,28,12,'Entonces tuvo un sueño: vio una escalinata que estaba apoyada en la tierra y cuya parte superior llegaba hasta el cielo ; y vio que los ángeles de Dios subían y bajaban por ella.',NULL),
(@vid,@bid,28,13,'Arriba de ella estaba Yahvé, quien le dijo: “ Yo soy Yahvé, el Dios de tu abuelo Abraham y el Dios de Isaac . A ti y a tu descendencia les daré la tierra sobre la que estás acostado .',NULL),
(@vid,@bid,28,14,'Tus descendientes serán tan numerosos como el polvo de la tierra , y te extenderás hacia el occidente y el oriente , hacia el norte y el sur. Por medio de ti y de tu descendencia serán bendecidas todas las familias de la tierra .',NULL),
(@vid,@bid,28,15,'Yo estoy contigo ; te protegeré por dondequiera que vayas y te traeré de vuelta a esta tierra. No te abandonaré hasta cumplir con todo lo que te he prometido”.',NULL),
(@vid,@bid,28,16,'Al despertar de su sueño , Jacob pensó: “¡En verdad Yahvé está en este lugar , y yo no lo sabía !”',NULL),
(@vid,@bid,28,17,'Lleno de temor , exclamó: “¡ Qué impresionante es este lugar ! No es otra cosa que la casa de Dios y la puerta del cielo ”.',NULL),
(@vid,@bid,28,18,'A la mañana siguiente, Jacob se levantó temprano, tomó la piedra que le había servido de almohada, la erigió como un pilar y derramó aceite sobre ella .',NULL),
(@vid,@bid,28,19,'A ese lugar le puso por nombre Betel, aunque al principio la ciudad se llamaba Luz .',NULL),
(@vid,@bid,28,20,'Luego Jacob hizo esta promesa : “ Si Dios me acompaña y me protege en este viaje que estoy haciendo, y si me da alimento para comer y ropa para vestirme,',NULL),
(@vid,@bid,28,21,'y si regreso sano y salvo a la casa de mi padre, entonces Yahvé será mi Dios .',NULL),
(@vid,@bid,28,22,'Esta piedra que he erigido como pilar será casa de Dios; y de todo lo que Dios me dé , le entregaré la décima parte”.',NULL),
(@vid,@bid,29,1,'Jacob continuó su viaje y llegó a la tierra de los pueblos del oriente .',NULL),
(@vid,@bid,29,2,'Al mirar , vio un pozo en el campo y tres rebaños de ovejas descansando junto a él , porque de ese pozo abrevaban a los rebaños . La piedra que cubría la boca del pozo era muy grande .',NULL),
(@vid,@bid,29,3,'Cuando se juntaban allí todos los rebaños , los pastores quitaban la piedra de la boca del pozo para dar de beber a las ovejas , y luego volvían a poner la piedra en su lugar .',NULL),
(@vid,@bid,29,4,'Jacob les preguntó a los pastores: “Hermanos míos, ¿de dónde son ustedes?” Ellos respondieron: “Somos de Jarán”.',NULL),
(@vid,@bid,29,5,'Él les dijo: “¿ Conocen a Labán , el nieto de Nacor?” Y ellos dijeron: “Sí, lo conocemos”.',NULL),
(@vid,@bid,29,6,'Jacob les preguntó: “¿ Cómo está él ?” Ellos contestaron: “Está bien . Miren, allí viene su hija Raquel con las ovejas ”.',NULL),
(@vid,@bid,29,7,'Jacob les dijo: “ Todavía es pleno día , y aún no es hora de encerrar el ganado . Denles de beber a las ovejas y llévenlas a pastar”.',NULL),
(@vid,@bid,29,8,'Pero ellos dijeron: “ No podemos hacerlo hasta que se junten todos los rebaños y quiten la piedra de la boca del pozo. Sólo entonces podremos darles de beber a las ovejas ”.',NULL),
(@vid,@bid,29,9,'Todavía estaba hablando con ellos cuando llegó Raquel con el rebaño de su padre, pues ella era la pastora.',NULL),
(@vid,@bid,29,10,'Cuando Jacob vio a Raquel, hija de Labán , el hermano de su madre, y vio también las ovejas de su tío Labán , se acercó , quitó la piedra de la boca del pozo y les dio de beber a las ovejas .',NULL),
(@vid,@bid,29,11,'Luego Jacob besó a Raquel y se echó a llorar de alegría.',NULL),
(@vid,@bid,29,12,'Jacob le contó a Raquel que él era pariente de su padre y que era hijo de Rebeca . Entonces ella corrió a contárselo a su padre.',NULL),
(@vid,@bid,29,13,'Tan pronto como Labán oyó las noticias acerca de Jacob , el hijo de su hermana, corrió a recibirlo, lo abrazó, lo besó y lo llevó a su casa . Allí Jacob le contó todo lo que había pasado.',NULL),
(@vid,@bid,29,14,'Labán le dijo: “¡Realmente eres de mi propia sangre!” Y Jacob se quedó con él todo un mes .',NULL),
(@vid,@bid,29,15,'Entonces Labán le dijo a Jacob : “ No vas a trabajar para mí de balde sólo porque eres mi pariente. Dime, ¿ cuánto quieres ganar?”',NULL),
(@vid,@bid,29,16,'Labán tenía dos hijas : la mayor se llamaba Lea , y la menor se llamaba Raquel.',NULL),
(@vid,@bid,29,17,'Lea tenía los ojos apagados, pero Raquel era de hermosa figura y muy atractiva.',NULL),
(@vid,@bid,29,18,'Como Jacob se había enamorado de Raquel, le dijo a Labán: “Trabajaré para ti siete años a cambio de Raquel, tu hija menor ”.',NULL),
(@vid,@bid,29,19,'Labán respondió: “Es mejor que te la dé a ti y no a un extraño. Quédate conmigo ”.',NULL),
(@vid,@bid,29,20,'Así que Jacob trabajó siete años para casarse con Raquel, pero le parecieron unos pocos días por el gran amor que le tenía .',NULL),
(@vid,@bid,29,21,'Cumplido el tiempo , Jacob le dijo a Labán : “Entrégame a mi esposa, pues ya he cumplido mi tiempo , para que me case con ella”.',NULL),
(@vid,@bid,29,22,'Entonces Labán reunió a toda la gente del lugar e hizo una gran fiesta.',NULL),
(@vid,@bid,29,23,'Pero al anochecer, Labán tomó a su hija Lea y se la entregó a Jacob, y Jacob tuvo relaciones con ella.',NULL),
(@vid,@bid,29,24,'Como sirvienta para su hija Lea , Labán le dio a su propia sirvienta Zilpá .',NULL),
(@vid,@bid,29,25,'A la mañana siguiente, Jacob se dio cuenta de que era Lea . Así que le reclamó a Labán : “¿ Qué es esto que me has hecho ? ¿Acaso no trabajé para ti a cambio de Raquel? ¿ Por qué me has engañado ?”',NULL),
(@vid,@bid,29,26,'Labán le contestó: “La costumbre de nuestro país no permite entregar a la hija menor antes que a la mayor.',NULL),
(@vid,@bid,29,27,'Cumple con la semana de bodas de ésta , y también te daremos a la otra , a cambio de que trabajes para mí otros siete años ”.',NULL),
(@vid,@bid,29,28,'Jacob aceptó, y cuando terminó la semana de bodas con Lea, Labán le dio por esposa a su hija Raquel.',NULL),
(@vid,@bid,29,29,'Como sirvienta para su hija Raquel, Labán le dio a su propia sirvienta Bilhá .',NULL),
(@vid,@bid,29,30,'Jacob tuvo relaciones también con Raquel, y la amó mucho más que a Lea . Y se quedó trabajando para Labán otros siete años .',NULL),
(@vid,@bid,29,31,'Cuando Yahvé vio que Lea no era amada, le concedió hijos, mientras que Raquel era estéril.',NULL),
(@vid,@bid,29,32,'Lea quedó embarazada y dio a luz un hijo , al que llamó Rubén , pues dijo: “Yahvé ha visto mi aflicción ; seguramente ahora mi esposo me amará”.',NULL),
(@vid,@bid,29,33,'Volvió a quedar embarazada y dio a luz otro hijo , y dijo: “Yahvé escuchó que yo no era amada, y por eso me dio también este hijo ”. Y lo llamó Simeón .',NULL),
(@vid,@bid,29,34,'Quedó embarazada de nuevo y dio a luz un tercer hijo . Entonces dijo: “ Ahora sí mi esposo se unirá a mí , porque le he dado tres hijos ”. Por eso lo llamó Leví .',NULL),
(@vid,@bid,29,35,'Volvió a quedar embarazada y dio a luz otro hijo . Entonces dijo: “ Esta vez alabaré a Yahvé”. Por eso lo llamó Judá . Después de esto , dejó de tener hijos .',NULL),
(@vid,@bid,30,1,'Cuando Raquel se dio cuenta de que no le podía dar hijos a Jacob , sintió envidia de su hermana y le dijo a Jacob : “¡ Dame hijos o me muero !”',NULL),
(@vid,@bid,30,2,'Jacob se enojó con Raquel y le contestó: “¿Acaso ocupo el lugar de Dios, que es quien te ha negado tener hijos?”',NULL),
(@vid,@bid,30,3,'Ella le dijo: “ Aquí tienes a mi sirvienta Bilhá . Ten relaciones con ella , para que dé a luz sobre mis rodillas y por medio de ella yo también pueda tener una familia”.',NULL),
(@vid,@bid,30,4,'Así que Raquel le dio a su sirvienta Bilhá por esposa, y Jacob tuvo relaciones con ella.',NULL),
(@vid,@bid,30,5,'Bilhá quedó embarazada y le dio un hijo a Jacob .',NULL),
(@vid,@bid,30,6,'Entonces Raquel dijo: “Dios me ha hecho justicia; ha escuchado mi voz y me ha dado un hijo ”. Por eso lo llamó Dan .',NULL),
(@vid,@bid,30,7,'Bilhá , la sirvienta de Raquel, volvió a quedar embarazada y le dio un segundo hijo a Jacob .',NULL),
(@vid,@bid,30,8,'Y Raquel dijo: “He tenido una lucha terrible con mi hermana, pero he vencido”. Por eso lo llamó Neftalí.',NULL),
(@vid,@bid,30,9,'Al ver Lea que había dejado de tener hijos, tomó a su sirvienta Zilpá y se la dio a Jacob por esposa.',NULL),
(@vid,@bid,30,10,'Zilpá , la sirvienta de Lea , le dio un hijo a Jacob .',NULL),
(@vid,@bid,30,11,'Entonces Lea exclamó: “¡Qué afortunada soy!” Y lo llamó Gad .',NULL),
(@vid,@bid,30,12,'Después Zilpá , la sirvienta de Lea , le dio un segundo hijo a Jacob .',NULL),
(@vid,@bid,30,13,'Y Lea dijo: “¡ Qué feliz soy! Las mujeres me llamarán feliz”. Y lo llamó Aser.',NULL),
(@vid,@bid,30,14,'Un día , durante la cosecha del trigo , Rubén fue al campo , encontró unas mandrágoras y se las llevó a su madre Lea . Al verlas, Raquel le dijo a Lea : “ Por favor, dame algunas de las mandrágoras de tu hijo ”.',NULL),
(@vid,@bid,30,15,'Pero Lea le contestó: “¿ Te parece poco haberme quitado a mi esposo, que ahora también quieres quitarme las mandrágoras de mi hijo ?” Y Raquel respondió: “ Está bien . A cambio de las mandrágoras de tu hijo , Jacob dormirá contigo esta noche ”.',NULL),
(@vid,@bid,30,16,'Al atardecer, cuando Jacob regresaba del campo , Lea salió a su encuentro y le dijo: “Hoy tienes que dormir conmigo , porque he pagado por ti con las mandrágoras de mi hijo ”. Y esa noche él durmió con ella .',NULL),
(@vid,@bid,30,17,'Dios escuchó a Lea , y ella quedó embarazada y le dio un quinto hijo a Jacob .',NULL),
(@vid,@bid,30,18,'Lea dijo: “Dios me ha dado mi recompensa por haberle dado mi sirvienta a mi esposo”. Por eso lo llamó Isacar.',NULL),
(@vid,@bid,30,19,'Lea volvió a quedar embarazada y le dio un sexto hijo a Jacob .',NULL),
(@vid,@bid,30,20,'Y dijo Lea : “Dios me ha dado un hermoso regalo. Ahora sí mi esposo se quedará a vivir conmigo, porque le he dado seis hijos ”. Y lo llamó Zabulón .',NULL),
(@vid,@bid,30,21,'Más tarde dio a luz una hija , a la que llamó Dina .',NULL),
(@vid,@bid,30,22,'Entonces Dios se acordó de Raquel, escuchó su ruego y le concedió tener hijos.',NULL),
(@vid,@bid,30,23,'Quedó embarazada , dio a luz un hijo y dijo: “Dios me ha quitado la vergüenza”.',NULL),
(@vid,@bid,30,24,'Lo llamó José , y dijo: “¡ Que Yahvé me añada otro hijo !”',NULL),
(@vid,@bid,30,25,'Después de que Raquel dio a luz a José , Jacob le dijo a Labán : “ Déjame ir ; quiero regresar a mi propia tierra.',NULL),
(@vid,@bid,30,26,'Entrégame a mis esposas y a mis hijos , por quienes he trabajado para ti, y me iré . Tú bien sabes cómo he trabajado para ti”.',NULL),
(@vid,@bid,30,27,'Labán le respondió: “Por favor, quédate. Me he dado cuenta de que Yahvé me ha bendecido gracias a ti”.',NULL),
(@vid,@bid,30,28,'Y añadió: “Dime cuánto quieres ganar, y yo te lo pagaré ”.',NULL),
(@vid,@bid,30,29,'Jacob le contestó: “Tú sabes cómo he trabajado para ti y cómo ha prosperado tu ganado bajo mi cuidado.',NULL),
(@vid,@bid,30,30,'Lo poco que tenías antes de que yo llegara se ha multiplicado enormemente, pues Yahvé te ha bendecido desde que estoy aquí. Pero , ¿ cuándo voy a trabajar para mi propia familia ?”',NULL),
(@vid,@bid,30,31,'Y preguntó Labán: “¿ Qué quieres que te dé ?” Jacob respondió : “ No me des nada . Si aceptas esta propuesta, seguiré cuidando y apacentando tus ovejas .',NULL),
(@vid,@bid,30,32,'Déjame pasar hoy por todos tus rebaños y apartar toda oveja manchada o moteada, y todas las ovejas negras, así como todos los cabritos manchados o moteados. Ése será mi salario .',NULL),
(@vid,@bid,30,33,'El día de mañana , mi honradez responderá por mí . Cuando vengas a revisar mi salario , todo cabrito que no esté manchado ni moteado, y toda oveja que no sea negra y que esté conmigo, será considerado un robo”.',NULL),
(@vid,@bid,30,34,'Labán aceptó: “ De acuerdo. Que sea tal como dices ”.',NULL),
(@vid,@bid,30,35,'Pero ese mismo día , Labán apartó los chivos rayados y manchados, y todas las cabras moteadas y manchadas , es decir, todos los que tenían alguna mancha blanca , junto con todas las ovejas negras, y los puso al cuidado de sus hijos .',NULL),
(@vid,@bid,30,36,'Luego puso una distancia de tres días de camino entre él y Jacob . Mientras tanto, Jacob siguió cuidando el resto del rebaño de Labán .',NULL),
(@vid,@bid,30,37,'Entonces Jacob tomó ramas verdes de álamo, de almendro y de plátano, y les quitó tiras de corteza para que se vieran franjas blancas en las ramas.',NULL),
(@vid,@bid,30,38,'Luego puso las ramas peladas frente a los rebaños, en los canales de los bebederos donde los animales venían a tomar agua . Allí se apareaban al venir a beber .',NULL),
(@vid,@bid,30,39,'Como los rebaños se apareaban frente a las ramas, las crías nacían rayadas, moteadas y manchadas .',NULL),
(@vid,@bid,30,40,'Jacob apartaba los corderos y ponía al rebaño frente a los animales rayados y negros del rebaño de Labán . Así formó sus propios rebaños y no los mezcló con los de Labán .',NULL),
(@vid,@bid,30,41,'Además, cada vez que los animales más fuertes y robustos estaban en celo, Jacob ponía las ramas en los bebederos, frente a los animales, para que se aparearan cerca de ellas.',NULL),
(@vid,@bid,30,42,'Pero cuando se trataba de los animales más débiles, no ponía las ramas. Así que los animales débiles eran para Labán , y los fuertes para Jacob .',NULL),
(@vid,@bid,30,43,'De esta manera el hombre prosperó muchísimo, y llegó a tener grandes rebaños, además de sirvientas, sirvientes, camellos y burros.',NULL),
(@vid,@bid,31,1,'Jacob se enteró de lo que andaban diciendo los hijos de Labán : “ Jacob se ha adueñado de todo lo que era de nuestro padre; toda su riqueza la ha sacado de los bienes de nuestro padre”.',NULL),
(@vid,@bid,31,2,'Además, Jacob notó que la actitud de Labán hacia él ya no era la misma de antes .',NULL),
(@vid,@bid,31,3,'Entonces Yahvé le dijo a Jacob : “Regresa a la tierra de tus padres y a tus parientes, y yo estaré contigo ”.',NULL),
(@vid,@bid,31,4,'Así que Jacob mandó llamar a Raquel y a Lea para que fueran al campo , donde estaba su rebaño ,',NULL),
(@vid,@bid,31,5,'y les dijo: “ Me he dado cuenta de que la actitud del padre de ustedes hacia mí ya no es la misma de antes ; pero el Dios de mi padre ha estado conmigo .',NULL),
(@vid,@bid,31,6,'Ustedes bien saben que he trabajado para su padre con todas mis fuerzas .',NULL),
(@vid,@bid,31,7,'Sin embargo, él me ha engañado y me ha cambiado el salario diez veces ; pero Dios no le ha permitido hacerme ningún daño.',NULL),
(@vid,@bid,31,8,'Si él decía: ‘ Los animales manchados serán tu salario ’, entonces todo el rebaño tenía crías manchadas ; y si decía: ‘ Los rayados serán tu salario ’, entonces todo el rebaño tenía crías rayadas.',NULL),
(@vid,@bid,31,9,'De esta manera, Dios le ha quitado el ganado al padre de ustedes y me lo ha dado a mí.',NULL),
(@vid,@bid,31,10,'Una vez , durante la época de celo del rebaño , tuve un sueño en el que vi que los machos que se apareaban con las hembras eran rayados, manchados y moteados.',NULL),
(@vid,@bid,31,11,'En ese sueño , el ángel de Dios me llamó: ‘¡ Jacob !’, y yo le respondí: ‘ Aquí estoy’.',NULL),
(@vid,@bid,31,12,'Y él me dijo: ‘Fíjate bien , y verás que todos los machos que se aparean con el rebaño son rayados, manchados y moteados, porque he visto todo lo que Labán te está haciendo .',NULL),
(@vid,@bid,31,13,'Yo soy el Dios de Betel, donde ungiste un pilar y donde me hiciste una promesa . Levántate ahora mismo, sal de esta tierra y regresa a la tierra donde naciste’”.',NULL),
(@vid,@bid,31,14,'Raquel y Lea le respondieron : “¿Acaso nos queda alguna herencia en la casa de nuestro padre?',NULL),
(@vid,@bid,31,15,'¿ No nos trata ya como a extranjeras ? No solo nos vendió , sino que además se ha gastado todo lo que pagaste por nosotras.',NULL),
(@vid,@bid,31,16,'En realidad, toda la riqueza que Dios le ha quitado a nuestro padre nos pertenece a nosotras y a nuestros hijos . Así que haz todo lo que Dios te ha ordenado”.',NULL),
(@vid,@bid,31,17,'Entonces Jacob se preparó, montó a sus hijos y a sus esposas en los camellos ,',NULL),
(@vid,@bid,31,18,'y se llevó todo su ganado y todas las posesiones que había acumulado en Padán Aram, para ir a la tierra de Canaán , a la casa de su padre Isaac .',NULL),
(@vid,@bid,31,19,'Como Labán había ido a esquilar sus ovejas , Raquel aprovechó para robarse los terafines de su padre.',NULL),
(@vid,@bid,31,20,'Además , Jacob engañó a Labán el arameo, ocultándole que se iba a fugar.',NULL),
(@vid,@bid,31,21,'Así que huyó con todo lo que tenía . Cruzó el río Éufrates y se dirigió hacia la región montañosa de Galaad .',NULL),
(@vid,@bid,31,22,'Al tercer día , le avisaron a Labán que Jacob se había escapado.',NULL),
(@vid,@bid,31,23,'Entonces Labán reunió a sus parientes y lo persiguió durante siete días , hasta que lo alcanzó en los montes de Galaad .',NULL),
(@vid,@bid,31,24,'Pero esa noche , Dios se le apareció a Labán el arameo en un sueño y le advirtió: “¡Cuidado con decirle a Jacob una sola palabra , ya sea buena o mala !”',NULL),
(@vid,@bid,31,25,'Cuando Labán alcanzó a Jacob , éste ya había levantado su campamento en la montaña. Así que Labán y sus parientes también acamparon en la montaña de Galaad .',NULL),
(@vid,@bid,31,26,'Y Labán le reclamó a Jacob : “¿ Qué te pasa? ¿ Por qué me has engañado y te has llevado a mis hijas como si fueran prisioneras de guerra?',NULL),
(@vid,@bid,31,27,'¿ Por qué huiste a escondidas y me engañaste? ¡ Si me lo hubieras dicho, yo te habría despedido con gran alegría , con cantos y música de panderos y arpas !',NULL),
(@vid,@bid,31,28,'Ni siquiera me dejaste despedirme de mis nietos y de mis hijas con un beso . ¡Te has portado como un tonto!',NULL),
(@vid,@bid,31,29,'Yo tengo el poder para hacerles mucho daño; pero anoche el Dios del padre de ustedes me habló y me dijo : ‘¡ Cuidado con decirle a Jacob una sola palabra , ya sea buena o mala !’',NULL),
(@vid,@bid,31,30,'Entiendo que te hayas ido porque extrañabas mucho la casa de tu padre, pero ¿ por qué tenías que robarte mis dioses?”',NULL),
(@vid,@bid,31,31,'Jacob le respondió : “ Me fui así porque tuve miedo , pues pensé que me quitarías a tus hijas por la fuerza.',NULL),
(@vid,@bid,31,32,'Pero en cuanto a tus dioses, si los encuentras en poder de alguien aquí, esa persona morirá. Revisa todo lo que tengo delante de nuestros parientes, y si encuentras algo tuyo, llévatelo”. Y es que Jacob no sabía que Raquel se los había robado.',NULL),
(@vid,@bid,31,33,'Labán entró a buscar en la tienda de Jacob , luego en la de Lea , y en la de las dos sirvientas, pero no encontró nada . Al salir de la tienda de Lea , entró en la de Raquel.',NULL),
(@vid,@bid,31,34,'Pero Raquel había tomado los terafines y los había escondido en la montura de su camello , y luego se había sentado sobre ellos . Labán revisó toda la tienda, pero no los encontró.',NULL),
(@vid,@bid,31,35,'Entonces ella le dijo a su padre: “ Por favor, señor mío, no te enojes si no me levanto para saludarte, pero es que estoy en mi período”. Labán buscó por todas partes, pero no encontró los terafines.',NULL),
(@vid,@bid,31,36,'Entonces Jacob se enojó y le reclamó a Labán : “¿ Cuál es mi delito? ¿ Qué pecado he cometido, para que me persigas con tanta furia?',NULL),
(@vid,@bid,31,37,'Ya revisaste todas mis cosas , ¿acaso encontraste algo que pertenezca a tu casa ? ¡ Ponlo aquí , delante de mis parientes y de los tuyos , para que ellos juzguen quién de los dos tiene la razón!',NULL),
(@vid,@bid,31,38,'En estos veinte años que he estado contigo , tus ovejas y tus cabras jamás abortaron , ni nunca me comí un solo carnero de tus rebaños.',NULL),
(@vid,@bid,31,39,'Nunca te llevé los restos de los animales despedazados por las fieras, sino que yo mismo asumía la pérdida. Y tú me cobrabas todo lo que se robaban, ya fuera de día o de noche .',NULL),
(@vid,@bid,31,40,'De día me consumía el calor, y de noche el frío; ¡ hasta el sueño se me espantaba!',NULL),
(@vid,@bid,31,41,'Así pasé veinte años en tu casa : catorce años trabajé por tus dos hijas , y seis años por tu rebaño , ¡y me cambiaste el salario diez veces !',NULL),
(@vid,@bid,31,42,'Si el Dios de mi padre, el Dios de Abraham y el Temor de Isaac , no hubiera estado conmigo, seguramente me habrías despedido con las manos vacías . Pero Dios vio mi aflicción y el duro trabajo de mis manos , y anoche te reprendió”.',NULL),
(@vid,@bid,31,43,'Labán le respondió a Jacob : “ Estas mujeres son mis hijas , estos niños son mis nietos , y estos rebaños son míos. ¡ Todo lo que ves me pertenece! Pero, ¿ qué les puedo hacer ahora a mis hijas o a los hijos que han tenido?',NULL),
(@vid,@bid,31,44,'Ven , hagamos un pacto tú y yo, y que quede como un testimonio entre nosotros”.',NULL),
(@vid,@bid,31,45,'Entonces Jacob tomó una piedra y la erigió como un pilar.',NULL),
(@vid,@bid,31,46,'Luego les dijo a sus parientes: “Junten piedras”. Ellos tomaron piedras e hicieron un montón , y comieron allí , junto al montón .',NULL),
(@vid,@bid,31,47,'Labán llamó a ese montón Yegar Sahaduta, pero Jacob lo llamó Galaad .',NULL),
(@vid,@bid,31,48,'Y Labán declaró: “ Este montón es hoy un testigo entre tú y yo”. Por eso se le llamó Galaad ,',NULL),
(@vid,@bid,31,49,'y también Mizpá , porque Labán añadió: “ Que Yahvé nos vigile a los dos cuando estemos lejos el uno del otro .',NULL),
(@vid,@bid,31,50,'Si maltratas a mis hijas , o si tomas otras esposas además de ellas , aunque no haya nadie con nosotros , recuerda que Dios es testigo entre tú y yo”.',NULL),
(@vid,@bid,31,51,'Labán también le dijo a Jacob : “ Mira este montón y este pilar que he levantado entre nosotros.',NULL),
(@vid,@bid,31,52,'Que este montón y este pilar nos sirvan de testigos de que yo no pasaré de aquí para hacerte daño, y de que tú tampoco pasarás de aquí para hacerme daño.',NULL),
(@vid,@bid,31,53,'Que el Dios de Abraham y el Dios de Nacor, el Dios del padre de ellos, juzgue entre nosotros”. Entonces Jacob hizo un juramento en el nombre del Temor de su padre Isaac .',NULL),
(@vid,@bid,31,54,'Luego Jacob ofreció un sacrificio en la montaña, e invitó a sus parientes a comer. Después de comer, pasaron la noche en la montaña.',NULL),
(@vid,@bid,31,55,'A la mañana siguiente, Labán se levantó temprano, besó y bendijo a sus nietos y a sus hijas, y emprendió el camino de regreso a su casa.',NULL),
(@vid,@bid,32,1,'Mientras Jacob seguía su camino, unos ángeles de Dios salieron a su encuentro.',NULL),
(@vid,@bid,32,2,'Al verlos, Jacob exclamó: “¡Este es el campamento de Dios!” Por eso llamó a aquel lugar Mahanaim.',NULL),
(@vid,@bid,32,3,'Luego Jacob envió mensajeros por delante para que fueran a buscar a su hermano Esaú en la tierra de Seír, en la región de Edom.',NULL),
(@vid,@bid,32,4,'Y les ordenó: “Esto es lo que le dirán a mi señor Esaú : ‘Esto dice tu siervo Jacob : He vivido como extranjero con Labán, y me he quedado con él hasta ahora.',NULL),
(@vid,@bid,32,5,'Tengo vacas, burros, ovejas, esclavos y esclavas. Envío este mensaje a mi señor, con la esperanza de ganarme su favor’”.',NULL),
(@vid,@bid,32,6,'Los mensajeros regresaron a donde estaba Jacob y le dijeron: “ Fuimos a ver a tu hermano Esaú. Ya viene a tu encuentro, y lo acompañan cuatrocientos hombres”.',NULL),
(@vid,@bid,32,7,'Jacob se llenó de mucho miedo y angustia. Entonces dividió en dos campamentos a la gente que lo acompañaba, y también a las ovejas, las vacas y los camellos.',NULL),
(@vid,@bid,32,8,'Pues pensó: “Si Esaú ataca a uno de los campamentos , el otro campamento podrá escapar”.',NULL),
(@vid,@bid,32,9,'Luego Jacob oró: “Dios de mi abuelo Abraham, y Dios de mi padre Isaac; Yahvé, tú me dijiste: ‘Regresa a tu tierra y a tus parientes, y yo te haré prosperar’.',NULL),
(@vid,@bid,32,10,'No soy digno de la inmensa bondad y lealtad que le has mostrado a tu siervo. Cuando crucé este río Jordán, no tenía más que mi bastón, ¡y ahora he llegado a formar dos campamentos!',NULL),
(@vid,@bid,32,11,'Por favor, sálvame de las manos de mi hermano Esaú, porque tengo miedo de que venga y me mate a mí , y también a las madres con sus hijos.',NULL),
(@vid,@bid,32,12,'Tú mismo dijiste: ‘ Ciertamente te haré prosperar, y haré que tu descendencia sea tan numerosa como la arena del mar, que no se puede contar’”.',NULL),
(@vid,@bid,32,13,'Jacob pasó la noche allí, y de lo que tenía a la mano escogió un regalo para su hermano Esaú:',NULL),
(@vid,@bid,32,14,'doscientas cabras y veinte chivos, doscientas ovejas y veinte carneros,',NULL),
(@vid,@bid,32,15,'treinta camellas lecheras con sus crías, cuarenta vacas y diez toros, y veinte burras y diez burritos.',NULL),
(@vid,@bid,32,16,'Puso cada manada al cuidado de sus siervos, y les dijo: “Vayan delante de mí, y dejen un buen espacio entre manada y manada”.',NULL),
(@vid,@bid,32,17,'Al que iba al frente le ordenó : “ Cuando mi hermano Esaú te encuentre y te pregunte: ‘¿ De quién eres sirviente? ¿ A dónde vas? ¿ Y de quién son estos animales que llevas adelante?’,',NULL),
(@vid,@bid,32,18,'le contestarás: ‘ Son de tu siervo Jacob. Es un regalo que le envía a mi señor Esaú . Y mire, él mismo viene detrás de nosotros’”.',NULL),
(@vid,@bid,32,19,'Le dio la misma orden al segundo, al tercero y a todos los que iban detrás de las manadas: “ Esto mismo le dirán a Esaú cuando se encuentren con él .',NULL),
(@vid,@bid,32,20,'Y asegúrense de decirle: ‘Su siervo Jacob viene justo detrás de nosotros ’”. Porque Jacob pensaba: “ Lo apaciguaré con los regalos que van por delante, y cuando lo vea cara a cara, tal vez me reciba bien”.',NULL),
(@vid,@bid,32,21,'Así que los regalos se fueron por delante , mientras que él pasó esa noche en el campamento.',NULL),
(@vid,@bid,32,22,'Pero esa misma noche Jacob se levantó, tomó a sus dos esposas, a sus dos sirvientas y a sus once hijos, y cruzó el vado del río Jaboc.',NULL),
(@vid,@bid,32,23,'Una vez que los hizo cruzar el arroyo, hizo pasar también todo lo que tenía .',NULL),
(@vid,@bid,32,24,'Jacob se quedó completamente solo, y un hombre luchó con él hasta que amaneció.',NULL),
(@vid,@bid,32,25,'Cuando el hombre se dio cuenta de que no podía vencer a Jacob , lo golpeó en la articulación de la cadera, y la cadera de Jacob se dislocó mientras luchaba con él .',NULL),
(@vid,@bid,32,26,'Entonces el hombre le dijo: “¡Suéltame, que ya está amaneciendo!” Pero Jacob le respondió: “ No te soltaré hasta que me bendigas”.',NULL),
(@vid,@bid,32,27,'“¿ Cómo te llamas?”, le preguntó el hombre. “Jacob”, contestó él .',NULL),
(@vid,@bid,32,28,'Y el hombre le dijo: “ Ya no te llamarás Jacob , sino Israel, porque has luchado con Dios y con los hombres, y has vencido”.',NULL),
(@vid,@bid,32,29,'Entonces Jacob le pidió: “ Por favor, dime tu nombre ”. Pero él respondió: “¿ Por qué me preguntas mi nombre ?” Y allí mismo lo bendijo.',NULL),
(@vid,@bid,32,30,'Jacob llamó a aquel lugar Peniel, pues dijo : “He visto a Dios cara a cara, y sin embargo sigo con vida”.',NULL),
(@vid,@bid,32,31,'El sol estaba saliendo cuando Jacob pasó por Peniel , y se fue cojeando a causa de su cadera.',NULL),
(@vid,@bid,32,32,'Por eso , hasta el día de hoy, los israelitas no comen el tendón que está en la articulación de la cadera, porque a Jacob lo golpearon en ese mismo tendón de la cadera.',NULL),
(@vid,@bid,33,1,'Jacob levantó la vista y vio que Esaú se acercaba con cuatrocientos hombres . Entonces repartió a los niños entre Lea , Raquel y las dos sirvientas.',NULL),
(@vid,@bid,33,2,'Puso por delante a las sirvientas y a sus hijos , luego a Lea y a sus hijos , y por último a Raquel y a José .',NULL),
(@vid,@bid,33,3,'Él mismo se adelantó y se inclinó hasta el suelo siete veces , antes de acercarse a su hermano.',NULL),
(@vid,@bid,33,4,'Pero Esaú corrió a su encuentro, lo abrazó, se le echó al cuello y lo besó , y ambos lloraron .',NULL),
(@vid,@bid,33,5,'Luego Esaú levantó la vista, y al ver a las mujeres y a los niños , preguntó: “¿ Y quiénes son estos que vienen contigo?”. Jacob le respondió: “Son los hijos que Dios, en su bondad, le ha dado a tu siervo ”.',NULL),
(@vid,@bid,33,6,'Entonces se acercaron las sirvientas con sus hijos , y se inclinaron.',NULL),
(@vid,@bid,33,7,'Luego se acercaron Lea y sus hijos , y se inclinaron. Finalmente se acercaron José y Raquel, y también se inclinaron.',NULL),
(@vid,@bid,33,8,'Esaú le preguntó: “¿ Qué pretendes con todos estos rebaños con los que me he topado?”. Jacob contestó: “Ganarme el favor de mi señor”.',NULL),
(@vid,@bid,33,9,'Pero Esaú le dijo: “Hermano mío, yo ya tengo mucho . Quédate con lo que es tuyo”.',NULL),
(@vid,@bid,33,10,'Jacob insistió: “¡ No , por favor! Si realmente me he ganado tu favor, acepta el regalo que te ofrezco. El ver tu rostro ha sido para mí como ver el rostro de Dios, ya que me has recibido muy bien .',NULL),
(@vid,@bid,33,11,'Por favor, acepta este regalo que te he traído, porque Dios ha sido muy bueno conmigo y tengo de todo ”. Y como Jacob le insistió, Esaú lo aceptó.',NULL),
(@vid,@bid,33,12,'Luego Esaú le dijo: “Sigamos nuestro viaje; yo iré por delante de ti”.',NULL),
(@vid,@bid,33,13,'Pero Jacob le contestó: “ Mi señor sabe que los niños son delicados, y que las ovejas y las vacas que traen crías necesitan cuidado. Si se les apura un solo día , morirá todo el rebaño .',NULL),
(@vid,@bid,33,14,'Por favor, adelántese mi señor a su siervo . Yo avanzaré poco a poco, al paso del ganado que va delante de mí y al paso de los niños , hasta que alcance a mi señor en Seír ”.',NULL),
(@vid,@bid,33,15,'Esaú le ofreció: “Permíteme dejarte a algunos de mis hombres”. Pero Jacob le dijo: “¿ Para qué molestarte? Me basta con haberte caído bien , mi señor”.',NULL),
(@vid,@bid,33,16,'Ese mismo día , Esaú emprendió el camino de regreso a Seír .',NULL),
(@vid,@bid,33,17,'Jacob , por su parte , se dirigió a Sucot. Allí se construyó una casa y armó unos corrales para su ganado . Por eso a ese lugar se le llamó Sucot.',NULL),
(@vid,@bid,33,18,'En su viaje desde Padán Aram, Jacob llegó sano y salvo a la ciudad de Siquén, en la tierra de Canaán , y acampó frente a la ciudad .',NULL),
(@vid,@bid,33,19,'Por cien monedas de plata, les compró a los hijos de Jamor, el padre de Siquén, la parcela donde había armado su campamento.',NULL),
(@vid,@bid,33,20,'Allí construyó un altar y lo llamó El Elohe Israel .',NULL),
(@vid,@bid,34,1,'Un día, Dina , la hija que Lea le había dado a Jacob , salió a visitar a las jóvenes del lugar.',NULL),
(@vid,@bid,34,2,'Al verla, Siquén, hijo de Jamor el heveo , que era el jefe de aquella región, la agarró, se acostó con ella y la deshonró.',NULL),
(@vid,@bid,34,3,'Pero se enamoró perdidamente de Dina , la hija de Jacob ; amó a la joven y le habló con ternura.',NULL),
(@vid,@bid,34,4,'Entonces Siquén le dijo a su padre Jamor: “Consígueme a esta joven para que sea mi esposa”.',NULL),
(@vid,@bid,34,5,'Jacob se enteró de que Siquén había deshonrado a su hija Dina . Pero como sus hijos estaban en el campo con el ganado , no dijo nada hasta que ellos regresaron.',NULL),
(@vid,@bid,34,6,'Mientras tanto, Jamor, el padre de Siquén, fue a hablar con Jacob .',NULL),
(@vid,@bid,34,7,'Al enterarse de lo sucedido, los hijos de Jacob regresaron del campo . Estaban indignados y furiosos, porque Siquén había cometido una infamia en Israel al acostarse con la hija de Jacob , algo que jamás debía hacerse.',NULL),
(@vid,@bid,34,8,'Jamor habló con ellos y les dijo : “ Mi hijo Siquén está perdidamente enamorado de la hija de ustedes. Por favor, dénsela por esposa.',NULL),
(@vid,@bid,34,9,'Emparentemos: dennos a sus hijas , y cásense ustedes con las nuestras.',NULL),
(@vid,@bid,34,10,'Quédense a vivir con nosotros. La tierra está a su disposición; vivan y hagan negocios aquí, y adquieran propiedades”.',NULL),
(@vid,@bid,34,11,'Siquén también les rogó al padre y a los hermanos de Dina: “Concédanme este favor, y yo les daré todo lo que me pidan.',NULL),
(@vid,@bid,34,12,'Fijen un precio alto por la dote y los regalos, y yo pagaré lo que me pidan; pero denme a la joven por esposa”.',NULL),
(@vid,@bid,34,13,'Como Siquén había deshonrado a su hermana Dina , los hijos de Jacob les respondieron a Siquén y a su padre Jamor con engaños.',NULL),
(@vid,@bid,34,14,'Les dijeron : “ No podemos hacer eso . Entregar a nuestra hermana a un hombre incircunciso sería una vergüenza para nosotros .',NULL),
(@vid,@bid,34,15,'Sólo aceptaremos con esta condición: que ustedes se hagan como nosotros y que todos sus varones sean circuncidados.',NULL),
(@vid,@bid,34,16,'Si lo hacen, les daremos a nuestras hijas y nos casaremos con las de ustedes. Nos quedaremos a vivir con ustedes y seremos un solo pueblo .',NULL),
(@vid,@bid,34,17,'Pero si no aceptan y no se circuncidan, nos llevaremos a nuestra hermana y nos iremos ”.',NULL),
(@vid,@bid,34,18,'La propuesta les pareció bien a Jamor y a su hijo Siquén.',NULL),
(@vid,@bid,34,19,'El joven no tardó en hacerlo, pues estaba muy enamorado de la hija de Jacob , y además era el hombre más respetado de toda su familia .',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,34,20,'Así que Jamor y su hijo Siquén fueron a la puerta de su ciudad y hablaron con sus conciudadanos:',NULL),
(@vid,@bid,34,21,'“ Estos hombres son pacíficos. Dejemos que se queden a vivir y a hacer negocios en nuestra tierra, pues hay lugar de sobra para ellos . Podremos casarnos con sus hijas , y darles las nuestras.',NULL),
(@vid,@bid,34,22,'Pero ellos aceptarán quedarse a vivir entre nosotros y ser un solo pueblo con una sola condición: que todos nuestros varones sean circuncidados, así como ellos lo están .',NULL),
(@vid,@bid,34,23,'¿Acaso no pasarán a ser nuestros todos sus rebaños, sus bienes y sus animales? Aceptemos su condición, y así se quedarán a vivir con nosotros ”.',NULL),
(@vid,@bid,34,24,'Todos los hombres que salían por la puerta de la ciudad estuvieron de acuerdo con Jamor y con su hijo Siquén, y todos los varones de la ciudad fueron circuncidados.',NULL),
(@vid,@bid,34,25,'Al tercer día , cuando más les dolía la herida, Simeón y Leví , que eran dos de los hijos de Jacob y hermanos de Dina , tomaron cada uno su espada , entraron a la ciudad sin que nadie lo sospechara y mataron a todos los varones .',NULL),
(@vid,@bid,34,26,'Mataron a filo de espada a Jamor y a su hijo Siquén, sacaron a Dina de la casa de Siquén, y se fueron.',NULL),
(@vid,@bid,34,27,'Luego los otros hijos de Jacob pasaron sobre los muertos y saquearon la ciudad , para vengarse por la deshonra de su hermana.',NULL),
(@vid,@bid,34,28,'Se apoderaron de sus rebaños, sus vacas y sus burros, y de todo lo que había tanto en la ciudad como en el campo .',NULL),
(@vid,@bid,34,29,'Se llevaron todas sus riquezas y saquearon todo lo que había en las casas , llevándose prisioneros a los niños y a las mujeres.',NULL),
(@vid,@bid,34,30,'Entonces Jacob les reclamó a Simeón y a Leví : “¡Ustedes me han metido en un grave problema! Me han hecho odioso ante los habitantes de esta tierra, ante los cananeos y los ferezeos. Nosotros somos pocos ; si se unen contra mí y me atacan, seremos destruidos yo y toda mi familia ”.',NULL),
(@vid,@bid,34,31,'Pero ellos respondieron: “¿Acaso íbamos a permitir que tratara a nuestra hermana como a una prostituta?”',NULL),
(@vid,@bid,35,1,'Dios le dijo a Jacob : “ Levántate , sube a Betel y quédate a vivir allí . Construye allí un altar al Dios que se te apareció cuando huías de tu hermano Esaú ”.',NULL),
(@vid,@bid,35,2,'Entonces Jacob les dijo a su familia y a todos los que lo acompañaban: “Desháganse de los dioses extranjeros que tienen entre ustedes, purifíquense y cámbiense de ropa .',NULL),
(@vid,@bid,35,3,'Preparémonos para subir a Betel. Allí construiré un altar al Dios que me escuchó cuando estadi angustiado, y que me ha acompañado en todo mi camino ”.',NULL),
(@vid,@bid,35,4,'Así que ellos le entregaron a Jacob todos los dioses extranjeros que tenían, y también los aretes que llevaban en las orejas; y Jacob los enterró debajo del roble que está cerca de Siquén.',NULL),
(@vid,@bid,35,5,'Cuando reanudaron su viaje, un pánico enviado por Dios se apoderó de las ciudades vecinas, de modo que nadie persiguió a los hijos de Jacob .',NULL),
(@vid,@bid,35,6,'Jacob y todos los que lo acompañaban llegaron a Luz ( es decir, Betel), en la tierra de Canaán .',NULL),
(@vid,@bid,35,7,'Allí construyó un altar , y a ese lugar lo llamó El Betel, porque allí Dios se le había revelado cuando huía de su hermano.',NULL),
(@vid,@bid,35,8,'Por esos días murió Débora , la nodriza de Rebeca , y la enterraron al pie de Betel, debajo del roble. Por eso aquel lugar fue llamado Alón Bacut.',NULL),
(@vid,@bid,35,9,'Dios se le apareció de nuevo a Jacob cuando regresaba de Padán Aram, y lo bendijo .',NULL),
(@vid,@bid,35,10,'Dios le dijo: “Tu nombre es Jacob , pero ya no te llamarás así . De ahora en adelante tu nombre será Israel ”. Y así le puso por nombre Israel .',NULL),
(@vid,@bid,35,11,'Además , Dios le dijo: “ Yo soy el Dios Todopoderoso . Sé fecundo y multiplícate. De ti nacerán una nación y una comunidad de naciones , y de tu descendencia surgirán reyes .',NULL),
(@vid,@bid,35,12,'La tierra que les di a Abraham y a Isaac , te la doy a ti, y también se la daré a tus descendientes”.',NULL),
(@vid,@bid,35,13,'Y Dios se alejó del lugar donde había hablado con él .',NULL),
(@vid,@bid,35,14,'Entonces Jacob levantó un monumento de piedra en el lugar donde Dios le había hablado , y sobre él derramó una ofrenda de vino y aceite .',NULL),
(@vid,@bid,35,15,'Jacob llamó Betel a ese lugar donde Dios le había hablado .',NULL),
(@vid,@bid,35,16,'Luego partieron de Betel. Cuando todavía faltaba un tramo para llegar a Efrata, a Raquel le llegaron los dolores de parto, y tuvo un parto muy difícil.',NULL),
(@vid,@bid,35,17,'Mientras sufría con los dolores, la partera le dijo: “¡ No tengas miedo , que vas a tener otro hijo varón!”',NULL),
(@vid,@bid,35,18,'Y al dar su último suspiro ( porque estaba a punto de morir ), Raquel lo llamó Benoní , pero su padre le puso por nombre Benjamín .',NULL),
(@vid,@bid,35,19,'Así murió Raquel, y la enterraron en el camino que va hacia Efrata ( es decir, Belén).',NULL),
(@vid,@bid,35,20,'Sobre su tumba Jacob levantó un monumento, el cual señala la tumba de Raquel hasta el día de hoy .',NULL),
(@vid,@bid,35,21,'Israel siguió su viaje y armó su campamento más allá de Migdal Eder.',NULL),
(@vid,@bid,35,22,'Mientras Israel vivía en esa región, Rubén fue y se acostó con Bilhá , la concubina de su padre. Y cuando Israel se enteró de esto , se enojó muchísimo. Los hijos de Jacob fueron doce .',NULL),
(@vid,@bid,35,23,'Los hijos de Lea fueron: Rubén ( el hijo mayor de Jacob ), Simeón , Leví , Judá , Isacar y Zabulón .',NULL),
(@vid,@bid,35,24,'Los hijos de Raquel fueron: José y Benjamín .',NULL),
(@vid,@bid,35,25,'Los hijos de Bilhá , la sirvienta de Raquel, fueron: Dan y Neftalí.',NULL),
(@vid,@bid,35,26,'Los hijos de Zilpá , la sirvienta de Lea , fueron: Gad y Aser. Éstos fueron los hijos de Jacob que nacieron en Padán Aram.',NULL),
(@vid,@bid,35,27,'Jacob llegó a donde estaba su padre Isaac en Mamre , cerca de Quiriat Arba ( es decir, Hebrón ), donde Abraham e Isaac habían vivido como extranjeros.',NULL),
(@vid,@bid,35,28,'Isaac vivió ciento ochenta años .',NULL),
(@vid,@bid,35,29,'Exhaló su último suspiro y murió a una edad muy avanzada, anciano y satisfecho de la vida , y fue a reunirse con sus antepasados. Sus hijos Esaú y Jacob lo sepultaron .',NULL),
(@vid,@bid,36,1,'Ésta es la historia de los descendientes de Esaú , es decir, Edom.',NULL),
(@vid,@bid,36,2,'Esaú tomó por esposas a mujeres cananeas: a Adá , hija de Elón el hitita; a Aholibama, hija de Aná y nieta de Zibeón el heveo ;',NULL),
(@vid,@bid,36,3,'y a Basemat, la hija de Ismael y hermana de Nebaiot.',NULL),
(@vid,@bid,36,4,'Adá le dio a Esaú un hijo llamado Elifaz, y Basemat dio a luz a Reuel .',NULL),
(@vid,@bid,36,5,'Aholibama dio a luz a Jeús, Jalam y Coré . Éstos fueron los hijos de Esaú que nacieron en la tierra de Canaán .',NULL),
(@vid,@bid,36,6,'Esaú tomó a sus esposas, a sus hijos y a sus hijas , y a todas las personas de su familia , junto con su ganado , todos sus animales y todos los bienes que había acumulado en Canaán , y se fue a otra región, lejos de su hermano Jacob .',NULL),
(@vid,@bid,36,7,'Lo hizo porque los bienes de ambos eran tantos que ya no podían vivir juntos . La tierra donde vivían como extranjeros no podía sostenerlos a causa de sus grandes rebaños.',NULL),
(@vid,@bid,36,8,'Así fue como Esaú , es decir, Edom, se estableció en la región montañosa de Seír .',NULL),
(@vid,@bid,36,9,'Ésta es la historia de los descendientes de Esaú , antepasado de los edomitas, en la región montañosa de Seír .',NULL),
(@vid,@bid,36,10,'Éstos son los nombres de los hijos de Esaú : Elifaz, hijo de Adá , la esposa de Esaú ; y Reuel , hijo de Basemat, la esposa de Esaú .',NULL),
(@vid,@bid,36,11,'Los hijos de Elifaz fueron Temán , Omar, Zefo, Gatam y Cenaz.',NULL),
(@vid,@bid,36,12,'Elifaz, el hijo de Esaú , tuvo una concubina llamada Timna , la cual le dio un hijo llamado Amalec . Éstos son los descendientes de Adá , la esposa de Esaú .',NULL),
(@vid,@bid,36,13,'Los hijos de Reuel fueron Nahat, Zera , Sama y Miza. Éstos son los descendientes de Basemat, la esposa de Esaú .',NULL),
(@vid,@bid,36,14,'Éstos son los hijos que Aholibama, esposa de Esaú , hija de Aná y nieta de Zibeón , le dio a Esaú : Jeús, Jalam y Coré .',NULL),
(@vid,@bid,36,15,'Éstos son los jefes de las tribus descendientes de Esaú . De los hijos de Elifaz, el hijo mayor de Esaú , salieron los siguientes jefes: Temán , Omar, Zefo, Cenaz,',NULL),
(@vid,@bid,36,16,'Coré , Gatam y Amalec . Éstos son los jefes que descienden de Elifaz en la tierra de Edom, y son los descendientes de Adá .',NULL),
(@vid,@bid,36,17,'De los descendientes de Reuel , hijo de Esaú , salieron los siguientes jefes: Nahat, Zera , Sama y Miza. Éstos son los jefes que descienden de Reuel en la tierra de Edom, y son los descendientes de Basemat, la esposa de Esaú .',NULL),
(@vid,@bid,36,18,'De los descendientes de Aholibama, la esposa de Esaú , salieron los siguientes jefes: Jeús , Jalam y Coré . Éstos son los jefes que descienden de Aholibama, la esposa de Esaú e hija de Aná .',NULL),
(@vid,@bid,36,19,'Éstos son los hijos de Esaú , es decir, Edom, y éstos son sus jefes.',NULL),
(@vid,@bid,36,20,'Éstos son los hijos de Seír el horeo , los habitantes originales de la tierra: Lotán , Sobal , Zibeón , Aná ,',NULL),
(@vid,@bid,36,21,'Disón , Ezer y Disán. Éstos son los jefes de los horeos, descendientes de Seír en la tierra de Edom.',NULL),
(@vid,@bid,36,22,'Los hijos de Lotán fueron Horí y Hemán. La hermana de Lotán se llamaba Timna .',NULL),
(@vid,@bid,36,23,'Los hijos de Sobal fueron Alván, Manajat, Ebal , Sefo y Onam.',NULL),
(@vid,@bid,36,24,'Los hijos de Zibeón fueron Aja y Aná . Éste es el mismo Aná que descubrió los manantiales de aguas termales en el desierto , mientras cuidaba los burros de su padre Zibeón .',NULL),
(@vid,@bid,36,25,'Los hijos de Aná fueron Disón y Aholibama, la hija de Aná .',NULL),
(@vid,@bid,36,26,'Los hijos de Disón fueron Hemdán , Esbán, Itrán y Querán.',NULL),
(@vid,@bid,36,27,'Los hijos de Ezer fueron Bilhán , Zaaván y Acán.',NULL),
(@vid,@bid,36,28,'Los hijos de Disán fueron Uz y Arán.',NULL),
(@vid,@bid,36,29,'Éstos son los jefes de los horeos: Lotán , Sobal , Zibeón , Aná ,',NULL),
(@vid,@bid,36,30,'Disón , Ezer y Disán. Éstos son los jefes horeos, según sus clanes en la región de Seír .',NULL),
(@vid,@bid,36,31,'Éstos son los reyes que gobernaron en la tierra de Edom antes de que los israelitas tuvieran un rey :',NULL),
(@vid,@bid,36,32,'Bela , hijo de Beor, reinó en Edom. Su ciudad se llamaba Dinaba.',NULL),
(@vid,@bid,36,33,'Cuando murió Bela , lo sucedió en el trono Jobab , que era hijo de Zera y de la ciudad de Bosra .',NULL),
(@vid,@bid,36,34,'Cuando murió Jobab , lo sucedió Jusam, de la tierra de los temanitas.',NULL),
(@vid,@bid,36,35,'Cuando murió Jusam, lo sucedió Hadad, el hijo de Bedad, quien derrotó a Madián en el campo de Moab . Su ciudad se llamaba Avit.',NULL),
(@vid,@bid,36,36,'Cuando murió Hadad, lo sucedió Samlá , de la ciudad de Masreca.',NULL),
(@vid,@bid,36,37,'Cuando murió Samlá , lo sucedió Saúl , de la ciudad de Rejobot, que está junto al río .',NULL),
(@vid,@bid,36,38,'Cuando murió Saúl , lo sucedió Baal Janán, hijo de Acbor.',NULL),
(@vid,@bid,36,39,'Cuando murió Baal Janán, hijo de Acbor, lo sucedió Hadar. Su ciudad se llamaba Pau. Su esposa fue Mehetabel, hija de Matred y nieta de Mezab.',NULL),
(@vid,@bid,36,40,'Éstos son los nombres de los jefes que descienden de Esaú , según sus familias , lugares y nombres : los jefes Timna , Alva, Jetet,',NULL),
(@vid,@bid,36,41,'Aholibama, Ela, Pinón,',NULL),
(@vid,@bid,36,42,'Cenaz, Temán , Mibzar,',NULL),
(@vid,@bid,36,43,'Magdiel e Iram. Éstos son los jefes de Edom, según los lugares donde se establecieron y las tierras que ocuparon. Éste es Esaú , el padre de los edomitas.',NULL),
(@vid,@bid,37,1,'Jacob se quedó a vivir en la tierra de Canaán , donde su padre había vivido como extranjero.',NULL),
(@vid,@bid,37,2,'Ésta es la historia de la familia de Jacob . Cuando José tenía diecisiete años , cuidaba el rebaño junto con sus hermanos, los hijos de Bilhá y de Zilpá , las esposas de su padre. Y José le contaba a su padre lo mal que se portaban sus hermanos.',NULL),
(@vid,@bid,37,3,'Israel amaba a José más que a sus otros hijos , porque lo había tenido en su vejez, y le hizo una túnica de muchos colores.',NULL),
(@vid,@bid,37,4,'Al ver sus hermanos que su padre lo amaba más que a todos ellos , lo odiaron y ni siquiera le podían hablar pacíficamente .',NULL),
(@vid,@bid,37,5,'Un día José tuvo un sueño , y cuando se lo contó a sus hermanos, ellos lo odiaron aún más .',NULL),
(@vid,@bid,37,6,'Les dijo: “ Escuchen el sueño que tuve:',NULL),
(@vid,@bid,37,7,'Resulta que estábamos en el campo atando gavillas de trigo, y de repente mi gavilla se levantó y se quedó derecha, mientras que las gavillas de ustedes la rodeaban y se inclinaban ante la mía”.',NULL),
(@vid,@bid,37,8,'Sus hermanos le respondieron: “¿ De veras crees que vas a reinar sobre nosotros y a dominarnos?” Y lo odiaron todavía más por sus sueños y por sus palabras .',NULL),
(@vid,@bid,37,9,'Después José tuvo otro sueño , y se lo contó a sus hermanos. Les dijo: “Tuve otro sueño , en el que veía que el sol , la luna y once estrellas se inclinaban ante mí ”.',NULL),
(@vid,@bid,37,10,'Cuando se lo contó a su padre y a sus hermanos, su padre lo reprendió diciéndole: “¿ Qué clase de sueño es este ? ¿Acaso tu madre, tus hermanos y yo vamos a venir a inclinarnos hasta el suelo ante ti?”',NULL),
(@vid,@bid,37,11,'Sus hermanos le tenían envidia , pero su padre se quedó pensando en el asunto .',NULL),
(@vid,@bid,37,12,'Un día, sus hermanos se fueron a Siquén para cuidar el rebaño de su padre.',NULL),
(@vid,@bid,37,13,'Entonces Israel le dijo a José : “Tus hermanos están cuidando el rebaño en Siquén. Ven , quiero que vayas a verlos”. José le respondió: “ Aquí estoy, dispuesto a ir ”.',NULL),
(@vid,@bid,37,14,'Israel le dijo: “ Ve a ver cómo están tus hermanos y el rebaño , y tráeme noticias”. Así que lo envió desde el valle de Hebrón , y José llegó a Siquén.',NULL),
(@vid,@bid,37,15,'Mientras José andaba perdido por el campo , un hombre lo encontró y le preguntó : “¿ Qué estás buscando ?”',NULL),
(@vid,@bid,37,16,'Él respondió: “Estoy buscando a mis hermanos. Por favor, dime dónde están cuidando el rebaño”.',NULL),
(@vid,@bid,37,17,'El hombre le dijo: “ Ya se fueron de aquí . Los oí decir que se iban a Dotán”. Entonces José fue a buscar a sus hermanos y los encontró en Dotán.',NULL),
(@vid,@bid,37,18,'Ellos lo vieron de lejos , y antes de que se acercara, hicieron planes para matarlo .',NULL),
(@vid,@bid,37,19,'Se dijeron unos a otros: “¡Ahí viene el de los sueños !',NULL),
(@vid,@bid,37,20,'Vengan, vamos a matarlo y a echarlo en uno de estos pozos. Luego diremos que un animal salvaje se lo comió. ¡ Ya veremos en qué terminan sus sueños !”',NULL),
(@vid,@bid,37,21,'Al oír esto, Rubén intentó salvarlo de sus manos y les dijo: “ No le quitemos la vida ”.',NULL),
(@vid,@bid,37,22,'Y añadió: “ No derramen sangre . Arrójenlo en este pozo que está en el desierto , pero no le hagan daño”. Rubén decía esto con la intención de rescatarlo después y devolvérselo a su padre.',NULL),
(@vid,@bid,37,23,'Cuando José llegó a donde estaban sus hermanos, ellos le quitaron la túnica de muchos colores que llevaba puesta;',NULL),
(@vid,@bid,37,24,'lo agarraron y lo echaron al pozo. El pozo estaba vacío, no tenía agua .',NULL),
(@vid,@bid,37,25,'Luego se sentaron a comer, y al levantar la vista, vieron venir de Galaad una caravana de ismaelitas. Sus camellos venían cargados de especias, bálsamo y mirra, que llevaban a Egipto .',NULL),
(@vid,@bid,37,26,'Entonces Judá les dijo a sus hermanos: “¿ Qué ganamos con matar a nuestro hermano y ocultar su muerte?',NULL),
(@vid,@bid,37,27,'Vengan, vamos a vendérselo a los ismaelitas. No le pongamos la mano encima, porque al fin y al cabo es nuestro hermano, de nuestra misma sangre”. Y sus hermanos estuvieron de acuerdo.',NULL),
(@vid,@bid,37,28,'Cuando pasaron los mercaderes madianitas, los hermanos sacaron a José del pozo y se lo vendieron a los ismaelitas por veinte monedas de plata . Así los mercaderes se llevaron a José a Egipto .',NULL),
(@vid,@bid,37,29,'Cuando Rubén regresó al pozo y vio que José ya no estaba allí, se rasgó la ropa en señal de dolor.',NULL),
(@vid,@bid,37,30,'Volvió a donde estaban sus hermanos y les dijo: “¡El muchacho ya no está! Y ahora, ¿qué voy a hacer?”',NULL),
(@vid,@bid,37,31,'Entonces ellos tomaron la túnica de José , mataron un cabrito, y empaparon la túnica con la sangre .',NULL),
(@vid,@bid,37,32,'Mandaron la túnica de muchos colores a su padre, con este mensaje: “Encontramos esto . Fíjate bien si es la túnica de tu hijo o no ”.',NULL),
(@vid,@bid,37,33,'Jacob la reconoció y exclamó: “¡Es la túnica de mi hijo ! Un animal salvaje se lo ha comido. ¡Seguramente José fue despedazado!”',NULL),
(@vid,@bid,37,34,'Jacob se rasgó la ropa , se vistió de luto y lloró por su hijo durante muchos días .',NULL),
(@vid,@bid,37,35,'Todos sus hijos y sus hijas intentaron consolarlo, pero él no se dejó consolar, sino que decía: “ Llorando bajaré al Seol para reunirme con mi hijo ”. Y su padre siguió llorándolo.',NULL),
(@vid,@bid,37,36,'Mientras tanto, en Egipto , los madianitas le vendieron a José a Potifar, que era un funcionario del faraón y capitán de la guardia.',NULL),
(@vid,@bid,38,1,'En aquel tiempo , Judá se separó de sus hermanos y se fue a vivir cerca de un hombre de Adulam, llamado Hira .',NULL),
(@vid,@bid,38,2,'Allí Judá conoció a la hija de un cananeo llamado Súa . Se casó con ella y tuvo relaciones con ella .',NULL),
(@vid,@bid,38,3,'Ella quedó embarazada y dio a luz un hijo , al que llamó Er .',NULL),
(@vid,@bid,38,4,'Volvió a quedar embarazada y tuvo otro hijo , al que llamó Onán.',NULL),
(@vid,@bid,38,5,'Quedó embarazada de nuevo y dio a luz un tercer hijo , al que llamó Selá . Judá estaba en Quezib cuando ella dio a luz.',NULL),
(@vid,@bid,38,6,'Judá le consiguió una esposa a su hijo mayor, Er . Ella se llamaba Tamar.',NULL),
(@vid,@bid,38,7,'Pero Er , el hijo mayor de Judá , era muy malo a los ojos de Yahvé; por eso Yahvé le quitó la vida.',NULL),
(@vid,@bid,38,8,'Entonces Judá le dijo a Onán: “Cásate con la viuda de tu hermano para cumplir con tu deber de cuñado, y dale descendencia a tu hermano”.',NULL),
(@vid,@bid,38,9,'Pero como Onán sabía que los hijos que nacieran no serían considerados suyos, cada vez que tenía relaciones con la esposa de su hermano, derramaba el semen en el suelo para no darle descendencia a su hermano.',NULL),
(@vid,@bid,38,10,'Lo que hacía le desagradó mucho a Yahvé, así que a él también le quitó la vida.',NULL),
(@vid,@bid,38,11,'Entonces Judá le dijo a su nuera Tamar: “ Quédate a vivir como viuda en la casa de tu padre hasta que mi hijo Selá crezca”. Judá pensaba: “ No vaya a ser que él también muera como sus hermanos”. Así que Tamar se fue a vivir a la casa de su padre.',NULL),
(@vid,@bid,38,12,'Pasó mucho tiempo y murió la hija de Súa , la esposa de Judá . Cuando Judá terminó de guardar luto, subió a Timnat, junto con su amigo Hira el adulamita, para ver a los que esquilaban sus ovejas .',NULL),
(@vid,@bid,38,13,'Alguien le avisó a Tamar: “ Mira , tu suegro va subiendo a Timnat para esquilar sus ovejas ”.',NULL),
(@vid,@bid,38,14,'Como ella había visto que Selá ya había crecido y , sin embargo, no se la habían dado por esposa, se quitó la ropa de viuda, se cubrió el rostro con un velo para que no la reconocieran, y se sentó a la entrada de Enaim, en el camino que va hacia Timnat.',NULL),
(@vid,@bid,38,15,'Cuando Judá la vio , pensó que era una prostituta, pues llevaba el rostro cubierto.',NULL),
(@vid,@bid,38,16,'Sin saber que era su propia nuera , se acercó a ella en el camino y le propuso: “Ven, déjame acostarme contigo”. Ella le preguntó: “¿ Y qué me vas a dar por acostarte conmigo?”',NULL),
(@vid,@bid,38,17,'Él le contestó: “ Te enviaré un cabrito de mi rebaño ”. Ella le dijo: “Está bien, pero tienes que darme una prenda en garantía hasta que me lo envíes”.',NULL),
(@vid,@bid,38,18,'“¿ Qué prenda quieres que te dé ?”, le preguntó Judá. “Tu sello, tu cordón y el bastón que llevas en la mano ”, respondió ella. Él se los entregó y se acostó con ella, y ella quedó embarazada de él.',NULL),
(@vid,@bid,38,19,'Luego ella se levantó y se fue . Se quitó el velo y volvió a ponerse su ropa de viuda.',NULL),
(@vid,@bid,38,20,'Judá envió el cabrito por medio de su amigo el adulamita, para recuperar la prenda que le había dejado a la mujer, pero no la encontró.',NULL),
(@vid,@bid,38,21,'Entonces les preguntó a los hombres de ese lugar : “¿ Dónde está la prostituta que se sentaba en Enaim, junto al camino ?” Ellos le respondieron: “ Por aquí no ha habido ninguna prostituta”.',NULL),
(@vid,@bid,38,22,'Así que el adulamita regresó a donde estaba Judá y le dijo: “ No pude encontrarla; además , los hombres del lugar me dijeron que allí no ha habido ninguna prostituta”.',NULL),
(@vid,@bid,38,23,'Judá comentó: “¡ Pues que se quede con esas cosas! No vayamos a hacer el ridículo. Yo cumplí con enviarle este cabrito , pero tú no pudiste encontrarla”.',NULL),
(@vid,@bid,38,24,'Pasaron unos tres meses , y alguien le fue a decir a Judá : “Tu nuera Tamar se ha prostituido, y a causa de eso ahora está embarazada”. Entonces Judá ordenó: “¡Sáquenla y quémenla viva!”',NULL),
(@vid,@bid,38,25,'Cuando la sacaban para quemarla, ella le envió este mensaje a su suegro : “Estoy embarazada del dueño de estas cosas”. Y añadió: “Por favor, fíjate bien de quién son este sello, este cordón y este bastón”.',NULL),
(@vid,@bid,38,26,'Judá los reconoció y declaró: “ Ella es más justa que yo , porque no cumplí con dársela por esposa a mi hijo Selá ”. Y nunca más volvió a tener relaciones con ella .',NULL),
(@vid,@bid,38,27,'Cuando llegó el momento de dar a luz, resultó que Tamar llevaba gemelos en su vientre.',NULL),
(@vid,@bid,38,28,'Durante el parto, uno de ellos sacó una mano , y la partera la tomó y le ató un hilo rojo, diciendo: “ Éste fue el primero en salir ”.',NULL),
(@vid,@bid,38,29,'Pero él volvió a meter la mano , y el que salió primero fue su hermano. Entonces la partera exclamó: “¡ Cómo te has abierto paso!” Por eso le pusieron por nombre Fares.',NULL),
(@vid,@bid,38,30,'Después salió su hermano, el que tenía el hilo rojo en la mano , y le pusieron por nombre Zera .',NULL),
(@vid,@bid,39,1,'Cuando José fue llevado a Egipto , un egipcio llamado Potifar, que era funcionario del faraón y capitán de la guardia, se lo compró a los ismaelitas que lo habían llevado hasta allá .',NULL),
(@vid,@bid,39,2,'Pero Yahvé estaba con José , y él llegó a ser un hombre muy próspero, y vivía en la casa de su amo el egipcio .',NULL),
(@vid,@bid,39,3,'Su amo se dio cuenta de que Yahvé estaba con José, y de que Yahvé hacía prosperar todo lo que él emprendía.',NULL),
(@vid,@bid,39,4,'Así José se ganó la confianza de su amo y llegó a ser su sirviente personal. Potifar lo nombró administrador de su casa y dejó a su cargo todo lo que tenía .',NULL),
(@vid,@bid,39,5,'Desde el momento en que lo nombró administrador de su casa y de todos sus bienes, Yahvé bendijo la casa del egipcio por causa de José . La bendición de Yahvé se extendió a todo lo que tenía , tanto en la casa como en el campo .',NULL),
(@vid,@bid,39,6,'Así que Potifar dejó todo lo que tenía en manos de José , y ya no se preocupaba de nada , más que de la comida que se servía en su mesa. Además , José era muy apuesto y de buena presencia .',NULL),
(@vid,@bid,39,7,'Después de algún tiempo, la esposa de su amo se fijó en José y le dijo: “ Acuéstate conmigo ”.',NULL),
(@vid,@bid,39,8,'Pero él se negó y le contestó a la esposa de su amo: “Mire, mi señor confía tanto en mí que no se preocupa de nada de lo que pasa en la casa , sino que ha puesto a mi cargo todo lo que tiene .',NULL),
(@vid,@bid,39,9,'En esta casa no hay nadie que tenga más autoridad que yo . Él no me ha negado nada , excepto a usted, porque es su esposa. ¿ Cómo podría yo cometer semejante maldad y pecar contra Dios?”',NULL),
(@vid,@bid,39,10,'Y aunque ella le insistía a José todos los días , él se negaba a acostarse o a estar con ella.',NULL),
(@vid,@bid,39,11,'Pero un día , cuando José entró en la casa para cumplir con sus deberes, y no había ningún sirviente allí adentro ,',NULL),
(@vid,@bid,39,12,'ella lo agarró de la ropa y le dijo: “¡ Acuéstate conmigo !” Pero José le dejó su ropa en las manos y salió corriendo de la casa.',NULL),
(@vid,@bid,39,13,'Cuando ella vio que José había salido corriendo y le había dejado su ropa en las manos ,',NULL),
(@vid,@bid,39,14,'llamó a los sirvientes de la casa y les dijo: “¡Miren! Mi esposo nos ha traído a un hebreo para que se aproveche de nosotros . Entró a mi cuarto para acostarse conmigo , pero yo grité con todas mis fuerzas.',NULL),
(@vid,@bid,39,15,'Al oír que yo levantaba la voz y gritaba, dejó su ropa a mi lado y salió corriendo de la casa”.',NULL),
(@vid,@bid,39,16,'Ella guardó la ropa de José hasta que su amo regresó a casa ,',NULL),
(@vid,@bid,39,17,'y le contó la misma historia: “Ese esclavo hebreo que nos trajiste entró a mi cuarto para aprovecharse de mí.',NULL),
(@vid,@bid,39,18,'Pero cuando yo levanté la voz y grité, él dejó su ropa a mi lado y salió corriendo”.',NULL),
(@vid,@bid,39,19,'Cuando el amo escuchó la historia de su esposa, que le decía: “ Así me trató tu esclavo”, se enfureció muchísimo.',NULL),
(@vid,@bid,39,20,'Agarró a José y lo metió en la cárcel, en el lugar donde estaban los presos del rey . Y José se quedó allí en la cárcel.',NULL),
(@vid,@bid,39,21,'Pero Yahvé estaba con José y le mostró su bondad, haciendo que se ganara la simpatía del jefe de la cárcel.',NULL),
(@vid,@bid,39,22,'El jefe de la cárcel puso a José a cargo de todos los presos que estaban allí , de modo que José era responsable de todo lo que se hacía en la cárcel.',NULL),
(@vid,@bid,39,23,'El jefe de la cárcel no supervisaba nada de lo que estaba al cuidado de José, porque Yahvé estaba con él , y Yahvé hacía prosperar todo lo que José emprendía.',NULL),
(@vid,@bid,40,1,'Tiempo después , el copero y el panadero del rey de Egipto ofendieron a su señor.',NULL),
(@vid,@bid,40,2,'El faraón se enojó con estos dos funcionarios, es decir, con el jefe de los coperos y el jefe de los panaderos,',NULL),
(@vid,@bid,40,3,'y los mandó a la cárcel que estaba en la casa del capitán de la guardia, el mismo lugar donde José estaba preso.',NULL),
(@vid,@bid,40,4,'El capitán de la guardia se los encargó a José , y él los atendía. Después de que pasaron algún tiempo en la cárcel ,',NULL),
(@vid,@bid,40,5,'una misma noche , tanto el copero como el panadero del rey de Egipto tuvieron un sueño , y cada sueño tenía su propio significado.',NULL),
(@vid,@bid,40,6,'A la mañana siguiente, cuando José fue a verlos, los notó muy preocupados.',NULL),
(@vid,@bid,40,7,'Entonces les preguntó a los funcionarios del faraón que estaban presos con él en la casa de su amo: “¿ Por qué se ven tan tristes hoy ?”',NULL),
(@vid,@bid,40,8,'Ellos le respondieron: “Anoche tuvimos un sueño , y no hay nadie que nos lo pueda interpretar”. José les dijo: “¿Acaso las interpretaciones no provienen de Dios? Por favor, cuéntenmelo”.',NULL),
(@vid,@bid,40,9,'El jefe de los coperos le contó su sueño a José : “En mi sueño , veía una vid delante de mí .',NULL),
(@vid,@bid,40,10,'La vid tenía tres ramas. De pronto comenzó a brotar y a florecer, hasta que sus racimos dieron uvas maduras.',NULL),
(@vid,@bid,40,11,'Yo tenía la copa del faraón en la mano ; entonces tomaba las uvas , las exprimía en la copa y se la entregaba al faraón en su propia mano ”.',NULL),
(@vid,@bid,40,12,'José le dijo: “ Ésta es la interpretación: las tres ramas representan tres días .',NULL),
(@vid,@bid,40,13,'Dentro de tres días el faraón te perdonará y te devolverá tu cargo , y volverás a entregarle la copa en la mano , tal como lo hacías antes cuando eras su copero.',NULL),
(@vid,@bid,40,14,'Pero cuando te vaya bien , por favor acuérdate de mí . Te ruego que me hagas el favor de hablarle de mí al faraón para que me saque de este lugar.',NULL),
(@vid,@bid,40,15,'A mí me secuestraron de la tierra de los hebreos , y aquí no he hecho nada para merecer que me metan en este calabozo”.',NULL),
(@vid,@bid,40,16,'Al ver el jefe de los panaderos que la interpretación había sido favorable, le dijo a José : “ Yo también tuve un sueño . Veía tres canastas de pan blanco sobre mi cabeza .',NULL),
(@vid,@bid,40,17,'En la canasta de arriba había toda clase de repostería para el faraón , pero las aves se comían todo lo que había en la canasta que llevaba sobre mi cabeza ”.',NULL),
(@vid,@bid,40,18,'José le respondió : “ Ésta es la interpretación: las tres canastas representan tres días .',NULL),
(@vid,@bid,40,19,'Dentro de tres días el faraón te mandará decapitar y te colgará de un árbol , y las aves se comerán tu carne ”.',NULL),
(@vid,@bid,40,20,'Al tercer día se celebraba el cumpleaños del faraón , así que él ofreció un banquete para todos sus funcionarios. En presencia de todos ellos , mandó sacar de la cárcel al jefe de los coperos y al jefe de los panaderos.',NULL),
(@vid,@bid,40,21,'Al jefe de los coperos le restituyó su cargo, de modo que volvió a entregarle la copa en la mano al faraón .',NULL),
(@vid,@bid,40,22,'Pero al jefe de los panaderos lo mandó ahorcar, tal como José se lo había interpretado.',NULL),
(@vid,@bid,40,23,'Sin embargo, el jefe de los coperos no volvió a acordarse de José , sino que se olvidó de él por completo.',NULL),
(@vid,@bid,41,1,'Pasaron dos años completos, y un día el faraón tuvo un sueño. Soñó que estaba de pie junto al río Nilo,',NULL),
(@vid,@bid,41,2,'y que del río subían siete vacas hermosas y muy gordas, las cuales se pusieron a pastar entre los juncos de la orilla.',NULL),
(@vid,@bid,41,3,'Detrás de ellas subieron del río otras siete vacas , pero éstas eran muy feas y flacas, y se pararon junto a las primeras vacas en la orilla del río .',NULL),
(@vid,@bid,41,4,'¡ Y resulta que las vacas feas y flacas se comieron a las siete vacas hermosas y gordas! En ese momento el faraón se despertó .',NULL),
(@vid,@bid,41,5,'Volvió a dormirse y tuvo un segundo sueño. Soñó que siete espigas de trigo, llenas y hermosas , crecían de un solo tallo.',NULL),
(@vid,@bid,41,6,'Detrás de ellas brotaron otras siete espigas , pero éstas eran delgadas y estaban resecas por el viento del este.',NULL),
(@vid,@bid,41,7,'¡ Y las espigas delgadas se tragaron a las siete espigas gruesas y llenas ! El faraón se despertó y se dio cuenta de que había sido un sueño .',NULL),
(@vid,@bid,41,8,'A la mañana siguiente, el faraón amaneció muy preocupado, así que mandó llamar a todos los adivinos y sabios de Egipto . Les contó sus sueños , pero no hubo nadie que se los pudiera interpretar.',NULL),
(@vid,@bid,41,9,'Entonces el jefe de los coperos se dirigió al faraón y le dijo : “ Hoy debo confesar mis faltas .',NULL),
(@vid,@bid,41,10,'Hace tiempo, el faraón se enojó con sus servidores, y nos metió en la cárcel de la casa del capitán de la guardia, a mí y al jefe de los panaderos.',NULL),
(@vid,@bid,41,11,'Una noche , los dos tuvimos un sueño , y cada sueño tenía su propio significado.',NULL),
(@vid,@bid,41,12,'Con nosotros estaba un joven hebreo , que era esclavo del capitán de la guardia. Le contamos nuestros sueños , y él nos los interpretó, dándole a cada uno el significado de su sueño .',NULL),
(@vid,@bid,41,13,'Y las cosas sucedieron tal como él nos las había interpretado: a mí se me devolvió mi cargo, y al otro lo ahorcaron”.',NULL),
(@vid,@bid,41,14,'Entonces el faraón mandó llamar a José . Lo sacaron rápidamente del calabozo; él se afeitó, se cambió de ropa y se presentó ante el faraón .',NULL),
(@vid,@bid,41,15,'El faraón le dijo a José : “Tuve un sueño y no hay nadie que pueda interpretarlo. Pero me han dicho que tú sólo necesitas oír un sueño para interpretarlo”.',NULL),
(@vid,@bid,41,16,'José le respondió : “Yo no puedo hacerlo, pero Dios le dará al faraón una respuesta favorable”.',NULL),
(@vid,@bid,41,17,'Entonces el faraón le contó su sueño a José : “ En mi sueño , yo estaba de pie a la orilla del río Nilo,',NULL),
(@vid,@bid,41,18,'y del río subían siete vacas hermosas y muy gordas, las cuales se pusieron a pastar entre los juncos.',NULL),
(@vid,@bid,41,19,'Detrás de ellas subieron otras siete vacas , tan flacas , huesudas y de aspecto tan horrible, que jamás había visto vacas tan feas en toda la tierra de Egipto .',NULL),
(@vid,@bid,41,20,'¡ Y las vacas flacas y feas se comieron a las siete primeras vacas gordas!',NULL),
(@vid,@bid,41,21,'Pero después de habérselas comido, nadie se habría dado cuenta, porque seguían viéndose tan flacas y horribles como antes . En ese momento me desperté.',NULL),
(@vid,@bid,41,22,'Volví a dormirme, y en mi sueño vi que siete espigas de trigo, llenas y hermosas , crecían de un solo tallo.',NULL),
(@vid,@bid,41,23,'Detrás de ellas brotaron otras siete espigas , pero éstas eran delgadas, marchitas y resecas por el viento del este.',NULL),
(@vid,@bid,41,24,'¡ Y las espigas delgadas se tragaron a las siete espigas hermosas ! Les he contado esto a los adivinos, pero no hay nadie que me lo pueda explicar”.',NULL),
(@vid,@bid,41,25,'Entonces José le dijo al faraón : “ Los dos sueños del faraón significan lo mismo . Dios le ha mostrado al faraón lo que está a punto de hacer .',NULL),
(@vid,@bid,41,26,'Las siete vacas hermosas representan siete años , y las siete espigas hermosas también representan siete años ; los dos sueños son uno solo .',NULL),
(@vid,@bid,41,27,'Las siete vacas flacas y feas que subieron después , y las siete espigas delgadas y resecas por el viento del este , también representan siete años , pero serán siete años de hambre .',NULL),
(@vid,@bid,41,28,'Es tal como le he dicho al faraón : Dios le ha mostrado lo que está a punto de hacer .',NULL),
(@vid,@bid,41,29,'Vienen siete años de gran abundancia en toda la tierra de Egipto .',NULL),
(@vid,@bid,41,30,'Pero después de ellos , vendrán siete años de hambre . Se olvidará toda la abundancia en la tierra de Egipto , y el hambre arruinará al país.',NULL),
(@vid,@bid,41,31,'El hambre que vendrá será tan terrible que nadie volverá a acordarse de los tiempos de abundancia en la tierra.',NULL),
(@vid,@bid,41,32,'El hecho de que el faraón haya tenido el sueño dos veces significa que Dios ya ha tomado la decisión, y que la llevará a cabo muy pronto .',NULL),
(@vid,@bid,41,33,'“ Por lo tanto , el faraón debería buscar a un hombre inteligente y sabio , para ponerlo a cargo de la tierra de Egipto .',NULL),
(@vid,@bid,41,34,'Además , el faraón debería nombrar inspectores en todo el país, para que cobren la quinta parte de las cosechas de Egipto durante los siete años de abundancia.',NULL),
(@vid,@bid,41,35,'Que recolecten todo el alimento posible durante estos años buenos que vienen, y que bajo la autoridad del faraón almacenen el grano en las ciudades y lo guarden como reserva.',NULL),
(@vid,@bid,41,36,'Este alimento servirá de reserva para el país durante los siete años de hambre que habrá en la tierra de Egipto , para que la gente no muera de hambre ”.',NULL),
(@vid,@bid,41,37,'La propuesta le pareció muy buena al faraón y a todos sus funcionarios.',NULL),
(@vid,@bid,41,38,'Así que el faraón les preguntó: “¿Acaso podremos encontrar a otro hombre como éste , que tenga el espíritu de Dios?”',NULL),
(@vid,@bid,41,39,'Y a José le dijo: “Puesto que Dios te ha revelado todo esto , no hay nadie más inteligente y sabio que tú.',NULL),
(@vid,@bid,41,40,'Tú estarás a cargo de mi casa , y todo mi pueblo obedecerá tus órdenes. Sólo yo tendré más autoridad que tú, porque soy el rey”.',NULL),
(@vid,@bid,41,41,'El faraón añadió: “ Desde este momento, te pongo a cargo de toda la tierra de Egipto ”.',NULL),
(@vid,@bid,41,42,'Luego, el faraón se quitó el anillo con su sello oficial y se lo puso a José en la mano . Lo mandó vestir con ropas de lino fino y le puso un collar de oro en el cuello .',NULL),
(@vid,@bid,41,43,'Lo hizo subir al segundo carruaje en importancia, y los guardias gritaban delante de él : “¡Abran paso!” Así fue como José quedó a cargo de toda la tierra de Egipto .',NULL),
(@vid,@bid,41,44,'Y el faraón le dijo a José : “Yo soy el faraón , pero sin tu permiso nadie levantará una mano ni moverá un pie en toda la tierra de Egipto ”.',NULL),
(@vid,@bid,41,45,'El faraón le puso a José el nombre egipcio de Zafnat Panea, y le dio por esposa a Asenat, que era hija de Potifera, el sacerdote de la ciudad de On. Y José salió a inspeccionar toda la tierra de Egipto .',NULL),
(@vid,@bid,41,46,'José tenía treinta años cuando comenzó a servir al faraón , rey de Egipto . Salió de la presencia del rey y recorrió todo el país.',NULL),
(@vid,@bid,41,47,'Durante los siete años de abundancia, la tierra produjo grandes cosechas.',NULL),
(@vid,@bid,41,48,'José recolectó todo el alimento producido en Egipto durante esos siete años , y lo almacenó en las ciudades . En cada ciudad guardó el alimento de los campos vecinos.',NULL),
(@vid,@bid,41,49,'Fue tanto el trigo que José almacenó, que parecía la arena del mar ; era tanto que hasta dejó de contarlo o llevar un registro.',NULL),
(@vid,@bid,41,50,'Antes de que llegaran los años de hambre , José tuvo dos hijos con Asenat, la hija de Potifera, el sacerdote de On.',NULL),
(@vid,@bid,41,51,'Al primero lo llamó Manasés , porque dijo: “Dios me ha hecho olvidar de todos mis sufrimientos y de toda la familia de mi padre”.',NULL),
(@vid,@bid,41,52,'Al segundo lo llamó Efraín, porque dijo: “Dios me ha hecho dar frutos en la tierra donde he sufrido”.',NULL),
(@vid,@bid,41,53,'Finalmente, los siete años de abundancia en la tierra de Egipto llegaron a su fin,',NULL),
(@vid,@bid,41,54,'y comenzaron los siete años de hambre , tal como José lo había anunciado. Hubo hambre en todos los demás países, pero en todo Egipto había alimento.',NULL),
(@vid,@bid,41,55,'Cuando el hambre comenzó a sentirse en todo Egipto , el pueblo le rogó al faraón que les diera de comer. Pero el faraón les dijo a todos los egipcios : “ Vayan a ver a José , y hagan todo lo que él les diga”.',NULL),
(@vid,@bid,41,56,'Como el hambre se había extendido por toda la tierra, José abrió las bodegas y les vendió trigo a los egipcios , pues la situación en Egipto era muy grave.',NULL),
(@vid,@bid,41,57,'Y de todos los países llegaba gente a Egipto para comprarle trigo a José , porque el hambre en todo el mundo era terrible.',NULL),
(@vid,@bid,42,1,'Cuando Jacob se enteró de que había trigo en Egipto , les dijo a sus hijos : “¿ Por qué se quedan ahí mirándose unos a otros?”',NULL),
(@vid,@bid,42,2,'Y añadió: “He oído que hay trigo en Egipto . Bajen allá y compren trigo para nosotros, para que podamos sobrevivir y no muramos ”.',NULL),
(@vid,@bid,42,3,'Así que los diez hermanos de José bajaron a Egipto para comprar trigo .',NULL),
(@vid,@bid,42,4,'Pero Jacob no dejó que Benjamín , el hermano de José , se fuera con ellos, porque pensó: “ No vaya a ser que le pase alguna desgracia”.',NULL),
(@vid,@bid,42,5,'Entre los que iban a comprar trigo se encontraban los hijos de Israel , pues el hambre también había llegado a la tierra de Canaán .',NULL),
(@vid,@bid,42,6,'Como José era el gobernador del país, era él quien le vendía el trigo a toda la gente . Así que los hermanos de José llegaron y se inclinaron ante él , con el rostro hasta el suelo.',NULL),
(@vid,@bid,42,7,'En cuanto José vio a sus hermanos, los reconoció; pero fingió ser un extraño y les habló con dureza: “¿De dónde vienen?”, les preguntó. Ellos le respondieron : “Venimos de la tierra de Canaán , para comprar alimentos”.',NULL),
(@vid,@bid,42,8,'Aunque José reconoció a sus hermanos, ellos no lo reconocieron a él .',NULL),
(@vid,@bid,42,9,'Entonces José se acordó de los sueños que había tenido acerca de ellos, y les dijo: “¡Ustedes son espías ! Han venido a ver cuáles son los puntos débiles de nuestro país”.',NULL),
(@vid,@bid,42,10,'Ellos le respondieron: “¡ No , señor nuestro! Sus siervos sólo han venido a comprar alimentos.',NULL),
(@vid,@bid,42,11,'Todos nosotros somos hijos de un mismo padre. Somos hombres honrados; sus siervos jamás han sido espías ”.',NULL),
(@vid,@bid,42,12,'Pero él les insistió: “¡Mienten! Ustedes han venido a ver los puntos débiles de nuestro país”.',NULL),
(@vid,@bid,42,13,'Ellos le explicaron: “ Nosotros , sus siervos , somos doce hermanos, hijos de un mismo padre en la tierra de Canaán . Nuestro hermano menor se quedó hoy con nuestro padre, y el otro ya ha muerto”.',NULL),
(@vid,@bid,42,14,'José les respondió: “ Es tal como les dije : ¡ustedes son espías !',NULL),
(@vid,@bid,42,15,'Y de esta manera los voy a poner a prueba: ¡Juro por la vida del faraón que no saldrán de aquí hasta que su hermano menor venga a este lugar!',NULL),
(@vid,@bid,42,16,'Manden a uno de ustedes a buscar a su hermano, mientras los demás se quedan en la cárcel. Así comprobaremos si lo que dicen es verdad; y si no , ¡ por la vida del faraón , es porque son espías !”',NULL),
(@vid,@bid,42,17,'Y los metió a todos juntos en la cárcel durante tres días .',NULL),
(@vid,@bid,42,18,'Al tercer día , José les dijo: “ Hagan lo siguiente, y conservarán la vida , pues yo temo a Dios.',NULL),
(@vid,@bid,42,19,'Si realmente son hombres honrados, que uno de ustedes se quede preso en la cárcel , mientras los demás se llevan el trigo para calmar el hambre en sus casas .',NULL),
(@vid,@bid,42,20,'Pero tendrán que traerme a su hermano menor . De esa manera podré comprobar si dicen la verdad , y no morirán ”. Ellos estuvieron de acuerdo.',NULL),
(@vid,@bid,42,21,'Y se decían unos a otros: “ La verdad es que nos estamos ganando este castigo por lo que le hicimos a nuestro hermano. Vimos su gran angustia cuando nos rogaba por su vida , pero no le hicimos caso. ¡ Por eso nos ha sobrevenido esta desgracia!”',NULL),
(@vid,@bid,42,22,'Entonces Rubén les reclamó: “¿Acaso no les dije que no le hicieran daño al muchacho? Pero ustedes no me escucharon . ¡ Ahora tenemos que pagar por su sangre !”',NULL),
(@vid,@bid,42,23,'Ellos no sabían que José les estaba entendiendo, porque había estado hablando con ellos por medio de un intérprete.',NULL),
(@vid,@bid,42,24,'José se alejó de ellos y se puso a llorar. Luego regresó, habló de nuevo con ellos , y ordenó que tomaran a Simeón y lo ataran frente a todos.',NULL),
(@vid,@bid,42,25,'Después José mandó que les llenaran sus costales con trigo , que pusieran el dinero de cada uno dentro de su propio costal, y que les dieran provisiones para el viaje . Así se hizo con ellos.',NULL),
(@vid,@bid,42,26,'Los hermanos cargaron el trigo en sus burros y emprendieron el viaje.',NULL),
(@vid,@bid,42,27,'Por la noche, al llegar al lugar donde iban a acampar, uno de ellos abrió su costal para darle de comer a su burro, ¡y vio que su dinero estaba en la boca del costal!',NULL),
(@vid,@bid,42,28,'Y les dijo a sus hermanos: “¡Me devolvieron mi dinero ! ¡ Aquí está , dentro de mi costal!” Se les heló la sangre y , temblando de miedo, se dijeron unos a otros: “¿ Qué es esto que Dios nos ha hecho ?”',NULL),
(@vid,@bid,42,29,'Cuando llegaron a la tierra de Canaán , a donde estaba su padre Jacob , le contaron todo lo que les había pasado:',NULL),
(@vid,@bid,42,30,'“Aquel hombre, el gobernador del país, nos habló con dureza y nos trató como si fuéramos espías .',NULL),
(@vid,@bid,42,31,'Nosotros le dijimos: ‘ Somos hombres honrados, nunca hemos sido espías .',NULL),
(@vid,@bid,42,32,'Somos doce hermanos, hijos de nuestro padre. Uno ya murió, y el menor se quedó hoy con nuestro padre en la tierra de Canaán ’.',NULL),
(@vid,@bid,42,33,'Pero ese hombre, el gobernador del país, nos contestó: ‘ Con esto podré comprobar si realmente son hombres honrados: dejen a uno de ustedes conmigo, llévense trigo para calmar el hambre en sus casas , y váyanse.',NULL),
(@vid,@bid,42,34,'Tráiganme a su hermano menor . Así sabré que no son espías , sino hombres honrados. Entonces les devolveré a su hermano y podrán hacer negocios en este país’”.',NULL),
(@vid,@bid,42,35,'Y resulta que , al vaciar sus costales, ¡cada uno encontró su paquete de dinero dentro de su costal! Cuando ellos y su padre vieron los paquetes de dinero , se asustaron muchísimo.',NULL),
(@vid,@bid,42,36,'Su padre Jacob les reclamó: “¡Ustedes me van a dejar sin hijos! José ya no está , Simeón ya no está , ¡ y ahora se quieren llevar a Benjamín ! ¡ Todo está en mi contra !”',NULL),
(@vid,@bid,42,37,'Rubén le dijo a su padre: “ Si no te lo traigo de regreso, puedes matar a mis dos hijos . Déjalo a mi cuidado , que yo te lo devolveré”.',NULL),
(@vid,@bid,42,38,'Pero Jacob le contestó: “ Mi hijo no irá con ustedes. Su hermano ya murió , y solo me queda él . Si le pasa alguna desgracia en el viaje que van a emprender, ¡harán que este viejo baje al Seol lleno de dolor !”',NULL),
(@vid,@bid,43,1,'El hambre era muy grave en toda la región.',NULL),
(@vid,@bid,43,2,'Cuando se acabaron el trigo que habían traído de Egipto , su padre les dijo: “ Vuelvan allá y cómprennos un poco más de comida”.',NULL),
(@vid,@bid,43,3,'Pero Judá le advirtió: “Aquel hombre nos advirtió muy seriamente: ‘ No volverán a ver mi rostro si no traen a su hermano con ustedes’.',NULL),
(@vid,@bid,43,4,'Si dejas que nuestro hermano vaya con nosotros, bajaremos a comprarte comida.',NULL),
(@vid,@bid,43,5,'Pero si no lo dejas ir , no bajaremos; porque aquel hombre nos dijo: ‘ No volverán a ver mi rostro si no traen a su hermano con ustedes’”.',NULL),
(@vid,@bid,43,6,'Israel se quejó: “¿ Por qué me trataron tan mal ? ¿ Por qué le dijeron a ese hombre que tenían otro hermano?”',NULL),
(@vid,@bid,43,7,'Ellos le respondieron: “ Es que el hombre nos preguntó directamente por nosotros y por nuestra familia. Nos dijo : ‘¿ Todavía vive su padre? ¿ Tienen algún otro hermano?’ Nosotros sólo contestamos a sus preguntas . ¿ Cómo íbamos a saber que nos pediría que lleváramos a nuestro hermano?”',NULL),
(@vid,@bid,43,8,'Entonces Judá le dijo a su padre Israel : “ Deja que el muchacho vaya conmigo. Así nos pondremos en camino de inmediato, y podremos sobrevivir. De lo contrario, moriremos nosotros, tú y nuestros niños .',NULL),
(@vid,@bid,43,9,'Yo me hago responsable de él ; a mí me pedirás cuentas. Si no te lo traigo de regreso y lo pongo sano y salvo delante de ti, seré culpable ante ti toda mi vida .',NULL),
(@vid,@bid,43,10,'La verdad es que , si no nos hubiéramos demorado tanto, ¡ ya habríamos ido y regresado dos veces !”',NULL),
(@vid,@bid,43,11,'Entonces su padre Israel les dijo: “Si no hay más remedio, háganlo. Tomen de los mejores productos de nuestra tierra, échenlos en sus costales, y llévenselos a ese hombre como regalo: un poco de bálsamo , un poco de miel , especias, mirra, nueces y almendras .',NULL),
(@vid,@bid,43,12,'Llévense también el doble de dinero , porque tienen que devolver el dinero que apareció en la boca de sus costales. Tal vez fue una equivocación.',NULL),
(@vid,@bid,43,13,'Tomen también a su hermano, y prepárense para volver a ver a aquel hombre.',NULL),
(@vid,@bid,43,14,'¡Que el Dios Todopoderoso haga que ese hombre se compadezca de ustedes, y que les devuelva a su otro hermano y a Benjamín ! En cuanto a mí, si he de perder a mis hijos, me quedaré sin ellos”.',NULL),
(@vid,@bid,43,15,'Así que los hermanos tomaron los regalos, el doble del dinero y a Benjamín , y bajaron a Egipto para presentarse ante José .',NULL),
(@vid,@bid,43,16,'Cuando José vio que Benjamín venía con ellos , le dijo al administrador de su casa : “Lleva a estos hombres a mi casa , mata un animal y prepáralo, porque hoy al mediodía comerán conmigo”.',NULL),
(@vid,@bid,43,17,'El administrador hizo lo que José le había ordenado, y los llevó a la casa .',NULL),
(@vid,@bid,43,18,'Pero ellos se asustaron al ver que los llevaban a la casa de José , y pensaron: “ Nos traen aquí por el dinero que apareció en nuestros costales la primera vez. Seguro que nos van a tender una trampa, nos atacarán, nos convertirán en sus esclavos y se quedarán con nuestros burros”.',NULL),
(@vid,@bid,43,19,'Por eso, al llegar a la puerta de la casa , se acercaron al administrador',NULL),
(@vid,@bid,43,20,'y le dijeron: “¡Por favor, señor nuestro! La primera vez que bajamos, realmente vinimos a comprar comida.',NULL),
(@vid,@bid,43,21,'Pero cuando llegamos al lugar donde íbamos a pasar la noche y abrimos nuestros costales, ¡cada uno encontró todo su dinero en la boca de su propio costal! Aquí lo traemos de regreso con nosotros.',NULL),
(@vid,@bid,43,22,'Además, traemos más dinero para comprar comida. No tenemos idea de quién puso ese dinero en nuestros costales”.',NULL),
(@vid,@bid,43,23,'“Tranquilos, no tengan miedo ”, les contestó el administrador. “Su Dios, el Dios de su padre, les ha dado un tesoro en sus costales. Yo recibí el dinero que ustedes pagaron”. Luego les sacó a Simeón y se lo entregó .',NULL),
(@vid,@bid,43,24,'El administrador hizo pasar a los hombres a la casa de José , les dio agua para que se lavaran los pies , y también les dio forraje para sus burros.',NULL),
(@vid,@bid,43,25,'Como ellos ya se habían enterado de que iban a comer allí , prepararon los regalos para cuando José llegara al mediodía.',NULL),
(@vid,@bid,43,26,'Cuando José llegó a la casa , ellos le entregaron los regalos que le habían llevado, y se inclinaron ante él hasta el suelo.',NULL),
(@vid,@bid,43,27,'José les preguntó cómo estaban, y luego les dijo: “¿ Cómo está su padre, aquel anciano del que me hablaron? ¿ Todavía vive ?”',NULL),
(@vid,@bid,43,28,'“Su siervo , nuestro padre, está muy bien y todavía vive ”, respondieron ellos, inclinándose con profundo respeto.',NULL),
(@vid,@bid,43,29,'Al levantar la vista, José vio a su hermano Benjamín , el hijo de su propia madre, y preguntó: “¿ Es éste su hermano menor , del que me hablaron?” Y a Benjamín le dijo: “¡ Que Dios te bendiga, hijo mío!”',NULL),
(@vid,@bid,43,30,'José tuvo que salir rápidamente de allí , porque se conmovió profundamente al ver a su hermano y sintió ganas de llorar. Entró a su cuarto y allí se puso a llorar.',NULL),
(@vid,@bid,43,31,'Luego se lavó la cara , salió , y controlando sus emociones ordenó : “¡Sirvan la comida !”',NULL),
(@vid,@bid,43,32,'A José le sirvieron en una mesa aparte , y a sus hermanos en otra. A los egipcios que comían con él también les sirvieron aparte , pues los egipcios no pueden comer con los hebreos , ya que lo consideran algo repugnante.',NULL),
(@vid,@bid,43,33,'A los hermanos los sentaron frente a José en orden de edad, desde el mayor hasta el menor , lo cual los dejó muy asombrados, mirándose unos a otros.',NULL),
(@vid,@bid,43,34,'José ordenó que les pasaran porciones de la comida que le servían a él , ¡y la porción de Benjamín era cinco veces más grande que la de los demás! Ese día comieron, bebieron y se alegraron con José.',NULL),
(@vid,@bid,44,1,'José le dio esta orden al administrador de su casa : “ Llena de alimento los costales de estos hombres, todo lo que puedan llevar, y pon el dinero de cada uno en la boca de su costal.',NULL),
(@vid,@bid,44,2,'Además, pon mi copa de plata en la boca del costal del más joven, junto con el dinero que pagó por su trigo”. El administrador hizo todo tal como José se lo había ordenado.',NULL),
(@vid,@bid,44,3,'Al amanecer, despidieron a los hombres y los dejaron ir con sus burros.',NULL),
(@vid,@bid,44,4,'Todavía no se habían alejado mucho de la ciudad , cuando José le dijo a su administrador: “¡Prepárate y persigue a esos hombres! Cuando los alcances, pregúntales: ‘¿ Por qué han pagado mal por bien ?',NULL),
(@vid,@bid,44,5,'¿Acaso no es ésta la copa en la que bebe mi señor, y la que usa para adivinar ? ¡Han cometido una gran maldad!’”',NULL),
(@vid,@bid,44,6,'Cuando el administrador los alcanzó , les repitió estas mismas palabras .',NULL),
(@vid,@bid,44,7,'Ellos le respondieron : “¿ Por qué nos habla así mi señor? ¡ Lejos estén sus siervos de hacer semejante cosa !',NULL),
(@vid,@bid,44,8,'Fíjese que el dinero que encontramos en la boca de nuestros costales se lo trajimos de regreso desde la tierra de Canaán . ¿Cómo íbamos a robar plata u oro de la casa de su señor?',NULL),
(@vid,@bid,44,9,'Si usted encuentra la copa en poder de alguno de sus siervos , ¡ que ese hombre muera , y el resto de nosotros seremos esclavos de mi señor!”',NULL),
(@vid,@bid,44,10,'El administrador les dijo: “ De acuerdo, que sea como ustedes dicen: aquel a quien se le encuentre la copa será mi esclavo, y los demás quedarán libres de culpa”.',NULL),
(@vid,@bid,44,11,'Rápidamente, cada uno bajó su costal al suelo y lo abrió .',NULL),
(@vid,@bid,44,12,'El administrador los revisó, empezando por el costal del mayor y terminando con el del menor . ¡ Y la copa apareció en el costal de Benjamín !',NULL),
(@vid,@bid,44,13,'Llenos de angustia, se rasgaron la ropa , cargaron de nuevo sus burros y regresaron a la ciudad .',NULL),
(@vid,@bid,44,14,'Cuando Judá y sus hermanos llegaron a la casa de José , él todavía estaba allí . Ellos se postraron hasta el suelo delante de él .',NULL),
(@vid,@bid,44,15,'José les reclamó: “¿ Qué es lo que han hecho ? ¿Acaso no saben que un hombre como yo puede adivinar las cosas ?”',NULL),
(@vid,@bid,44,16,'Judá le respondió: “¿ Qué le podemos decir a mi señor? ¿ Qué le podemos contestar? ¿ Cómo podremos justificarnos? Dios ha descubierto la maldad de sus siervos . Aquí nos tiene; somos esclavos de mi señor, tanto nosotros como aquel a quien se le encontró la copa”.',NULL),
(@vid,@bid,44,17,'Pero José declaró: “¡ Lejos esté de mí hacer semejante cosa ! Sólo aquel a quien se le encontró la copa será mi esclavo; en cuanto a ustedes, regresen en paz a donde está su padre”.',NULL),
(@vid,@bid,44,18,'Entonces Judá se acercó a él y le rogó: “Ay, señor mío, le ruego que le permita a su siervo decirle unas palabras en privado. Por favor, no se enoje con su siervo , pues usted tiene tanta autoridad como el propio faraón .',NULL),
(@vid,@bid,44,19,'Mi señor les preguntó a sus siervos : ‘¿ Tienen padre o algún otro hermano?’',NULL),
(@vid,@bid,44,20,'Y nosotros le respondimos: ‘ Tenemos un padre anciano , y un hermano menor que le nació en su vejez. El hermano de este muchacho ya murió , así que es el único hijo que le queda de esa madre, y su padre lo ama muchísimo’.',NULL),
(@vid,@bid,44,21,'Entonces usted nos ordenó : ‘Tráiganmelo, para que yo lo vea con mis propios ojos ’.',NULL),
(@vid,@bid,44,22,'Nosotros le advertimos a mi señor: ‘El muchacho no puede dejar a su padre, porque si lo hace, su padre morirá ’.',NULL),
(@vid,@bid,44,23,'Pero usted nos dijo: ‘ Si su hermano menor no baja con ustedes, no volverán a ver mi rostro ’.',NULL),
(@vid,@bid,44,24,'Cuando regresamos a donde está su siervo , mi padre, le contamos todo lo que mi señor había dicho .',NULL),
(@vid,@bid,44,25,'Más tarde, nuestro padre nos dijo: ‘ Vuelvan y cómprennos un poco más de comida’.',NULL),
(@vid,@bid,44,26,'Nosotros le respondimos: ‘ No podemos ir . Sólo bajaremos si nuestro hermano menor va con nosotros; porque no podremos ver el rostro de aquel hombre si nuestro hermano menor no nos acompaña’.',NULL),
(@vid,@bid,44,27,'Entonces su siervo , mi padre, nos dijo: ‘Ustedes saben que mi esposa me dio dos hijos.',NULL),
(@vid,@bid,44,28,'Uno de ellos me dejó, y llegué a la conclusión de que un animal salvaje lo había despedazado; ¡ hasta el día de hoy no lo he vuelto a ver !',NULL),
(@vid,@bid,44,29,'Si se llevan también a éste de mi lado, y le pasa alguna desgracia, ¡harán que este viejo baje al Seol lleno de dolor!’',NULL),
(@vid,@bid,44,30,'“ Así que , si yo regreso a donde está su siervo , mi padre, y el muchacho no va con nosotros, como la vida de mi padre depende de la vida del muchacho ,',NULL),
(@vid,@bid,44,31,'al ver que el muchacho no está , él morirá . Y nosotros, sus siervos , seremos los culpables de que nuestro padre baje al Seol lleno de dolor .',NULL),
(@vid,@bid,44,32,'Yo , su siervo , me hice responsable del muchacho ante mi padre, diciéndole: ‘ Si no te lo traigo de regreso, seré culpable ante ti toda mi vida ’.',NULL),
(@vid,@bid,44,33,'Por lo tanto, le ruego a mi señor que me deje quedarme como su esclavo en lugar del muchacho , y permita que él regrese con sus hermanos.',NULL),
(@vid,@bid,44,34,'Porque , ¿ cómo podré volver a donde está mi padre, si el muchacho no está conmigo? ¡ No podría soportar ver la desgracia que le sobrevendría a mi padre!”',NULL),
(@vid,@bid,45,1,'Entonces José ya no pudo controlarse delante de sus servidores, y gritó : “¡ Que salgan todos de aquí!” Así que no quedó nadie con él cuando José se dio a conocer a sus hermanos.',NULL),
(@vid,@bid,45,2,'Se puso a llorar a gritos. Los egipcios lo oyeron , y la noticia llegó hasta el palacio del faraón .',NULL),
(@vid,@bid,45,3,'José les dijo a sus hermanos: “¡ Yo soy José ! ¿ Todavía vive mi padre?” Pero sus hermanos estaban tan aterrados de estar frente a él , que no pudieron responderle .',NULL),
(@vid,@bid,45,4,'Entonces José les dijo: “Por favor, acérquense a mí ”. Y cuando ellos se acercaron, él añadió: “ Yo soy José , su hermano, al que ustedes vendieron a Egipto .',NULL),
(@vid,@bid,45,5,'Pero ahora , no se entristezcan ni se reprochen el haberme vendido acá , pues Dios me envió delante de ustedes para salvarles la vida .',NULL),
(@vid,@bid,45,6,'Ya van dos años de hambre en el país, y aún quedan cinco años en los que no habrá siembra ni cosecha.',NULL),
(@vid,@bid,45,7,'Dios me envió delante de ustedes para asegurarles descendencia en la tierra, y para salvarles la vida mediante una gran liberación.',NULL),
(@vid,@bid,45,8,'Así que no fueron ustedes los que me mandaron acá , sino Dios. Él me ha convertido en padre para el faraón , en amo de toda su casa y en gobernador de toda la tierra de Egipto .',NULL),
(@vid,@bid,45,9,'Apresúrense, regresen a donde está mi padre y díganle: ‘ Esto dice tu hijo José : “Dios me ha puesto como señor de todo Egipto . Baja a verme de inmediato; no te demores.',NULL),
(@vid,@bid,45,10,'Vivirás en la región de Gosén, y estarás cerca de mí , junto con tus hijos , tus nietos , tus ovejas , tus vacas y todo lo que tienes.',NULL),
(@vid,@bid,45,11,'Yo te proveeré de todo allí , porque aún faltan cinco años de hambre . Así no caerán en la miseria tú, ni tu familia , ni los que dependen de ti”’.',NULL),
(@vid,@bid,45,12,'Ustedes mismos y mi hermano Benjamín son testigos de que soy yo mismo quien les está hablando .',NULL),
(@vid,@bid,45,13,'Cuéntenle a mi padre de todos los honores que tengo en Egipto y de todo lo que han visto . ¡ Y apresúrense a traer a mi padre acá !”',NULL),
(@vid,@bid,45,14,'Luego José abrazó a su hermano Benjamín y se echó a llorar, y Benjamín también lloró abrazado a él .',NULL),
(@vid,@bid,45,15,'Después José besó a todos sus hermanos y lloró con ellos . Sólo entonces sus hermanos se atrevieron a hablar con él .',NULL),
(@vid,@bid,45,16,'Cuando la noticia de que los hermanos de José habían llegado se escuchó en el palacio, el faraón y sus funcionarios se alegraron mucho.',NULL),
(@vid,@bid,45,17,'Y el faraón le dijo a José : “Diles a tus hermanos que hagan lo siguiente: ‘Carguen sus animales y regresen a la tierra de Canaán .',NULL),
(@vid,@bid,45,18,'Tomen a su padre y a sus familias , y vengan a verme. Yo les daré lo mejor de la tierra de Egipto , y comerán de la abundancia del país’.',NULL),
(@vid,@bid,45,19,'También ordénales esto : ‘Llévense carretas de Egipto para sus niños y sus esposas, y traigan a su padre.',NULL),
(@vid,@bid,45,20,'No se preocupen por las cosas que dejen allá, porque lo mejor de todo Egipto será para ustedes’”.',NULL),
(@vid,@bid,45,21,'Así lo hicieron los hijos de Israel . José les dio carretas, tal como el faraón lo había ordenado, y también les dio provisiones para el viaje .',NULL),
(@vid,@bid,45,22,'A cada uno de ellos le regaló ropa nueva, pero a Benjamín le dio trescientas monedas de plata y cinco mudas de ropa .',NULL),
(@vid,@bid,45,23,'A su padre le envió diez burros cargados con lo mejor de Egipto , y diez burras cargadas de trigo , pan y provisiones para el viaje de su padre.',NULL),
(@vid,@bid,45,24,'Luego despidió a sus hermanos, y al verlos partir, les advirtió: “¡ No se vayan peleando por el camino !”',NULL),
(@vid,@bid,45,25,'Así salieron de Egipto y llegaron a la tierra de Canaán , a donde estaba su padre Jacob .',NULL),
(@vid,@bid,45,26,'Cuando le dieron la noticia: “¡ José todavía está vivo , y es el gobernador de todo Egipto !”, el corazón de Jacob se paralizó, porque no podía creerles.',NULL),
(@vid,@bid,45,27,'Pero cuando le contaron todo lo que José les había dicho , y vio las carretas que José había enviado para llevarlo , el espíritu de Jacob revivió .',NULL),
(@vid,@bid,45,28,'Entonces Israel exclamó: “¡ Basta ! ¡Mi hijo José todavía está vivo ! Iré a verlo antes de morirme”.',NULL),
(@vid,@bid,46,1,'Israel emprendió el viaje con todo lo que tenía, y al llegar a Beerseba, ofreció sacrificios al Dios de su padre Isaac .',NULL),
(@vid,@bid,46,2,'Durante la noche , Dios le habló a Israel en una visión y lo llamó: “¡ Jacob , Jacob !” “ Aquí estoy”, respondió él.',NULL),
(@vid,@bid,46,3,'Y Dios le dijo: “ Yo soy Dios, el Dios de tu padre. No tengas miedo de bajar a Egipto , porque allí haré de ti una gran nación .',NULL),
(@vid,@bid,46,4,'Yo mismo bajaré contigo a Egipto , y yo mismo te haré volver de allá. Y cuando mueras, José cerrará tus ojos con sus propias manos ”.',NULL),
(@vid,@bid,46,5,'Jacob se marchó de Beerseba, y los hijos de Israel llevaron a su padre Jacob , junto con sus niños y sus esposas, en las carretas que el faraón había enviado para transportarlo.',NULL),
(@vid,@bid,46,6,'También se llevaron su ganado y los bienes que habían adquirido en la tierra de Canaán . Así fue como Jacob y toda su descendencia llegaron a Egipto .',NULL),
(@vid,@bid,46,7,'Jacob se llevó a Egipto a sus hijos y a sus nietos , a sus hijas y a sus nietas; es decir, a toda su descendencia .',NULL),
(@vid,@bid,46,8,'Éstos son los nombres de los israelitas que llegaron a Egipto ( Jacob y sus descendientes): Rubén , el hijo mayor de Jacob .',NULL),
(@vid,@bid,46,9,'Los hijos de Rubén fueron Hanoc, Falú, Hezrón y Carmí .',NULL),
(@vid,@bid,46,10,'Los hijos de Simeón fueron Jemuel , Jamín , Ohad, Jaquín, Zóhar y Saúl , que era hijo de una mujer cananea .',NULL),
(@vid,@bid,46,11,'Los hijos de Leví fueron Gersón , Coat y Merarí .',NULL),
(@vid,@bid,46,12,'Los hijos de Judá fueron Er , Onán, Selá , Fares y Zera ; pero Er y Onán habían muerto en la tierra de Canaán . Los hijos de Fares fueron Hezrón y Hamul.',NULL),
(@vid,@bid,46,13,'Los hijos de Isacar fueron Tola , Fúa, Job y Simrón.',NULL),
(@vid,@bid,46,14,'Los hijos de Zabulón fueron Sered , Elón y Jahleel.',NULL),
(@vid,@bid,46,15,'Éstos fueron los hijos que Lea le dio a Jacob en Padán Aram, además de su hija Dina . En total, los hijos y las hijas de Lea eran treinta y tres personas .',NULL),
(@vid,@bid,46,16,'Los hijos de Gad fueron Zifión, Hagui, Suni, Ezbón, Erí, Arodí y Arelí.',NULL),
(@vid,@bid,46,17,'Los hijos de Aser fueron Imná , Isúa , Isúi y Bería , y la hermana de ellos se llamaba Sera . Los hijos de Bería fueron Heber y Malquiel.',NULL),
(@vid,@bid,46,18,'Éstos fueron los hijos que Zilpá le dio a Jacob ( Zilpá era la sirvienta que Labán le había regalado a su hija Lea ). En total fueron dieciséis personas .',NULL),
(@vid,@bid,46,19,'Los hijos de Raquel, la esposa de Jacob , fueron José y Benjamín .',NULL),
(@vid,@bid,46,20,'En Egipto , Asenat, la hija de Potifera, el sacerdote de On, le dio dos hijos a José : Manasés y Efraín.',NULL),
(@vid,@bid,46,21,'Los hijos de Benjamín fueron Bela , Bequer, Asbel, Gera , Naamán , Ehí, Ros, Mupim, Hupim y Ard.',NULL),
(@vid,@bid,46,22,'Éstos fueron los hijos que Raquel le dio a Jacob ; en total fueron catorce personas .',NULL),
(@vid,@bid,46,23,'El hijo de Dan fue Husim .',NULL),
(@vid,@bid,46,24,'Los hijos de Neftalí fueron Jahzeel, Guní , Jezer y Silem.',NULL),
(@vid,@bid,46,25,'Éstos fueron los hijos que Bilhá le dio a Jacob ( Bilhá era la sirvienta que Labán le había regalado a su hija Raquel). En total fueron siete personas .',NULL),
(@vid,@bid,46,26,'El total de las personas que llegaron a Egipto con Jacob y que eran de su propia sangre (sin contar a las esposas de sus hijos ), fue de sesenta y seis .',NULL),
(@vid,@bid,46,27,'Y los hijos que le nacieron a José en Egipto fueron dos . Así que el total de las personas de la familia de Jacob que llegaron a Egipto fue de setenta .',NULL),
(@vid,@bid,46,28,'Jacob mandó a Judá por delante para que le avisara a José que estaban en camino a Gosén. Cuando llegaron a la región de Gosén,',NULL),
(@vid,@bid,46,29,'José preparó su carruaje y salió a recibir a su padre Israel . Al encontrarse con él , José lo abrazó y lloró abrazado a él por un largo rato.',NULL),
(@vid,@bid,46,30,'Entonces Israel le dijo a José : “ Ya me puedo morir en paz, porque te he visto y sé que todavía estás vivo ”.',NULL),
(@vid,@bid,46,31,'Luego José les dijo a sus hermanos y a la familia de su padre: “Voy a ir a avisarle al faraón . Le diré: ‘Mis hermanos y la familia de mi padre, que vivían en la tierra de Canaán , han venido a quedarse conmigo.',NULL),
(@vid,@bid,46,32,'Como estos hombres son pastores y se dedican a la cría de animales, han traído sus ovejas , sus vacas y todo lo que tienen ’.',NULL),
(@vid,@bid,46,33,'Así que , cuando el faraón los mande llamar y les pregunte: ‘¿ A qué se dedican?’,',NULL),
(@vid,@bid,46,34,'ustedes responderán: ‘Sus siervos se han dedicado a la cría de ganado desde su juventud hasta ahora , al igual que nuestros antepasados’. Digan esto para que puedan quedarse a vivir en la región de Gosén, ya que los egipcios detestan a los pastores de ovejas ”.',NULL),
(@vid,@bid,47,1,'José fue a informarle al faraón : “Mi padre y mis hermanos ya salieron de la tierra de Canaán , junto con sus ovejas , sus vacas y todo lo que tienen, y ahora se encuentran en la región de Gosén”.',NULL),
(@vid,@bid,47,2,'Había escogido a cinco de sus hermanos para presentárselos al faraón .',NULL),
(@vid,@bid,47,3,'El faraón les preguntó: “¿ A qué se dedican?” Ellos le respondieron: “Sus siervos son pastores de ovejas , al igual que nuestros antepasados”.',NULL),
(@vid,@bid,47,4,'Y añadieron: “Hemos venido a vivir como extranjeros en este país, porque el hambre en la tierra de Canaán es tan terrible que ya no hay pastos para los rebaños de sus siervos . Por favor, permítanos usted vivir en la región de Gosén”.',NULL),
(@vid,@bid,47,5,'El faraón le dijo a José : “Tu padre y tus hermanos han venido a reunirse contigo,',NULL),
(@vid,@bid,47,6,'y la tierra de Egipto está a tu disposición. Haz que tu padre y tus hermanos vivan en la mejor región del país. Que se establezcan en la región de Gosén. Y si sabes que entre ellos hay hombres capaces, ponlos a cargo de mi propio ganado ”.',NULL),
(@vid,@bid,47,7,'Después José hizo pasar a su padre Jacob y se lo presentó al faraón , y Jacob bendijo al faraón .',NULL),
(@vid,@bid,47,8,'El faraón le preguntó a Jacob : “¿ Cuántos años tiene usted?”',NULL),
(@vid,@bid,47,9,'Jacob le respondió: “ Mi vida de andar peregrinando ha sido de ciento treinta años . Han sido años pocos y difíciles, y no se comparan con los años que vivieron mis antepasados en sus peregrinaciones”.',NULL),
(@vid,@bid,47,10,'Jacob volvió a bendecir al faraón y se retiró de su presencia .',NULL),
(@vid,@bid,47,11,'José instaló a su padre y a sus hermanos, dándoles propiedades en la mejor región de Egipto , en la tierra de Ramsés, tal como el faraón lo había ordenado .',NULL),
(@vid,@bid,47,12,'Además, José les proveyó alimentos a su padre, a sus hermanos y a toda la familia de su padre, según el número de sus hijos.',NULL),
(@vid,@bid,47,13,'No había pan en toda la región, porque el hambre era gravísima . Tanto Egipto como Canaán estaban agotados a causa del hambre .',NULL),
(@vid,@bid,47,14,'José recolectó todo el dinero que había en Egipto y en Canaán , a cambio del trigo que le compraban, y lo guardó en el tesoro del faraón .',NULL),
(@vid,@bid,47,15,'Cuando se acabó el dinero en Egipto y en Canaán , todos los egipcios acudieron a José y le suplicaron: “¡ Danos de comer! ¿Vas a dejar que nos muramos delante de ti sólo porque se nos acabó el dinero ?”',NULL),
(@vid,@bid,47,16,'José les contestó: “Entréguenme su ganado , y yo les daré comida a cambio de sus animales, ya que se les acabó el dinero ”.',NULL),
(@vid,@bid,47,17,'Así que le llevaron su ganado a José , y él les dio pan a cambio de sus caballos , ovejas , vacas y burros. Durante ese año los abasteció de pan a cambio de todo su ganado .',NULL),
(@vid,@bid,47,18,'Al terminar ese año , acudieron a él al año siguiente y le dijeron: “ No podemos ocultarle a mi señor que el dinero se ha agotado, y que nuestros animales ya le pertenecen a usted. Ya no nos queda nada que ofrecerle a mi señor, excepto nuestros cuerpos y nuestras tierras.',NULL),
(@vid,@bid,47,19,'¿Vamos a morir ante sus propios ojos , nosotros y nuestras tierras? Cómprenos a nosotros y a nuestras tierras a cambio de pan , y seremos esclavos del faraón y la tierra será de él . Pero denos semilla para que podamos sobrevivir, para que no muramos y la tierra no quede desolada”.',NULL),
(@vid,@bid,47,20,'Fue así como José compró toda la tierra de Egipto para el faraón . Todos los egipcios se vieron obligados a vender sus campos , porque el hambre se hizo insoportable. De este modo, la tierra pasó a ser propiedad del faraón .',NULL),
(@vid,@bid,47,21,'En cuanto al pueblo , José lo trasladó a las ciudades desde un extremo de Egipto hasta el otro .',NULL),
(@vid,@bid,47,22,'La única tierra que José no compró fue la de los sacerdotes , porque ellos recibían una ración fija de parte del faraón , y vivían de esa ración. Por eso no tuvieron que vender sus tierras.',NULL),
(@vid,@bid,47,23,'Entonces José le dijo al pueblo : “Miren, hoy los he comprado a ustedes y a sus tierras para el faraón . Aquí tienen semilla; vayan y siembren la tierra.',NULL),
(@vid,@bid,47,24,'Cuando llegue el tiempo de la cosecha, le entregarán la quinta parte al faraón . Las otras cuatro partes serán para ustedes, para que tengan semilla para el campo y alimento para ustedes, para sus familias y para sus niños ”.',NULL),
(@vid,@bid,47,25,'Ellos respondieron: “¡Usted nos ha salvado la vida ! Con tal de contar con el favor de mi señor, seremos esclavos del faraón ”.',NULL),
(@vid,@bid,47,26,'José estableció como ley en la tierra de Egipto , válida hasta el día de hoy , que la quinta parte de las cosechas le pertenece al faraón . Las únicas tierras que no pasaron a ser del faraón fueron las de los sacerdotes .',NULL),
(@vid,@bid,47,27,'Los israelitas se establecieron en Egipto , en la región de Gosén. Allí adquirieron propiedades, prosperaron y se multiplicaron muchísimo.',NULL),
(@vid,@bid,47,28,'Jacob vivió en Egipto diecisiete años , así que llegó a la edad de ciento cuarenta y siete años .',NULL),
(@vid,@bid,47,29,'Cuando se acercaba el momento de su muerte , Israel llamó a su hijo José y le dijo: “ Si realmente me amas, por favor pon tu mano debajo de mi muslo y júrame que me tratarás con lealtad y bondad: por favor, no me entierres en Egipto .',NULL),
(@vid,@bid,47,30,'Cuando yo muera y vaya a reunirme con mis antepasados, sácame de Egipto y entiérrame en el mismo sepulcro que ellos”. José le respondió: “ Haré exactamente lo que me has pedido”.',NULL),
(@vid,@bid,47,31,'“ Júramelo ”, insistió Israel . Y José se lo juró . Entonces Israel se inclinó sobre la cabecera de su cama en actitud de adoración.',NULL),
(@vid,@bid,48,1,'Pasado algún tiempo, le avisaron a José : “Tu padre está muy enfermo ”. Entonces José tomó a sus dos hijos , Manasés y Efraín, y fue a verlo.',NULL),
(@vid,@bid,48,2,'Cuando le informaron a Jacob : “Tu hijo José ha venido a verte”, Israel hizo un gran esfuerzo y se sentó en la cama .',NULL),
(@vid,@bid,48,3,'Y Jacob le dijo a José : “El Dios Todopoderoso se me apareció en Luz , en la tierra de Canaán , y me bendijo',NULL),
(@vid,@bid,48,4,'con estas palabras: ‘Yo te haré muy fecundo y multiplicaré tu descendencia . Haré de ti una multitud de naciones, y a tu descendencia le daré esta tierra como propiedad eterna ’.',NULL),
(@vid,@bid,48,5,'Pues bien, tus dos hijos , los que te nacieron en Egipto antes de que yo viniera a reunirme contigo, ahora son míos . Efraín y Manasés serán tan míos como lo son Rubén y Simeón .',NULL),
(@vid,@bid,48,6,'Los hijos que tengas después de ellos serán tuyos, pero recibirán su herencia bajo el nombre de estos dos hermanos suyos.',NULL),
(@vid,@bid,48,7,'Cuando yo regresaba de Padán Aram, para mi gran dolor, Raquel murió en el camino , en la tierra de Canaán , cuando todavía faltaba un tramo para llegar a Efrata. Y allí la enterré, en el camino hacia Efrata” ( es decir, Belén).',NULL),
(@vid,@bid,48,8,'Al notar Israel la presencia de los hijos de José , preguntó: “¿ Y estos quiénes son?”',NULL),
(@vid,@bid,48,9,'José le respondió: “Son los hijos que Dios me ha dado aquí ”. Y su padre le dijo: “ Por favor, acércalos a mí para que los bendiga ”.',NULL),
(@vid,@bid,48,10,'Los ojos de Israel ya estaban muy debilitados por la vejez, de modo que casi no podía ver . Así que José acercó a los muchachos, y su padre los besó y los abrazó.',NULL),
(@vid,@bid,48,11,'Luego Israel le dijo a José : “ Nunca pensé que volvería a ver tu rostro , ¡ y resulta que Dios me ha permitido ver también a tus hijos !”',NULL),
(@vid,@bid,48,12,'Entonces José los retiró de las rodillas de su padre y se inclinó hasta tocar el suelo con la frente.',NULL),
(@vid,@bid,48,13,'Luego José los tomó a los dos : a Efraín lo puso a su derecha , para que quedara a la izquierda de Israel , y a Manasés a su izquierda , para que quedara a la derecha de Israel , y los acercó a él .',NULL),
(@vid,@bid,48,14,'Pero Israel cruzó las manos a propósito y extendió su mano derecha para ponerla sobre la cabeza de Efraín, aunque era el menor , y su mano izquierda la puso sobre la cabeza de Manasés , a pesar de que él era el primogénito .',NULL),
(@vid,@bid,48,15,'Y bendijo a José con estas palabras: “ Que el Dios en cuya presencia caminaron mis padres Abraham e Isaac , el Dios que ha sido mi pastor toda mi vida y hasta el día de hoy ,',NULL),
(@vid,@bid,48,16,'el ángel que me ha rescatado de todo mal , bendiga a estos muchachos. Que mi nombre y el nombre de mis padres, Abraham e Isaac , se perpetúe por medio de ellos . ¡ Que lleguen a ser una gran multitud en medio de la tierra!”',NULL),
(@vid,@bid,48,17,'A José no le agradó ver que su padre ponía la mano derecha sobre la cabeza de Efraín, así que tomó la mano de su padre para quitarla de la cabeza de Efraín y pasarla a la de Manasés .',NULL),
(@vid,@bid,48,18,'José le dijo: “¡ Así no , padre mío ! Éste es el primogénito ; pon tu mano derecha sobre su cabeza ”.',NULL),
(@vid,@bid,48,19,'Pero su padre se negó y le respondió: “ Ya lo sé , hijo mío , ya lo sé . Él también llegará a ser un gran pueblo , y será muy importante. Sin embargo, su hermano menor será más importante que él , y su descendencia formará una multitud de naciones ”.',NULL),
(@vid,@bid,48,20,'Aquel día los bendijo diciendo: “ El pueblo de Israel usará el nombre de ustedes para bendecir, diciendo: ‘¡ Que Dios te haga como a Efraín y como a Manasés !’” De este modo, puso a Efraín por encima de Manasés .',NULL),
(@vid,@bid,48,21,'Luego Israel le dijo a José : “ Como ves, estoy a punto de morir ; pero Dios estará con ustedes y los hará volver a la tierra de sus antepasados.',NULL),
(@vid,@bid,48,22,'Y a ti , como estás por encima de tus hermanos, te doy la porción de tierra que conquisté de los amorreos con mi espada y con mi arco ”.',NULL),
(@vid,@bid,49,1,'Jacob llamó a sus hijos y les dijo : “Reúnanse, para que les anuncie lo que les sucederá en el futuro.',NULL),
(@vid,@bid,49,2,'Reúnanse y escuchen , hijos de Jacob ; escuchen a su padre Israel .',NULL),
(@vid,@bid,49,3,'“ Rubén , tú eres mi primogénito , mi fuerza y el principio de mi vigor , el primero en honor y el primero en poder .',NULL),
(@vid,@bid,49,4,'Pero eres incontrolable como el agua , y ya no serás el primero, porque te acostaste en la cama de tu padre; deshonraste mi propio lecho.',NULL),
(@vid,@bid,49,5,'“ Simeón y Leví son hermanos; sus espadas son armas de violencia .',NULL),
(@vid,@bid,49,6,'¡ Que nunca entre yo en su consejo ! ¡ Que nunca me una yo a su asamblea! Porque en su enojo mataron hombres, y por capricho les cortaron los tendones a los toros.',NULL),
(@vid,@bid,49,7,'¡Maldito sea su enojo, porque fue feroz! ¡Maldita sea su furia, porque fue cruel! Los dispersaré entre los descendientes de Jacob ; los esparciré por todo Israel .',NULL),
(@vid,@bid,49,8,'“ Judá , tus hermanos te alabarán ; agarrarás por el cuello a tus enemigos, y tus propios hermanos se inclinarán ante ti.',NULL),
(@vid,@bid,49,9,'Judá es un cachorro de león. ¡Has vuelto de la matanza, hijo mío! Se recuesta y se agazapa como un león, como una leona, ¿ quién se atreve a despertarlo?',NULL),
(@vid,@bid,49,10,'El cetro no se apartará de Judá , ni el bastón de mando de entre sus pies , hasta que llegue aquel a quien le pertenece, a quien los pueblos obedecerán.',NULL),
(@vid,@bid,49,11,'Amarrará su burro a la vid , y la cría de su burra a la mejor cepa; lavará su ropa en vino , sus vestiduras en la sangre de las uvas .',NULL),
(@vid,@bid,49,12,'Sus ojos serán más oscuros que el vino , y sus dientes más blancos que la leche .',NULL),
(@vid,@bid,49,13,'“ Zabulón vivirá a la orilla del mar ; será un puerto seguro para los barcos, y sus fronteras llegarán hasta Sidón .',NULL),
(@vid,@bid,49,14,'“Isacar es un burro fuerte, echado entre dos alforjas.',NULL),
(@vid,@bid,49,15,'Al ver que el lugar de descanso era bueno , y que la tierra era agradable, inclinó sus hombros para llevar la carga, y se sometió a trabajos forzados.',NULL),
(@vid,@bid,49,16,'“ Dan le hará justicia a su pueblo , como una de las tribus de Israel .',NULL),
(@vid,@bid,49,17,'Dan será una serpiente junto al camino , una víbora junto al sendero, que muerde los talones del caballo para que el jinete caiga de espaldas.',NULL),
(@vid,@bid,49,18,'¡Oh Yahvé, espero tu salvación!',NULL),
(@vid,@bid,49,19,'“ A Gad lo atacarán bandas de saqueadores, pero él los atacará por la espalda.',NULL),
(@vid,@bid,49,20,'“Aser disfrutará de comidas deliciosas, y ofrecerá manjares dignos de reyes .',NULL),
(@vid,@bid,49,21,'“Neftalí es una cierva libre, que tiene hermosas crías.',NULL),
(@vid,@bid,49,22,'“ José es una vid muy fructífera, una vid fructífera junto a un manantial; sus ramas trepan por el muro.',NULL),
(@vid,@bid,49,23,'Con amargura lo atacaron los arqueros; le dispararon y lo persiguieron.',NULL),
(@vid,@bid,49,24,'Pero su arco se mantuvo firme, y sus brazos no perdieron la fuerza, gracias a las manos del Poderoso de Jacob , gracias al Pastor y a la Roca de Israel .',NULL),
(@vid,@bid,49,25,'¡ Que te ayude el Dios de tu padre! ¡ Que te bendiga el Dios Todopoderoso con las bendiciones del alto cielo , con las bendiciones de las profundidades de la tierra, con las bendiciones de los pechos y del vientre!',NULL),
(@vid,@bid,49,26,'Las bendiciones de tu padre superan a las bendiciones de los montes antiguos , y a la abundancia de las colinas eternas . ¡ Que descansen sobre la cabeza de José , sobre la frente del príncipe entre sus hermanos!',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,49,27,'“ Benjamín es un lobo voraz; por la mañana devora a su presa , y por la tarde reparte los despojos ”.',NULL),
(@vid,@bid,49,28,'Éstas son las doce tribus de Israel , y esto fue lo que su padre les dijo al bendecir a cada uno de ellos con la bendición que le correspondía.',NULL),
(@vid,@bid,49,29,'Luego Jacob les dio estas instrucciones: “Pronto iré a reunirme con mis antepasados. Entiérrenme junto a mis padres en la cueva que está en el campo de Efrón el hitita.',NULL),
(@vid,@bid,49,30,'Es la cueva de Macpelá, al oriente de Mamre , en la tierra de Canaán . Abraham le compró esa cueva y ese campo a Efrón el hitita, para tener su propio lugar de sepultura .',NULL),
(@vid,@bid,49,31,'Allí enterraron a Abraham y a su esposa Sara ; allí enterraron a Isaac y a su esposa Rebeca ; y allí también enterré a Lea .',NULL),
(@vid,@bid,49,32,'Ese campo y su cueva se los compraron a los hititas”.',NULL),
(@vid,@bid,49,33,'Cuando Jacob terminó de darles estas instrucciones a sus hijos , volvió a acostarse en la cama , exhaló su último suspiro y fue a reunirse con sus antepasados.',NULL),
(@vid,@bid,50,1,'Entonces José se abrazó al rostro de su padre, lloró sobre él y lo besó .',NULL),
(@vid,@bid,50,2,'Luego José ordenó a los médicos que estaban a su servicio que embalsamaran a su padre; y los médicos embalsamaron a Israel .',NULL),
(@vid,@bid,50,3,'En esto se tomaron cuarenta días , que es el tiempo necesario para embalsamar. Y los egipcios guardaron luto por Israel durante setenta días .',NULL),
(@vid,@bid,50,4,'Cuando pasaron los días de luto, José habló con la corte del faraón y les dijo : “ Si me he ganado el favor de ustedes, por favor háganle llegar este mensaje al faraón :',NULL),
(@vid,@bid,50,5,'‘ Mi padre me hizo hacerle un juramento. Me dijo: “Estoy a punto de morir . Tienes que enterrarme en la tumba que me preparé en la tierra de Canaán ”. Por lo tanto, le ruego que me permita ir a enterrar a mi padre, y luego regresaré’”.',NULL),
(@vid,@bid,50,6,'El faraón le respondió: “ Ve y entierra a tu padre, tal como le juraste ”.',NULL),
(@vid,@bid,50,7,'Así que José fue a enterrar a su padre. Con él fueron todos los funcionarios del faraón , los ancianos de su corte y todos los ancianos de la tierra de Egipto .',NULL),
(@vid,@bid,50,8,'También lo acompañó toda su propia familia , además de sus hermanos y la familia de su padre. En la región de Gosén sólo se quedaron los niños , las ovejas y las vacas .',NULL),
(@vid,@bid,50,9,'También lo acompañaron carruajes y jinetes , formando una caravana inmensa.',NULL),
(@vid,@bid,50,10,'Al llegar a la era de Atad, que está cerca del río Jordán , hicieron un llanto muy grande y doloroso, y José guardó siete días de luto por su padre.',NULL),
(@vid,@bid,50,11,'Cuando los cananeos que vivían allí vieron el luto en la era de Atad, comentaron: “ Este luto de los egipcios es muy grande ”. Por eso , a ese lugar que está junto al Jordán se le llamó Abel Mizraim.',NULL),
(@vid,@bid,50,12,'Así que los hijos de Jacob hicieron con él tal como les había ordenado :',NULL),
(@vid,@bid,50,13,'lo llevaron a la tierra de Canaán y lo enterraron en la cueva del campo de Macpelá, cerca de Mamre . Era la misma cueva y el mismo campo que Abraham le había comprado a Efrón el hitita para tener un lugar de sepultura .',NULL),
(@vid,@bid,50,14,'Después de enterrar a su padre, José regresó a Egipto junto con sus hermanos y con todos los que lo habían acompañado al entierro.',NULL),
(@vid,@bid,50,15,'Al ver los hermanos de José que su padre había muerto , pensaron: “¿ Qué tal si José nos guarda rencor y ahora nos hace pagar por todo el mal que le hicimos?”',NULL),
(@vid,@bid,50,16,'Por eso le enviaron este mensaje a José : “ Antes de morir, tu padre nos dejó esta orden :',NULL),
(@vid,@bid,50,17,'‘Díganle a José que por favor perdone la maldad y el pecado de sus hermanos, porque lo trataron muy mal ’. Por lo tanto, te rogamos que perdones la maldad de los siervos del Dios de tu padre”. Al escuchar este mensaje, José se puso a llorar.',NULL),
(@vid,@bid,50,18,'Luego sus hermanos fueron personalmente, se postraron ante él y le dijeron: “¡ Aquí nos tienes! Somos tus esclavos”.',NULL),
(@vid,@bid,50,19,'Pero José les respondió: “ No tengan miedo . ¿Acaso estoy yo en el lugar de Dios?',NULL),
(@vid,@bid,50,20,'Es verdad que ustedes pensaron hacerme mal , pero Dios lo cambió en bien para que se cumpliera lo que hoy estamos viendo: salvar la vida de mucha gente .',NULL),
(@vid,@bid,50,21,'Así que no tengan miedo . Yo los sustentaré a ustedes y a sus hijos”. De esta manera los consoló y les habló con mucho cariño.',NULL),
(@vid,@bid,50,22,'José y la familia de su padre se quedaron a vivir en Egipto , y José llegó a vivir ciento diez años .',NULL),
(@vid,@bid,50,23,'Alcanzó a ver a los hijos de Efraín hasta la tercera generación. Además , cuando nacieron los hijos de Maquir, que era hijo de Manasés , José los recibió sobre sus rodillas y los reconoció como suyos.',NULL),
(@vid,@bid,50,24,'Tiempo después, José les dijo a sus hermanos: “ Yo estoy a punto de morir ; pero estoy seguro de que Dios vendrá a ayudarlos, y de que los sacará de este país para llevarlos a la tierra que les prometió a Abraham, a Isaac y a Jacob ”.',NULL),
(@vid,@bid,50,25,'Entonces José les hizo hacer un juramento a los israelitas, diciéndoles: “Cuando Dios venga a ayudarlos, ustedes se llevarán de aquí mis huesos ”.',NULL),
(@vid,@bid,50,26,'José murió a la edad de ciento diez años . Lo embalsamaron y lo pusieron en un ataúd en Egipto .',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'Estos son los nombres de los hijos de Israel que llegaron a Egipto (cada hombre y su familia llegaron con Jacob ):',NULL),
(@vid,@bid,1,2,'Rubén , Simeón , Leví y Judá ,',NULL),
(@vid,@bid,1,3,'Isacar, Zabulón y Benjamín ,',NULL),
(@vid,@bid,1,4,'Dan y Neftalí, Gad y Aser.',NULL),
(@vid,@bid,1,5,'Todas las personas que descendieron de Jacob fueron setenta en total, y José ya estaba en Egipto .',NULL),
(@vid,@bid,1,6,'José murió , al igual que todos sus hermanos y toda aquella generación .',NULL),
(@vid,@bid,1,7,'Los hijos de Israel fructificaron, se multiplicaron y se hicieron muy poderosos, y la tierra se llenó de ellos.',NULL),
(@vid,@bid,1,8,'Se levantó un nuevo rey sobre Egipto , que no conocía a José .',NULL),
(@vid,@bid,1,9,'Le dijo a su pueblo : “Miren, el pueblo de los hijos de Israel es cada vez más poderoso que nosotros.',NULL),
(@vid,@bid,1,10,'Vengan , seamos astutos con ellos , no sea que se multipliquen, y suceda que cuando estalle alguna guerra , ellos también se unan a nuestros enemigos , luchen contra nosotros y escapen del país.”',NULL),
(@vid,@bid,1,11,'Por lo tanto , les pusieron capataces para que los oprimieran con trabajos pesados. Construyeron ciudades de almacenamiento para el faraón : Pitón y Ramsés.',NULL),
(@vid,@bid,1,12,'Pero cuanto más los oprimían, más se multiplicaban y más se extendían. Los egipcios comenzaron a temer a los hijos de Israel ,',NULL),
(@vid,@bid,1,13,'y los hicieron trabajar sin piedad.',NULL),
(@vid,@bid,1,14,'Les amargaron la vida con un duro servicio haciendo barro y ladrillos , y con todo tipo de trabajo en el campo ; en todos sus trabajos los hacían servir con crueldad.',NULL),
(@vid,@bid,1,15,'El rey de Egipto habló con las parteras hebreas , de las cuales una se llamaba Sifra y la otra Fúa,',NULL),
(@vid,@bid,1,16,'y les dijo: “Cuando atiendan los partos de las mujeres hebreas y las vean en la silla de dar a luz, si es un niño, lo matarán ; pero si es una niña, la dejarán vivir.”',NULL),
(@vid,@bid,1,17,'Pero las parteras temían a Dios, y no hicieron lo que el rey de Egipto les ordenó, sino que dejaron vivir a los niños .',NULL),
(@vid,@bid,1,18,'El rey de Egipto llamó a las parteras y les dijo: “¿ Por qué han hecho esto y han dejado vivir a los niños ?”',NULL),
(@vid,@bid,1,19,'Las parteras le dijeron al faraón : “ Porque las mujeres hebreas no son como las egipcias; son vigorosas y dan a luz antes de que la partera llegue a atenderlas.”',NULL),
(@vid,@bid,1,20,'Dios trató bien a las parteras, y el pueblo se multiplicó y se hizo muy fuerte.',NULL),
(@vid,@bid,1,21,'Como las parteras temieron a Dios, él les concedió tener sus propias familias .',NULL),
(@vid,@bid,1,22,'Entonces el faraón le ordenó a todo su pueblo : “ Echarán al río a todo niño hebreo que nazca, pero a toda niña la dejarán vivir .”',NULL),
(@vid,@bid,2,1,'Un hombre de la tribu de Leví fue y se casó con una mujer de su misma tribu.',NULL),
(@vid,@bid,2,2,'La mujer quedó embarazada y dio a luz un hijo . Al ver que era un niño hermoso , lo escondió durante tres meses .',NULL),
(@vid,@bid,2,3,'Cuando ya no pudo esconderlo más , tomó una canasta de papiro para él y la recubrió con asfalto y brea. Puso al niño adentro y dejó la canasta entre los juncos a la orilla del río .',NULL),
(@vid,@bid,2,4,'La hermana del niño se quedó a lo lejos para ver qué pasaba con él .',NULL),
(@vid,@bid,2,5,'La hija del faraón bajó a bañarse al río , mientras sus doncellas caminaban por la orilla. Al ver la canasta entre los juncos, mandó a su sirvienta a buscarla.',NULL),
(@vid,@bid,2,6,'La abrió y vio al niño , y resulta que el pequeño estaba llorando . Se compadeció de él y dijo: “ Este es uno de los niños hebreos ”.',NULL),
(@vid,@bid,2,7,'Entonces la hermana del niño le dijo a la hija del faraón : “¿Quiere que vaya a llamar a una nodriza hebrea para que le amamante al niño?”',NULL),
(@vid,@bid,2,8,'La hija del faraón le contestó: “ Ve ”. La joven fue y llamó a la madre del niño.',NULL),
(@vid,@bid,2,9,'La hija del faraón le dijo: “Llévate a este niño y críalo por mí, y yo te pagaré por tu trabajo”. La mujer tomó al niño y lo amamantó.',NULL),
(@vid,@bid,2,10,'Cuando el niño creció , se lo llevó a la hija del faraón , y él se convirtió en su hijo . Ella le puso por nombre Moisés , y dijo: “ Porque lo saqué del agua ”.',NULL),
(@vid,@bid,2,11,'En aquellos días , cuando Moisés ya era adulto, salió a ver a su propia gente y vio sus duros trabajos. Vio que un egipcio estaba golpeando a un hebreo , uno de los suyos.',NULL),
(@vid,@bid,2,12,'Miró a un lado y a otro, y al ver que no había nadie, mató al egipcio y lo escondió en la arena.',NULL),
(@vid,@bid,2,13,'Al día siguiente salió de nuevo, y vio a dos hebreos que estaban peleando. Le dijo al que tenía la culpa: “¿ Por qué golpeas a tu compañero ?”.',NULL),
(@vid,@bid,2,14,'El hombre le respondió: “¿ Quién te puso como jefe y juez sobre nosotros ? ¿Acaso piensas matarme , como mataste al egipcio ?” Moisés tuvo miedo y pensó: “Seguramente ya se sabe lo que hice”.',NULL),
(@vid,@bid,2,15,'Cuando el faraón se enteró de esto , intentó matar a Moisés . Pero Moisés huyó del faraón y se fue a vivir a la región de Madián , y se sentó junto a un pozo.',NULL),
(@vid,@bid,2,16,'El sacerdote de Madián tenía siete hijas . Ellas fueron a sacar agua y llenaron los bebederos para darle agua al rebaño de su padre.',NULL),
(@vid,@bid,2,17,'En eso llegaron unos pastores y las echaron de allí; pero Moisés se levantó , las defendió y le dio agua a su rebaño .',NULL),
(@vid,@bid,2,18,'Cuando ellas regresaron a donde estaba Reuel , su padre, él les preguntó: “¿ Cómo es que hoy regresaron tan temprano?”',NULL),
(@vid,@bid,2,19,'Ellas respondieron: “Un egipcio nos defendió de los pastores ; además , nos sacó agua y le dio de beber al rebaño .”',NULL),
(@vid,@bid,2,20,'Él les dijo a sus hijas : “¿ Y dónde está ? ¿ Por qué dejaron a ese hombre allá? Llámenlo para que venga a comer con nosotros”.',NULL),
(@vid,@bid,2,21,'Moisés aceptó quedarse a vivir con aquel hombre, y él le dio por esposa a su hija Séfora.',NULL),
(@vid,@bid,2,22,'Ella dio a luz un hijo , y Moisés le puso por nombre Gersón, porque dijo: “He sido un extranjero en tierra extraña ”.',NULL),
(@vid,@bid,2,23,'Pasó mucho tiempo y el rey de Egipto murió . Los hijos de Israel gemían a causa de su esclavitud y clamaban pidiendo ayuda, y sus gritos llegaron hasta Dios.',NULL),
(@vid,@bid,2,24,'Dios escuchó sus gemidos y se acordó de su pacto con Abraham, con Isaac y con Jacob .',NULL),
(@vid,@bid,2,25,'Dios miró a los hijos de Israel y comprendió su situación.',NULL),
(@vid,@bid,3,1,'Moisés cuidaba las ovejas de su suegro Jetro, el sacerdote de Madián . Un día llevó el rebaño más allá del desierto y llegó a Horeb , el monte de Dios.',NULL),
(@vid,@bid,3,2,'Allí se le apareció el ángel de Yahvé en una llama de fuego en medio de una zarza. Moisés miró y vio que la zarza ardía en llamas, pero no se consumía.',NULL),
(@vid,@bid,3,3,'Entonces Moisés pensó: “Voy a acercarme para ver esta maravilla y descubrir por qué la zarza no se quema”.',NULL),
(@vid,@bid,3,4,'Cuando Yahvé vio que Moisés se acercaba para mirar , Dios lo llamó desde la zarza: “¡ Moisés ! ¡ Moisés !” Y él respondió: “ Aquí estoy”.',NULL),
(@vid,@bid,3,5,'Dios le dijo: “ No te acerques más . Quítate las sandalias, porque el lugar donde estás parado es tierra santa ”.',NULL),
(@vid,@bid,3,6,'Y añadió: “ Yo soy el Dios de tu padre, el Dios de Abraham, el Dios de Isaac y el Dios de Jacob ”. Moisés se cubrió el rostro porque tuvo miedo de mirar a Dios.',NULL),
(@vid,@bid,3,7,'Yahvé le dijo: “He visto el sufrimiento de mi pueblo en Egipto . He escuchado sus gritos de angustia por culpa de sus capataces, y conozco muy bien sus dolores .',NULL),
(@vid,@bid,3,8,'He bajado para rescatarlos del poder de los egipcios y para sacarlos de ese país, a fin de llevarlos a una tierra buena y espaciosa , una tierra donde abundan la leche y la miel ; es la tierra donde viven los cananeos , los hititas, los amorreos, los ferezeos, los heveos y los jebuseos .',NULL),
(@vid,@bid,3,9,'El clamor de los hijos de Israel ha llegado hasta mí , y también he visto cómo los oprimen los egipcios .',NULL),
(@vid,@bid,3,10,'Así que prepárate, porque te voy a enviar al faraón para que saques de Egipto a mi pueblo , a los hijos de Israel ”.',NULL),
(@vid,@bid,3,11,'Pero Moisés le dijo a Dios: “¿ Y quién soy yo para presentarme ante el faraón y sacar de Egipto a los hijos de Israel ?”',NULL),
(@vid,@bid,3,12,'Dios le contestó: “ Yo estaré contigo . Y esta será la señal de que yo te he enviado : cuando hayas sacado de Egipto al pueblo , ustedes adorarán a Dios en este mismo monte .”',NULL),
(@vid,@bid,3,13,'Moisés le dijo a Dios: “Supongamos que me presento ante los hijos de Israel y les digo: El Dios de sus antepasados me ha enviado a ustedes. Si ellos me preguntan: ¿ Cuál es su nombre ?, ¿ qué les voy a responder?”',NULL),
(@vid,@bid,3,14,'Dios le contestó a Moisés : “YO SOY EL QUE SOY ”. Y agregó: “ A los hijos de Israel les dirás esto : YO SOY me ha enviado a ustedes”.',NULL),
(@vid,@bid,3,15,'Dios también le dijo a Moisés : “Diles a los hijos de Israel : Yahvé, el Dios de sus antepasados, el Dios de Abraham, el Dios de Isaac y el Dios de Jacob , me ha enviado a ustedes. Este es mi nombre para siempre ; con este nombre seré recordado por todas las generaciones .',NULL),
(@vid,@bid,3,16,'Ve y reúne a los líderes de Israel , y diles: Yahvé, el Dios de sus antepasados, el Dios de Abraham, de Isaac y de Jacob , se me ha aparecido y me ha dicho: Ciertamente he venido a verlos y he visto lo que les están haciendo en Egipto .',NULL),
(@vid,@bid,3,17,'Y he decidido sacarlos de la opresión de Egipto para llevarlos a la tierra de los cananeos , de los hititas, de los amorreos, de los ferezeos, de los heveos y de los jebuseos , a una tierra donde abundan la leche y la miel .',NULL),
(@vid,@bid,3,18,'Los líderes escucharán tu voz . Luego tú y los líderes de Israel se presentarán ante el rey de Egipto y le dirán: Yahvé, el Dios de los hebreos , ha venido a nuestro encuentro. Ahora , por favor, déjanos hacer un viaje de tres días hacia el desierto , para ofrecerle sacrificios a Yahvé, nuestro Dios .',NULL),
(@vid,@bid,3,19,'Yo sé muy bien que el rey de Egipto no los dejará ir , a menos que una mano poderosa lo obligue.',NULL),
(@vid,@bid,3,20,'Por eso , extenderé mi mano y castigaré a Egipto con todas las maravillas que haré en ese país, y después de eso el rey los dejará ir .',NULL),
(@vid,@bid,3,21,'Yo haré que los egipcios vean con buenos ojos a este pueblo , de modo que cuando ustedes se vayan , no se irán con las manos vacías .',NULL),
(@vid,@bid,3,22,'Cada mujer les pedirá a sus vecinas y a las mujeres que vivan en su casa , objetos de plata y de oro , y ropa . Todo eso se lo pondrán a sus hijos y a sus hijas . Así despojarán a los egipcios ”.',NULL),
(@vid,@bid,4,1,'Moisés respondió : “¿ Y qué pasa si no me creen ni me hacen caso, y me dicen: Yahvé no se te ha aparecido?”',NULL),
(@vid,@bid,4,2,'Yahvé le preguntó: “¿ Qué tienes en la mano ?” Él respondió: “Una vara ”.',NULL),
(@vid,@bid,4,3,'Dios le dijo: “Tírala al suelo”. Moisés la tiró al suelo, y la vara se convirtió en una serpiente ; y Moisés se alejó de ella huyendo.',NULL),
(@vid,@bid,4,4,'Pero Yahvé le dijo: “ Extiende la mano y agárrala por la cola ”. Moisés extendió la mano , la agarró, y la serpiente volvió a ser una vara en su mano .',NULL),
(@vid,@bid,4,5,'“Esto es para que crean que se te ha aparecido Yahvé, el Dios de sus antepasados, el Dios de Abraham, el Dios de Isaac y el Dios de Jacob ”.',NULL),
(@vid,@bid,4,6,'Luego Yahvé le dijo: “Mete la mano dentro de tu ropa”. Moisés metió la mano dentro de su ropa, y cuando la sacó , su mano estaba cubierta de lepra, blanca como la nieve.',NULL),
(@vid,@bid,4,7,'Dios le ordenó: “ Vuelve a meter la mano dentro de tu ropa”. Él la volvió a meter, y cuando la sacó , vio que estaba sana de nuevo, como el resto de su piel.',NULL),
(@vid,@bid,4,8,'“ Si no te creen ni te hacen caso con la primera señal, te creerán con la segunda.',NULL),
(@vid,@bid,4,9,'Y si a pesar de estas dos señales no te creen ni te hacen caso , sacarás agua del río y la derramarás sobre la tierra seca. Esa agua del río se convertirá en sangre al tocar el suelo”.',NULL),
(@vid,@bid,4,10,'Moisés le dijo a Yahvé: “Ay, Señor , yo nunca he tenido facilidad de palabra , ni antes ni ahora que le hablas a tu siervo . Soy muy lento para hablar y me cuesta expresarme”.',NULL),
(@vid,@bid,4,11,'Yahvé le respondió: “¿ Quién le dio la boca al ser humano? ¿Acaso no soy yo, Yahvé, quien lo hace mudo o sordo , o quien le da la vista o lo hace ciego ?',NULL),
(@vid,@bid,4,12,'Así que ve , que yo estaré en tu boca y te enseñaré lo que tienes que decir”.',NULL),
(@vid,@bid,4,13,'Pero Moisés insistió: “Ay, Señor, te ruego que envíes a otra persona”.',NULL),
(@vid,@bid,4,14,'Entonces Yahvé se enojó con Moisés y le dijo : “¿ Qué hay de tu hermano Aarón, el levita ? Yo sé que él habla muy bien . Además , ya viene en camino a buscarte, y se alegrará mucho al verte.',NULL),
(@vid,@bid,4,15,'Tú le hablarás y le pondrás las palabras en la boca . Yo estaré con ustedes cuando hablen , y les enseñaré lo que tienen que hacer .',NULL),
(@vid,@bid,4,16,'Él hablará por ti ante el pueblo . Él será como tu boca , y tú serás para él como Dios.',NULL),
(@vid,@bid,4,17,'Lleva en tu mano esta vara , porque con ella harás las señales”.',NULL),
(@vid,@bid,4,18,'Moisés se fue y regresó a donde estaba su suegro Jetro, y le dijo: “ Por favor, déjame volver a Egipto para ver si mis hermanos todavía están vivos .” Jetro le respondió : “ Vete en paz ”.',NULL),
(@vid,@bid,4,19,'Yahvé le había dicho a Moisés en Madián : “Regresa a Egipto , porque ya han muerto todos los que querían quitarte la vida ”.',NULL),
(@vid,@bid,4,20,'Moisés tomó a su esposa y a sus hijos , los montó en un burro y emprendió el regreso a Egipto . Moisés llevaba en la mano la vara de Dios.',NULL),
(@vid,@bid,4,21,'Yahvé le dijo a Moisés : “Cuando regreses a Egipto , asegúrate de hacer ante el faraón todos los milagros que te he dado el poder de realizar. Pero yo haré que él se ponga terco, y no dejará ir al pueblo .',NULL),
(@vid,@bid,4,22,'Entonces le dirás al faraón : Así dice Yahvé: Israel es mi hijo , mi primogénito ,',NULL),
(@vid,@bid,4,23,'y yo te he ordenado que dejes ir a mi hijo para que me adore. Pero como te has negado a dejarlo ir , voy a quitarle la vida a tu hijo primogénito ”.',NULL),
(@vid,@bid,4,24,'En el camino , en el lugar donde pasaban la noche, Yahvé salió al encuentro de Moisés y quiso matarlo .',NULL),
(@vid,@bid,4,25,'Entonces Séfora agarró un cuchillo de pedernal, le cortó el prepucio a su hijo y lo arrojó a los pies de Moisés, diciendo: “Eres para mí un esposo de sangre ”.',NULL),
(@vid,@bid,4,26,'Así que Dios lo dejó vivir. Ella le dijo “ esposo de sangre ” por causa de la circuncisión.',NULL),
(@vid,@bid,4,27,'Yahvé le dijo a Aarón: “ Ve al desierto a encontrarte con Moisés ”. Aarón fue , se encontró con él en el monte de Dios y lo besó .',NULL),
(@vid,@bid,4,28,'Moisés le contó a Aarón todo lo que Yahvé le había encargado decir, y le habló de todas las señales milagrosas que le había mandado hacer.',NULL),
(@vid,@bid,4,29,'Moisés y Aarón se fueron y reunieron a todos los líderes de los hijos de Israel .',NULL),
(@vid,@bid,4,30,'Aarón repitió todo lo que Yahvé le había dicho a Moisés , y realizó las señales delante del pueblo .',NULL),
(@vid,@bid,4,31,'El pueblo creyó, y al escuchar que Yahvé había venido a ver a los hijos de Israel y que había visto su sufrimiento, se inclinaron y adoraron .',NULL),
(@vid,@bid,5,1,'Después vinieron Moisés y Aarón y le dijeron al faraón : “ Esto es lo que dice Yahvé, el Dios de Israel : ‘ Deja ir a mi pueblo para que me celebre una fiesta en el desierto ’”.',NULL),
(@vid,@bid,5,2,'El faraón respondió: “¿ Quién es Yahvé, para que yo escuche su voz y deje ir a Israel ? Yo no conozco a Yahvé, y tampoco voy a dejar ir a Israel ”.',NULL),
(@vid,@bid,5,3,'Ellos le dijeron: “ El Dios de los hebreos ha venido a nuestro encuentro. Por favor, déjanos ir tres días de camino al desierto para ofrecerle sacrificios a Yahvé, nuestro Dios , no sea que nos castigue con enfermedades o con la espada .”',NULL),
(@vid,@bid,5,4,'El rey de Egipto les reclamó: “¿ Por qué ustedes, Moisés y Aarón, distraen al pueblo de su trabajo? ¡Vuelvan a sus obligaciones!”',NULL),
(@vid,@bid,5,5,'Y el faraón añadió: “Miren, ahora el pueblo es muy numeroso en la tierra, y ustedes hacen que dejen de trabajar”.',NULL),
(@vid,@bid,5,6,'Ese mismo día el faraón les dio esta orden a los capataces del pueblo y a sus supervisores:',NULL),
(@vid,@bid,5,7,'“ Ya no le darán al pueblo paja para hacer ladrillos , como hacían antes . ¡ Que vayan ellos mismos a juntar la paja !',NULL),
(@vid,@bid,5,8,'Pero les exigirán la misma cantidad de ladrillos que hacían antes . No les rebajarán nada , porque son unos flojos. Por eso andan gritando: ‘ Vamos a ofrecerle sacrificios a nuestro Dios’.',NULL),
(@vid,@bid,5,9,'Auméntenles el trabajo pesado a estos hombres, para que se mantengan ocupados y no anden creyendo en mentiras ”.',NULL),
(@vid,@bid,5,10,'Los capataces y los supervisores salieron y le dijeron al pueblo : “ Esto es lo que dice el faraón : ‘ Ya no les voy a dar paja .',NULL),
(@vid,@bid,5,11,'Vayan ustedes mismos y consigan paja donde puedan encontrarla, porque no se les va a rebajar nada de su trabajo’”.',NULL),
(@vid,@bid,5,12,'Así que el pueblo se dispersó por todo Egipto para recoger rastrojos en lugar de paja .',NULL),
(@vid,@bid,5,13,'Los capataces los presionaban diciendo: “¡ Tienen que terminar su cuota de trabajo diaria , igual que cuando se les daba paja !”',NULL),
(@vid,@bid,5,14,'Además , a los supervisores israelitas que los capataces del faraón habían puesto a cargo, los golpeaban y les reclamaban: “¿ Por qué no cumplieron con su cuota de ladrillos ni ayer ni hoy , como lo hacían antes ?”',NULL),
(@vid,@bid,5,15,'Entonces los supervisores israelitas fueron a quejarse con el faraón : “¿ Por qué tratas así a tus siervos ?',NULL),
(@vid,@bid,5,16,'No nos dan paja , y encima nos exigen: ‘¡ Hagan ladrillos !’ Y mira , a tus siervos nos agarran a golpes, cuando la culpa es de tu propia gente .”',NULL),
(@vid,@bid,5,17,'Pero el faraón les contestó: “¡Son unos flojos! ¡ Eso es lo que son! Por eso andan diciendo: ‘Queremos ir a ofrecerle sacrificios a Yahvé’.',NULL),
(@vid,@bid,5,18,'¡ Así que vayan a trabajar ahora mismo! No se les va a dar paja , pero tendrán que entregar la misma cantidad de ladrillos .”',NULL),
(@vid,@bid,5,19,'Los supervisores israelitas se dieron cuenta de que estaban en graves problemas cuando se les dijo: “¡ No se les rebajará ni un solo ladrillo de su cuota diaria !”',NULL),
(@vid,@bid,5,20,'Al salir de hablar con el faraón , se encontraron con Moisés y Aarón, que los estaban esperando en el camino.',NULL),
(@vid,@bid,5,21,'Y les dijeron: “¡ Que Yahvé los vea y los juzgue ! Ustedes nos han hecho quedar muy mal ante el faraón y sus funcionarios; ¡prácticamente les pusieron una espada en la mano para que nos maten !”',NULL),
(@vid,@bid,5,22,'Moisés regresó a donde estaba Yahvé y le dijo: “ Señor , ¿ por qué le has traído tantos problemas a este pueblo ? ¿ Para qué me enviaste ?',NULL),
(@vid,@bid,5,23,'Porque desde que fui a hablar con el faraón en tu nombre , él no ha hecho más que maltratar a este pueblo , y tú no has hecho nada para rescatarlos”.',NULL),
(@vid,@bid,6,1,'Yahvé le respondió a Moisés : “ Ahora vas a ver lo que le haré al faraón . Una mano poderosa lo obligará a dejarlos ir ; es más , ¡esa misma mano poderosa hará que los eche de su país!”',NULL),
(@vid,@bid,6,2,'Dios habló con Moisés y le dijo : “Yo soy Yahvé.',NULL),
(@vid,@bid,6,3,'Me aparecí a Abraham, a Isaac y a Jacob como Dios Todopoderoso , pero no me di a conocer a ellos por mi nombre : Yahvé.',NULL),
(@vid,@bid,6,4,'También establecí mi pacto con ellos , prometiendo darles la tierra de Canaán , la tierra donde vivieron como extranjeros.',NULL),
(@vid,@bid,6,5,'Además , he escuchado los gemidos de los hijos de Israel , a quienes los egipcios tienen esclavizados, y me he acordado de mi pacto .',NULL),
(@vid,@bid,6,6,'Por lo tanto , diles a los hijos de Israel : ‘Yo soy Yahvé. Los sacaré de los duros trabajos de Egipto , los liberaré de su esclavitud y los rescataré con gran poder y con fuertes castigos.',NULL),
(@vid,@bid,6,7,'Los tomaré como mi propio pueblo y yo seré su Dios . Entonces sabrán que yo soy Yahvé, su Dios , el que los saca de los duros trabajos de Egipto .',NULL),
(@vid,@bid,6,8,'Los llevaré a la tierra que juré darles a Abraham, a Isaac y a Jacob , y se la daré como herencia. Yo soy Yahvé’”.',NULL),
(@vid,@bid,6,9,'Moisés les comunicó todo esto a los hijos de Israel , pero ellos no le hicieron caso, porque estaban muy desanimados por culpa de la cruel esclavitud.',NULL),
(@vid,@bid,6,10,'Entonces Yahvé le dijo a Moisés :',NULL),
(@vid,@bid,6,11,'“Ve y dile al faraón , rey de Egipto , que deje salir de su país a los hijos de Israel .”',NULL),
(@vid,@bid,6,12,'Pero Moisés le contestó a Yahvé: “ Si los hijos de Israel no me hacen caso, ¿cómo me va a escuchar el faraón , si soy tan torpe para hablar ?”',NULL),
(@vid,@bid,6,13,'Sin embargo, Yahvé les habló a Moisés y a Aarón, y les dio órdenes estrictas para los hijos de Israel y para el faraón , rey de Egipto , con el fin de sacar a los israelitas del país.',NULL),
(@vid,@bid,6,14,'Estos son los jefes de las familias patriarcales. Los hijos de Rubén , el primogénito de Israel , fueron: Hanoc, Falú, Hezrón y Carmí . Estas son las familias de Rubén .',NULL),
(@vid,@bid,6,15,'Los hijos de Simeón fueron: Jemuel , Jamín , Ohad, Jaquín, Zóhar y Saúl , hijo de una mujer cananea . Estas son las familias de Simeón .',NULL),
(@vid,@bid,6,16,'Estos son los nombres de los hijos de Leví , según sus descendientes: Gersón , Coat y Merari . Leví vivió ciento treinta y siete años .',NULL),
(@vid,@bid,6,17,'Los hijos de Gersón fueron: Libní y Simeí, con sus respectivas familias .',NULL),
(@vid,@bid,6,18,'Los hijos de Coat fueron: Amram , Izhar, Hebrón y Uziel. Coat vivió ciento treinta y tres años .',NULL),
(@vid,@bid,6,19,'Los hijos de Merari fueron: Mahlí y Musí. Estas son las familias de los levitas, según sus descendientes.',NULL),
(@vid,@bid,6,20,'Amram se casó con su tía Jocabed, y ella dio a luz a Aarón y a Moisés . Amram vivió ciento treinta y siete años .',NULL),
(@vid,@bid,6,21,'Los hijos de Izhar fueron: Coré , Néfeg y Zicrí.',NULL),
(@vid,@bid,6,22,'Los hijos de Uziel fueron: Misael , Elzafán y Sitrí.',NULL),
(@vid,@bid,6,23,'Aarón se casó con Eliseba, hija de Aminadab y hermana de Naasón , y ella dio a luz a Nadab , a Abiú, a Eleazar y a Itamar.',NULL),
(@vid,@bid,6,24,'Los hijos de Coré fueron: Asir, Elcaná y Abiasaf. Estas son las familias de los coreítas.',NULL),
(@vid,@bid,6,25,'Eleazar, hijo de Aarón, se casó con una de las hijas de Putiel, y ella dio a luz a Finees. Estos son los jefes de las familias patriarcales de los levitas .',NULL),
(@vid,@bid,6,26,'Estos son los mismos Aarón y Moisés a quienes Yahvé les ordenó: “Saquen de Egipto a los hijos de Israel , ordenados por escuadrones.”',NULL),
(@vid,@bid,6,27,'Ellos fueron los que hablaron con el faraón , rey de Egipto , para sacar de allí a los israelitas. Fueron Moisés y Aarón.',NULL),
(@vid,@bid,6,28,'El día que Yahvé le habló a Moisés en Egipto ,',NULL),
(@vid,@bid,6,29,'le dijo : “Yo soy Yahvé. Dile al faraón , rey de Egipto , todo lo que yo te diga ”.',NULL),
(@vid,@bid,6,30,'Pero Moisés le respondió a Yahvé: “ Mira , a mí me cuesta mucho expresarme, ¿cómo me va a hacer caso el faraón ?”',NULL),
(@vid,@bid,7,1,'Yahvé le dijo a Moisés : “ Mira , te voy a hacer como un Dios ante el faraón , y tu hermano Aarón será tu profeta .',NULL),
(@vid,@bid,7,2,'Tú le dirás a Aarón todo lo que yo te ordene , y él le hablará al faraón para que deje salir de su país a los hijos de Israel .',NULL),
(@vid,@bid,7,3,'Pero yo voy a hacer que el faraón se ponga terco, para multiplicar mis señales y maravillas en Egipto .',NULL),
(@vid,@bid,7,4,'El faraón no les va a hacer caso; entonces descargaré mi poder sobre Egipto y, mediante grandes castigos, sacaré de allí a mis escuadrones, a mi pueblo , los hijos de Israel .',NULL),
(@vid,@bid,7,5,'Y cuando yo extienda mi mano contra Egipto y saque de allí a los israelitas, los egipcios sabrán que yo soy Yahvé.”',NULL),
(@vid,@bid,7,6,'Moisés y Aarón hicieron todo exactamente como Yahvé se lo había ordenado .',NULL),
(@vid,@bid,7,7,'Moisés tenía ochenta años y Aarón ochenta y tres cuando hablaron con el faraón .',NULL),
(@vid,@bid,7,8,'Yahvé les dijo a Moisés y a Aarón:',NULL),
(@vid,@bid,7,9,'“ Cuando el faraón les pida que hagan un milagro , tú le dirás a Aarón: ‘ Toma tu vara y tírala al piso delante del faraón ’, y la vara se convertirá en una serpiente”.',NULL),
(@vid,@bid,7,10,'Moisés y Aarón se presentaron ante el faraón e hicieron lo que Yahvé les había ordenado . Aarón tiró su vara delante del faraón y de sus funcionarios, y la vara se convirtió en una serpiente.',NULL),
(@vid,@bid,7,11,'Pero el faraón mandó llamar a sus sabios y hechiceros; y los magos de Egipto hicieron lo mismo con sus trucos de magia.',NULL),
(@vid,@bid,7,12,'Cada uno de ellos tiró su vara , y estas se convirtieron en serpientes; pero la vara de Aarón se tragó a las de ellos.',NULL),
(@vid,@bid,7,13,'A pesar de esto, el faraón se puso terco y no les hizo caso , tal como Yahvé lo había advertido.',NULL),
(@vid,@bid,7,14,'Entonces Yahvé le dijo a Moisés : “El faraón está terco de corazón y se niega a dejar ir al pueblo .',NULL),
(@vid,@bid,7,15,'Búscalo por la mañana , cuando él baje al río . Espéralo en la orilla y lleva contigo la vara que se convirtió en serpiente .',NULL),
(@vid,@bid,7,16,'Y dile: ‘Yahvé, el Dios de los hebreos , me ha enviado para decirte: Deja ir a mi pueblo para que me adore en el desierto . Pero como hasta ahora no has querido obedecer ,',NULL),
(@vid,@bid,7,17,'Yahvé dice: Con esto sabrás que yo soy Yahvé. Mira , voy a golpear el agua del río con la vara que tengo en la mano , y el agua se convertirá en sangre .',NULL),
(@vid,@bid,7,18,'Los peces del río morirán , el río apestará, y a los egipcios les dará asco beber de su agua ’”.',NULL),
(@vid,@bid,7,19,'Yahvé también le dijo a Moisés : “Dile a Aarón: ‘ Toma tu vara y extiende tu mano sobre las aguas de Egipto , sobre sus ríos , canales, lagunas y todos sus depósitos de agua , para que se conviertan en sangre . Habrá sangre por todo Egipto , ¡incluso en los recipientes de madera y de piedra!’”',NULL),
(@vid,@bid,7,20,'Moisés y Aarón hicieron exactamente lo que Yahvé les mandó . A la vista del faraón y de sus funcionarios, Aarón levantó la vara , golpeó el agua del río , ¡y toda el agua se convirtió en sangre !',NULL),
(@vid,@bid,7,21,'Los peces del río murieron y el río apestaba tanto que los egipcios no podían beber de él . Había sangre por todo el país de Egipto .',NULL),
(@vid,@bid,7,22,'Pero los magos egipcios hicieron lo mismo con sus trucos de magia. Así que el faraón siguió terco y no les hizo caso a Moisés y Aarón, tal como Yahvé había dicho .',NULL),
(@vid,@bid,7,23,'El faraón dio media vuelta, regresó a su palacio y no le dio ninguna importancia al asunto.',NULL),
(@vid,@bid,7,24,'Mientras tanto, como los egipcios no podían beber agua del río , tuvieron que cavar pozos a las orillas para conseguir agua .',NULL),
(@vid,@bid,7,25,'Pasaron siete días completos desde que Yahvé golpeó el río .',NULL),
(@vid,@bid,8,1,'Yahvé le dijo a Moisés : “ Ve a ver al faraón y dile: ‘Así dice Yahvé: Deja ir a mi pueblo para que me adore.',NULL),
(@vid,@bid,8,2,'Si te niegas a dejarlos ir, voy a plagar de ranas todo tu territorio.',NULL),
(@vid,@bid,8,3,'El río se va a llenar de ranas ; saldrán del agua y se meterán a tu palacio, a tu recámara, a tu cama, a las casas de tus funcionarios y a las de tu pueblo. ¡ Se meterán hasta en tus hornos y en donde amasas el pan!',NULL),
(@vid,@bid,8,4,'Las ranas se treparán sobre ti , sobre tu pueblo y sobre todos tus funcionarios’”.',NULL),
(@vid,@bid,8,5,'Yahvé le añadió a Moisés : “Dile a Aarón: ‘Extiende la mano con tu vara sobre los ríos , canales y lagunas, y haz que salgan ranas por todo Egipto’”.',NULL),
(@vid,@bid,8,6,'Aarón extendió su mano sobre las aguas de Egipto, y las ranas salieron y cubrieron todo el país.',NULL),
(@vid,@bid,8,7,'Pero los magos hicieron lo mismo con sus trucos de magia, y también hicieron que salieran ranas sobre Egipto.',NULL),
(@vid,@bid,8,8,'Entonces el faraón mandó llamar a Moisés y a Aarón, y les dijo: “Rueguen a Yahvé que nos quite las ranas a mí y a mi pueblo , y dejaré ir al pueblo para que le ofrezca sacrificios a Yahvé.”',NULL),
(@vid,@bid,8,9,'Moisés le contestó al faraón: “ Te doy el honor de elegir cuándo quieres que ore por ti , por tus funcionarios y por tu pueblo, para que las ranas desaparezcan de sus casas y solo queden en el río.”',NULL),
(@vid,@bid,8,10,'“Mañana mismo”, respondió el faraón. Moisés le dijo: “Se hará como tú dices, para que sepas que no hay nadie como Yahvé, nuestro Dios.',NULL),
(@vid,@bid,8,11,'Las ranas se irán de tu presencia, de tus casas, de tus funcionarios y de tu pueblo. Solamente quedarán en el río”.',NULL),
(@vid,@bid,8,12,'Moisés y Aarón salieron de la presencia del faraón, y Moisés le rogó a Yahvé que quitara las ranas que había mandado contra el faraón.',NULL),
(@vid,@bid,8,13,'Yahvé hizo lo que Moisés le pidió, y las ranas se murieron en las casas, en los patios y en los campos.',NULL),
(@vid,@bid,8,14,'Las juntaron e hicieron grandes montones con ellas, y todo el país apestaba.',NULL),
(@vid,@bid,8,15,'Pero cuando el faraón vio que la situación había mejorado, volvió a ponerse terco y no les hizo caso , tal como Yahvé lo había advertido.',NULL),
(@vid,@bid,8,16,'Yahvé le dijo a Moisés : “Dile a Aarón: ‘ Extiende tu vara y golpea el polvo del piso, para que se convierta en piojos por todo Egipto’”.',NULL),
(@vid,@bid,8,17,'Así lo hicieron. Aarón extendió la mano, golpeó el polvo del piso con su vara, ¡ y todo el polvo de Egipto se convirtió en piojos que atacaron a la gente y a los animales!',NULL),
(@vid,@bid,8,18,'Los magos intentaron producir piojos con sus trucos de magia, pero esta vez no pudieron. Y los piojos seguían atacando a la gente y a los animales.',NULL),
(@vid,@bid,8,19,'Entonces los magos le dijeron al faraón: “¡ Este es el dedo de Dios!” Pero el faraón siguió terco y no los escuchó, tal como Yahvé lo había dicho.',NULL),
(@vid,@bid,8,20,'Yahvé le dijo a Moisés: “Levántate muy temprano y espéralo. Cuando el faraón baje al agua, dile: ‘ Así dice Yahvé: Deja ir a mi pueblo para que me adore.',NULL),
(@vid,@bid,8,21,'Porque si no los dejas ir , voy a mandar enjambres de moscas sobre ti, sobre tus funcionarios, sobre tu pueblo y sobre tus casas. Las casas de los egipcios se van a llenar de moscas, y hasta el suelo donde pisan estará cubierto de ellas.',NULL),
(@vid,@bid,8,22,'Pero ese día haré una excepción con la región de Gosén, donde vive mi pueblo; allí no habrá ninguna mosca, para que sepas que yo , Yahvé, estoy presente en esta tierra.',NULL),
(@vid,@bid,8,23,'Haré una clara diferencia entre mi pueblo y el tuyo. Esta señal ocurrirá mañana’”.',NULL),
(@vid,@bid,8,24,'Y así lo hizo Yahvé. Llegaron densos enjambres de moscas al palacio del faraón y a las casas de sus funcionarios. ¡Todo el país de Egipto quedó arruinado por culpa de las moscas!',NULL),
(@vid,@bid,8,25,'Entonces el faraón mandó llamar a Moisés y a Aarón, y les dijo: “Vayan a ofrecerle sacrificios a su Dios , ¡pero aquí mismo en el país!”',NULL),
(@vid,@bid,8,26,'Moisés le respondió: “Eso no está bien, porque los sacrificios que le ofrecemos a Yahvé, nuestro Dios , resultan ofensivos para los egipcios. Si hacemos esos sacrificios delante de ellos, ¿acaso no nos agarrarán a pedradas?',NULL),
(@vid,@bid,8,27,'Tenemos que ir a tres días de camino por el desierto para ofrecerle sacrificios a Yahvé, nuestro Dios , tal como él nos lo ordene.”',NULL),
(@vid,@bid,8,28,'El faraón cedió: “Los dejaré ir para que le ofrezcan sacrificios a Yahvé, su Dios, en el desierto, siempre y cuando no se vayan muy lejos. Y rueguen por mí”.',NULL),
(@vid,@bid,8,29,'Moisés le dijo: “En cuanto salga de aquí, voy a orar a Yahvé para que mañana mismo las moscas se alejen del faraón, de sus funcionarios y de su pueblo. Pero no vuelvas a engañarnos negándote a dejar ir al pueblo a ofrecerle sacrificios a Yahvé.”',NULL),
(@vid,@bid,8,30,'Moisés salió de la presencia del faraón y oró a Yahvé.',NULL),
(@vid,@bid,8,31,'Yahvé hizo lo que Moisés le pidió, y apartó los enjambres de moscas del faraón, de sus funcionarios y de su pueblo. ¡No quedó ni una sola mosca!',NULL),
(@vid,@bid,8,32,'Pero una vez más, el faraón se puso terco y tampoco esta vez dejó ir al pueblo.',NULL),
(@vid,@bid,9,1,'Entonces Yahvé le dijo a Moisés : “Ve a ver al faraón y dile: ‘ Esto es lo que dice Yahvé, el Dios de los hebreos : Deja ir a mi pueblo para que me adore.',NULL),
(@vid,@bid,9,2,'Porque si te niegas a dejarlos ir y los sigues reteniendo,',NULL),
(@vid,@bid,9,3,'ten por seguro que la mano de Yahvé caerá sobre tu ganado que está en el campo , sobre los caballos , sobre los burros, sobre los camellos , sobre las vacas y sobre las ovejas , con una plaga muy grave .',NULL),
(@vid,@bid,9,4,'Pero Yahvé hará una distinción entre el ganado de Israel y el de Egipto , de modo que no morirá ningún animal que pertenezca a los hijos de Israel ’”.',NULL),
(@vid,@bid,9,5,'Yahvé fijó la fecha, diciendo: “ Mañana mismo Yahvé hará esto en el país”.',NULL),
(@vid,@bid,9,6,'Y Yahvé lo cumplió al día siguiente ; todo el ganado de Egipto murió , pero del ganado de los hijos de Israel no murió ni un solo animal.',NULL),
(@vid,@bid,9,7,'El faraón mandó a investigar, y resultó que no había muerto ni un solo animal de los israelitas. A pesar de esto, el faraón se puso terco y no dejó ir al pueblo .',NULL),
(@vid,@bid,9,8,'Yahvé les dijo a Moisés y a Aarón: “ Tomen puñados de ceniza de un horno y que Moisés la arroje al aire delante del faraón .',NULL),
(@vid,@bid,9,9,'Esa ceniza se convertirá en un polvo fino que cubrirá todo Egipto , y producirá llagas y úlceras en la piel de la gente y de los animales por todo el país.”',NULL),
(@vid,@bid,9,10,'Ellos tomaron ceniza del horno y se pararon frente al faraón ; Moisés la arrojó al aire, y salieron llagas y úlceras en la piel tanto de las personas como de los animales.',NULL),
(@vid,@bid,9,11,'Los magos ni siquiera pudieron presentarse delante de Moisés debido a las úlceras, porque las úlceras afectaron a los magos y a todos los egipcios .',NULL),
(@vid,@bid,9,12,'Pero Yahvé hizo que el faraón se pusiera terco y no les hizo caso , tal como Yahvé se lo había advertido a Moisés .',NULL),
(@vid,@bid,9,13,'Yahvé le dijo a Moisés : “ Levántate muy temprano, preséntate ante el faraón y dile: ‘ Así dice Yahvé, el Dios de los hebreos : Deja ir a mi pueblo para que me adore.',NULL),
(@vid,@bid,9,14,'Porque esta vez voy a enviar todas mis plagas contra ti mismo , contra tus funcionarios y contra tu pueblo , para que sepas que en toda la tierra no hay nadie como yo .',NULL),
(@vid,@bid,9,15,'Si yo hubiera extendido mi mano y los hubiera castigado con enfermedades a ti y a tu pueblo , ya habrías desaparecido del mapa;',NULL),
(@vid,@bid,9,16,'pero en realidad, te he dejado con vida para mostrarte mi poder y para que mi nombre sea famoso en toda la tierra,',NULL),
(@vid,@bid,9,17,'ya que todavía te crees superior a mi pueblo y no lo dejas ir .',NULL),
(@vid,@bid,9,18,'Por eso, mañana a esta hora voy a mandar la peor tormenta de granizo que haya caído en Egipto desde que el país fue fundado.',NULL),
(@vid,@bid,9,19,'Así que manda a refugiar tu ganado y todo lo que tengas en el campo . El granizo caerá sobre cualquier persona o animal que se quede afuera y no sea llevado a un lugar seguro, y morirán ’”.',NULL),
(@vid,@bid,9,20,'Los funcionarios del faraón que le tuvieron miedo a la advertencia de Yahvé metieron de prisa a sus esclavos y a sus animales en las casas .',NULL),
(@vid,@bid,9,21,'Pero los que no le dieron importancia a la advertencia de Yahvé, dejaron a sus esclavos y a sus animales en el campo .',NULL),
(@vid,@bid,9,22,'Yahvé le dijo a Moisés : “Levanta la mano hacia el cielo para que caiga granizo en todo Egipto , sobre la gente, sobre los animales y sobre todas las plantas del campo en todo el país.”',NULL),
(@vid,@bid,9,23,'Moisés levantó su vara hacia el cielo , y Yahvé mandó truenos y granizo , y cayeron rayos sobre la tierra. Yahvé hizo que lloviera granizo sobre Egipto .',NULL),
(@vid,@bid,9,24,'Fue una tormenta de granizo terrible, con rayos que caían sin parar, algo que jamás se había visto en Egipto desde que se formó como nación .',NULL),
(@vid,@bid,9,25,'En todo Egipto , el granizo destruyó todo lo que estaba a la intemperie, tanto personas como animales. El granizo también hizo pedazos todas las plantas y destrozó todos los árboles del campo .',NULL),
(@vid,@bid,9,26,'El único lugar donde no cayó granizo fue en la región de Gosén, donde vivían los israelitas.',NULL),
(@vid,@bid,9,27,'Entonces el faraón mandó llamar a Moisés y a Aarón, y les dijo: “Esta vez reconozco que he pecado . Yahvé tiene la razón, y mi pueblo y yo somos los culpables.',NULL),
(@vid,@bid,9,28,'Ruéguenle a Yahvé por nosotros, porque ya no aguantamos más estos truenos y este granizo . Los dejaré ir , ya no tendrán que quedarse más tiempo”.',NULL),
(@vid,@bid,9,29,'Moisés le respondió: “ En cuanto yo salga de la ciudad , levantaré mis manos para orarle a Yahvé. Los truenos se detendrán y ya no caerá más granizo , para que sepas que la tierra le pertenece a Yahvé.',NULL),
(@vid,@bid,9,30,'Pero sé muy bien que tú y tus funcionarios todavía no le tienen respeto a Yahvé Dios ”.',NULL),
(@vid,@bid,9,31,'Los cultivos de lino y de cebada quedaron arruinados, porque la cebada ya había espigado y el lino estaba floreciendo.',NULL),
(@vid,@bid,9,32,'Pero el trigo y el centeno no sufrieron daños porque maduran más tarde.',NULL),
(@vid,@bid,9,33,'Moisés salió de la ciudad , se alejó del faraón y levantó sus manos hacia Yahvé. Al instante se calmaron los truenos y el granizo , y dejó de llover.',NULL),
(@vid,@bid,9,34,'Pero cuando el faraón vio que la lluvia , el granizo y los truenos se habían detenido, volvió a pecar ; él y sus funcionarios se pusieron tercos otra vez.',NULL),
(@vid,@bid,9,35,'Y con el corazón endurecido, el faraón no dejó ir a los israelitas, tal como Yahvé lo había advertido por medio de Moisés .',NULL),
(@vid,@bid,10,1,'Yahvé le dijo a Moisés : “Ve a ver al faraón . Yo he hecho que él y sus funcionarios se pongan tercos, para poder mostrar mis señales milagrosas entre ellos,',NULL),
(@vid,@bid,10,2,'y para que les cuentes a tus hijos y a tus nietos lo que le hice a Egipto y las señales que realicé entre ellos. Así sabrán que yo soy Yahvé.”',NULL),
(@vid,@bid,10,3,'Moisés y Aarón se presentaron ante el faraón y le dijeron: “ Así dice Yahvé, el Dios de los hebreos : ‘¿ Hasta cuándo te vas a negar a someterte a mí? Deja ir a mi pueblo para que me adore.',NULL),
(@vid,@bid,10,4,'Porque si no los dejas ir , mañana voy a mandar langostas sobre tu país.',NULL),
(@vid,@bid,10,5,'Van a cubrir la superficie de la tierra de tal modo que ni siquiera se podrá ver el piso. Se van a comer lo poquito que se salvó del granizo y acabarán con todos los árboles que crecen en el campo .',NULL),
(@vid,@bid,10,6,'Llenarán tus palacios, las casas de tus funcionarios y las de todos los egipcios . Será algo que jamás vieron tus padres ni tus abuelos desde que vivieron en esta tierra hasta el día de hoy ’”. Luego Moisés dio media vuelta y salió de la presencia del faraón .',NULL),
(@vid,@bid,10,7,'Los funcionarios le dijeron al faraón : “¿ Hasta cuándo nos va a traer problemas este hombre? Deja que esa gente se vaya a adorar a Yahvé, su Dios . ¿Acaso no te das cuenta de que Egipto está en la ruina?”',NULL),
(@vid,@bid,10,8,'Entonces mandaron llamar de nuevo a Moisés y a Aarón, y el faraón les dijo: “ Vayan y adoren a Yahvé su Dios . Pero díganme, ¿ quiénes son los que se van ?”',NULL),
(@vid,@bid,10,9,'Moisés le contestó: “Nos vamos todos: nuestros jóvenes y nuestros ancianos , nuestros hijos y nuestras hijas , y también nos llevaremos nuestras ovejas y nuestras vacas , porque tenemos que celebrarle una fiesta a Yahvé”.',NULL),
(@vid,@bid,10,10,'El faraón les respondió: “¡ Que Yahvé los ayude si creen que voy a dejar que se lleven a sus familias! Se ve que tienen malas intenciones.',NULL),
(@vid,@bid,10,11,'¡ De ninguna manera! Vayan solo los hombres a adorar a Yahvé, ya que eso era lo que querían”. Y los echaron de la presencia del faraón .',NULL),
(@vid,@bid,10,12,'Yahvé le dijo a Moisés : “Levanta tu mano sobre Egipto para que vengan las langostas. Ellas devorarán todas las plantas del país, todo lo que dejó el granizo .”',NULL),
(@vid,@bid,10,13,'Moisés levantó su vara sobre Egipto , y Yahvé mandó un viento del este que sopló sobre el país todo el día y toda la noche . A la mañana siguiente, el viento del este había traído las langostas.',NULL),
(@vid,@bid,10,14,'Las langostas invadieron todo Egipto y se asentaron en todo el territorio. Fue una plaga espantosa. Nunca antes se habían visto tantas langostas, ni se volverán a ver.',NULL),
(@vid,@bid,10,15,'Cubrieron por completo la superficie de la tierra y la oscurecieron. Se comieron todas las plantas y todos los frutos de los árboles que se habían salvado del granizo . No quedó ni una sola hoja verde en los árboles ni en las plantas de todo Egipto .',NULL),
(@vid,@bid,10,16,'El faraón mandó llamar de urgencia a Moisés y a Aarón, y les dijo: “He pecado contra Yahvé su Dios , y contra ustedes.',NULL),
(@vid,@bid,10,17,'Les ruego que me perdonen esta vez . Pídanle a Yahvé su Dios que , por favor, me quite esta plaga mortal.”',NULL),
(@vid,@bid,10,18,'Moisés salió del palacio del faraón y oró a Yahvé.',NULL),
(@vid,@bid,10,19,'Entonces Yahvé cambió la dirección del viento y mandó un viento muy fuerte del oeste que se llevó a las langostas y las arrojó al Mar Rojo. No quedó ni una sola langosta en todo el territorio de Egipto .',NULL),
(@vid,@bid,10,20,'Pero Yahvé hizo que el faraón se pusiera terco, y no dejó ir a los israelitas.',NULL),
(@vid,@bid,10,21,'Yahvé le dijo a Moisés : “Levanta la mano hacia el cielo para que todo Egipto se cubra de oscuridad , una oscuridad tan densa que hasta se pueda sentir.”',NULL),
(@vid,@bid,10,22,'Moisés levantó la mano hacia el cielo , y una densa oscuridad cubrió todo Egipto durante tres días .',NULL),
(@vid,@bid,10,23,'Las personas no podían verse unas a otras, y nadie salió de su casa en tres días . En cambio, todos los israelitas tenían luz en los lugares donde vivían.',NULL),
(@vid,@bid,10,24,'El faraón mandó llamar a Moisés y le dijo: “ Vayan a adorar a Yahvé. Solo dejen aquí sus ovejas y sus vacas . Sus niños también pueden ir con ustedes.”',NULL),
(@vid,@bid,10,25,'Pero Moisés le contestó: “ Tú también tienes que darnos animales para ofrecerle sacrificios y holocaustos a Yahvé nuestro Dios .',NULL),
(@vid,@bid,10,26,'Así que nuestro ganado se irá con nosotros . No dejaremos ni una sola pezuña aquí , porque tenemos que tomar de esos animales para adorar a Yahvé nuestro Dios , y no sabremos cuáles vamos a sacrificar hasta que lleguemos allá .”',NULL),
(@vid,@bid,10,27,'Pero Yahvé hizo que el faraón se pusiera terco, y no quiso dejarlos ir .',NULL),
(@vid,@bid,10,28,'El faraón le gritó: “¡Lárgate de aquí! Y ten cuidado de no volver a presentarte ante mí , porque el día que vuelvas a verme la cara , te mueres”.',NULL),
(@vid,@bid,10,29,'Moisés le respondió: “ Tienes toda la razón. No volveré a verte la cara ”.',NULL),
(@vid,@bid,11,1,'Yahvé le dijo a Moisés : “Voy a mandar una plaga más sobre el faraón y sobre Egipto . Después de eso , los dejará ir . Y cuando los deje ir , definitivamente los echará a todos de aquí .',NULL),
(@vid,@bid,11,2,'Habla ahora con el pueblo , y diles que cada hombre le pida a su vecino, y cada mujer a su vecina, objetos de plata y de oro .”',NULL),
(@vid,@bid,11,3,'Yahvé hizo que los egipcios vieran con buenos ojos al pueblo . Además , en todo Egipto se le tenía un gran respeto a Moisés , tanto los funcionarios del faraón como el pueblo en general.',NULL),
(@vid,@bid,11,4,'Y Moisés dijo: “ Así dice Yahvé: ‘Alrededor de la medianoche pasaré por todo Egipto ,',NULL),
(@vid,@bid,11,5,'y morirán todos los hijos mayores en Egipto , desde el primogénito del faraón que se sienta en el trono , hasta el primogénito de la esclava que muele en el molino, y también todas las primeras crías de los animales.',NULL),
(@vid,@bid,11,6,'Habrá gritos de dolor en todo Egipto , como nunca antes se han escuchado ni se volverán a escuchar.',NULL),
(@vid,@bid,11,7,'Pero a los israelitas ni siquiera les gruñirá un perro , ni a ellos ni a sus animales . Así sabrán que Yahvé hace una clara diferencia entre Egipto e Israel ’.',NULL),
(@vid,@bid,11,8,'Entonces todos estos funcionarios tuyos vendrán a buscarme, se arrodillarán ante mí y me suplicarán: ‘¡Váyanse tú y todo tu pueblo !’ Y después de eso , me iré”. Y Moisés salió muy enojado de la presencia del faraón .',NULL),
(@vid,@bid,11,9,'Yahvé le había dicho a Moisés : “El faraón no les va a hacer caso, para que yo pueda multiplicar mis milagros en Egipto ”.',NULL),
(@vid,@bid,11,10,'Moisés y Aarón hicieron todos estos milagros delante del faraón , pero Yahvé hizo que el faraón se pusiera terco y no dejara salir de su país a los israelitas.',NULL),
(@vid,@bid,12,1,'Yahvé les habló a Moisés y a Aarón en Egipto , y les dijo:',NULL),
(@vid,@bid,12,2,'“ Este mes será para ustedes el primer mes , el mes más importante del año .',NULL),
(@vid,@bid,12,3,'Háblenle a toda la comunidad de Israel y díganles: ‘ El día diez de este mes , cada jefe de familia deberá escoger un cordero para su familia , un cordero por casa .',NULL),
(@vid,@bid,12,4,'Si la familia es muy pequeña para comerse un cordero entero, entonces se juntará con el vecino que viva más cerca , de acuerdo al número de personas . Calcularán la cantidad de cordero según lo que cada persona pueda comer .',NULL),
(@vid,@bid,12,5,'El animal deberá ser un macho de un año y sin ningún defecto; puede ser un cordero o un cabrito.',NULL),
(@vid,@bid,12,6,'Lo guardarán hasta el día catorce de este mismo mes , y al atardecer, toda la comunidad de Israel lo sacrificará.',NULL),
(@vid,@bid,12,7,'Tomarán un poco de la sangre y la untarán en los marcos y en la parte superior de la puerta de las casas donde se lo vayan a comer.',NULL),
(@vid,@bid,12,8,'Esa misma noche comerán la carne asada al fuego, acompañada de pan sin levadura y hierbas amargas.',NULL),
(@vid,@bid,12,9,'No coman nada de la carne cruda ni hervida en agua ; tiene que estar asada al fuego, entera, con su cabeza , sus patas y sus entrañas.',NULL),
(@vid,@bid,12,10,'No dejen que sobre nada para la mañana siguiente; si sobra algo, deberán quemarlo.',NULL),
(@vid,@bid,12,11,'Cuando coman el cordero, deberán estar listos para viajar: con el cinturón abrochado, las sandalias puestas y el bastón en la mano . Y tendrán que comerlo de prisa. Es la Pascua de Yahvé.',NULL),
(@vid,@bid,12,12,'Porque esa misma noche yo pasaré por todo Egipto y les quitaré la vida a todos los primogénitos , tanto personas como animales. Ejecutaré mi juicio contra todos los dioses de Egipto . Yo soy Yahvé.',NULL),
(@vid,@bid,12,13,'La sangre en sus casas les servirá de señal. Cuando yo vea la sangre , pasaré de largo, y no habrá entre ustedes ninguna plaga mortal cuando yo castigue a Egipto .',NULL),
(@vid,@bid,12,14,'Este será un día para recordar, y deberán celebrarlo como una fiesta en honor a Yahvé. Lo celebrarán generación tras generación como una ley permanente.',NULL),
(@vid,@bid,12,15,'Durante siete días comerán pan sin levadura . El primer día sacarán toda la levadura de sus casas , porque si alguien come pan con levadura entre el primer y el séptimo día , será expulsado del pueblo de Israel .',NULL),
(@vid,@bid,12,16,'El primer día celebrarán una reunión sagrada, y también el séptimo día . En esos días no se hará ningún trabajo, solo podrán preparar la comida que cada uno vaya a consumir.',NULL),
(@vid,@bid,12,17,'Celebrarán la fiesta del pan sin levadura porque ese mismo día saqué a los escuadrones de ustedes de Egipto . Por eso, deberán celebrar este día generación tras generación como una ley permanente.',NULL),
(@vid,@bid,12,18,'Comerán pan sin levadura desde el atardecer del día catorce del primer mes hasta el atardecer del día veintiuno del mismo mes .',NULL),
(@vid,@bid,12,19,'Durante siete días no debe haber levadura en sus casas . Todo el que coma algo que tenga levadura será expulsado de la comunidad de Israel , ya sea extranjero o nacido en el país.',NULL),
(@vid,@bid,12,20,'Así que no coman nada que tenga levadura. Dondequiera que vivan, comerán pan sin levadura’”.',NULL),
(@vid,@bid,12,21,'Entonces Moisés mandó llamar a todos los líderes de Israel y les dijo: “Vayan y escojan los corderos para sus familias , y sacrifiquen el animal para la Pascua .',NULL),
(@vid,@bid,12,22,'Tomen un manojo de hisopo, mójenlo en la sangre que está en el recipiente y unten con ella la parte superior y los lados de la puerta . Nadie debe salir de su casa hasta la mañana siguiente.',NULL),
(@vid,@bid,12,23,'Porque Yahvé pasará castigando a los egipcios ; y cuando él vea la sangre en la parte superior y en los lados de la puerta , pasará de largo y no dejará que el destructor entre a sus casas a quitarles la vida.',NULL),
(@vid,@bid,12,24,'Ustedes y sus descendientes deberán cumplir con esta ordenanza para siempre .',NULL),
(@vid,@bid,12,25,'Cuando entren a la tierra que Yahvé les prometió dar , deberán seguir celebrando esta ceremonia.',NULL),
(@vid,@bid,12,26,'Y cuando sus hijos les pregunten: ‘¿ Qué significa esta ceremonia para ustedes?’',NULL),
(@vid,@bid,12,27,'Le responderán: ‘ Es el sacrificio de la Pascua en honor a Yahvé, quien en Egipto pasó de largo por las casas de los israelitas; castigó a los egipcios pero salvó a nuestras familias ’”. Al escuchar esto , el pueblo se inclinó y adoró a Dios .',NULL),
(@vid,@bid,12,28,'Los israelitas fueron e hicieron todo tal como Yahvé se lo había ordenado a Moisés y a Aarón.',NULL),
(@vid,@bid,12,29,'A la medianoche, Yahvé les quitó la vida a todos los hijos mayores de Egipto , desde el primogénito del faraón que se sentaba en el trono , hasta el primogénito del preso que estaba en el calabozo, y también a todas las primeras crías de los animales.',NULL),
(@vid,@bid,12,30,'El faraón se despertó en la madrugada, junto con sus funcionarios y todos los egipcios . Había un llanto desgarrador en todo Egipto , porque no había una sola casa donde no hubiera un muerto .',NULL),
(@vid,@bid,12,31,'Esa misma noche el faraón mandó llamar a Moisés y a Aarón, y les dijo : “¡ Levántense y lárguense de mi país, ustedes y los israelitas! Vayan a adorar a Yahvé, tal como lo pidieron.',NULL),
(@vid,@bid,12,32,'Llévense también sus ovejas y sus vacas , como querían, pero ¡váyanse ya ! Y pidan que me vaya bien”.',NULL),
(@vid,@bid,12,33,'Los egipcios apuraban al pueblo para que se fueran rápido del país, pues decían: “ Si no se van, ¡ todos nos vamos a morir !”',NULL),
(@vid,@bid,12,34,'Así que el pueblo se llevó la masa antes de ponerle la levadura, y cargaron en los hombros los recipientes de amasar envueltos en sus mantos.',NULL),
(@vid,@bid,12,35,'Los israelitas hicieron lo que Moisés les había dicho , y les pidieron a los egipcios objetos de plata , objetos de oro y ropa .',NULL),
(@vid,@bid,12,36,'Yahvé hizo que los egipcios vieran con buenos ojos al pueblo , y les dieron lo que les pidieron . De esta manera, despojaron a los egipcios de sus riquezas.',NULL),
(@vid,@bid,12,37,'Los israelitas salieron de Ramesés rumbo a Sucot. Eran unos seiscientos mil hombres a pie, sin contar a las mujeres y a los niños .',NULL),
(@vid,@bid,12,38,'Con ellos también salió una gran multitud de gente de toda clase, y muchísimas ovejas , vacas y ganado .',NULL),
(@vid,@bid,12,39,'Como los echaron de Egipto y no tuvieron tiempo de prepararse comida , cocieron la masa que llevaban y comieron pan sin levadura.',NULL),
(@vid,@bid,12,40,'Los israelitas habían vivido en Egipto durante cuatrocientos treinta años .',NULL),
(@vid,@bid,12,41,'El mismo día en que se cumplieron los cuatrocientos treinta años , todos los escuadrones de Yahvé salieron de Egipto .',NULL),
(@vid,@bid,12,42,'Esa fue una noche en la que Yahvé estuvo cuidándolos para sacarlos de Egipto ; por eso , todos los israelitas, de generación en generación , deben celebrar esa noche en honor a Yahvé.',NULL),
(@vid,@bid,12,43,'Yahvé les dijo a Moisés y a Aarón: “ Estas son las reglas para la Pascua : Ningún extranjero podrá comer de ella .',NULL),
(@vid,@bid,12,44,'Todo esclavo que hayas comprado podrá participar, pero solo después de que lo hayas circuncidado .',NULL),
(@vid,@bid,12,45,'Los visitantes y los empleados no podrán comer de ella.',NULL),
(@vid,@bid,12,46,'Se deberá comer dentro de una sola casa ; no se puede sacar nada de carne de la casa , y no le quebrarán ningún hueso al animal.',NULL),
(@vid,@bid,12,47,'Toda la comunidad de Israel debe celebrar esta fiesta.',NULL),
(@vid,@bid,12,48,'Si un extranjero que viva entre ustedes quiere celebrar la Pascua en honor a Yahvé, primero deberán circuncidarse todos los hombres de su familia. Solo entonces podrá participar, y será considerado como alguien nacido en el país. Ningún hombre sin circuncidar podrá comer de la Pascua .',NULL),
(@vid,@bid,12,49,'Esta misma regla se aplicará tanto para el que haya nacido en el país como para el extranjero que viva entre ustedes.”',NULL),
(@vid,@bid,12,50,'Todos los israelitas lo hicieron así , cumpliendo exactamente con lo que Yahvé les había ordenado a Moisés y a Aarón.',NULL),
(@vid,@bid,12,51,'Ese mismo día , Yahvé sacó de Egipto a los israelitas, ordenados por escuadrones.',NULL),
(@vid,@bid,13,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,13,2,'“Conságrame a todos los hijos mayores. El primer hijo de cada familia israelita es mío, y también la primera cría de cada animal”.',NULL),
(@vid,@bid,13,3,'Moisés le dijo al pueblo : “Acuérdense de este día en que salieron de Egipto , donde eran esclavos, porque con el gran poder de su mano Yahvé los sacó de allí. Así que no coman nada que tenga levadura.',NULL),
(@vid,@bid,13,4,'Ustedes salen hoy , en el mes de Abib.',NULL),
(@vid,@bid,13,5,'Cuando Yahvé los lleve a la tierra de los cananeos , de los hititas, de los amorreos, de los heveos y de los jebuseos , esa tierra que promete abundancia y que él juró darles a sus antepasados, deberán celebrar esta ceremonia en este mismo mes .',NULL),
(@vid,@bid,13,6,'Durante siete días comerán pan sin levadura, y el séptimo día harán una fiesta en honor a Yahvé.',NULL),
(@vid,@bid,13,7,'En esos siete días solo se comerá pan sin levadura . No debe haber pan con levadura , ni levadura alguna , en todo el territorio de ustedes.',NULL),
(@vid,@bid,13,8,'En ese día le explicarás a tu hijo : ‘ Hacemos esto para recordar lo que Yahvé hizo por mí cuando salí de Egipto ’.',NULL),
(@vid,@bid,13,9,'Esta ceremonia les servirá como una marca en la mano y como un recordatorio en la frente, para que siempre hablen de la ley de Yahvé. Porque con mano poderosa Yahvé los sacó de Egipto .',NULL),
(@vid,@bid,13,10,'Por lo tanto, deberán cumplir con esta ley en la fecha señalada, año tras año.',NULL),
(@vid,@bid,13,11,'Cuando Yahvé los introduzca en la tierra de los cananeos , tal como se lo juró a ustedes y a sus antepasados, y se la entregue ,',NULL),
(@vid,@bid,13,12,'le dedicarán a Yahvé el primer hijo de cada familia, y también las primeras crías de sus animales. Todos los machos primerizos le pertenecerán a Yahvé.',NULL),
(@vid,@bid,13,13,'Para rescatar a la primera cría de un burro, deberán sacrificar un cordero a cambio; si no quieren rescatarlo, tendrán que romperle el cuello al burrito. También deberán rescatar al primer hijo varón de cada familia.',NULL),
(@vid,@bid,13,14,'Y si en el futuro sus hijos les preguntan: ‘¿ Qué significa todo esto ?’, ustedes les responderán: ‘ Con mano poderosa Yahvé nos sacó de Egipto , de ese lugar de esclavitud.',NULL),
(@vid,@bid,13,15,'Como el faraón se puso terco y no nos dejaba ir , Yahvé les quitó la vida a todos los primogénitos en Egipto , tanto de personas como de animales . Por eso le sacrificamos a Yahvé todos los machos primerizos de nuestros animales , pero rescatamos a todos nuestros hijos mayores’.',NULL),
(@vid,@bid,13,16,'Esto les servirá como una marca en la mano y como un recordatorio en la frente, de que con mano poderosa Yahvé nos sacó de Egipto .”',NULL),
(@vid,@bid,13,17,'Cuando el faraón dejó ir al pueblo , Dios no los llevó por el camino de la tierra de los filisteos , aunque era el más corto, porque Dios pensó: “ Si el pueblo se enfrenta a una guerra , podrían arrepentirse y regresarse a Egipto ”.',NULL),
(@vid,@bid,13,18,'En lugar de eso, Dios hizo que el pueblo diera un rodeo por el camino del desierto , rumbo al Mar Rojo. Y los israelitas salieron de Egipto armados y organizados como un ejército.',NULL),
(@vid,@bid,13,19,'Moisés se llevó los huesos de José , porque José les había hecho jurar a los israelitas diciéndoles: “Dios ciertamente vendrá a ayudarlos; cuando eso pase, llévense mis huesos con ustedes”.',NULL),
(@vid,@bid,13,20,'Partieron de Sucot y acamparon en Etam, justo donde empieza el desierto .',NULL),
(@vid,@bid,13,21,'Yahvé iba delante de ellos: de día iba en una columna de nube para guiarlos por el camino , y de noche en una columna de fuego para alumbrarlos, y así podían viajar de día o de noche .',NULL),
(@vid,@bid,13,22,'La columna de nube no se apartaba de ellos durante el día , ni la columna de fuego durante la noche .',NULL),
(@vid,@bid,14,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,14,2,'“ Diles a los israelitas que den la vuelta y acampen frente a Pi-hahirot, entre Migdol y el mar , frente a Baal-zefón. Acamparán allí, a la orilla del mar .',NULL),
(@vid,@bid,14,3,'Así el faraón pensará: ‘ Los israelitas andan perdidos en el país; el desierto los tiene acorralados’.',NULL),
(@vid,@bid,14,4,'Yo haré que el faraón se ponga terco y los persiga . Entonces mostraré mi gloria al derrotar al faraón y a todo su ejército , y los egipcios sabrán que yo soy Yahvé.” Y los israelitas hicieron lo que Dios ordenó.',NULL),
(@vid,@bid,14,5,'Cuando le avisaron al rey de Egipto que el pueblo había huido, el faraón y sus funcionarios cambiaron de parecer y dijeron: “¿ Qué hemos hecho ? ¡Dejamos ir a los israelitas y perdimos a nuestros esclavos!”',NULL),
(@vid,@bid,14,6,'Entonces el faraón mandó preparar su carro de guerra y se llevó a su ejército con él .',NULL),
(@vid,@bid,14,7,'Se llevó seiscientos de los mejores carros , y todos los demás carros de guerra de Egipto , todos al mando de sus capitanes.',NULL),
(@vid,@bid,14,8,'Yahvé hizo que el faraón , rey de Egipto , se pusiera terco y persiguiera a los israelitas, a pesar de que ellos habían salido libres y con la frente en alto .',NULL),
(@vid,@bid,14,9,'Los egipcios , con todos los caballos , los carros de guerra y la caballería del faraón , persiguieron a los israelitas y los alcanzaron mientras acampaban junto al mar , cerca de Pi-hahirot, frente a Baal-zefón.',NULL),
(@vid,@bid,14,10,'Al ver que el faraón y los egipcios se acercaban, los israelitas se murieron de miedo y empezaron a pedirle ayuda a Yahvé a gritos.',NULL),
(@vid,@bid,14,11,'Y le reclamaron a Moisés : “¿Acaso no había tumbas en Egipto , que nos trajiste a morir al desierto ? ¿ Por qué nos hiciste esto ? ¿Para qué nos sacaste de Egipto ?',NULL),
(@vid,@bid,14,12,'¿ No te decíamos cuando estábamos allá: ‘ Déjanos en paz, preferimos ser esclavos de los egipcios ’? ¡Hubiera sido mejor seguir de esclavos que morir aquí en el desierto !”',NULL),
(@vid,@bid,14,13,'Moisés le respondió al pueblo : “¡ No tengan miedo ! Quédense quietos y vean cómo Yahvé los va a salvar hoy . A estos egipcios que ven ahora , no los volverán a ver nunca más .',NULL),
(@vid,@bid,14,14,'Yahvé peleará por ustedes, y ustedes solo tienen que quedarse tranquilos”.',NULL),
(@vid,@bid,14,15,'Entonces Yahvé le dijo a Moisés : “¿ Por qué me pides ayuda a gritos? ¡ Diles a los israelitas que sigan avanzando!',NULL),
(@vid,@bid,14,16,'Y tú, levanta tu vara , extiende tu mano sobre el mar y ábrelo en dos, para que los israelitas crucen por en medio del mar sobre tierra seca.',NULL),
(@vid,@bid,14,17,'Yo haré que los egipcios se pongan tercos y entren al mar persiguiéndolos. Entonces mostraré mi gloria al derrotar al faraón , a todo su ejército , a sus carros y a su caballería.',NULL),
(@vid,@bid,14,18,'Y cuando yo haya mostrado mi gloria contra el faraón y sus tropas, los egipcios sabrán que yo soy Yahvé.”',NULL),
(@vid,@bid,14,19,'El ángel de Dios, que iba guiando el campamento de Israel , cambió de lugar y se puso detrás de ellos. La columna de nube también se movió y se puso a sus espaldas,',NULL),
(@vid,@bid,14,20,'quedando exactamente entre el campamento de los egipcios y el campamento de Israel . Del lado de los egipcios , la nube trajo oscuridad , pero del lado de los israelitas alumbraba la noche . Así que en toda la noche los egipcios no pudieron acercarse a los israelitas.',NULL),
(@vid,@bid,14,21,'Moisés extendió su mano sobre el mar , y Yahvé mandó un fuerte viento del este que sopló toda la noche y partió el mar en dos. Las aguas se dividieron y el fondo del mar quedó seco.',NULL),
(@vid,@bid,14,22,'Los israelitas cruzaron por en medio del mar caminando sobre tierra seca, mientras las aguas formaban dos grandes muros , uno a la derecha y otro a la izquierda .',NULL),
(@vid,@bid,14,23,'Los egipcios se lanzaron a perseguirlos, y todos los caballos del faraón , junto con sus carros y su caballería, entraron tras ellos hasta la mitad del mar .',NULL),
(@vid,@bid,14,24,'En la madrugada, Yahvé miró al ejército egipcio desde la columna de fuego y nube , y los llenó de confusión y pánico.',NULL),
(@vid,@bid,14,25,'Hizo que se les trabaran las ruedas a sus carros de guerra , para que no pudieran avanzar. Entonces los egipcios gritaron: “¡Huyamos de los israelitas, porque Yahvé está peleando a favor de ellos y contra nosotros!”',NULL),
(@vid,@bid,14,26,'Yahvé le dijo a Moisés : “ Extiende tu mano sobre el mar para que las aguas se regresen y cubran a los egipcios , a sus carros y a su caballería.”',NULL),
(@vid,@bid,14,27,'Moisés extendió su mano sobre el mar , y al amanecer el mar volvió a su lugar normal. Los egipcios intentaron huir, pero se toparon de frente con las aguas, y Yahvé los hundió en medio del mar .',NULL),
(@vid,@bid,14,28,'Las aguas regresaron y cubrieron los carros , la caballería y a todo el ejército del faraón que había entrado al mar para perseguir a los israelitas. ¡ No quedó ni uno solo de ellos con vida!',NULL),
(@vid,@bid,14,29,'En cambio, los israelitas cruzaron el mar caminando sobre tierra seca, con las aguas formando un muro a su derecha y otro a su izquierda .',NULL),
(@vid,@bid,14,30,'Así fue como Yahvé salvó a Israel del poder de los egipcios en aquel día ; y los israelitas vieron los cadáveres de los egipcios tirados a la orilla del mar .',NULL),
(@vid,@bid,14,31,'Al ver el tremendo poder que Yahvé había usado contra los egipcios , el pueblo le tuvo un profundo respeto a Yahvé, y creyeron en él y en su siervo Moisés .',NULL),
(@vid,@bid,15,1,'Entonces Moisés y los israelitas le cantaron esta canción a Yahvé: “Le cantaré a Yahvé, porque ha tenido una victoria gloriosa. Ha arrojado al mar a los caballos y a sus jinetes.',NULL),
(@vid,@bid,15,2,'Yahvé es mi fuerza y mi canción, él ha sido mi salvación. Él es mi Dios, y yo lo alabaré; es el Dios de mi padre, y yo lo exaltaré.',NULL),
(@vid,@bid,15,3,'Yahvé es un guerrero invencible. ¡Yahvé es su nombre !',NULL),
(@vid,@bid,15,4,'Hundió en el mar los carros del faraón y a su ejército . Sus mejores capitanes se ahogaron en el Mar Rojo.',NULL),
(@vid,@bid,15,5,'Las aguas profundas los cubrieron ; cayeron hasta el fondo como si fueran piedras.',NULL),
(@vid,@bid,15,6,'Tu mano derecha , Yahvé, es grandiosa en poder . Tu mano derecha , Yahvé, hace pedazos al enemigo.',NULL),
(@vid,@bid,15,7,'Con tu inmensa grandeza derribas a los que te atacan. Desatas tu furia y los consumes como a paja seca.',NULL),
(@vid,@bid,15,8,'Con el soplo de tu aliento, se amontonaron las aguas ; las corrientes se levantaron y formaron un muro; el fondo del mar quedó al descubierto.',NULL),
(@vid,@bid,15,9,'El enemigo pensó: ‘ Los perseguiré y los alcanzaré; les quitaré todo lo que tienen. Cumpliré mis deseos con ellos . Sacaré mi espada y los mataré con mis propias manos ’.',NULL),
(@vid,@bid,15,10,'Pero soplaste con tu viento y el mar los cubrió por completo. Se hundieron como plomo en las aguas violentas.',NULL),
(@vid,@bid,15,11,'¿ Qué dios se compara a ti, Yahvé? ¿ Quién como tú , grandioso y santo , digno de profundo respeto, hacedor de milagros?',NULL),
(@vid,@bid,15,12,'Extendiste tu mano derecha , y la tierra se los tragó.',NULL),
(@vid,@bid,15,13,'Con tu amor fiel has guiado a este pueblo que rescataste; con tu poder los llevas hacia tu santa morada .',NULL),
(@vid,@bid,15,14,'Las naciones escucharon y temblaron de miedo; los habitantes de Filistea se llenaron de angustia.',NULL),
(@vid,@bid,15,15,'Los líderes de Edom se asustaron; los hombres fuertes de Moab se pusieron a temblar. Todos los habitantes de Canaán perdieron el valor.',NULL),
(@vid,@bid,15,16,'El terror y el pánico cayeron sobre ellos ; por el poder de tu brazo , se quedaron paralizados como piedras, hasta que pasó tu pueblo , Yahvé, hasta que terminó de pasar el pueblo que tú compraste .',NULL),
(@vid,@bid,15,17,'Tú los traerás y los plantarás en el monte que te pertenece, en el lugar que preparaste para vivir, Yahvé, en el santuario , Señor , que tus propias manos construyeron.',NULL),
(@vid,@bid,15,18,'¡Yahvé reinará por siempre y para siempre !”',NULL),
(@vid,@bid,15,19,'Cuando los caballos del faraón , con sus carros de guerra y su caballería, entraron al mar , Yahvé hizo que las aguas se les vinieran encima ; pero los israelitas cruzaron el mar caminando sobre tierra seca.',NULL),
(@vid,@bid,15,20,'Entonces la profetisa Miriam, que era hermana de Aarón, tomó una pandereta, y todas las mujeres la siguieron tocando panderetas y bailando.',NULL),
(@vid,@bid,15,21,'Y Miriam les cantaba: “Cántenle a Yahvé, porque ha tenido una victoria gloriosa. Ha arrojado al mar a los caballos y a sus jinetes”.',NULL),
(@vid,@bid,15,22,'Moisés guio a los israelitas desde el Mar Rojo hacia el desierto de Shur . Caminaron por el desierto durante tres días sin encontrar agua .',NULL),
(@vid,@bid,15,23,'Cuando llegaron a un lugar llamado Mara, no pudieron tomar el agua de ahí porque era muy amarga . ( Por eso el lugar se llama Mara, que significa “ amargo ”).',NULL),
(@vid,@bid,15,24,'Entonces el pueblo se empezó a quejar con Moisés y le dijeron: “¿ Pues qué vamos a tomar?”',NULL),
(@vid,@bid,15,25,'Moisés le pidió ayuda a Yahvé, y Yahvé le mostró un pedazo de madera ; Moisés lo echó al agua , y el agua se volvió dulce. Allí en Mara, Yahvé les dio leyes y normas, y allí los puso a prueba .',NULL),
(@vid,@bid,15,26,'Les dijo: “ Si ustedes escuchan con atención mi voz , y hacen lo que a mí me agrada, y si obedecen mis mandamientos y cumplen todas mis leyes, no les mandaré ninguna de las enfermedades que les mandé a los egipcios ; porque yo soy Yahvé, el que los sana .”',NULL),
(@vid,@bid,15,27,'Después llegaron a Elim, un lugar donde había doce manantiales de agua y setenta palmeras , y acamparon allí , junto al agua .',NULL),
(@vid,@bid,16,1,'Toda la comunidad de los israelitas salió de Elim y llegó al desierto de Sin , que está entre Elim y el Sinaí . Llegaron allí el día quince del segundo mes , después de haber salido de Egipto .',NULL),
(@vid,@bid,16,2,'Allí en el desierto , toda la comunidad de los israelitas empezó a quejarse de Moisés y de Aarón;',NULL),
(@vid,@bid,16,3,'y les decían: “¡ Ojalá Yahvé nos hubiera quitado la vida en Egipto ! Allá nos sentábamos a comer carne de las ollas y comíamos pan hasta llenarnos. ¡ Pero ustedes nos trajeron a este desierto para matarnos de hambre a todos !”',NULL),
(@vid,@bid,16,4,'Entonces Yahvé le dijo a Moisés : “ Mira , voy a hacer que les llueva pan del cielo . La gente saldrá todos los días a recoger solo lo necesario para ese día . De esta manera los pondré a prueba para ver si obedecen mis instrucciones o no .',NULL),
(@vid,@bid,16,5,'El sexto día , cuando preparen lo que lleven, recogerán el doble de lo que recogen los demás días .”',NULL),
(@vid,@bid,16,6,'Moisés y Aarón les dijeron a todos los israelitas: “Hoy en la tarde se darán cuenta de que fue Yahvé quien los sacó de Egipto .',NULL),
(@vid,@bid,16,7,'Y mañana en la mañana verán la gloria de Yahvé, porque él ya escuchó cómo se andan quejando de él . Al fin y al cabo, ¿quiénes somos nosotros para que se anden quejando de nosotros ?”',NULL),
(@vid,@bid,16,8,'Moisés también les dijo: “Yahvé les va a dar carne para comer en la tarde , y pan en la mañana para que se llenen, porque ya escuchó las quejas que tienen contra él . ¿Acaso nosotros somos alguien? ¡Sus quejas no son contra nosotros , son contra Yahvé!”',NULL),
(@vid,@bid,16,9,'Luego Moisés le dijo a Aarón: “Diles a todos los israelitas que se acerquen a la presencia de Yahvé, porque él ya escuchó sus quejas”.',NULL),
(@vid,@bid,16,10,'Y mientras Aarón le hablaba a toda la comunidad de los israelitas, ellos voltearon hacia el desierto , ¡ y vieron que la gloria de Yahvé apareció en la nube !',NULL),
(@vid,@bid,16,11,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,16,12,'“He escuchado las quejas de los israelitas. Diles esto: ‘Al atardecer comerán carne , y por la mañana se llenarán de pan . Así sabrán que yo soy Yahvé, su Dios ’”.',NULL),
(@vid,@bid,16,13,'Esa misma tarde llegaron muchísimas codornices que cubrieron todo el campamento , y a la mañana siguiente había una capa de rocío alrededor de las carpas.',NULL),
(@vid,@bid,16,14,'Cuando el rocío se evaporó, vieron que sobre la superficie del desierto había quedado algo fino y con forma de escamas, tan fino como la escarcha en el suelo.',NULL),
(@vid,@bid,16,15,'Al verlo, los israelitas se preguntaban unos a otros: “¿ Y esto qué es ?” Porque no sabían lo que era . Moisés les explicó: “ Es el pan que Yahvé les ha dado para comer.',NULL),
(@vid,@bid,16,16,'Y esta es la orden de Yahvé: ‘ Cada uno debe recoger lo que necesite para comer . Recojan unos dos kilos por persona , según la cantidad de gente que viva en cada carpa’”.',NULL),
(@vid,@bid,16,17,'Los israelitas lo hicieron así . Unos recogieron más y otros menos.',NULL),
(@vid,@bid,16,18,'Pero al medirlo, ni le sobró al que recogió mucho , ni le faltó al que recogió poco . Cada uno había recogido exactamente lo que necesitaba para comer.',NULL),
(@vid,@bid,16,19,'Y Moisés les advirtió: “Nadie debe guardar nada para el día siguiente”.',NULL),
(@vid,@bid,16,20,'Pero algunos no le hicieron caso a Moisés y guardaron un poco para el otro día; pero la comida se llenó de gusanos y empezó a apestar. Moisés se enojó mucho con ellos .',NULL),
(@vid,@bid,16,21,'Así que todas las mañanas cada uno recogía lo que iba a comer, porque en cuanto el sol calentaba , aquello se derretía.',NULL),
(@vid,@bid,16,22,'El sexto día recogieron el doble de comida , o sea , unos cuatro kilos para cada persona. Entonces todos los líderes de la comunidad fueron a avisarle a Moisés .',NULL),
(@vid,@bid,16,23,'Moisés les dijo : “ Esto es lo que Yahvé ordenó: ‘ Mañana es un día de descanso, un sábado consagrado a Yahvé. Así que cocinen hoy lo que tengan que cocinar, y hiervan lo que tengan que hervir. Todo lo que sobre guárdenlo para mañana ’”.',NULL),
(@vid,@bid,16,24,'Ellos guardaron las sobras para el día siguiente, tal como Moisés les dijo, y la comida no se echó a perder ni se agusanó.',NULL),
(@vid,@bid,16,25,'Moisés les dijo: “Cómanse eso hoy , porque hoy es sábado , día de descanso en honor a Yahvé. Hoy no van a encontrar nada allá afuera.',NULL),
(@vid,@bid,16,26,'Tienen seis días a la semana para recogerlo, pero el séptimo día es de descanso; ese día no habrá nada ”.',NULL),
(@vid,@bid,16,27,'Aun así, el séptimo día algunos salieron a recoger, pero no encontraron nada .',NULL),
(@vid,@bid,16,28,'Entonces Yahvé le reclamó a Moisés : “¿ Hasta cuándo se van a negar a obedecer mis mandamientos y mis instrucciones?',NULL),
(@vid,@bid,16,29,'Entiendan que yo les di el sábado como día de descanso; por eso el sexto día les doy comida suficiente para dos días . El séptimo día todos deben quedarse donde están y no salir a buscar nada”.',NULL),
(@vid,@bid,16,30,'Así que el pueblo descansó el séptimo día .',NULL),
(@vid,@bid,16,31,'Los israelitas llamaron “ maná ” a ese alimento. Era blanco como la semilla de cilantro y sabía a galletas con miel .',NULL),
(@vid,@bid,16,32,'Luego Moisés dijo: “ Esto es lo que Yahvé ha ordenado : ‘Guarden unos dos kilos de maná para las futuras generaciones , para que vean el pan con el que los alimenté en el desierto cuando los saqué de Egipto ’”.',NULL),
(@vid,@bid,16,33,'Y Moisés le dijo a Aarón: “Consigue un frasco, pon adentro unos dos kilos de maná y ponlo en la presencia de Yahvé, para que se conserve para las futuras generaciones .”',NULL),
(@vid,@bid,16,34,'Aarón hizo lo que Yahvé le ordenó a Moisés , y puso el frasco con el maná frente al arca del pacto para que se conservara allí.',NULL),
(@vid,@bid,16,35,'Los israelitas comieron maná durante cuarenta años , hasta que llegaron a una tierra donde había gente; comieron maná hasta que llegaron a la frontera de Canaán .',NULL),
(@vid,@bid,16,36,'( La medida que usaban para recoger el maná era de unos dos litros).',NULL),
(@vid,@bid,17,1,'Toda la comunidad de los israelitas partió del desierto de Sin , viajando por etapas según el mandato de Yahvé, y acamparon en Refidim; pero no había agua para que la gente bebiera.',NULL),
(@vid,@bid,17,2,'Por eso el pueblo le reclamó a Moisés y le exigió: “ Danos agua para beber ”. Moisés les contestó: “¿ Por qué pelean conmigo ? ¿ Por qué ponen a prueba a Yahvé?”',NULL),
(@vid,@bid,17,3,'Pero la gente estaba muerta de sed ; por eso murmuraron contra Moisés y dijeron: “¿ Para qué nos sacaste de Egipto ? ¿Solo para matarnos de sed a nosotros , a nuestros hijos y a nuestro ganado ?”',NULL),
(@vid,@bid,17,4,'Moisés le suplicó a Yahvé: “¿ Qué hago con este pueblo ? ¡Falta poco para que me agarren a pedradas!”',NULL),
(@vid,@bid,17,5,'Yahvé le dijo a Moisés : “ Pasa al frente del pueblo , lleva contigo a algunos de los líderes de Israel , toma la vara con la que golpeaste el río Nilo, y vete para allá .',NULL),
(@vid,@bid,17,6,'Yo estaré esperándote sobre la roca que está en Horeb . Golpearás la roca , y saldrá agua de ella para que el pueblo beba”. Moisés lo hizo así , a la vista de los líderes de Israel .',NULL),
(@vid,@bid,17,7,'Y Moisés llamó a aquel lugar Masah, y también Meribá, por el pleito de los israelitas, y porque pusieron a prueba a Yahvé al decir : “¿ Está Yahvé entre nosotros , o no ?”',NULL),
(@vid,@bid,17,8,'En ese tiempo, los amalecitas vinieron y atacaron a Israel en Refidim.',NULL),
(@vid,@bid,17,9,'Moisés le dijo a Josué : “Escoge a algunos hombres y sal a pelear contra los amalecitas. Mañana yo estaré en la cima del cerro con la vara de Dios en mi mano ”.',NULL),
(@vid,@bid,17,10,'Josué hizo lo que Moisés le ordenó y salió a pelear contra los amalecitas, mientras que Moisés , Aarón y Hur subieron a la cima del cerro.',NULL),
(@vid,@bid,17,11,'Y resulta que , mientras Moisés mantenía los brazos en alto , los israelitas ganaban la batalla; pero cuando los bajaba, ganaban los amalecitas.',NULL),
(@vid,@bid,17,12,'Como los brazos de Moisés se cansaron, Aarón y Hur le consiguieron una piedra para que se sentara. Luego , uno de cada lado , le sostuvieron los brazos en alto, y así se mantuvieron firmes hasta que se puso el sol .',NULL),
(@vid,@bid,17,13,'De esta manera, Josué derrotó a los amalecitas a filo de espada .',NULL),
(@vid,@bid,17,14,'Entonces Yahvé le dijo a Moisés : “ Escribe esto en un libro para que quede como un recuerdo , y léeselo a Josué : Voy a borrar por completo el recuerdo de los amalecitas de la faz de la tierra.”',NULL),
(@vid,@bid,17,15,'Moisés construyó un altar y lo llamó “Yahvé es mi bandera”.',NULL),
(@vid,@bid,17,16,'Y exclamó: “¡Levantemos las manos hacia el trono de Yahvé! Yahvé estará en guerra contra los amalecitas de generación en generación .”',NULL),
(@vid,@bid,18,1,'Jetro, el sacerdote de Madián y suegro de Moisés , se enteró de todo lo que Dios había hecho por Moisés y por su pueblo Israel , y de cómo Yahvé los había sacado de Egipto .',NULL),
(@vid,@bid,18,2,'Entonces Jetro llevó a Séfora, la esposa de Moisés ( a quien Moisés había enviado de regreso a casa de su padre),',NULL),
(@vid,@bid,18,3,'junto con sus dos hijos . Uno de ellos se llamaba Gersón, porque Moisés había dicho: “ Fui un extranjero en tierra extraña ”.',NULL),
(@vid,@bid,18,4,'El otro hijo se llamaba Eliezer, porque Moisés había dicho: “ El Dios de mi padre me ayudó y me salvó de la espada del faraón ”.',NULL),
(@vid,@bid,18,5,'Jetro, el suegro de Moisés , llegó al desierto con la esposa y los hijos de Moisés , al lugar donde estaban acampando junto al monte de Dios.',NULL),
(@vid,@bid,18,6,'Y le mandó avisar: “Yo, tu suegro Jetro, voy a visitarte; vengo con tu esposa y con tus dos hijos ”.',NULL),
(@vid,@bid,18,7,'Moisés salió a recibir a su suegro , se inclinó ante él y lo besó . Se preguntaron cómo estaban de salud y entraron en la carpa.',NULL),
(@vid,@bid,18,8,'Moisés le contó a su suegro todo lo que Yahvé les había hecho al faraón y a los egipcios a favor de Israel , todas las dificultades que habían pasado en el camino , y cómo Yahvé los había salvado.',NULL),
(@vid,@bid,18,9,'Jetro se alegró mucho por todas las cosas buenas que Yahvé había hecho por Israel , al rescatarlos de las manos de los egipcios .',NULL),
(@vid,@bid,18,10,'Y exclamó Jetro: “¡Alabado sea Yahvé, que los rescató a ustedes del poder de los egipcios y del faraón ! ¡Él liberó al pueblo del control de Egipto !',NULL),
(@vid,@bid,18,11,'Ahora estoy seguro de que Yahvé es más grande que todos los demás dioses, porque él aplastó a los egipcios cuando estos trataron a Israel con tanta arrogancia.”',NULL),
(@vid,@bid,18,12,'Luego Jetro ofreció un holocausto y otros sacrificios a Dios. Aarón y todos los líderes de Israel fueron a compartir una comida con el suegro de Moisés en la presencia de Dios.',NULL),
(@vid,@bid,18,13,'Al día siguiente , Moisés se sentó a resolver los problemas de la gente , y el pueblo estuvo de pie a su alrededor desde la mañana hasta la noche.',NULL),
(@vid,@bid,18,14,'Cuando su suegro vio todo el trabajo que Moisés tenía con la gente , le preguntó: “¿ Qué es lo que estás haciendo con el pueblo ? ¿ Por qué te sientas tú solo a atenderlos, mientras todos se quedan de pie esperando desde la mañana hasta la noche?”',NULL),
(@vid,@bid,18,15,'Moisés le contestó: “ Es que la gente viene a mí para conocer la voluntad de Dios.',NULL),
(@vid,@bid,18,16,'Cuando tienen algún pleito, me lo traen para que yo decida quién tiene la razón, y de paso les enseño los mandamientos y las leyes de Dios.”',NULL),
(@vid,@bid,18,17,'El suegro le dijo: “ Lo que estás haciendo no está bien .',NULL),
(@vid,@bid,18,18,'Te vas a agotar tú , y también se va a agotar la gente . Este trabajo es demasiado pesado para ti ; no puedes hacerlo tú solo.',NULL),
(@vid,@bid,18,19,'Hazme caso, te voy a dar un buen consejo , y que Dios te ayude. Tú debes ser el representante del pueblo ante Dios y presentarle a él los problemas.',NULL),
(@vid,@bid,18,20,'Enséñales a ellos los mandamientos y las leyes , e indícales cómo deben portarse y qué es lo que deben hacer .',NULL),
(@vid,@bid,18,21,'Pero al mismo tiempo, escoge de entre todo el pueblo a hombres capaces y que respeten a Dios, hombres honestos que no se dejen sobornar. Nómbralos líderes de grupos de mil , de cien , de cincuenta y de diez personas.',NULL),
(@vid,@bid,18,22,'Deja que ellos se encarguen de resolver los problemas diarios del pueblo . Los casos más difíciles te los pasarán a ti , pero ellos resolverán los problemas menores . Así te quitarás un peso de encima y ellos compartirán la carga contigo .',NULL),
(@vid,@bid,18,23,'Si haces esto , y si Dios así te lo ordena , vas a poder aguantar el ritmo de trabajo, y toda esta gente se irá a su casa tranquila.”',NULL),
(@vid,@bid,18,24,'Moisés siguió el consejo de su suegro e hizo todo lo que le dijo.',NULL),
(@vid,@bid,18,25,'Escogió hombres capaces de entre todo Israel , y los nombró líderes del pueblo : los hizo jefes de mil , de cien , de cincuenta y de diez personas.',NULL),
(@vid,@bid,18,26,'A partir de entonces , ellos se encargaban de resolver los problemas diarios de la gente . Los casos más complicados se los llevaban a Moisés , pero ellos mismos decidían en los asuntos de menor importancia.',NULL),
(@vid,@bid,18,27,'Después, Moisés se despidió de su suegro , y Jetro regresó a su país.',NULL),
(@vid,@bid,19,1,'Exactamente al cumplirse tres meses desde que los israelitas salieron de Egipto , llegaron al desierto del Sinaí .',NULL),
(@vid,@bid,19,2,'Después de salir de Refidim, llegaron al desierto del Sinaí y acamparon allí , justo frente al monte .',NULL),
(@vid,@bid,19,3,'Moisés subió a encontrarse con Dios , y Yahvé lo llamó desde el monte y le dijo : “ Esto es lo que le vas a decir a la familia de Jacob ; anúnciales esto a los israelitas:',NULL),
(@vid,@bid,19,4,'‘Ustedes mismos vieron lo que les hice a los egipcios , y cómo los llevé a ustedes sobre alas de águila y los traje hacia mí .',NULL),
(@vid,@bid,19,5,'Ahora bien , si de verdad me obedecen y cumplen mi pacto , ustedes serán mi tesoro más preciado entre todas las naciones de la tierra; porque toda la tierra es mía.',NULL),
(@vid,@bid,19,6,'Serán para mí un reino de sacerdotes y una nación santa ’. Estas son las palabras que debes comunicarles a los israelitas”.',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,19,7,'Moisés regresó, mandó llamar a los líderes del pueblo y les explicó todo lo que Yahvé le había ordenado .',NULL),
(@vid,@bid,19,8,'Todo el pueblo respondió al mismo tiempo: “ Haremos todo lo que Yahvé ha dicho ”. Y Moisés le llevó la respuesta del pueblo a Yahvé.',NULL),
(@vid,@bid,19,9,'Yahvé le dijo a Moisés : “Voy a acercarme a ti en medio de una nube muy espesa , para que el pueblo escuche cuando yo hable contigo y así confíen en ti para siempre ”. Moisés le transmitió a Yahvé lo que el pueblo había dicho .',NULL),
(@vid,@bid,19,10,'Yahvé le ordenó a Moisés : “ Ve con el pueblo y diles que se purifiquen hoy y mañana , y que laven su ropa .',NULL),
(@vid,@bid,19,11,'Deben estar listos para el tercer día , porque ese día yo , Yahvé, bajaré al monte Sinaí a la vista de todo el pueblo .',NULL),
(@vid,@bid,19,12,'Ponle límites al pueblo alrededor del monte , y adviérteles: ‘Tengan mucho cuidado de no subir al monte ni de tocar sus faldas. Cualquiera que toque el monte será condenado a muerte .',NULL),
(@vid,@bid,19,13,'Nadie debe tocar a esa persona; al que lo haga lo matarán a pedradas o a flechazos. Ya sea un animal o una persona, no quedará con vida ’. Solo cuando la trompeta dé un toque largo, podrán acercarse al monte ”.',NULL),
(@vid,@bid,19,14,'Moisés bajó del monte a donde estaba el pueblo , y les ordenó purificarse; y ellos lavaron su ropa .',NULL),
(@vid,@bid,19,15,'Luego le dijo a la gente : “Prepárense para el tercer día . No tengan relaciones sexuales con sus mujeres”.',NULL),
(@vid,@bid,19,16,'La mañana del tercer día , hubo truenos y relámpagos , una nube muy espesa cubrió el monte , y se escuchó un toque de trompeta fuertísimo. Toda la gente que estaba en el campamento se puso a temblar de miedo.',NULL),
(@vid,@bid,19,17,'Entonces Moisés sacó al pueblo del campamento para encontrarse con Dios, y se detuvieron al pie del monte .',NULL),
(@vid,@bid,19,18,'Todo el monte Sinaí estaba cubierto de humo , porque Yahvé había bajado sobre él en medio de fuego. El humo subía como si fuera el de un horno, y todo el monte temblaba violentamente.',NULL),
(@vid,@bid,19,19,'El sonido de la trompeta se iba haciendo cada vez más fuerte; Moisés hablaba , y Dios le contestaba con voz de trueno.',NULL),
(@vid,@bid,19,20,'Yahvé bajó a la parte más alta del monte Sinaí y llamó a Moisés para que subiera. Y Moisés subió .',NULL),
(@vid,@bid,19,21,'Yahvé le dijo a Moisés : “ Baja y adviértele a la gente que no traspase los límites tratando de verme, porque si lo hacen, muchos morirán.',NULL),
(@vid,@bid,19,22,'Incluso los sacerdotes que se acercan a mí, tienen que purificarse para que yo no los destruya.”',NULL),
(@vid,@bid,19,23,'Moisés le contestó a Yahvé: “ El pueblo no va a poder subir al monte Sinaí , porque tú ya nos advertiste: ‘Ponle límites al monte y decláralo sagrado’”.',NULL),
(@vid,@bid,19,24,'Pero Yahvé le respondió: “¡ Baja de una vez! Luego vuelves a subir tú, y trae a Aarón contigo . Pero no dejes que los sacerdotes ni el pueblo traspasen los límites para subir a donde estoy yo, no sea que los destruya.”',NULL),
(@vid,@bid,19,25,'Entonces Moisés bajó a donde estaba el pueblo y se lo comunicó.',NULL),
(@vid,@bid,20,1,'Dios pronunció todas estas palabras :',NULL),
(@vid,@bid,20,2,'“Yo soy Yahvé, tu Dios , que te saqué de la tierra de Egipto , donde eras esclavo.',NULL),
(@vid,@bid,20,3,'No tendrás otros dioses además de mí .',NULL),
(@vid,@bid,20,4,'No te harás ningún ídolo, ni ninguna imagen de lo que hay arriba en el cielo , ni abajo en la tierra, ni en las aguas debajo de la tierra.',NULL),
(@vid,@bid,20,5,'No te inclinarás ante ellos ni los adorarás, porque yo , Yahvé, tu Dios , soy un Dios celoso . Yo castigo la maldad de los padres en los hijos , hasta la tercera y cuarta generación de los que me odian;',NULL),
(@vid,@bid,20,6,'pero muestro amor inagotable por mil generaciones a los que me aman y obedecen mis mandamientos .',NULL),
(@vid,@bid,20,7,'No uses el nombre de Yahvé, tu Dios , a la ligera, porque Yahvé no dejará sin castigo al que use mal su nombre .',NULL),
(@vid,@bid,20,8,'Acuérdate de santificar el sábado , que es el día de descanso.',NULL),
(@vid,@bid,20,9,'Tienes seis días en la semana para trabajar y hacer todas tus tareas,',NULL),
(@vid,@bid,20,10,'pero el séptimo día es de descanso, dedicado a Yahvé, tu Dios . Ese día no harás ningún tipo de trabajo, ni tú , ni tu hijo , ni tu hija , ni tu esclavo, ni tu esclava, ni tus animales , ni el extranjero que viva en tus ciudades .',NULL),
(@vid,@bid,20,11,'Porque en seis días Yahvé hizo los cielos , la tierra, el mar y todo lo que hay en ellos , pero descansó el séptimo día . Por eso , Yahvé bendijo el sábado y lo declaró día sagrado.',NULL),
(@vid,@bid,20,12,'Honra a tu padre y a tu madre, para que vivas una larga vida en la tierra que Yahvé, tu Dios , te da .',NULL),
(@vid,@bid,20,13,'No matarás .',NULL),
(@vid,@bid,20,14,'No cometerás adulterio.',NULL),
(@vid,@bid,20,15,'No robarás.',NULL),
(@vid,@bid,20,16,'No darás falso testimonio contra tu prójimo .',NULL),
(@vid,@bid,20,17,'No codiciarás la casa de tu prójimo ; tampoco codiciarás la esposa de tu prójimo , ni su esclavo, ni su esclava, ni su buey , ni su burro, ni ninguna otra cosa que le pertenezca”.',NULL),
(@vid,@bid,20,18,'Todo el pueblo veía los relámpagos y el humo del monte , y escuchaba los truenos y el sonido de la trompeta . Estaban tan asustados que se quedaron temblando a la distancia .',NULL),
(@vid,@bid,20,19,'Y le dijeron a Moisés : “Mejor háblanos tú, y nosotros te escucharemos; pero que Dios no nos hable directamente, porque nos vamos a morir .”',NULL),
(@vid,@bid,20,20,'Moisés los tranquilizó: “ No tengan miedo . Dios ha venido a ponerlos a prueba ; quiere que le tengan un profundo respeto para que no pequen”.',NULL),
(@vid,@bid,20,21,'Sin embargo, la gente se quedó a la distancia mientras Moisés se acercaba a la nube oscura donde estaba Dios.',NULL),
(@vid,@bid,20,22,'Yahvé le dijo a Moisés : “ Diles esto a los israelitas: ‘Ustedes mismos han visto que les he hablado desde el cielo .',NULL),
(@vid,@bid,20,23,'No se hagan dioses de plata ni de oro para ponerlos a mi nivel.',NULL),
(@vid,@bid,20,24,'Háganme un altar de tierra, y ofrezcan sobre él sus holocaustos y sus sacrificios de paz, sus ovejas y sus vacas . En cualquier lugar donde yo decida que se honre mi nombre , allí vendré a ustedes y los bendeciré .',NULL),
(@vid,@bid,20,25,'Si me construyen un altar de piedra, no usen piedras labradas ; porque al usar herramientas sobre la piedra, la profanan.',NULL),
(@vid,@bid,20,26,'Tampoco le pongan escaleras a mi altar , para que al subir no se les vea la ropa interior’”.',NULL),
(@vid,@bid,21,1,'“Estas son las leyes que les presentarás:',NULL),
(@vid,@bid,21,2,'“ Si compras un esclavo hebreo , te servirá durante seis años , pero al séptimo año quedará libre sin tener que pagar nada.',NULL),
(@vid,@bid,21,3,'Si llegó solo , se irá solo . Si estaba casado al llegar, su esposa se irá con él .',NULL),
(@vid,@bid,21,4,'Si su amo le da una esposa y ella le da hijos o hijas , la esposa y los niños serán de su amo, y el esclavo se irá solo .',NULL),
(@vid,@bid,21,5,'Pero si el esclavo dice claramente: ‘Amo a mi señor, a mi esposa y a mis hijos ; no quiero salir libre ’,',NULL),
(@vid,@bid,21,6,'entonces su amo lo llevará ante Dios. Lo acercará a la puerta o al marco de la puerta de su casa, le perforará la oreja con un punzón, y el esclavo le servirá para toda la vida.',NULL),
(@vid,@bid,21,7,'“ Si un hombre vende a su hija para que sea esclava, ella no quedará libre como los esclavos varones .',NULL),
(@vid,@bid,21,8,'Si la joven no le agrada a su amo, el cual la había comprado para hacerla su esposa, él deberá permitir que alguien pague por su rescate. No tendrá derecho a venderla a gente de otro país, pues la ha tratado con engaño.',NULL),
(@vid,@bid,21,9,'Si el amo la casa con su hijo , deberá tratarla con los mismos derechos que a una hija .',NULL),
(@vid,@bid,21,10,'Si el amo se casa con otra mujer, no le quitará a la primera su comida, ni su ropa, ni sus derechos conyugales.',NULL),
(@vid,@bid,21,11,'Si no cumple con estas tres cosas, la mujer podrá irse libre, sin tener que pagar nada .',NULL),
(@vid,@bid,21,12,'“El que golpee a una persona hasta matarla, será condenado a muerte ;',NULL),
(@vid,@bid,21,13,'pero si no fue un asesinato intencional, sino un accidente que Dios permitió que ocurriera, yo te indicaré un lugar a donde el responsable podrá huir.',NULL),
(@vid,@bid,21,14,'Si un hombre hace planes para matar a su prójimo a traición, lo sacarás incluso de mi altar para matarlo .',NULL),
(@vid,@bid,21,15,'“El que golpee a su padre o a su madre será condenado a muerte .',NULL),
(@vid,@bid,21,16,'“El que secuestre a una persona, ya sea que la venda o que todavía la tenga en su poder , será condenado a muerte .',NULL),
(@vid,@bid,21,17,'“El que maldiga a su padre o a su madre será condenado a muerte .',NULL),
(@vid,@bid,21,18,'“ Si dos hombres se pelean y uno golpea al otro con una piedra o con el puño, y el hombre no muere pero tiene que guardar cama ;',NULL),
(@vid,@bid,21,19,'si luego puede levantarse y caminar apoyado en un bastón, el que lo golpeó quedará libre de castigo . Solamente tendrá que pagarle por el tiempo que no pudo trabajar y hacerse cargo de sus gastos médicos hasta que sane por completo.',NULL),
(@vid,@bid,21,20,'“ Si un amo golpea a su esclavo o a su esclava con un palo, y el esclavo muere por los golpes, el amo será castigado.',NULL),
(@vid,@bid,21,21,'Pero si el esclavo sobrevive uno o dos días más , el amo no será castigado, porque el esclavo es de su propiedad.',NULL),
(@vid,@bid,21,22,'“ Si unos hombres se están peleando y golpean a una mujer embarazada haciendo que dé a luz antes de tiempo, pero la mujer no sufre ningún otro daño, el culpable pagará la multa que le exija el marido y que los jueces aprueben.',NULL),
(@vid,@bid,21,23,'Pero si la mujer sufre algún daño grave, entonces se cobrará vida por vida ,',NULL),
(@vid,@bid,21,24,'ojo por ojo , diente por diente , mano por mano , pie por pie ,',NULL),
(@vid,@bid,21,25,'quemadura por quemadura , herida por herida , golpe por golpe .',NULL),
(@vid,@bid,21,26,'“ Si un amo le pega en el ojo a su esclavo o a su esclava y lo deja ciego de ese ojo , le dará la libertad en compensación por su ojo .',NULL),
(@vid,@bid,21,27,'Y si le rompe un diente a su esclavo o a su esclava, lo dejará libre en compensación por su diente .',NULL),
(@vid,@bid,21,28,'“ Si un toro mata a cornadas a un hombre o a una mujer, el toro morirá a pedradas y nadie se comerá su carne ; pero el dueño del toro quedará libre de culpa.',NULL),
(@vid,@bid,21,29,'Pero si el toro ya tenía la costumbre de atacar, y el dueño estaba advertido pero no lo encerró, si ese toro mata a un hombre o a una mujer, matarán a pedradas al toro y también condenarán a muerte a su dueño .',NULL),
(@vid,@bid,21,30,'Si se le permite al dueño pagar un rescate por su vida , deberá pagar todo lo que se le exija.',NULL),
(@vid,@bid,21,31,'Esta misma regla se aplicará si el toro mata a un niño o a una niña.',NULL),
(@vid,@bid,21,32,'Si el toro mata a un esclavo o a una esclava, el dueño del toro le pagará treinta siclos de plata al amo del esclavo, y el toro morirá a pedradas.',NULL),
(@vid,@bid,21,33,'“ Si alguien destapa un pozo o cava un hoyo y no lo tapa, y un toro o un burro se cae adentro,',NULL),
(@vid,@bid,21,34,'el dueño del hoyo tendrá que pagar los daños. Le dará el dinero al dueño del animal, y podrá quedarse con el animal muerto .',NULL),
(@vid,@bid,21,35,'“ Si el toro de un hombre mata al toro de su vecino, venderán el toro vivo y se repartirán el dinero ; también se repartirán la carne del toro muerto .',NULL),
(@vid,@bid,21,36,'Pero si todos sabían que ese toro ya tenía la costumbre de atacar y su dueño no lo mantenía encerrado, el dueño tendrá que pagarle un toro vivo a su vecino y se quedará con el toro muerto .',NULL),
(@vid,@bid,22,1,'“Si alguien se roba un toro o una oveja, y luego lo mata o lo vende, tendrá que pagar cinco toros por el toro robado, o cuatro ovejas por la oveja robada.',NULL),
(@vid,@bid,22,2,'Si sorprenden a un ladrón metiéndose en una casa a la fuerza, y al golpearlo muere, el que lo mató no será culpable de asesinato.',NULL),
(@vid,@bid,22,3,'Pero si esto ocurre a plena luz del día, sí será culpable de asesinato. El ladrón está obligado a pagar todo lo que robó. Si no tiene con qué pagar , será vendido como esclavo para pagar el robo.',NULL),
(@vid,@bid,22,4,'Si le encuentran vivo el animal robado, ya sea un toro, un burro o una oveja, tendrá que pagar el doble.',NULL),
(@vid,@bid,22,5,'“ Si alguien deja sueltos a sus animales y estos se meten a pastar en el campo o en el viñedo de otra persona, el dueño de los animales tendrá que pagar el daño con lo mejor de su propio campo o viñedo.',NULL),
(@vid,@bid,22,6,'“ Si alguien prende una fogata y el fuego se extiende a los matorrales, quemando los manojos de trigo, las plantas o todo un campo, el que prendió el fuego tendrá que pagar los daños .',NULL),
(@vid,@bid,22,7,'“ Si alguien le da a cuidar dinero o cosas de valor a su vecino, y se las roban de la casa del vecino, el ladrón tendrá que pagar el doble si lo atrapan.',NULL),
(@vid,@bid,22,8,'Pero si no atrapan al ladrón, el dueño de la casa tendrá que presentarse ante Dios para que se investigue si él mismo se robó las cosas de su vecino.',NULL),
(@vid,@bid,22,9,'En cualquier caso de fraude, ya sea que se trate de un toro, un burro, una oveja , ropa o cualquier cosa perdida, si alguien dice: ‘Esto es mío’, el caso se llevará ante Dios. La persona a la que Dios declare culpable, tendrá que pagarle el doble a su vecino.',NULL),
(@vid,@bid,22,10,'“ Si alguien le da a cuidar a su vecino un burro, un toro, una oveja o cualquier otro animal, y el animal se muere, se lastima o se lo roban sin que nadie se dé cuenta,',NULL),
(@vid,@bid,22,11,'el vecino tendrá que jurar por Yahvé que él no se robó el animal. El dueño aceptará el juramento y el vecino no tendrá que pagar nada.',NULL),
(@vid,@bid,22,12,'Pero si el animal le fue robado, el vecino tendrá que pagarle al dueño.',NULL),
(@vid,@bid,22,13,'Si un animal salvaje despedazó al animal que cuidaba, deberá traer los restos como prueba y no tendrá que pagar nada.',NULL),
(@vid,@bid,22,14,'“ Si alguien le pide prestado un animal a su vecino, y el animal se lastima o se muere cuando el dueño no está presente, la persona que lo pidió prestado tendrá que pagarlo.',NULL),
(@vid,@bid,22,15,'Si el dueño estaba presente, no tendrá que pagar nada . Y si el animal era alquilado, el costo del alquiler cubrirá la pérdida.',NULL),
(@vid,@bid,22,16,'“Si un hombre seduce a una joven virgen que no está comprometida y se acuesta con ella, tendrá que pagar la dote para casarse con ella.',NULL),
(@vid,@bid,22,17,'Si el papá de la muchacha no quiere dársela en matrimonio, de todos modos el hombre tendrá que pagarle la cantidad de dinero que se acostumbra dar por una virgen.',NULL),
(@vid,@bid,22,18,'“No dejarás con vida a ninguna bruja ni hechicera.',NULL),
(@vid,@bid,22,19,'“El que tenga relaciones sexuales con un animal será condenado a muerte.',NULL),
(@vid,@bid,22,20,'“ El que le ofrezca sacrificios a cualquier otro dios que no sea solo Yahvé, será destruido por completo.',NULL),
(@vid,@bid,22,21,'“ No maltrates ni oprimas a los extranjeros, porque ustedes mismos fueron extranjeros en Egipto.',NULL),
(@vid,@bid,22,22,'“ No se aprovechen de las viudas ni de los huérfanos.',NULL),
(@vid,@bid,22,23,'Si ustedes se aprovechan de ellos, y ellos me piden ayuda, yo les aseguro que escucharé sus gritos;',NULL),
(@vid,@bid,22,24,'mi enojo se encenderá y los mataré a ustedes a filo de espada. Entonces serán sus esposas las que se quedarán viudas, y sus hijos los que se quedarán huérfanos.',NULL),
(@vid,@bid,22,25,'“Si le prestas dinero a algún pobre de mi pueblo que viva entre ustedes, no te portes con él como un usurero, ni le cobres intereses.',NULL),
(@vid,@bid,22,26,'Si tomas el manto de tu prójimo como garantía de un préstamo, devuélveselo antes de que se ponga el sol,',NULL),
(@vid,@bid,22,27,'porque ese manto es lo único que tiene para taparse. ¿Con qué otra cosa se va a abrigar para dormir? Si él me pide ayuda a gritos, yo lo escucharé, porque soy compasivo.',NULL),
(@vid,@bid,22,28,'“ No maldigas a Dios, ni hables mal de los líderes de tu pueblo.',NULL),
(@vid,@bid,22,29,'“ No te demores en presentarme las ofrendas de tus cosechas y de tus lagares. “ Me entregarás al primer hijo varón que tengas .',NULL),
(@vid,@bid,22,30,'Lo mismo harás con la primera cría de tus vacas y tus ovejas. La cría se quedará con su madre los primeros siete días, pero al octavo día me la entregarás.',NULL),
(@vid,@bid,22,31,'“Ustedes serán un pueblo santo para mí. Por eso, no coman la carne de ningún animal que haya sido despedazado por las fieras en el campo; échensela a los perros.',NULL),
(@vid,@bid,23,1,'“ No andes esparciendo chismes ni noticias falsas. No te juntes con gente malvada para dar falsos testimonios en el tribunal.',NULL),
(@vid,@bid,23,2,'“ No te dejes llevar por la mayoría para hacer el mal . Cuando declares en un juicio , no te pongas del lado de la mayoría para torcer la justicia.',NULL),
(@vid,@bid,23,3,'Pero tampoco favorezcas a un pobre en su pleito solo por ser pobre .',NULL),
(@vid,@bid,23,4,'“ Si te encuentras el toro o el burro de tu enemigo andando perdido, asegúrate de devolvérselo.',NULL),
(@vid,@bid,23,5,'Si ves que el burro de alguien que te cae mal se ha caído bajo el peso de su carga , no lo dejes ahí tirado. ¡Ayúdalo a levantarlo!',NULL),
(@vid,@bid,23,6,'“ No le niegues la justicia al pobre en sus demandas legales.',NULL),
(@vid,@bid,23,7,'“Aléjate por completo de las acusaciones falsas. No condenes a muerte a una persona inocente o justa , porque yo no perdonaré al malvado.',NULL),
(@vid,@bid,23,8,'“ No aceptes sobornos, porque el soborno ciega a la gente y hace que las personas honestas tuerzan la verdad.',NULL),
(@vid,@bid,23,9,'“ No oprimas al extranjero . Ustedes saben muy bien lo que se siente ser extranjero , porque ustedes mismos fueron extranjeros en Egipto .',NULL),
(@vid,@bid,23,10,'“Durante seis años sembrarás tus campos y recogerás las cosechas,',NULL),
(@vid,@bid,23,11,'pero el séptimo año dejarás descansar la tierra y no la cultivarás. De lo que crezca por sí solo, podrán comer los pobres de tu pueblo , y lo que ellos dejen se lo comerán los animales del campo . Harás lo mismo con tus viñedos y tus olivos.',NULL),
(@vid,@bid,23,12,'“Tienes seis días a la semana para hacer tu trabajo, pero el séptimo día debes descansar. Así podrán descansar también tu toro y tu burro, y podrán reponer fuerzas el hijo de tu esclava y el extranjero .',NULL),
(@vid,@bid,23,13,'“Asegúrense de cumplir todo lo que les he mandado. Ni siquiera mencionen el nombre de otros dioses; ¡ que no se escuche salir de su boca !',NULL),
(@vid,@bid,23,14,'“Celebrarás una fiesta en mi honor tres veces al año .',NULL),
(@vid,@bid,23,15,'Celebrarás la fiesta del pan sin levadura. Durante siete días comerán pan sin levadura en el mes de Abib, tal como te lo ordené , porque en ese mes salieron de Egipto . Nadie debe presentarse ante mí con las manos vacías .',NULL),
(@vid,@bid,23,16,'También celebrarás la fiesta de la cosecha, en la que me ofrecerás los primeros frutos de lo que hayas sembrado en el campo . Y al final del año celebrarás la fiesta de la recolección, cuando recojas todos los frutos de tu trabajo.',NULL),
(@vid,@bid,23,17,'Tres veces al año , todos los hombres se presentarán ante Yahvé el Señor .',NULL),
(@vid,@bid,23,18,'“ No ofrezcas la sangre de mis sacrificios junto con pan que tenga levadura. Tampoco dejes que la grasa de mis ofrendas se quede guardada hasta la mañana siguiente.',NULL),
(@vid,@bid,23,19,'“Llevarás a la casa de Yahvé tu Dios lo mejor de los primeros frutos de tus cosechas. “ No cocines a un cabrito en la leche de su propia madre.',NULL),
(@vid,@bid,23,20,'“ Mira , voy a enviar un ángel delante de ti para que te proteja en el camino y te lleve al lugar que te he preparado.',NULL),
(@vid,@bid,23,21,'Préstale mucha atención y obedece todo lo que te diga. No te rebeles contra él , porque no perdonará los pecados de ustedes, ya que él actúa en mi nombre .',NULL),
(@vid,@bid,23,22,'Pero si tú lo obedeces y haces todo lo que yo te digo, entonces seré enemigo de tus enemigos y me opondré a los que se te opongan.',NULL),
(@vid,@bid,23,23,'Mi ángel irá delante de ti y te llevará a la tierra de los amorreos, los hititas, los ferezeos, los cananeos , los heveos y los jebuseos , y yo los destruiré por completo.',NULL),
(@vid,@bid,23,24,'No te inclines ante sus dioses ni los adores, y no imites lo que ellos hacen . Al contrario, destruye por completo sus ídolos y haz pedazos sus monumentos sagrados.',NULL),
(@vid,@bid,23,25,'Adoren a Yahvé su Dios , y él bendecirá su comida y su agua . Yo alejaré de ustedes las enfermedades.',NULL),
(@vid,@bid,23,26,'En tu país no habrá mujeres que pierdan a sus bebés, ni mujeres que no puedan tener hijos. Yo te daré una vida larga y plena.',NULL),
(@vid,@bid,23,27,'Enviaré mi terror delante de ti; causaré pánico en las naciones a las que llegues, y haré que todos tus enemigos huyan corriendo de ti.',NULL),
(@vid,@bid,23,28,'Enviaré avispas delante de ti para ahuyentar a los heveos , a los cananeos y a los hititas.',NULL),
(@vid,@bid,23,29,'No los expulsaré a todos en un solo año , no sea que la tierra se quede vacía y los animales salvajes se multipliquen y te ataquen.',NULL),
(@vid,@bid,23,30,'Los iré expulsando poco a poco , hasta que ustedes sean lo suficientemente numerosos para ocupar toda la tierra.',NULL),
(@vid,@bid,23,31,'Estableceré tus fronteras desde el Mar Rojo hasta el mar de los filisteos , y desde el desierto hasta el río Éufrates. Yo entregaré en sus manos a los habitantes de esa tierra, y tú los echarás de allí.',NULL),
(@vid,@bid,23,32,'No hagas ningún trato con ellos ni con sus dioses.',NULL),
(@vid,@bid,23,33,'No les permitas vivir en tu país, porque si adoran a sus dioses, ellos te harán pecar contra mí , y eso será una trampa mortal para ti.”',NULL),
(@vid,@bid,24,1,'Entonces Dios le dijo a Moisés : “ Sube a presentarte ante Yahvé, y trae contigo a Aarón, a Nadab , a Abiú y a setenta de los líderes de Israel . Ellos me adorarán desde lejos .',NULL),
(@vid,@bid,24,2,'Solo Moisés se acercará a Yahvé; los demás no deberán acercarse, ni tampoco el pueblo subirá con él ”.',NULL),
(@vid,@bid,24,3,'Moisés bajó y le contó al pueblo todo lo que Yahvé había dicho y todas sus leyes. Y el pueblo entero contestó a una sola voz : “ Cumpliremos con todo lo que Yahvé ha dicho ”.',NULL),
(@vid,@bid,24,4,'Luego Moisés escribió todas las palabras de Yahvé. A la mañana siguiente se levantó temprano y construyó un altar al pie del monte , y levantó doce monumentos de piedra, uno por cada tribu de Israel .',NULL),
(@vid,@bid,24,5,'Mandó a unos jóvenes israelitas a que ofrecieran holocaustos y sacrificaran toros jóvenes como ofrenda de paz para Yahvé.',NULL),
(@vid,@bid,24,6,'Moisés tomó la mitad de la sangre de los animales y la puso en unos tazones, y la otra mitad la roció sobre el altar .',NULL),
(@vid,@bid,24,7,'Después tomó el libro del pacto y se lo leyó en voz alta al pueblo . Ellos respondieron : “ Haremos todo lo que Yahvé nos ha ordenado y seremos obedientes ”.',NULL),
(@vid,@bid,24,8,'Entonces Moisés tomó la sangre de los tazones, la roció sobre el pueblo y les dijo: “Miren, esta es la sangre que confirma el pacto que Yahvé ha hecho con ustedes, basado en todas estas palabras .”',NULL),
(@vid,@bid,24,9,'Después de esto, Moisés , Aarón, Nadab , Abiú y los setenta líderes de Israel subieron al monte.',NULL),
(@vid,@bid,24,10,'Allí vieron al Dios de Israel . Debajo de sus pies había algo parecido a un piso de piedra de zafiro, brillante y claro como el cielo mismo .',NULL),
(@vid,@bid,24,11,'Y aunque estos líderes de Israel vieron a Dios, él no los destruyó; es más , ¡comieron y bebieron allí mismo en su presencia!',NULL),
(@vid,@bid,24,12,'Yahvé le dijo a Moisés : “ Sube a la montaña, hasta donde yo estoy , y espérame ahí . Te voy a dar unas tablas de piedra donde he escrito la ley y los mandamientos para que le enseñes al pueblo.”',NULL),
(@vid,@bid,24,13,'Moisés se preparó para subir junto con su ayudante Josué , y comenzaron a subir a la montaña de Dios.',NULL),
(@vid,@bid,24,14,'Antes de irse, Moisés les dijo a los líderes: “Espérennos aquí hasta que regresemos. Aarón y Hur se quedarán con ustedes. Si alguien tiene algún problema legal, que vaya con ellos”.',NULL),
(@vid,@bid,24,15,'Cuando Moisés subió a la montaña, una nube la cubrió por completo.',NULL),
(@vid,@bid,24,16,'La gloria de Yahvé descansó sobre el monte Sinaí , y la nube lo cubrió durante seis días . Al séptimo día , Yahvé llamó a Moisés desde adentro de la nube .',NULL),
(@vid,@bid,24,17,'Para los israelitas que observaban desde abajo, la gloria de Yahvé parecía un fuego que consumía la cima de la montaña.',NULL),
(@vid,@bid,24,18,'Moisés se metió en la nube y subió a lo más alto de la montaña. Y allí se quedó Moisés durante cuarenta días y cuarenta noches .',NULL),
(@vid,@bid,25,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,25,2,'“ Diles a los israelitas que me traigan una ofrenda . Recibirán mi ofrenda de cualquier persona que la dé de todo corazón .',NULL),
(@vid,@bid,25,3,'Esta es la ofrenda que recibirán de ellos: oro , plata , bronce,',NULL),
(@vid,@bid,25,4,'hilo azul, púrpura, escarlata, lino fino, pelo de cabra ,',NULL),
(@vid,@bid,25,5,'pieles de carnero teñidas de rojo, cueros finos, madera de acacia,',NULL),
(@vid,@bid,25,6,'aceite para las lámparas, especias para el aceite de la unción y para el incienso aromático ,',NULL),
(@vid,@bid,25,7,'y piedras de ónice y otras piedras preciosas para engastarlas en el efod y en el pectoral.',NULL),
(@vid,@bid,25,8,'Que me construyan un santuario , para que yo viva en medio de ellos.',NULL),
(@vid,@bid,25,9,'Deberán construir el santuario y todos sus muebles exactamente igual al modelo que te voy a mostrar.',NULL),
(@vid,@bid,25,10,'“ Harán un arca de madera de acacia. Su largo será de un metro con quince centímetros, y su ancho y su alto serán de casi setenta centímetros.',NULL),
(@vid,@bid,25,11,'La recubrirás de oro puro por dentro y por fuera , y le pondrás una moldura de oro alrededor .',NULL),
(@vid,@bid,25,12,'Harás cuatro argollas de oro y se las pondrás en las cuatro patas: dos argollas en un lado y dos argollas en el otro lado .',NULL),
(@vid,@bid,25,13,'Harás unas varas de madera de acacia y las recubrirás de oro .',NULL),
(@vid,@bid,25,14,'Meterás las varas por las argollas a los lados del arca, para que puedan cargarla.',NULL),
(@vid,@bid,25,15,'Las varas se dejarán puestas en las argollas del arca; no se las quitarán.',NULL),
(@vid,@bid,25,16,'Adentro del arca pondrás las tablas del pacto que yo te daré .',NULL),
(@vid,@bid,25,17,'Harás una tapa de oro puro que servirá de propiciatorio. Su largo será de un metro con quince centímetros y su ancho de casi setenta centímetros.',NULL),
(@vid,@bid,25,18,'Harás dos querubines de oro trabajado a martillo y los pondrás en los dos extremos del propiciatorio.',NULL),
(@vid,@bid,25,19,'Haz un querubín en un extremo y el otro querubín en el otro extremo. Los querubines y el propiciatorio formarán una sola pieza.',NULL),
(@vid,@bid,25,20,'Los querubines tendrán las alas extendidas hacia arriba , cubriendo el propiciatorio con ellas . Estarán uno frente al otro, mirando hacia el propiciatorio.',NULL),
(@vid,@bid,25,21,'Pondrás el propiciatorio como tapa encima del arca, y adentro del arca pondrás las tablas del pacto que yo te daré .',NULL),
(@vid,@bid,25,22,'Allí me reuniré contigo , y desde encima del propiciatorio, de entre los dos querubines que están sobre el arca del pacto, te daré todas mis órdenes para los israelitas.',NULL),
(@vid,@bid,25,23,'“ Harás también una mesa de madera de acacia. Su largo será de casi un metro, su ancho de cuarenta y cinco centímetros, y su alto de casi setenta centímetros.',NULL),
(@vid,@bid,25,24,'La recubrirás de oro puro y le pondrás una moldura de oro alrededor .',NULL),
(@vid,@bid,25,25,'Le harás un borde a su alrededor del ancho de una mano, y le pondrás una moldura de oro a todo el borde.',NULL),
(@vid,@bid,25,26,'Le harás cuatro argollas de oro y se las pondrás en las cuatro esquinas , junto a las cuatro patas.',NULL),
(@vid,@bid,25,27,'Las argollas deberán estar cerca del borde, para pasar por ellas las varas y así poder cargar la mesa .',NULL),
(@vid,@bid,25,28,'Harás las varas de madera de acacia y las recubrirás de oro , para que la mesa pueda ser transportada.',NULL),
(@vid,@bid,25,29,'También harás de oro puro sus platos , sus cucharas , sus jarras y sus tazones para derramar las ofrendas de vino.',NULL),
(@vid,@bid,25,30,'Y sobre la mesa pondrás siempre delante de mí el pan de la presencia .',NULL),
(@vid,@bid,25,31,'“ Harás un candelabro de oro puro . El candelabro y su base deberán ser trabajados a martillo. Su tronco, sus brazos , sus copas , sus botones y sus flores formarán una sola pieza.',NULL),
(@vid,@bid,25,32,'De los lados del candelabro saldrán seis brazos : tres brazos de un lado y tres brazos del otro lado .',NULL),
(@vid,@bid,25,33,'Cada uno de los seis brazos que salen del candelabro tendrá tres copas en forma de flor de almendro, con su botón y su flor .',NULL),
(@vid,@bid,25,34,'El tronco del candelabro tendrá cuatro copas en forma de flor de almendro, con sus botones y sus flores :',NULL),
(@vid,@bid,25,35,'un botón debajo del primer par de brazos , un botón debajo del segundo par de brazos , y un botón debajo del tercer par de brazos ; todos formando una sola pieza con el candelabro.',NULL),
(@vid,@bid,25,36,'Los botones y los brazos formarán una sola pieza con el candelabro, y todo será hecho de oro puro , trabajado a martillo.',NULL),
(@vid,@bid,25,37,'Harás siete lámparas para el candelabro y las acomodarás de tal manera que alumbren hacia el frente.',NULL),
(@vid,@bid,25,38,'Sus tijeras para las mechas y sus platillos también serán de oro puro .',NULL),
(@vid,@bid,25,39,'Para hacer el candelabro y todos sus accesorios se usarán unos treinta y cuatro kilos de oro puro .',NULL),
(@vid,@bid,25,40,'Asegúrate de hacerlo todo exactamente como se te mostró en la montaña.',NULL),
(@vid,@bid,26,1,'“Construirás el santuario con diez cortinas de lino fino torcido , de color azul, púrpura y escarlata. Un artesano experto deberá bordarles figuras de querubines .',NULL),
(@vid,@bid,26,2,'Todas las cortinas medirán lo mismo : trece metros de largo por casi dos metros de ancho.',NULL),
(@vid,@bid,26,3,'Vas a coser cinco de estas cortinas juntas , y harás lo mismo con las otras cinco .',NULL),
(@vid,@bid,26,4,'Harás unos ojales de hilo azul en la orilla de la cortina que queda al extremo del primer conjunto, y harás lo mismo en la orilla de la cortina que queda al extremo del segundo conjunto.',NULL),
(@vid,@bid,26,5,'Harás cincuenta ojales en la primera cortina , y cincuenta ojales en la orilla de la otra cortina , de modo que los ojales queden frente a frente.',NULL),
(@vid,@bid,26,6,'Luego harás cincuenta ganchos de oro para unir las dos cortinas y que el santuario forme una sola pieza.',NULL),
(@vid,@bid,26,7,'“ Harás once cortinas de pelo de cabra para formar una carpa que cubra el santuario.',NULL),
(@vid,@bid,26,8,'Todas las once cortinas medirán lo mismo: catorce metros de largo por casi dos metros de ancho.',NULL),
(@vid,@bid,26,9,'Vas a unir cinco de estas cortinas por un lado, y las otras seis por el otro, doblando la sexta cortina hacia el frente de la carpa.',NULL),
(@vid,@bid,26,10,'Harás cincuenta ojales en la orilla de la cortina que cierra el primer conjunto, y otros cincuenta ojales en la orilla de la cortina que cierra el segundo conjunto.',NULL),
(@vid,@bid,26,11,'Luego harás cincuenta ganchos de bronce y los meterás en los ojales para unir la carpa y que forme una sola pieza.',NULL),
(@vid,@bid,26,12,'La parte de la cortina que sobre , es decir, la mitad que cuelga, caerá por la parte de atrás del santuario.',NULL),
(@vid,@bid,26,13,'Y los cuarenta y cinco centímetros que sobren de largo a cada lado de las cortinas colgarán para proteger los costados del santuario.',NULL),
(@vid,@bid,26,14,'Harás una cubierta para la carpa de pieles de carnero teñidas de rojo, y otra cubierta de cueros finos para ponerla por encima .',NULL),
(@vid,@bid,26,15,'“ Harás tablas de madera de acacia para formar las paredes del santuario.',NULL),
(@vid,@bid,26,16,'Cada tabla medirá cuatro metros y medio de largo, por setenta centímetros de ancho.',NULL),
(@vid,@bid,26,17,'Cada tabla tendrá dos espigas paralelas para que encajen unas con otras. Así harás todas las tablas del santuario.',NULL),
(@vid,@bid,26,18,'Harás veinte tablas para el lado sur del santuario,',NULL),
(@vid,@bid,26,19,'y harás cuarenta bases de plata para ponerlas debajo de las veinte tablas : dos bases debajo de cada tabla para que encajen sus dos espigas.',NULL),
(@vid,@bid,26,20,'Para el lado norte del santuario harás otras veinte tablas ,',NULL),
(@vid,@bid,26,21,'con sus cuarenta bases de plata : dos bases debajo de cada tabla .',NULL),
(@vid,@bid,26,22,'Para la parte de atrás del santuario, que da al oeste, harás seis tablas .',NULL),
(@vid,@bid,26,23,'Además, harás dos tablas para las esquinas traseras del santuario.',NULL),
(@vid,@bid,26,24,'Estas tablas de las esquinas estarán unidas por abajo y también por arriba , hasta la primera argolla. Así se harán las tablas para las dos esquinas .',NULL),
(@vid,@bid,26,25,'En total serán ocho tablas con sus dieciséis bases de plata : dos bases debajo de cada tabla .',NULL),
(@vid,@bid,26,26,'“ Harás unos travesaños de madera de acacia: cinco para las tablas de un lado del santuario,',NULL),
(@vid,@bid,26,27,'cinco para las tablas del otro lado , y cinco para las tablas de la parte trasera, del lado oeste.',NULL),
(@vid,@bid,26,28,'El travesaño del medio pasará por el centro de las tablas , de un extremo al otro .',NULL),
(@vid,@bid,26,29,'Recubrirás de oro las tablas , y harás argollas de oro por donde pasarán los travesaños. También recubrirás de oro los travesaños.',NULL),
(@vid,@bid,26,30,'Armarás el santuario exactamente como se te mostró en la montaña.',NULL),
(@vid,@bid,26,31,'“ Harás un velo de lino fino torcido , de color azul, púrpura y escarlata, y un artesano experto le bordará querubines .',NULL),
(@vid,@bid,26,32,'Lo colgarás de unos ganchos de oro sobre cuatro postes de madera de acacia recubiertos de oro , que estarán apoyados sobre cuatro bases de plata .',NULL),
(@vid,@bid,26,33,'Colgarás el velo debajo de los ganchos, y allí , detrás del velo, pondrás el arca del pacto. Este velo servirá para separar el Lugar Santo del Lugar Santísimo .',NULL),
(@vid,@bid,26,34,'Pondrás el propiciatorio sobre el arca del pacto en el Lugar Santísimo .',NULL),
(@vid,@bid,26,35,'Afuera del velo pondrás la mesa , y el candelabro lo pondrás frente a la mesa . El candelabro irá en el lado sur del santuario, y la mesa en el lado norte .',NULL),
(@vid,@bid,26,36,'“ Harás una cortina para la entrada de la carpa. Será de lino fino torcido , de color azul, púrpura y escarlata, y estará finamente bordada.',NULL),
(@vid,@bid,26,37,'Para colgar esta cortina harás cinco postes de acacia recubiertos de oro . Sus ganchos serán de oro , y fundirás para ellos cinco bases de bronce.',NULL),
(@vid,@bid,27,1,'“ Harás un altar de madera de acacia, que sea cuadrado . Medirá dos metros y medio de largo por dos metros y medio de ancho, y tendrá un metro y medio de alto.',NULL),
(@vid,@bid,27,2,'Le harás un cuerno en cada una de sus cuatro esquinas , de manera que los cuernos formen una sola pieza con el altar, y lo recubrirás todo de bronce.',NULL),
(@vid,@bid,27,3,'Harás de bronce todos sus utensilios: los recipientes para las cenizas, las palas, los tazones , los tenedores y los braseros.',NULL),
(@vid,@bid,27,4,'Le harás una rejilla de bronce en forma de red , y le pondrás cuatro argollas de bronce en las cuatro esquinas .',NULL),
(@vid,@bid,27,5,'Colocarás la rejilla por debajo del borde del altar , de manera que llegue hasta la mitad del altar .',NULL),
(@vid,@bid,27,6,'Harás unas varas de madera de acacia y las recubrirás de bronce.',NULL),
(@vid,@bid,27,7,'Estas varas se meterán por las argollas a los dos lados del altar para poder transportarlo.',NULL),
(@vid,@bid,27,8,'El altar será hueco y estará hecho de tablas , tal como se te mostró en la montaña.',NULL),
(@vid,@bid,27,9,'“ Harás un patio alrededor del santuario. El lado sur del patio medirá cuarenta y cinco metros de largo, y tendrá cortinas de lino fino torcido .',NULL),
(@vid,@bid,27,10,'Tendrá veinte postes apoyados sobre veinte bases de bronce; pero los ganchos y las uniones de los postes serán de plata .',NULL),
(@vid,@bid,27,11,'El lado norte también medirá cuarenta y cinco metros de largo, con cortinas colgadas de veinte postes sobre veinte bases de bronce. Los ganchos y las uniones de los postes serán de plata .',NULL),
(@vid,@bid,27,12,'El lado oeste del patio medirá veintidós metros y medio de ancho, y tendrá cortinas colgadas de diez postes sobre diez bases.',NULL),
(@vid,@bid,27,13,'El lado este del patio , por donde sale el sol, también medirá veintidós metros y medio de ancho.',NULL),
(@vid,@bid,27,14,'A un lado de la entrada habrá cortinas a lo largo de casi siete metros, colgadas de tres postes sobre tres bases.',NULL),
(@vid,@bid,27,15,'Al otro lado también habrá cortinas a lo largo de casi siete metros, colgadas de tres postes sobre tres bases.',NULL),
(@vid,@bid,27,16,'La entrada del patio tendrá una cortina de nueve metros de largo, hecha de lino fino torcido , de color azul, púrpura y escarlata, finamente bordada. Estará colgada de cuatro postes sobre cuatro bases.',NULL),
(@vid,@bid,27,17,'Todos los postes alrededor del patio estarán unidos con barras de plata ; sus ganchos serán de plata y sus bases de bronce.',NULL),
(@vid,@bid,27,18,'El patio medirá cuarenta y cinco metros de largo por veintidós y medio de ancho. Las cortinas de lino fino medirán poco más de dos metros de alto, y las bases serán de bronce.',NULL),
(@vid,@bid,27,19,'Todos los utensilios para el servicio del santuario, así como las estacas del santuario y las estacas del patio , serán de bronce.',NULL),
(@vid,@bid,27,20,'“Mándales a los israelitas que te traigan el mejor aceite de oliva para las lámparas , para que siempre haya una lámpara encendida.',NULL),
(@vid,@bid,27,21,'Aarón y sus hijos deberán mantener las lámparas encendidas delante de Yahvé desde la tarde hasta la mañana . Esto se hará en la Tienda de Reunión, afuera del velo que protege el arca del pacto. Los israelitas y sus descendientes deberán cumplir con esta ley para siempre .',NULL),
(@vid,@bid,28,1,'“ De entre todos los israelitas, llama a tu hermano Aarón y a sus hijos Nadab , Abiú, Eleazar e Itamar, para que me sirvan como sacerdotes.',NULL),
(@vid,@bid,28,2,'Manda a hacerle a tu hermano Aarón ropas sagradas , que le den honra y belleza.',NULL),
(@vid,@bid,28,3,'Habla con todos los artesanos expertos, a quienes les he dado la habilidad para hacer estos trabajos, y pídeles que le hagan las ropas a Aarón. Así será consagrado para que me sirva como sacerdote.',NULL),
(@vid,@bid,28,4,'Estas son las ropas que deberán hacerle : un pectoral, un efod, un manto , una túnica bordada, un turbante y un cinturón. Harán estas ropas sagradas para tu hermano Aarón y para sus hijos , para que me sirvan como sacerdotes.',NULL),
(@vid,@bid,28,5,'Deberán usar hilo de oro , y lino fino de color azul, púrpura y escarlata.',NULL),
(@vid,@bid,28,6,'“ El efod lo harán de hilo de oro , de lino fino de color azul, púrpura y escarlata, obra de un artesano experto.',NULL),
(@vid,@bid,28,7,'Tendrá dos tirantes unidos a sus esquinas para poder sujetarlo.',NULL),
(@vid,@bid,28,8,'El cinturón que va sobre el efod formará una sola pieza con él , y estará hecho del mismo material: hilo de oro , y lino fino de color azul, púrpura y escarlata.',NULL),
(@vid,@bid,28,9,'Tomarás dos piedras de ónice y grabarás en ellas los nombres de las tribus de Israel .',NULL),
(@vid,@bid,28,10,'Grabarás seis nombres en una piedra, y los otros seis nombres en la otra piedra, en el orden en que nacieron.',NULL),
(@vid,@bid,28,11,'Las grabarás con el mismo cuidado que un joyero graba un sello, y luego las montarás en engastes de oro .',NULL),
(@vid,@bid,28,12,'Sujetarás estas dos piedras en los tirantes del efod, para que sirvan de recuerdo para los israelitas. Así Aarón llevará los nombres de ellos sobre sus hombros ante Yahvé, para recordarlos continuamente.',NULL),
(@vid,@bid,28,13,'Harás los engastes de oro ,',NULL),
(@vid,@bid,28,14,'y dos cadenas de oro puro tejidas en forma de cordón, y sujetarás estas cadenas a los engastes .',NULL),
(@vid,@bid,28,15,'“ También harás el pectoral para dictar justicia . Será hecho por un artesano experto, usando los mismos materiales que el efod: hilo de oro , y lino fino torcido de color azul, púrpura y escarlata.',NULL),
(@vid,@bid,28,16,'Será cuadrado y doble ; medirá una cuarta de largo por una cuarta de ancho.',NULL),
(@vid,@bid,28,17,'Le pondrás cuatro hileras de piedras preciosas. En la primera hilera habrá un rubí, un topacio y un berilo;',NULL),
(@vid,@bid,28,18,'en la segunda hilera, una turquesa, un zafiro y una esmeralda;',NULL),
(@vid,@bid,28,19,'en la tercera hilera, un jacinto, una ágata y una amatista;',NULL),
(@vid,@bid,28,20,'y en la cuarta hilera, un crisólito , un ónice y un jaspe. Todas estas piedras deberán estar montadas en oro .',NULL),
(@vid,@bid,28,21,'Serán doce piedras en total, una por cada tribu de Israel , y cada piedra tendrá grabado el nombre de una de las doce tribus , como si fuera un sello.',NULL),
(@vid,@bid,28,22,'Para el pectoral, harás unas cadenas trenzadas de oro puro , en forma de cordón.',NULL),
(@vid,@bid,28,23,'Harás también dos argollas de oro y las pondrás en las dos esquinas superiores del pectoral.',NULL),
(@vid,@bid,28,24,'Luego engancharás las dos cadenas de oro en las dos argollas que están en el pectoral.',NULL),
(@vid,@bid,28,25,'Los otros dos extremos de las cadenas los sujetarás a los dos engastes , y los fijarás a la parte delantera de los tirantes del efod.',NULL),
(@vid,@bid,28,26,'Harás otras dos argollas de oro y las pondrás en las dos esquinas inferiores del pectoral, por la parte de adentro que queda junto al efod.',NULL),
(@vid,@bid,28,27,'Además , harás otras dos argollas de oro y las pondrás en la parte baja de los tirantes del efod, por el frente, cerca de la costura y un poco más arriba del cinturón del efod.',NULL),
(@vid,@bid,28,28,'Amarrarán las argollas del pectoral a las argollas del efod con un cordón azul, para que el pectoral quede ajustado por encima del cinturón y no se separe del efod.',NULL),
(@vid,@bid,28,29,'Así, cuando Aarón entre al Lugar Santo , llevará los nombres de las tribus de Israel sobre su corazón en el pectoral de justicia , para recordarlos siempre delante de Yahvé.',NULL),
(@vid,@bid,28,30,'Adentro del pectoral de justicia pondrás el Urim y el Tumim, para que estén sobre el corazón de Aarón cada vez que se presente ante Yahvé. Así Aarón llevará siempre sobre su corazón la responsabilidad de las decisiones de los israelitas ante Yahvé.',NULL),
(@vid,@bid,28,31,'“ El manto que se usa con el efod lo harás todo de tela azul.',NULL),
(@vid,@bid,28,32,'Tendrá una abertura en el centro para meter la cabeza . El borde de esta abertura estará reforzado con un tejido especial, como el cuello de una armadura, para que no se rompa.',NULL),
(@vid,@bid,28,33,'En todo el borde inferior del manto bordarás granadas de hilo azul, púrpura y escarlata, e intercalarás campanitas de oro entre ellas .',NULL),
(@vid,@bid,28,34,'O sea que todo el borde del manto llevará una campanita de oro y luego una granada, otra campanita de oro y otra granada, y así sucesivamente.',NULL),
(@vid,@bid,28,35,'Aarón deberá ponerse este manto siempre que oficie como sacerdote. Así, cuando él entre y salga del Lugar Santo ante Yahvé, se escucharán las campanitas, y él no morirá .',NULL),
(@vid,@bid,28,36,'“ Harás una placa de oro puro , y la grabarás como si fuera un sello, con las palabras: ‘ CONSAGRADO A YAHVÉ’.',NULL),
(@vid,@bid,28,37,'Amarrarás la placa con un cordón azul a la parte delantera del turbante.',NULL),
(@vid,@bid,28,38,'Así la placa quedará sobre la frente de Aarón, y él se hará responsable de cualquier error que cometan los israelitas al presentar sus ofrendas sagradas a Dios . La placa estará siempre en su frente , para que Yahvé acepte las ofrendas del pueblo.',NULL),
(@vid,@bid,28,39,'“La túnica y el turbante los harás de lino fino, y el cinturón deberá estar finamente bordado.',NULL),
(@vid,@bid,28,40,'“ A los hijos de Aarón también les harás túnicas , cinturones y gorros, para que se vean honrosos y hermosos.',NULL),
(@vid,@bid,28,41,'Viste a tu hermano Aarón y a sus hijos con estas ropas sagradas; y úngelos con aceite, conságralos y santifícalos para que me sirvan como sacerdotes.',NULL),
(@vid,@bid,28,42,'Hazles ropa interior de lino que les cubra desde la cintura hasta los muslos, para que no se les vea el cuerpo desnudo.',NULL),
(@vid,@bid,28,43,'Aarón y sus hijos deberán ponérsela siempre que entren en la Tienda de Reunión o cuando se acerquen al altar para oficiar en el Lugar Santo . Así no cometerán ningún pecado ni morirán . Esta es una ley que Aarón y sus descendientes deberán cumplir para siempre .”',NULL),
(@vid,@bid,29,1,'“ Esto es lo que harás con ellos para consagrarlos, a fin de que me sirvan como sacerdotes: toma un toro joven y dos carneros sin ningún defecto;',NULL),
(@vid,@bid,29,2,'panes sin levadura, tortas sin levadura amasadas con aceite , y hojaldres sin levadura untados con aceite . Los harás con la mejor harina de trigo .',NULL),
(@vid,@bid,29,3,'Los pondrás en una canasta y me los presentarás en ella , junto con el toro y los dos carneros.',NULL),
(@vid,@bid,29,4,'Llevarás a Aarón y a sus hijos a la entrada de la Carpa de Reunión, y allí los lavarás con agua .',NULL),
(@vid,@bid,29,5,'Tomarás las ropas sagradas y vestirás a Aarón con la túnica, el manto del efod, el efod y el pectoral, y le amarrarás el cinturón finamente bordado del efod.',NULL),
(@vid,@bid,29,6,'Le pondrás el turbante en la cabeza , y sobre el turbante colocarás la placa sagrada.',NULL),
(@vid,@bid,29,7,'Luego tomarás el aceite de la unción , lo derramarás sobre su cabeza y lo ungirás .',NULL),
(@vid,@bid,29,8,'Harás que se acerquen sus hijos y les pondrás las túnicas .',NULL),
(@vid,@bid,29,9,'Les pondrás los cinturones a Aarón y a sus hijos , y les atarás los gorros. Ellos y sus descendientes serán sacerdotes para siempre , como una ley permanente. De esta manera consagrarás a Aarón y a sus hijos .',NULL),
(@vid,@bid,29,10,'“Llevarás el toro a la entrada de la Carpa de Reunión, y Aarón y sus hijos pondrán las manos sobre la cabeza del toro .',NULL),
(@vid,@bid,29,11,'Matarás el toro en la presencia de Yahvé, a la entrada de la Carpa de Reunión.',NULL),
(@vid,@bid,29,12,'Tomarás con el dedo un poco de la sangre del toro y la untarás en los cuernos del altar , y el resto de la sangre lo derramarás al pie del altar .',NULL),
(@vid,@bid,29,13,'Tomarás toda la grasa que cubre los intestinos, la mejor parte del hígado , los dos riñones y la grasa que los cubre , y los quemarás sobre el altar .',NULL),
(@vid,@bid,29,14,'Pero la carne del toro , su piel y su excremento los quemarás en el fuego, fuera del campamento . Es un sacrificio por el pecado .',NULL),
(@vid,@bid,29,15,'“También tomarás uno de los carneros, y Aarón y sus hijos pondrán las manos sobre la cabeza del carnero.',NULL),
(@vid,@bid,29,16,'Matarás el carnero, tomarás su sangre y la rociarás por todos los lados del altar .',NULL),
(@vid,@bid,29,17,'Cortarás el carnero en pedazos, lavarás sus intestinos y sus patas, y los pondrás junto con los otros pedazos y con la cabeza .',NULL),
(@vid,@bid,29,18,'Y quemarás todo el carnero sobre el altar . Es un holocausto para Yahvé; es un aroma agradable, una ofrenda quemada para Yahvé.',NULL),
(@vid,@bid,29,19,'“Luego tomarás el otro carnero, y Aarón y sus hijos pondrán las manos sobre su cabeza .',NULL),
(@vid,@bid,29,20,'Matarás el carnero, tomarás un poco de su sangre y se la untarás a Aarón y a sus hijos en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho . Rociarás el resto de la sangre por todos los lados del altar .',NULL),
(@vid,@bid,29,21,'Tomarás un poco de la sangre que está en el altar y del aceite de la unción , y rociarás a Aarón y a sus ropas, y también a sus hijos y a sus ropas. De esta manera quedarán consagrados él , sus hijos y la ropa de todos ellos .',NULL),
(@vid,@bid,29,22,'Tomarás también la grasa del carnero, la cola gorda, la grasa que cubre los intestinos, la mejor parte del hígado , los dos riñones , la grasa que los cubre y el muslo derecho ( pues es el carnero para la ceremonia de consagración),',NULL),
(@vid,@bid,29,23,'junto con un pan redondo, una torta de pan amasada con aceite y un hojaldre de la canasta de panes sin levadura que está en la presencia de Yahvé.',NULL),
(@vid,@bid,29,24,'Pondrás todo esto en las manos de Aarón y de sus hijos , y lo presentarán meciéndolo ante Yahvé como una ofrenda especial.',NULL),
(@vid,@bid,29,25,'Después lo tomarás de sus manos y lo quemarás en el altar , junto con el holocausto , como un aroma agradable a Yahvé. Es una ofrenda quemada para Yahvé.',NULL),
(@vid,@bid,29,26,'“ Tomarás el pecho del carnero usado para la consagración de Aarón, y lo mecerás ante Yahvé como ofrenda especial. Esa será tu porción .',NULL),
(@vid,@bid,29,27,'Consagrarás el pecho que fue mecido y el muslo que fue elevado, las partes del carnero de consagración que les corresponden a Aarón y a sus hijos .',NULL),
(@vid,@bid,29,28,'Estas porciones serán siempre para Aarón y para sus hijos . Es una regla permanente para los israelitas, porque se trata de una ofrenda apartada . Será la porción que los israelitas siempre le darán a Yahvé de sus sacrificios de paz.',NULL),
(@vid,@bid,29,29,'“ Cuando Aarón muera, sus ropas sagradas pasarán a sus descendientes, para que con ellas los unjan y los consagren.',NULL),
(@vid,@bid,29,30,'El hijo de Aarón que lo reemplace como sumo sacerdote deberá ponerse esas ropas durante siete días , cuando entre en la Carpa de Reunión para oficiar en el Lugar Santo .',NULL),
(@vid,@bid,29,31,'“ Tomarás el carnero usado en la consagración y cocinarás su carne en un lugar sagrado.',NULL),
(@vid,@bid,29,32,'Aarón y sus hijos se comerán la carne del carnero y el pan de la canasta a la entrada de la Carpa de Reunión.',NULL),
(@vid,@bid,29,33,'Se comerán estas ofrendas con las que se hizo el perdón de pecados al consagrarlos y santificarlos. Ninguna persona que no sea de la familia sacerdotal podrá comer de esto, porque es sagrado .',NULL),
(@vid,@bid,29,34,'Si sobra algo de la carne o del pan para la mañana siguiente, tendrás que quemarlo. No se debe comer, porque es sagrado .',NULL),
(@vid,@bid,29,35,'“ Haz todo esto con Aarón y con sus hijos , tal como te lo he ordenado . La ceremonia de consagración durará siete días .',NULL),
(@vid,@bid,29,36,'Cada día ofrecerás un toro como sacrificio por el pecado para obtener el perdón. Así purificarás el altar , y luego lo ungirás para consagrarlo.',NULL),
(@vid,@bid,29,37,'Durante siete días harás la ceremonia de perdón por el altar para consagrarlo. Así el altar será santísimo , y cualquier cosa que toque el altar quedará consagrada .',NULL),
(@vid,@bid,29,38,'“ Esto es lo que ofrecerás sobre el altar todos los días , sin falta: dos corderos de un año .',NULL),
(@vid,@bid,29,39,'Ofrecerás un cordero en la mañana , y el otro al atardecer.',NULL),
(@vid,@bid,29,40,'Con el primer cordero ofrecerás dos kilos y medio de la mejor harina mezclada con un litro de aceite puro de oliva prensada, y un litro de vino como ofrenda líquida.',NULL),
(@vid,@bid,29,41,'Al atardecer ofrecerás el otro cordero , junto con una ofrenda de harina y de vino igual a la de la mañana . Será una ofrenda quemada de aroma agradable a Yahvé.',NULL),
(@vid,@bid,29,42,'Este será el holocausto diario que se ofrecerá generación tras generación a la entrada de la Carpa de Reunión, en la presencia de Yahvé. Allí me reuniré con ustedes para hablarte .',NULL),
(@vid,@bid,29,43,'Allí me encontraré con los israelitas, y ese lugar quedará consagrado por mi gloria .',NULL),
(@vid,@bid,29,44,'Consagraré la Carpa de Reunión y el altar . También consagraré a Aarón y a sus hijos para que me sirvan como sacerdotes.',NULL),
(@vid,@bid,29,45,'Yo viviré entre los israelitas y seré su Dios.',NULL),
(@vid,@bid,29,46,'Y sabrán que yo soy Yahvé su Dios , el que los sacó de Egipto para vivir en medio de ellos. Yo soy Yahvé su Dios .',NULL),
(@vid,@bid,30,1,'“ Harás un altar para quemar incienso, y lo harás de madera de acacia.',NULL),
(@vid,@bid,30,2,'Será cuadrado , de cuarenta y cinco centímetros de largo por cuarenta y cinco de ancho, y tendrá noventa centímetros de alto. Los cuernos del altar formarán una sola pieza con él.',NULL),
(@vid,@bid,30,3,'Lo recubrirás de oro puro : la parte de arriba, los cuatro lados y sus cuernos ; y le pondrás una moldura de oro alrededor .',NULL),
(@vid,@bid,30,4,'Le harás dos argollas de oro y se las pondrás debajo de la moldura, en dos lados opuestos, para pasar por ellas las varas y poder cargarlo.',NULL),
(@vid,@bid,30,5,'Harás las varas de madera de acacia y las recubrirás de oro .',NULL),
(@vid,@bid,30,6,'Pondrás el altar frente al velo que oculta el arca del pacto, frente al propiciatorio que cubre las tablas del pacto, que es el lugar donde me reuniré contigo .',NULL),
(@vid,@bid,30,7,'Todas las mañanas, cuando Aarón prepare las lámparas , quemará incienso aromático sobre el altar.',NULL),
(@vid,@bid,30,8,'Y al atardecer, cuando Aarón encienda las lámparas , volverá a quemar incienso. Esta será una ofrenda continua de incienso ante Yahvé, de generación en generación .',NULL),
(@vid,@bid,30,9,'No ofrecerán sobre este altar ningún incienso no autorizado, ni ofrendas quemadas ni ofrendas de grano; tampoco derramarán ofrendas líquidas sobre él .',NULL),
(@vid,@bid,30,10,'Una vez al año , Aarón hará la ceremonia del perdón sobre los cuernos del altar. Con la sangre del sacrificio que se ofrece cada año para el perdón de los pecados , hará la ceremonia de limpieza sobre el altar. Esto se hará de generación en generación , pues el altar es un lugar santísimo , consagrado a Yahvé”.',NULL),
(@vid,@bid,30,11,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,30,12,'“ Cuando hagas un censo para contar a los israelitas, cada uno deberá darle a Yahvé un rescate por su vida al ser contado. Así no caerá ninguna plaga sobre ellos por hacer el censo.',NULL),
(@vid,@bid,30,13,'Todo el que sea censado deberá pagar medio siclo de plata, pesado según el siclo oficial del santuario (un siclo equivale a veinte geras ). Este medio siclo es una ofrenda para Yahvé.',NULL),
(@vid,@bid,30,14,'Todos los mayores de veinte años que sean censados deberán dar esta ofrenda a Yahvé.',NULL),
(@vid,@bid,30,15,'Cuando entreguen esta ofrenda a Yahvé para pagar el rescate por sus vidas , el rico no dará más de medio siclo , ni el pobre dará menos.',NULL),
(@vid,@bid,30,16,'Recibirás el dinero de este rescate pagado por los israelitas, y lo usarás para los gastos de la Carpa de Reunión. Esto le servirá de recordatorio a los israelitas ante Yahvé, de que han pagado el rescate por sus vidas .”',NULL),
(@vid,@bid,30,17,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,30,18,'“ Harás un lavamanos de bronce, con su base de bronce. Lo pondrás entre la Carpa de Reunión y el altar , y lo llenarás de agua .',NULL),
(@vid,@bid,30,19,'Aarón y sus hijos usarán esa agua para lavarse las manos y los pies .',NULL),
(@vid,@bid,30,20,'Siempre que entren a la Carpa de Reunión, o cuando se acerquen al altar para servir y presentar las ofrendas quemadas a Yahvé, deberán lavarse con agua para no morir .',NULL),
(@vid,@bid,30,21,'Se lavarán las manos y los pies para no morir . Esta será una ley permanente para Aarón y sus descendientes, de generación en generación .”',NULL),
(@vid,@bid,30,22,'Yahvé le dijo también a Moisés :',NULL),
(@vid,@bid,30,23,'“ Toma las siguientes especias finas: cinco kilos de mirra líquida; dos kilos y medio de canela aromática ; dos kilos y medio de caña aromática ;',NULL),
(@vid,@bid,30,24,'cinco kilos de casia (pesado todo según el peso oficial del santuario ), y unos cuatro litros de aceite de oliva.',NULL),
(@vid,@bid,30,25,'Con estos ingredientes prepararás el aceite sagrado para la unción , mezclándolo con el mismo cuidado que un perfumista prepara un perfume. Será el aceite sagrado para la unción .',NULL),
(@vid,@bid,30,26,'Con este aceite ungirás la Carpa de Reunión, el arca del pacto,',NULL),
(@vid,@bid,30,27,'la mesa con todos sus utensilios, el candelabro con sus utensilios, el altar del incienso,',NULL),
(@vid,@bid,30,28,'el altar de los holocaustos con todos sus utensilios, y el lavamanos con su base.',NULL),
(@vid,@bid,30,29,'De esta manera los consagrarás, y serán cosas santísimas. Cualquier cosa que los toque quedará santificada .',NULL),
(@vid,@bid,30,30,'También ungirás a Aarón y a sus hijos , y los consagrarás para que me sirvan como sacerdotes.',NULL),
(@vid,@bid,30,31,'Y les dirás a los israelitas: ‘ Este será mi aceite sagrado para la unción , de generación en generación .',NULL),
(@vid,@bid,30,32,'No lo derramen sobre el cuerpo de cualquier persona, ni preparen ningún otro aceite con esta misma fórmula. Es sagrado , y ustedes deben tratarlo como algo sagrado .',NULL),
(@vid,@bid,30,33,'Cualquiera que prepare una mezcla igual a esta , o que unja con él a alguien que no sea sacerdote, será expulsado de su pueblo ’”.',NULL),
(@vid,@bid,30,34,'Yahvé le dijo a Moisés : “ Toma cantidades iguales de las siguientes especias aromáticas: resina, uña aromática, gálbano e incienso puro .',NULL),
(@vid,@bid,30,35,'Con estos ingredientes prepararás un incienso aromático, mezclado con el cuidado de un perfumista. Échale sal para que sea puro y sagrado .',NULL),
(@vid,@bid,30,36,'Muele una parte hasta convertirla en polvo fino, y ponlo frente al arca del pacto en la Carpa de Reunión, que es donde yo me encontraré contigo . Este incienso será algo santísimo para ustedes.',NULL),
(@vid,@bid,30,37,'No preparen nunca este mismo incienso para uso personal; considérenlo como algo sagrado y exclusivo para Yahvé.',NULL),
(@vid,@bid,30,38,'Cualquiera que haga un incienso como este para disfrutar de su fragancia, será expulsado de su pueblo .”',NULL),
(@vid,@bid,31,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,31,2,'“ Mira , he escogido personalmente a Bezalel, que es hijo de Uri y nieto de Hur , de la tribu de Judá .',NULL),
(@vid,@bid,31,3,'Lo he llenado del Espíritu de Dios, y le he dado gran sabiduría , inteligencia y capacidad creativa para hacer toda clase de trabajos artesanales.',NULL),
(@vid,@bid,31,4,'Él es experto en diseñar obras de arte, en trabajar el oro , la plata y el bronce;',NULL),
(@vid,@bid,31,5,'en cortar y engastar piedras preciosas, en tallar madera , y en toda clase de artesanías.',NULL),
(@vid,@bid,31,6,'Además, le he asignado como ayudante a Aholiab, hijo de Ahisamac, de la tribu de Dan . Y a todos los demás artesanos expertos les he dado la sabiduría necesaria para hacer todo lo que te he ordenado :',NULL),
(@vid,@bid,31,7,'la Carpa de Reunión, el arca del pacto y el propiciatorio que la cubre, todos los muebles de la Carpa,',NULL),
(@vid,@bid,31,8,'la mesa con sus utensilios, el candelabro de oro puro con sus utensilios, el altar del incienso,',NULL),
(@vid,@bid,31,9,'el altar de los holocaustos con todos sus utensilios, el lavamanos con su base,',NULL),
(@vid,@bid,31,10,'las ropas finamente tejidas, las ropas sagradas para el sacerdote Aarón y las ropas para que sus hijos oficien como sacerdotes ,',NULL),
(@vid,@bid,31,11,'el aceite de la unción y el incienso aromático para el Lugar Santo . Ellos deberán hacerlo todo exactamente como te lo he ordenado .”',NULL),
(@vid,@bid,31,12,'Yahvé le habló a Moisés y le dijo:',NULL),
(@vid,@bid,31,13,'“ Diles a los israelitas: ‘Asegúrense de respetar mis sábados , porque es una señal de mi pacto entre ustedes y yo , de generación en generación . Así sabrán que yo soy Yahvé, quien los santifica .',NULL),
(@vid,@bid,31,14,'Respeten el sábado , porque es un día sagrado para ustedes. Cualquiera que lo profane será condenado a muerte ; y si alguien trabaja en ese día, será expulsado de su pueblo .',NULL),
(@vid,@bid,31,15,'Tienen seis días para trabajar , pero el séptimo día es un día de descanso absoluto, consagrado a Yahvé. Cualquiera que trabaje en el día de descanso será condenado a muerte .',NULL),
(@vid,@bid,31,16,'Por lo tanto, los israelitas guardarán el sábado y lo celebrarán de generación en generación como un pacto eterno .',NULL),
(@vid,@bid,31,17,'Será una señal permanente entre los israelitas y yo ; porque en seis días Yahvé hizo los cielos y la tierra, y el séptimo día descansó’”.',NULL),
(@vid,@bid,31,18,'Cuando Yahvé terminó de hablar con Moisés en el monte Sinaí , le dio las dos tablas del pacto, que eran de piedra y estaban escritas por el dedo mismo de Dios.',NULL),
(@vid,@bid,32,1,'El pueblo , al ver que Moisés tardaba tanto en bajar de la montaña, se juntó alrededor de Aarón y le dijo: “¡Ándale, haznos dioses que nos guíen! Porque no sabemos qué le pasó a ese tal Moisés , el hombre que nos sacó de Egipto .”',NULL),
(@vid,@bid,32,2,'Aarón les contestó: “Quítenles los aretes de oro a sus esposas, a sus hijos y a sus hijas , y tráiganmelos”.',NULL),
(@vid,@bid,32,3,'Entonces todo el pueblo se quitó los aretes de oro que llevaban puestos y se los entregaron a Aarón.',NULL),
(@vid,@bid,32,4,'Él recibió el oro, lo trabajó con un cincel y fundió un becerro de metal. Al verlo, el pueblo gritó: “¡ Israel , estos son tus dioses que te sacaron de Egipto !”.',NULL),
(@vid,@bid,32,5,'Cuando Aarón vio el entusiasmo de la gente, construyó un altar frente al becerro y anunció: “¡ Mañana tendremos una fiesta en honor a Yahvé!”.',NULL),
(@vid,@bid,32,6,'Al día siguiente , todos se levantaron temprano, ofrecieron holocaustos y presentaron sacrificios de paz. Luego el pueblo se sentó a comer y a beber , y después se levantaron para divertirse y hacer un desastre.',NULL),
(@vid,@bid,32,7,'Entonces Yahvé le dijo a Moisés : “ Baja enseguida, porque tu pueblo , el que sacaste de Egipto , se ha corrompido .',NULL),
(@vid,@bid,32,8,'Muy rápido se desviaron del camino que yo les marqué. Se hicieron un becerro de metal fundido, se han inclinado ante él , le han ofrecido sacrificios y han dicho: ‘¡ Israel , estos son tus dioses que te sacaron de Egipto !’”.',NULL),
(@vid,@bid,32,9,'Yahvé le dijo además a Moisés : “Me he fijado en este pueblo , y es un pueblo muy terco y rebelde.',NULL),
(@vid,@bid,32,10,'¡Déjame en paz! Mi enojo va a estallar contra ellos y los voy a destruir. Pero a ti te convertiré en una gran nación ”.',NULL),
(@vid,@bid,32,11,'Pero Moisés le suplicó a Yahvé su Dios : “ Oh Yahvé, ¿ por qué vas a descargar tu enojo contra tu pueblo , al que sacaste de Egipto con tanto poder y con mano fuerte ?',NULL),
(@vid,@bid,32,12,'¿ Por qué darles a los egipcios el gusto de decir: ‘Dios los sacó con malas intenciones, solo para matarlos en las montañas y borrarlos de la faz de la tierra’? ¡Cálmate! No dejes que tu enojo te lleve a destruir a tu pueblo .',NULL),
(@vid,@bid,32,13,'Acuérdate de tus siervos Abraham, Isaac e Israel , a quienes les juraste por ti mismo : ‘ Haré que sus descendientes sean tan numerosos como las estrellas del cielo , y les daré a sus descendientes toda esta tierra que les prometí, para que sea de ellos para siempre ’”.',NULL),
(@vid,@bid,32,14,'Al oír esto , Yahvé cambió de parecer y ya no destruyó a su pueblo como había amenazado.',NULL),
(@vid,@bid,32,15,'Moisés se dio la vuelta y bajó de la montaña, llevando en sus manos las dos tablas del pacto. Estaban escritas por los dos lados , tanto por el frente como por el reverso.',NULL),
(@vid,@bid,32,16,'Las tablas eran obra de Dios, y la escritura grabada en ellas era de Dios mismo .',NULL),
(@vid,@bid,32,17,'Cuando Josué escuchó el griterío de la gente , le dijo a Moisés : “¡ Suena como si hubiera guerra en el campamento !”.',NULL),
(@vid,@bid,32,18,'Pero Moisés le respondió : “No son gritos de victoria, ni son lamentos de derrota. Lo que escucho son cantos de fiesta”.',NULL),
(@vid,@bid,32,19,'En cuanto Moisés se acercó al campamento y vio el becerro y a la gente bailando, se enfureció tanto que arrojó las tablas y las hizo pedazos al pie de la montaña.',NULL),
(@vid,@bid,32,20,'Agarró el becerro que habían hecho , lo tiró al fuego y lo molió hasta hacerlo polvo; luego esparció el polvo sobre el agua y obligó a los israelitas a bebérsela.',NULL),
(@vid,@bid,32,21,'Después Moisés le reclamó a Aarón: “¿ Qué te hizo este pueblo para que los hicieras cometer un pecado tan grave ?”',NULL),
(@vid,@bid,32,22,'Aarón le contestó: “¡ No te enojes conmigo, mi señor! Tú sabes muy bien que esta gente siempre está buscando hacer lo malo .',NULL),
(@vid,@bid,32,23,'Me dijeron: ‘ Haznos dioses que nos guíen, porque no sabemos qué le pasó a ese tal Moisés , el hombre que nos sacó de Egipto ’.',NULL),
(@vid,@bid,32,24,'Y yo les dije: ‘ El que tenga oro , que se lo quite’. Me lo dieron , lo eché al fuego, ¡y salió este becerro !”.',NULL),
(@vid,@bid,32,25,'Moisés vio que el pueblo estaba descontrolado, ya que Aarón los había dejado hacer lo que querían, para burla de sus enemigos;',NULL),
(@vid,@bid,32,26,'así que se paró a la entrada del campamento y gritó: “¡ El que esté del lado de Yahvé, que se una a mí!”. Y todos los hombres de la tribu de Leví se juntaron con él .',NULL),
(@vid,@bid,32,27,'Entonces Moisés les ordenó : “ Así dice Yahvé, el Dios de Israel : ‘¡Pónganse la espada al cinto! Recorran todo el campamento , de un lado a otro , y maten cada uno a su hermano, a su amigo y a su vecino’”.',NULL),
(@vid,@bid,32,28,'Los levitas obedecieron la orden de Moisés , y ese día murieron unas tres mil personas del pueblo .',NULL),
(@vid,@bid,32,29,'Moisés les dijo: “ Hoy ustedes se han consagrado al servicio de Yahvé, pues no les importó matar a sus propios hijos o hermanos; y por eso hoy él los ha bendecido.”',NULL),
(@vid,@bid,32,30,'Al día siguiente , Moisés le dijo al pueblo : “Ustedes han cometido un pecado muy grave . Pero ahora voy a subir a hablar con Yahvé; tal vez logre que los perdone”.',NULL),
(@vid,@bid,32,31,'Moisés regresó a donde estaba Yahvé y le dijo: “¡Ay, Señor ! Este pueblo ha cometido un pecado terrible al hacerse dioses de oro .',NULL),
(@vid,@bid,32,32,'Te ruego que los perdones ; pero si no vas a perdonarlos, ¡bórrame a mí del libro que has escrito !”.',NULL),
(@vid,@bid,32,33,'Yahvé le respondió a Moisés : “Solo borraré de mi libro al que haya pecado contra mí.',NULL),
(@vid,@bid,32,34,'Ahora ve y guía al pueblo hacia el lugar que te dije . Mi ángel irá delante de ti . Pero el día que yo venga a castigar, los castigaré por su pecado ”.',NULL),
(@vid,@bid,32,35,'Y así Yahvé castigó al pueblo con una plaga, por culpa del becerro que obligaron a hacer a Aarón.',NULL),
(@vid,@bid,33,1,'Yahvé le dijo a Moisés : “ Anda , vete de aquí , tú y el pueblo que sacaste de Egipto . Suban hacia la tierra que le prometí a Abraham, a Isaac y a Jacob cuando les dije : ‘ A sus descendientes se la daré ’.',NULL),
(@vid,@bid,33,2,'Yo enviaré un ángel delante de ti, y expulsaré a los cananeos , a los amorreos, a los hititas, a los ferezeos, a los heveos y a los jebuseos .',NULL),
(@vid,@bid,33,3,'Suban a esa tierra donde abundan la leche y la miel . Pero yo no iré en medio de ustedes, porque son un pueblo muy terco, y podría destruirlos en el camino .”',NULL),
(@vid,@bid,33,4,'Al oír el pueblo esta mala noticia, se pusieron de luto y nadie usó sus joyas.',NULL),
(@vid,@bid,33,5,'Porque Yahvé le había dicho a Moisés : “Diles a los israelitas: ‘Ustedes son un pueblo muy terco. Si yo los acompañara por un solo momento , los destruiría. Así que quítense ahora mismo sus joyas, para que yo decida qué voy a hacer con ustedes’”.',NULL),
(@vid,@bid,33,6,'Y así lo hicieron: los israelitas se quitaron sus joyas desde que estuvieron en el monte Horeb en adelante.',NULL),
(@vid,@bid,33,7,'Moisés tenía la costumbre de armar la Carpa de Reunión a buena distancia, fuera del campamento . Todo el que quería consultar a Yahvé tenía que salir a la Carpa de Reunión, fuera del campamento .',NULL),
(@vid,@bid,33,8,'Cuando Moisés salía hacia la Carpa, todo el pueblo se levantaba y se quedaba de pie a la entrada de su propia carpa, y seguían a Moisés con la mirada hasta que él entraba.',NULL),
(@vid,@bid,33,9,'En cuanto Moisés entraba a la Carpa, la columna de nube bajaba y se quedaba a la entrada, y Yahvé hablaba con Moisés .',NULL),
(@vid,@bid,33,10,'Al ver la columna de nube detenida a la entrada de la Carpa, todo el pueblo se ponía de pie y adoraba a Dios, cada uno a la entrada de su propia carpa.',NULL),
(@vid,@bid,33,11,'Yahvé hablaba con Moisés cara a cara , como cuando alguien platica con un amigo . Después Moisés regresaba al campamento , pero su joven ayudante Josué , hijo de Nun , nunca se apartaba de la Carpa.',NULL),
(@vid,@bid,33,12,'Moisés le dijo a Yahvé: “ Mira , tú me has dicho: ‘Lleva a este pueblo a la tierra prometida’, pero no me has dicho a quién vas a enviar conmigo . También me has dicho: ‘ Te conozco por tu nombre y te has ganado mi favor’.',NULL),
(@vid,@bid,33,13,'Así que , si de verdad me he ganado tu favor, te ruego que me enseñes tus caminos ; así podré conocerte y seguir contando con tu favor. Y recuerda que esta nación es tu propio pueblo .”',NULL),
(@vid,@bid,33,14,'Yahvé le respondió: “Mi presencia irá contigo , y yo te daré descanso”.',NULL),
(@vid,@bid,33,15,'Moisés le contestó: “ Si tu presencia no va a ir con nosotros, mejor no nos hagas salir de aquí .',NULL),
(@vid,@bid,33,16,'¿ Cómo va a saber la gente que este pueblo y yo contamos con tu favor, si no vienes con nosotros ? Tu presencia es lo que nos hace diferentes, a mí y a tu pueblo , de todas las demás naciones de la tierra.”',NULL),
(@vid,@bid,33,17,'Y Yahvé le dijo a Moisés : “Voy a hacer esto que me pides, porque te has ganado mi favor y te conozco por tu nombre .”',NULL),
(@vid,@bid,33,18,'Entonces Moisés le rogó: “¡Por favor, déjame ver tu gloria !”',NULL),
(@vid,@bid,33,19,'Yahvé le respondió: “Haré pasar toda mi bondad delante de ti , y pronunciaré mi nombre , Yahvé, en tu presencia . Tendré compasión de quien yo quiera tener compasión , y tendré misericordia de quien yo quiera tener misericordia ”.',NULL),
(@vid,@bid,33,20,'Y agregó: “ Pero no podrás ver mi rostro , porque nadie puede verme y seguir con vida.”',NULL),
(@vid,@bid,33,21,'Yahvé también le dijo: “ Mira , aquí a mi lado hay un lugar sobre la roca ; párate ahí.',NULL),
(@vid,@bid,33,22,'Cuando pase mi gloria , te meteré en una grieta de la roca y te cubriré con mi mano hasta que yo haya pasado .',NULL),
(@vid,@bid,33,23,'Después quitaré mi mano y podrás ver mi espalda, pero mi rostro no lo verás .”',NULL),
(@vid,@bid,34,1,'Yahvé le dijo a Moisés : “Corta dos tablas de piedra iguales a las primeras . Yo voy a escribir en ellas las mismas palabras que estaban en las primeras tablas que rompiste.',NULL),
(@vid,@bid,34,2,'Prepárate para mañana temprano, y sube al monte Sinaí . Allí te presentarás ante mí , en la cima de la montaña.',NULL),
(@vid,@bid,34,3,'Nadie debe subir contigo , ni debe verse a nadie en toda la montaña. Tampoco deben andar pastando ovejas ni vacas frente a la montaña”.',NULL),
(@vid,@bid,34,4,'Moisés cortó dos tablas de piedra iguales a las primeras ; se levantó muy temprano y subió al monte Sinaí tal como Yahvé se lo había ordenado , llevando en sus manos las dos tablas de piedra.',NULL),
(@vid,@bid,34,5,'Yahvé bajó en la nube , se detuvo allí junto a él y pronunció su nombre : Yahvé.',NULL),
(@vid,@bid,34,6,'Yahvé pasó por delante de Moisés, proclamando : “¡Yahvé! ¡Yahvé! Dios compasivo y misericordioso , lento para enojarse y lleno de amor inagotable y fidelidad.',NULL),
(@vid,@bid,34,7,'Que mantiene su amor por mil generaciones, que perdona la maldad , la rebeldía y el pecado ; pero que no deja sin castigo al culpable, sino que castiga la maldad de los padres en los hijos y en los nietos , hasta la tercera y la cuarta generación.”',NULL),
(@vid,@bid,34,8,'De inmediato, Moisés se inclinó hasta tocar el suelo con la frente y lo adoró .',NULL),
(@vid,@bid,34,9,'Y le dijo: “Señor, si de verdad me he ganado tu favor, te ruego que Yahvé nos acompañe. Es cierto que somos un pueblo muy terco, pero perdona nuestra maldad y nuestro pecado , y acéptanos como tu propio pueblo .”',NULL),
(@vid,@bid,34,10,'Yahvé le contestó: “ Mira , voy a hacer un pacto : delante de todo tu pueblo haré milagros tan grandes que jamás se han visto en toda la tierra ni en ninguna otra nación . Y todos los pueblos que te rodean verán lo que Yahvé puede hacer , porque haré cosas asombrosas a través de ti .',NULL),
(@vid,@bid,34,11,'Obedece todo lo que te ordeno hoy . Voy a expulsar de tu presencia a los amorreos, a los cananeos , a los hititas, a los ferezeos, a los heveos y a los jebuseos .',NULL),
(@vid,@bid,34,12,'Ten mucho cuidado de no hacer ningún pacto con los habitantes de la tierra a donde vas, para que no se conviertan en una trampa para ustedes.',NULL),
(@vid,@bid,34,13,'Al contrario, derrumben sus altares , hagan pedazos sus piedras sagradas y corten sus imágenes de la diosa Asera.',NULL),
(@vid,@bid,34,14,'No adoren a ningún otro dios , porque Yahvé, cuyo nombre es Celoso , exige lealtad absoluta.',NULL),
(@vid,@bid,34,15,'“ No hagas ningún pacto con los habitantes del país, porque cuando ellos se prostituyan adorando a sus dioses y ofrezcan sus sacrificios , podrían invitarte y tú terminarías comiendo de sus ofrendas.',NULL),
(@vid,@bid,34,16,'Además, podrías tomar a las hijas de ellos para que se casen con tus hijos , y cuando ellas se prostituyan adorando a sus dioses, harán que tus hijos también se prostituyan tras ellos.',NULL),
(@vid,@bid,34,17,'“ No se harán ídolos de metal fundido.',NULL),
(@vid,@bid,34,18,'“Celebrarán la fiesta del pan sin levadura. Durante siete días comerán pan sin levadura en el mes de Abib, tal como te lo ordené , porque en ese mes salieron de Egipto .',NULL),
(@vid,@bid,34,19,'“ El primer hijo que nazca me pertenece. Lo mismo aplica para las primeras crías machos de tus vacas y ovejas.',NULL),
(@vid,@bid,34,20,'Pero la primera cría de un burro la podrás rescatar entregando un cordero a cambio; si no la rescatas, tendrás que romperle el cuello al burrito. También deberás rescatar a todos tus hijos mayores. Nadie debe presentarse ante mí con las manos vacías .',NULL),
(@vid,@bid,34,21,'“Tienes seis días a la semana para trabajar, pero el séptimo día debes descansar; incluso en las épocas de siembra y de cosecha tendrás que descansar.',NULL),
(@vid,@bid,34,22,'“Celebrarás la fiesta de las Semanas , que es la fiesta de los primeros frutos de la cosecha del trigo , y también la fiesta de la Cosecha al final del año .',NULL),
(@vid,@bid,34,23,'Tres veces al año todos los hombres se presentarán ante el Señor Yahvé, el Dios de Israel .',NULL),
(@vid,@bid,34,24,'Yo expulsaré a las naciones que te rodean y ampliaré tu territorio; y nadie intentará apoderarse de tus tierras cuando subas a presentarte ante Yahvé tu Dios , tres veces al año .',NULL),
(@vid,@bid,34,25,'“ No ofrezcas la sangre de mi sacrificio junto con pan que tenga levadura. Tampoco dejes que sobre nada del sacrificio de la Pascua para la mañana siguiente.',NULL),
(@vid,@bid,34,26,'“Llevarás a la casa de Yahvé tu Dios lo mejor de los primeros frutos de tus cosechas. “ No cocines a un cabrito en la leche de su propia madre”.',NULL),
(@vid,@bid,34,27,'Yahvé le dijo a Moisés : “ Escribe estas palabras , porque en ellas se basa el pacto que he hecho contigo y con Israel ”.',NULL),
(@vid,@bid,34,28,'Moisés se quedó allí con Yahvé durante cuarenta días y cuarenta noches , sin comer ni beber nada . Y escribió en las tablas las palabras del pacto , es decir, los Diez Mandamientos.',NULL),
(@vid,@bid,34,29,'Cuando Moisés bajó del monte Sinaí trayendo en sus manos las dos tablas del pacto, no se había dado cuenta de que la piel de su cara brillaba por haber estado hablando con Dios.',NULL),
(@vid,@bid,34,30,'Al ver Aarón y todos los israelitas que la cara de Moisés brillaba, tuvieron miedo de acercarse a él .',NULL),
(@vid,@bid,34,31,'Pero Moisés los llamó ; entonces Aarón y todos los líderes de la comunidad se acercaron, y Moisés habló con ellos .',NULL),
(@vid,@bid,34,32,'Después se acercaron todos los israelitas, y Moisés les transmitió todos los mandamientos que Yahvé le había dado en el monte Sinaí .',NULL),
(@vid,@bid,34,33,'Cuando Moisés terminó de hablar con ellos , se tapó la cara con un velo.',NULL),
(@vid,@bid,34,34,'Siempre que Moisés entraba a la presencia de Yahvé para hablar con él , se quitaba el velo hasta que salía ; y al salir , les comunicaba a los israelitas lo que Dios le había ordenado .',NULL),
(@vid,@bid,34,35,'Como los israelitas veían que la cara de Moisés brillaba, él volvía a taparse la cara con el velo, hasta que entraba de nuevo a hablar con Dios.',NULL),
(@vid,@bid,35,1,'Moisés reunió a toda la comunidad de los israelitas y les dijo: “ Esto es lo que Yahvé ha ordenado que hagan :',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,35,2,'‘ Tienen seis días en la semana para trabajar , pero el séptimo día será un día sagrado para ustedes, un día de descanso absoluto en honor a Yahvé. Cualquiera que trabaje ese día será condenado a muerte .',NULL),
(@vid,@bid,35,3,'Ese día de descanso ni siquiera deberán prender fuego en ninguna de sus casas’”.',NULL),
(@vid,@bid,35,4,'Moisés le dijo a toda la comunidad de los israelitas: “ Esto es lo que Yahvé ha ordenado :',NULL),
(@vid,@bid,35,5,'‘Recojan de entre ustedes una ofrenda para Yahvé. Todo el que quiera dar de corazón , que traiga como ofrenda a Yahvé lo siguiente: oro , plata , bronce,',NULL),
(@vid,@bid,35,6,'hilo azul, púrpura, escarlata, lino fino, pelo de cabra ,',NULL),
(@vid,@bid,35,7,'pieles de carnero teñidas de rojo, cueros finos, madera de acacia,',NULL),
(@vid,@bid,35,8,'aceite para las lámparas, especias para el aceite de la unción y para el incienso aromático ,',NULL),
(@vid,@bid,35,9,'y piedras de ónice y otras piedras preciosas para engastarlas en el efod y en el pectoral.',NULL),
(@vid,@bid,35,10,'‘ Todos los artesanos expertos que haya entre ustedes deberán venir para hacer todo lo que Yahvé ha ordenado :',NULL),
(@vid,@bid,35,11,'el santuario con su carpa y su cubierta, sus ganchos, sus tablas , sus travesaños, sus postes y sus bases;',NULL),
(@vid,@bid,35,12,'el arca y sus varas, el propiciatorio y el velo que lo protege;',NULL),
(@vid,@bid,35,13,'la mesa con sus varas y todos sus utensilios, y el pan de la Presencia ;',NULL),
(@vid,@bid,35,14,'el candelabro para alumbrar, con sus utensilios, sus lámparas y el aceite para la luz;',NULL),
(@vid,@bid,35,15,'el altar del incienso con sus varas, el aceite de la unción , el incienso aromático , y la cortina para la entrada del santuario;',NULL),
(@vid,@bid,35,16,'el altar de los holocaustos con su rejilla de bronce, sus varas y todos sus utensilios, el lavamanos con su base;',NULL),
(@vid,@bid,35,17,'las cortinas del patio con sus postes y sus bases, y la cortina para la entrada del patio ;',NULL),
(@vid,@bid,35,18,'las estacas del santuario y del patio , junto con sus cuerdas;',NULL),
(@vid,@bid,35,19,'la ropa finamente tejida para oficiar en el Lugar Santo , la ropa sagrada para el sacerdote Aarón y la ropa de sus hijos para que sirvan como sacerdotes ’”.',NULL),
(@vid,@bid,35,20,'Toda la comunidad de los israelitas se retiró de la presencia de Moisés .',NULL),
(@vid,@bid,35,21,'Y todos los que sintieron el deseo en su corazón , y todos los que tuvieron la buena voluntad, regresaron trayendo la ofrenda a Yahvé para la construcción de la Carpa de Reunión, para todos sus servicios y para las ropas sagradas .',NULL),
(@vid,@bid,35,22,'Llegaron hombres y mujeres; todos los que quisieron dar de corazón trajeron broches, aretes, anillos , brazaletes y toda clase de joyas de oro . Todos ellos presentaron una ofrenda de oro a Yahvé.',NULL),
(@vid,@bid,35,23,'Todos los que tenían hilo azul, púrpura, escarlata, lino fino, pelo de cabra , pieles de carnero teñidas de rojo y cueros finos, también los trajeron.',NULL),
(@vid,@bid,35,24,'Todos los que querían ofrecer plata o bronce, lo trajeron como ofrenda para Yahvé; y los que tenían madera de acacia que pudiera servir para la obra , también la trajeron.',NULL),
(@vid,@bid,35,25,'Todas las mujeres expertas en el tejido hilaron con sus propias manos y trajeron lo que habían hecho: hilo azul, púrpura, escarlata y lino fino.',NULL),
(@vid,@bid,35,26,'Y todas las mujeres que sintieron el deseo y tenían la habilidad, hilaron el pelo de cabra .',NULL),
(@vid,@bid,35,27,'Los líderes trajeron las piedras de ónice y las demás piedras preciosas para el efod y el pectoral,',NULL),
(@vid,@bid,35,28,'junto con las especias y el aceite para las lámparas, para el aceite de la unción y para el incienso aromático .',NULL),
(@vid,@bid,35,29,'Todos los israelitas, hombres y mujeres, que sintieron en su corazón el deseo de colaborar con la obra que Yahvé había mandado hacer por medio de Moisés , llevaron su ofrenda voluntaria a Yahvé.',NULL),
(@vid,@bid,35,30,'Moisés les dijo a los israelitas: “Fíjense bien , Yahvé ha escogido personalmente a Bezalel, hijo de Uri y nieto de Hur , de la tribu de Judá .',NULL),
(@vid,@bid,35,31,'Lo ha llenado del Espíritu de Dios y le ha dado gran sabiduría , inteligencia y capacidad para toda clase de trabajos artesanales;',NULL),
(@vid,@bid,35,32,'para diseñar obras de arte y trabajar en oro , plata y bronce;',NULL),
(@vid,@bid,35,33,'para cortar y engastar piedras preciosas, tallar madera y hacer cualquier tipo de trabajo artístico.',NULL),
(@vid,@bid,35,34,'Además, le ha dado el don de enseñar a otros, tanto a él como a Aholiab, hijo de Ahisamac, de la tribu de Dan .',NULL),
(@vid,@bid,35,35,'Los ha llenado de habilidad para hacer toda clase de trabajos: pueden grabar, diseñar, bordar en hilo azul, púrpura, escarlata y lino fino, y también tejer. Son capaces de hacer cualquier labor y de idear toda clase de diseños .',NULL),
(@vid,@bid,36,1,'“ Por lo tanto, Bezalel, Aholiab y todos los demás artesanos expertos a los que Yahvé les ha dado sabiduría e inteligencia , harán todo el trabajo para el santuario , exactamente como Yahvé lo ha ordenado .”',NULL),
(@vid,@bid,36,2,'Moisés mandó llamar a Bezalel, a Aholiab y a todos los artesanos a los que Yahvé les había dado talento, y a todos los que estaban dispuestos a ayudar en la obra .',NULL),
(@vid,@bid,36,3,'Recibieron de Moisés todas las ofrendas que los israelitas habían traído para la construcción del santuario . Y como la gente seguía trayendo ofrendas voluntarias todas las mañanas,',NULL),
(@vid,@bid,36,4,'los artesanos que estaban trabajando en el santuario tuvieron que dejar su labor',NULL),
(@vid,@bid,36,5,'para ir a decirle a Moisés : “La gente está trayendo más de lo necesario para hacer el trabajo que Yahvé ordenó .”',NULL),
(@vid,@bid,36,6,'Entonces Moisés dio una orden , y mandó que se anunciara por todo el campamento : “¡ Que ningún hombre ni mujer prepare más ofrendas para el santuario !”. Así se logró que la gente dejara de llevar cosas,',NULL),
(@vid,@bid,36,7,'porque lo que ya tenían era más que suficiente para terminar todo el trabajo.',NULL),
(@vid,@bid,36,8,'Todos los artesanos expertos hicieron el santuario con diez cortinas de lino fino torcido , de color azul, púrpura y escarlata. Un artista experto les bordó figuras de querubines .',NULL),
(@vid,@bid,36,9,'Todas las cortinas medían lo mismo : trece metros de largo por casi dos metros de ancho.',NULL),
(@vid,@bid,36,10,'Bezalel unió cinco cortinas juntas , y luego unió las otras cinco .',NULL),
(@vid,@bid,36,11,'Hizo unos ojales de hilo azul en la orilla de la cortina que quedaba al extremo del primer conjunto, y lo mismo hizo en la orilla de la cortina del segundo conjunto.',NULL),
(@vid,@bid,36,12,'Hizo cincuenta ojales en la primera cortina , y cincuenta ojales en la orilla de la segunda , de modo que los ojales quedaran frente a frente.',NULL),
(@vid,@bid,36,13,'Hizo también cincuenta ganchos de oro , y con ellos unió las cortinas , de modo que el santuario quedó como una sola pieza.',NULL),
(@vid,@bid,36,14,'Luego hizo once cortinas de pelo de cabra para formar una carpa que cubriera el santuario.',NULL),
(@vid,@bid,36,15,'Todas las once cortinas medían lo mismo: catorce metros de largo por casi dos metros de ancho.',NULL),
(@vid,@bid,36,16,'Unió cinco de estas cortinas por un lado, y las otras seis por el otro.',NULL),
(@vid,@bid,36,17,'Hizo cincuenta ojales en la orilla de la cortina que cerraba el primer conjunto, y otros cincuenta ojales en la orilla de la cortina del segundo conjunto.',NULL),
(@vid,@bid,36,18,'Hizo también cincuenta ganchos de bronce para unir la carpa y que formara una sola pieza.',NULL),
(@vid,@bid,36,19,'Fabricó una cubierta para la carpa con pieles de carnero teñidas de rojo, y otra cubierta de cueros finos para ponerla por encima .',NULL),
(@vid,@bid,36,20,'Hizo unas tablas de madera de acacia para formar las paredes del santuario.',NULL),
(@vid,@bid,36,21,'Cada tabla medía cuatro metros y medio de largo, por setenta centímetros de ancho,',NULL),
(@vid,@bid,36,22,'y tenía dos espigas paralelas para encajar unas con otras. Así hizo todas las tablas para el santuario.',NULL),
(@vid,@bid,36,23,'Para el lado sur del santuario hizo veinte tablas ,',NULL),
(@vid,@bid,36,24,'y fabricó cuarenta bases de plata para ponerlas debajo de las veinte tablas : dos bases debajo de cada tabla para encajar sus dos espigas.',NULL),
(@vid,@bid,36,25,'Para el lado norte del santuario hizo otras veinte tablas ,',NULL),
(@vid,@bid,36,26,'con sus cuarenta bases de plata : dos bases debajo de cada tabla .',NULL),
(@vid,@bid,36,27,'Para la parte trasera del santuario, que daba al oeste, hizo seis tablas .',NULL),
(@vid,@bid,36,28,'Además, hizo dos tablas para las esquinas traseras del santuario.',NULL),
(@vid,@bid,36,29,'Estas tablas estaban unidas por abajo y también por arriba , hasta la primera argolla. Así hizo las dos tablas para las dos esquinas .',NULL),
(@vid,@bid,36,30,'En total eran ocho tablas con sus dieciséis bases de plata : dos bases debajo de cada tabla .',NULL),
(@vid,@bid,36,31,'Hizo unos travesaños de madera de acacia: cinco para las tablas de un lado del santuario,',NULL),
(@vid,@bid,36,32,'cinco para las tablas del otro lado , y cinco para las tablas de la parte trasera, al lado oeste.',NULL),
(@vid,@bid,36,33,'Hizo que el travesaño de en medio pasara por el centro de las tablas , de un extremo al otro .',NULL),
(@vid,@bid,36,34,'Recubrió de oro las tablas , hizo argollas de oro por donde pasarían los travesaños, y también recubrió de oro los travesaños.',NULL),
(@vid,@bid,36,35,'Hizo un velo de lino fino torcido , de color azul, púrpura y escarlata, y un artista experto le bordó querubines .',NULL),
(@vid,@bid,36,36,'Le hizo cuatro postes de madera de acacia y los recubrió de oro . Sus ganchos eran de oro , y les fundió cuatro bases de plata .',NULL),
(@vid,@bid,36,37,'Hizo también una cortina para la entrada de la carpa. Era de lino fino torcido , de color azul, púrpura y escarlata, y estaba finamente bordada.',NULL),
(@vid,@bid,36,38,'Le hizo cinco postes con sus ganchos. Recubrió de oro la parte superior de los postes y sus molduras , pero las cinco bases las hizo de bronce.',NULL),
(@vid,@bid,37,1,'Bezalel hizo el arca de madera de acacia. Medía un metro con quince centímetros de largo, y casi setenta centímetros de ancho y de alto.',NULL),
(@vid,@bid,37,2,'La recubrió de oro puro por dentro y por fuera , y le puso una moldura de oro alrededor .',NULL),
(@vid,@bid,37,3,'Fundió cuatro argollas de oro y se las puso en sus cuatro patas: dos argollas en un lado y dos argollas en el otro .',NULL),
(@vid,@bid,37,4,'Hizo varas de madera de acacia y las recubrió de oro .',NULL),
(@vid,@bid,37,5,'Metió las varas por las argollas a los lados del arca, para poder cargarla.',NULL),
(@vid,@bid,37,6,'Hizo un propiciatorio de oro puro que medía un metro con quince centímetros de largo y casi setenta centímetros de ancho.',NULL),
(@vid,@bid,37,7,'Hizo dos querubines de oro trabajado a martillo y los puso en los dos extremos del propiciatorio:',NULL),
(@vid,@bid,37,8,'un querubín en un extremo y el otro querubín en el otro extremo. Los querubines y el propiciatorio formaban una sola pieza.',NULL),
(@vid,@bid,37,9,'Los querubines tenían las alas extendidas hacia arriba , cubriendo el propiciatorio con ellas . Estaban uno frente al otro, mirando hacia el propiciatorio.',NULL),
(@vid,@bid,37,10,'También hizo la mesa de madera de acacia. Medía casi un metro de largo, cuarenta y cinco centímetros de ancho y casi setenta centímetros de alto.',NULL),
(@vid,@bid,37,11,'La recubrió de oro puro y le puso una moldura de oro alrededor .',NULL),
(@vid,@bid,37,12,'Le hizo un borde a su alrededor del ancho de una mano, y le puso una moldura de oro a todo el borde.',NULL),
(@vid,@bid,37,13,'Fundió cuatro argollas de oro y se las puso en las cuatro esquinas , junto a las cuatro patas.',NULL),
(@vid,@bid,37,14,'Las argollas estaban cerca del borde, para pasar por ellas las varas y así poder cargar la mesa .',NULL),
(@vid,@bid,37,15,'Hizo las varas de madera de acacia y las recubrió de oro para transportar la mesa .',NULL),
(@vid,@bid,37,16,'Hizo de oro puro los utensilios para la mesa : sus platos , sus cucharas , sus tazones y sus jarras para derramar las ofrendas de vino.',NULL),
(@vid,@bid,37,17,'Hizo el candelabro de oro puro . El candelabro y su base fueron trabajados a martillo. Su tronco, sus brazos , sus copas , sus botones y sus flores formaban una sola pieza.',NULL),
(@vid,@bid,37,18,'De los lados del candelabro salían seis brazos : tres brazos de un lado y tres brazos del otro .',NULL),
(@vid,@bid,37,19,'Cada uno de los seis brazos tenía tres copas en forma de flor de almendro, con su botón y su flor .',NULL),
(@vid,@bid,37,20,'El tronco del candelabro tenía cuatro copas en forma de flor de almendro, con sus botones y sus flores :',NULL),
(@vid,@bid,37,21,'un botón debajo del primer par de brazos , un botón debajo del segundo par de brazos , y un botón debajo del tercer par de brazos ; todos formando una sola pieza con el candelabro.',NULL),
(@vid,@bid,37,22,'Los botones y los brazos formaban una sola pieza con el candelabro, y todo fue hecho de oro puro trabajado a martillo.',NULL),
(@vid,@bid,37,23,'Hizo de oro puro sus siete lámparas , sus tijeras para las mechas y sus platillos.',NULL),
(@vid,@bid,37,24,'Usó unos treinta y cuatro kilos de oro puro para hacer el candelabro y todos sus accesorios.',NULL),
(@vid,@bid,37,25,'Hizo el altar del incienso de madera de acacia. Era cuadrado : medía cuarenta y cinco centímetros por lado, y noventa centímetros de alto. Los cuernos del altar formaban una sola pieza con él .',NULL),
(@vid,@bid,37,26,'Lo recubrió de oro puro : la parte de arriba, los cuatro lados y sus cuernos ; y le puso una moldura de oro alrededor .',NULL),
(@vid,@bid,37,27,'Le hizo dos argollas de oro y se las puso debajo de la moldura, en dos lados opuestos, para pasar por ellas las varas y poder cargarlo.',NULL),
(@vid,@bid,37,28,'Hizo las varas de madera de acacia y las recubriró de oro .',NULL),
(@vid,@bid,37,29,'Preparó también el aceite sagrado de la unción y el incienso puro y aromático , mezclándolos con el cuidado de un perfumista.',NULL),
(@vid,@bid,38,1,'Hizo el altar de los holocaustos de madera de acacia. Era cuadrado : medía dos metros y medio de largo por dos metros y medio de ancho, y un metro y medio de alto.',NULL),
(@vid,@bid,38,2,'Le hizo un cuerno en cada una de sus cuatro esquinas , de manera que los cuernos formaban una sola pieza con el altar, y lo recubrió todo de bronce.',NULL),
(@vid,@bid,38,3,'Hizo de bronce todos los utensilios para el altar : los recipientes para las cenizas, las palas, los tazones , los tenedores y los braseros.',NULL),
(@vid,@bid,38,4,'Le hizo una rejilla de bronce en forma de red , y la puso por debajo del borde del altar , de manera que llegaba hasta la mitad.',NULL),
(@vid,@bid,38,5,'Fundió cuatro argollas y las puso en las cuatro esquinas de la rejilla de bronce, para pasar las varas.',NULL),
(@vid,@bid,38,6,'Hizo las varas de madera de acacia y las recubrió de bronce.',NULL),
(@vid,@bid,38,7,'Estas varas se metieron por las argollas a los dos lados del altar para poder transportarlo. El altar era hueco y estaba hecho de tablas .',NULL),
(@vid,@bid,38,8,'Hizo el lavamanos de bronce y su base de bronce, utilizando los espejos de las mujeres que servían a la entrada de la Carpa de Reunión.',NULL),
(@vid,@bid,38,9,'Hizo el patio alrededor del santuario. El lado sur medía cuarenta y cinco metros de largo y tenía cortinas de lino fino torcido .',NULL),
(@vid,@bid,38,10,'Tenía veinte postes apoyados sobre veinte bases de bronce; pero los ganchos y las uniones de los postes eran de plata .',NULL),
(@vid,@bid,38,11,'El lado norte también medía cuarenta y cinco metros de largo, con veinte postes sobre veinte bases de bronce. Los ganchos y las uniones de los postes eran de plata .',NULL),
(@vid,@bid,38,12,'El lado oeste medía veintidós metros y medio de ancho, y tenía cortinas colgadas de diez postes sobre diez bases. Los ganchos y las uniones de los postes eran de plata .',NULL),
(@vid,@bid,38,13,'El lado este , por donde sale el sol, también medía veintidós metros y medio de ancho.',NULL),
(@vid,@bid,38,14,'A un lado de la entrada había cortinas a lo largo de casi siete metros, colgadas de tres postes sobre tres bases.',NULL),
(@vid,@bid,38,15,'Al otro lado también había cortinas a lo largo de casi siete metros, colgadas de tres postes sobre tres bases.',NULL),
(@vid,@bid,38,16,'Todas las cortinas alrededor del patio eran de lino fino torcido .',NULL),
(@vid,@bid,38,17,'Las bases de los postes eran de bronce. Los ganchos y las uniones de los postes eran de plata , y la parte superior de los postes estaba recubierta de plata . Todos los postes del patio estaban unidos con barras de plata .',NULL),
(@vid,@bid,38,18,'La cortina para la entrada del patio estaba finamente bordada en hilo azul, púrpura, escarlata y lino fino torcido . Medía nueve metros de largo y poco más de dos metros de alto, al igual que las cortinas del patio .',NULL),
(@vid,@bid,38,19,'Estaba colgada de cuatro postes sobre cuatro bases de bronce; sus ganchos, sus uniones y el recubrimiento de la parte superior de los postes eran de plata .',NULL),
(@vid,@bid,38,20,'Todas las estacas del santuario y del patio eran de bronce.',NULL),
(@vid,@bid,38,21,'Esta es la lista de los materiales que se usaron para construir el santuario, es decir, el Santuario del Pacto. Moisés ordenó que los levitas , bajo la dirección de Itamar, hijo del sacerdote Aarón, hicieran este inventario.',NULL),
(@vid,@bid,38,22,'Bezalel, hijo de Uri y nieto de Hur , de la tribu de Judá , hizo todo lo que Yahvé le había ordenado a Moisés .',NULL),
(@vid,@bid,38,23,'Su ayudante fue Aholiab, hijo de Ahisamac, de la tribu de Dan . Aholiab era un artesano experto en grabar, diseñar y bordar en hilo azul, púrpura, escarlata y lino fino.',NULL),
(@vid,@bid,38,24,'El total del oro que el pueblo dio como ofrenda y que se usó en la construcción del santuario , fue de unos mil kilos, pesado según el peso oficial del santuario .',NULL),
(@vid,@bid,38,25,'La plata que se recolectó en el censo de la comunidad pesó unos tres mil cuatrocientos kilos, pesada según el peso oficial del santuario .',NULL),
(@vid,@bid,38,26,'Esto equivalía a medio siclo por cabeza (unos cinco gramos), que fue lo que pagó cada uno de los seiscientos tres mil quinientos cincuenta hombres mayores de veinte años que fueron censados.',NULL),
(@vid,@bid,38,27,'De esa plata , se usaron unos tres mil cuatrocientos kilos para fundir las cien bases del santuario y del velo, de manera que cada base pesaba treinta y cuatro kilos.',NULL),
(@vid,@bid,38,28,'Con los veinte kilos de plata restantes, Bezalel hizo los ganchos para los postes, recubrió la parte superior de los postes e hizo las barras para unirlos.',NULL),
(@vid,@bid,38,29,'El bronce que el pueblo dio como ofrenda pesó unos dos mil cuatrocientos kilos.',NULL),
(@vid,@bid,38,30,'Con él se hicieron las bases para la entrada de la Carpa de Reunión, el altar de bronce con su rejilla y todos sus utensilios,',NULL),
(@vid,@bid,38,31,'las bases para el patio y para la entrada del patio , y todas las estacas para el santuario y para el patio .',NULL),
(@vid,@bid,39,1,'Con el hilo azul, púrpura y escarlata se hicieron las ropas finamente tejidas para oficiar en el Lugar Santo . Así hicieron las ropas sagradas para Aarón, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,2,'El efod lo hicieron de hilo de oro , y de lino fino torcido de color azul, púrpura y escarlata.',NULL),
(@vid,@bid,39,3,'Batieron el oro en láminas muy finas y las cortaron en hilos , para bordarlos entre el lino fino azul, púrpura y escarlata. Todo esto fue hecho por artesanos expertos.',NULL),
(@vid,@bid,39,4,'Le hicieron tirantes y los cosieron a las esquinas del efod para poder sujetarlo.',NULL),
(@vid,@bid,39,5,'El cinturón que iba sobre el efod formaba una sola pieza con él , y estaba hecho del mismo material: hilo de oro , y lino fino torcido de color azul, púrpura y escarlata, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,6,'Prepararon las piedras de ónice y las montaron en engastes de oro . Las piedras fueron grabadas con el mismo cuidado que un joyero graba un sello, con los nombres de las tribus de Israel .',NULL),
(@vid,@bid,39,7,'Luego colocaron estas piedras en los tirantes del efod, para que sirvieran de recuerdo constante a favor de los israelitas, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,8,'También hicieron el pectoral, obra de un artesano experto. Lo hicieron con los mismos materiales que el efod: hilo de oro , y lino fino torcido de color azul, púrpura y escarlata.',NULL),
(@vid,@bid,39,9,'Era cuadrado y doble ; medía una cuarta de largo por una cuarta de ancho.',NULL),
(@vid,@bid,39,10,'Le pusieron cuatro hileras de piedras preciosas. En la primera hilera había un rubí, un topacio y un berilo;',NULL),
(@vid,@bid,39,11,'en la segunda hilera, una turquesa, un zafiro y una esmeralda;',NULL),
(@vid,@bid,39,12,'en la tercera hilera, un jacinto, una ágata y una amatista;',NULL),
(@vid,@bid,39,13,'y en la cuarta hilera, un crisólito , un ónice y un jaspe. Todas estas piedras estaban montadas en engastes de oro .',NULL),
(@vid,@bid,39,14,'Eran doce piedras en total, una por cada tribu de Israel , y cada piedra tenía grabado el nombre de una de las doce tribus , como si fuera un sello.',NULL),
(@vid,@bid,39,15,'Para el pectoral hicieron cadenas trenzadas de oro puro , en forma de cordón.',NULL),
(@vid,@bid,39,16,'Hicieron dos engastes de oro y dos argollas de oro , y pusieron las argollas en las dos esquinas superiores del pectoral.',NULL),
(@vid,@bid,39,17,'Luego engancharon las dos cadenas de oro en las dos argollas del pectoral.',NULL),
(@vid,@bid,39,18,'Los otros dos extremos de las cadenas los sujetaron a los dos engastes , y los fijaron a la parte delantera de los tirantes del efod.',NULL),
(@vid,@bid,39,19,'Hicieron otras dos argollas de oro y las pusieron en las dos esquinas inferiores del pectoral, por la parte de adentro que quedaba junto al efod.',NULL),
(@vid,@bid,39,20,'Además , hicieron otras dos argollas de oro y las pusieron en la parte baja de los tirantes del efod, por el frente, cerca de la costura y un poco más arriba del cinturón del efod.',NULL),
(@vid,@bid,39,21,'Amarraron las argollas del pectoral a las argollas del efod con un cordón azul, para que el pectoral quedara ajustado por encima del cinturón y no se separara del efod, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,22,'El manto que se usaba con el efod lo hicieron todo tejido en hilo azul.',NULL),
(@vid,@bid,39,23,'La abertura del manto en el centro era como el cuello de una armadura, y tenía el borde reforzado para que no se rompiera.',NULL),
(@vid,@bid,39,24,'En todo el borde inferior del manto bordaron granadas de hilo azul, púrpura, escarlata y lino torcido .',NULL),
(@vid,@bid,39,25,'Hicieron campanitas de oro puro , y las pusieron intercaladas entre las granadas en todo el borde inferior del manto .',NULL),
(@vid,@bid,39,26,'O sea que todo el borde del manto llevaba una campanita de oro y luego una granada, otra campanita de oro y otra granada, y así sucesivamente. Era para usarse al oficiar como sacerdote, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,27,'Las túnicas para Aarón y para sus hijos las hicieron de lino fino tejido.',NULL),
(@vid,@bid,39,28,'El turbante y los hermosos gorros también los hicieron de lino fino, al igual que la ropa interior de lino torcido .',NULL),
(@vid,@bid,39,29,'El cinturón lo hicieron de lino fino torcido , y de hilo azul, púrpura y escarlata, finamente bordado, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,30,'Finalmente, hicieron la placa de oro puro , que era el distintivo sagrado , y grabaron en ella , como si fuera un sello, las palabras: “ CONSAGRADO A YAHVÉ”.',NULL),
(@vid,@bid,39,31,'Le amarraron un cordón azul para sujetarla por encima del turbante, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,32,'Así se terminó todo el trabajo del santuario de la Carpa de Reunión. Los israelitas hicieron todo exactamente como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,33,'Y le presentaron a Moisés el santuario, la carpa con todos sus utensilios, sus ganchos, sus tablas , sus travesaños, sus postes y sus bases;',NULL),
(@vid,@bid,39,34,'la cubierta de pieles de carnero teñidas de rojo, la cubierta de cueros finos, el velo protector;',NULL),
(@vid,@bid,39,35,'el arca del pacto con sus varas y el propiciatorio;',NULL),
(@vid,@bid,39,36,'la mesa , todos sus utensilios y el pan de la Presencia ;',NULL),
(@vid,@bid,39,37,'el candelabro de oro puro , sus lámparas listas para encenderse, todos sus utensilios y el aceite para alumbrar;',NULL),
(@vid,@bid,39,38,'el altar de oro , el aceite de la unción , el incienso aromático y la cortina para la entrada de la carpa;',NULL),
(@vid,@bid,39,39,'el altar de bronce con su rejilla de bronce, sus varas y todos sus utensilios, el lavamanos y su base;',NULL),
(@vid,@bid,39,40,'las cortinas del patio , sus postes y sus bases, la cortina para la entrada del patio , sus cuerdas, sus estacas y todos los utensilios para el servicio del santuario de la Carpa de Reunión;',NULL),
(@vid,@bid,39,41,'y la ropa finamente tejida para oficiar en el Lugar Santo , es decir, la ropa sagrada para el sacerdote Aarón y la ropa de sus hijos para que sirvieran como sacerdotes .',NULL),
(@vid,@bid,39,42,'Los israelitas hicieron todo el trabajo exactamente como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,39,43,'Moisés revisó todo el trabajo, y vio que lo habían hecho tal como Yahvé lo había ordenado . Y Moisés los bendijo .',NULL),
(@vid,@bid,40,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,40,2,'“El primer día del primer mes levantarás el santuario de la Carpa de Reunión.',NULL),
(@vid,@bid,40,3,'Pondrás allí adentro el arca del pacto, y la ocultarás detrás del velo.',NULL),
(@vid,@bid,40,4,'Meterás la mesa y acomodarás en ella todo lo que lleva encima. Meterás también el candelabro y le encenderás sus lámparas .',NULL),
(@vid,@bid,40,5,'Pondrás el altar de oro para el incienso frente al arca del pacto, y colgarás la cortina a la entrada del santuario.',NULL),
(@vid,@bid,40,6,'“ Pondrás el altar de los holocaustos frente a la entrada del santuario de la Carpa de Reunión.',NULL),
(@vid,@bid,40,7,'Pondrás el lavamanos entre la Carpa de Reunión y el altar , y lo llenarás de agua .',NULL),
(@vid,@bid,40,8,'Armarás el patio alrededor , y colgarás la cortina en la entrada del patio .',NULL),
(@vid,@bid,40,9,'“ Tomarás el aceite de la unción y ungirás el santuario y todo lo que hay adentro. Así consagrarás el santuario y todos sus muebles, y será un lugar sagrado .',NULL),
(@vid,@bid,40,10,'Ungirás también el altar de los holocaustos con todos sus utensilios. Así consagrarás el altar , y será un altar santísimo .',NULL),
(@vid,@bid,40,11,'Ungirás el lavamanos con su base, y lo consagrarás.',NULL),
(@vid,@bid,40,12,'“Llevarás a Aarón y a sus hijos a la entrada de la Carpa de Reunión, y allí los lavarás con agua .',NULL),
(@vid,@bid,40,13,'Vestirás a Aarón con la ropa sagrada, lo ungirás y lo consagrarás para que me sirva como sacerdote.',NULL),
(@vid,@bid,40,14,'Llevarás también a sus hijos y les pondrás las túnicas .',NULL),
(@vid,@bid,40,15,'Los ungirás , tal como ungiste a su padre, para que me sirvan como sacerdotes. Esta unción confirmará que ellos y sus descendientes serán sacerdotes para siempre .”',NULL),
(@vid,@bid,40,16,'Moisés hizo todo esto ; cumplió con todo exactamente como Yahvé se lo había ordenado .',NULL),
(@vid,@bid,40,17,'Y así, el primer día del primer mes del segundo año , se levantó el santuario.',NULL),
(@vid,@bid,40,18,'Moisés levantó el santuario: colocó las bases, puso las tablas , metió los travesaños y paró los postes.',NULL),
(@vid,@bid,40,19,'Extendió la carpa sobre el santuario y le puso la cubierta por encima , tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,20,'Tomó las tablas del pacto y las puso dentro del arca, le colocó las varas al arca y le puso el propiciatorio encima .',NULL),
(@vid,@bid,40,21,'Metió el arca en el santuario, colgó el velo protector y ocultó el arca del pacto, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,22,'Colocó la mesa en la Carpa de Reunión, en el lado norte del santuario, afuera del velo.',NULL),
(@vid,@bid,40,23,'Sobre la mesa acomodó el pan en la presencia de Yahvé, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,24,'Colocó el candelabro en la Carpa de Reunión, frente a la mesa , en el lado sur del santuario.',NULL),
(@vid,@bid,40,25,'Y encendió las lámparas en la presencia de Yahvé, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,26,'Colocó el altar de oro en la Carpa de Reunión, frente al velo,',NULL),
(@vid,@bid,40,27,'y quemó en él incienso aromático , tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,28,'Colgó la cortina a la entrada del santuario.',NULL),
(@vid,@bid,40,29,'Colocó el altar de los holocaustos a la entrada del santuario de la Carpa de Reunión, y ofreció sobre él el holocausto y la ofrenda de grano, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,30,'Colocó el lavamanos entre la Carpa de Reunión y el altar , y lo llenó de agua para lavarse.',NULL),
(@vid,@bid,40,31,'Moisés , Aarón y sus hijos se lavaban allí las manos y los pies .',NULL),
(@vid,@bid,40,32,'Siempre que entraban a la Carpa de Reunión o se acercaban al altar , se lavaban , tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,40,33,'Finalmente, levantó el patio alrededor del santuario y del altar , y colgó la cortina en la entrada del patio . De esta manera, Moisés terminó la obra .',NULL),
(@vid,@bid,40,34,'Entonces la nube cubrió la Carpa de Reunión, y la gloria de Yahvé llenó el santuario.',NULL),
(@vid,@bid,40,35,'Moisés no podía entrar a la Carpa de Reunión, porque la nube se había posado sobre ella y la gloria de Yahvé llenaba el santuario.',NULL),
(@vid,@bid,40,36,'En todos sus viajes, cuando la nube se levantaba de encima del santuario, los israelitas levantaban el campamento y se ponían en marcha.',NULL),
(@vid,@bid,40,37,'Pero si la nube no se levantaba, ellos no se movían hasta el día en que la nube se levantaba.',NULL),
(@vid,@bid,40,38,'Porque durante todos sus viajes, la nube de Yahvé estaba sobre el santuario de día , y de noche había fuego en la nube , para que todos los israelitas pudieran verla.',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'Yahvé llamó a Moisés y le habló desde la Tienda del Encuentro, diciendo :',NULL),
(@vid,@bid,1,2,'“ Habla a los hijos de Israel y diles : ‘ Cuando alguno de ustedes presente una ofrenda a Yahvé, podrá ofrecer animales de sus ganados , ya sea de las vacas o de las ovejas .',NULL),
(@vid,@bid,1,3,'“‘ Si su ofrenda es un holocausto de las vacas , ofrecerá un macho sin defecto. Lo presentará a la entrada de la Tienda del Encuentro, para que sea aceptado ante Yahvé.',NULL),
(@vid,@bid,1,4,'Pondrá su mano sobre la cabeza de la víctima, y Yahvé se la aceptará para hacer expiación por él .',NULL),
(@vid,@bid,1,5,'Entonces degollará el becerro delante de Yahvé. Los hijos de Aarón, los sacerdotes , presentarán la sangre y la rociarán por todos los lados del altar que está a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,1,6,'Después desollará el animal y lo cortará en pedazos.',NULL),
(@vid,@bid,1,7,'Los hijos del sacerdote Aarón encenderán el fuego en el altar y acomodarán la leña sobre el fuego.',NULL),
(@vid,@bid,1,8,'Luego los hijos de Aarón, los sacerdotes , acomodarán los pedazos, junto con la cabeza y la grasa, sobre la leña que arde en el altar .',NULL),
(@vid,@bid,1,9,'El que ofrece la víctima lavará con agua las entrañas y las patas, y el sacerdote lo quemará todo en el altar . Es un holocausto , una ofrenda quemada de aroma agradable para Yahvé.',NULL),
(@vid,@bid,1,10,'“Si su ofrenda para el holocausto es del rebaño , de las ovejas o de las cabras , ofrecerá un macho sin defecto.',NULL),
(@vid,@bid,1,11,'Lo degollará al lado norte del altar , delante de Yahvé. Los hijos de Aarón, los sacerdotes , rociarán la sangre por todos los lados del altar .',NULL),
(@vid,@bid,1,12,'Luego lo cortará en pedazos, con la cabeza y la grasa, y el sacerdote los acomodará sobre la leña que arde en el altar .',NULL),
(@vid,@bid,1,13,'Pero el que ofrece la víctima lavará las entrañas y las patas con agua . El sacerdote presentará todo el animal y lo quemará en el altar . Es un holocausto , una ofrenda quemada de aroma agradable para Yahvé.',NULL),
(@vid,@bid,1,14,'“Si su ofrenda para Yahvé es un holocausto de aves , ofrecerá tórtolas o pichones.',NULL),
(@vid,@bid,1,15,'El sacerdote llevará el ave al altar , le cortará la cabeza y la quemará en el altar . La sangre será exprimida contra la pared del altar .',NULL),
(@vid,@bid,1,16,'Le quitará el buche y las plumas , y los echará al lado oriental del altar , en el lugar de las cenizas.',NULL),
(@vid,@bid,1,17,'La abrirá por las alas , pero sin llegar a dividirla. El sacerdote la quemará en el altar , sobre la leña que está en el fuego. Es un holocausto , una ofrenda quemada de aroma agradable para Yahvé.',NULL),
(@vid,@bid,2,1,'“‘ Cuando alguien presente una ofrenda de cereal a Yahvé, su ofrenda será de harina fina. Derramará aceite sobre ella y le pondrá incienso .',NULL),
(@vid,@bid,2,2,'La llevará a los hijos de Aarón, los sacerdotes . El sacerdote tomará un puñado de la harina fina con el aceite y todo el incienso , y lo quemará en el altar como un memorial. Es una ofrenda quemada de aroma agradable para Yahvé.',NULL),
(@vid,@bid,2,3,'El resto de la ofrenda será para Aarón y sus hijos . Es una parte muy santa de las ofrendas quemadas para Yahvé.',NULL),
(@vid,@bid,2,4,'“‘ Cuando presentes una ofrenda de cereal cocida al horno , será de harina fina: tortas sin levadura amasadas con aceite , u hojuelas sin levadura untadas con aceite .',NULL),
(@vid,@bid,2,5,'Si tu ofrenda es de cereal cocido a la plancha, será de harina fina sin levadura, amasada con aceite .',NULL),
(@vid,@bid,2,6,'La partirás en pedazos y derramarás aceite sobre ella . Es una ofrenda de cereal.',NULL),
(@vid,@bid,2,7,'Si tu ofrenda es de cereal cocido en sartén, será de harina fina con aceite .',NULL),
(@vid,@bid,2,8,'Llevarás a Yahvé la ofrenda que se prepare con estos ingredientes. Se la entregarás al sacerdote , y él la llevará al altar .',NULL),
(@vid,@bid,2,9,'El sacerdote tomará de la ofrenda la porción memorial y la quemará en el altar . Es una ofrenda quemada de aroma agradable para Yahvé.',NULL),
(@vid,@bid,2,10,'El resto de la ofrenda de cereal será para Aarón y sus hijos . Es una parte muy santa de las ofrendas quemadas para Yahvé.',NULL),
(@vid,@bid,2,11,'“‘ Ninguna ofrenda de cereal que presenten a Yahvé se preparará con levadura , porque no deben quemar levadura ni miel como ofrenda para Yahvé.',NULL),
(@vid,@bid,2,12,'Podrán presentarlas a Yahvé como ofrenda de primicias , pero no se quemarán en el altar como aroma agradable.',NULL),
(@vid,@bid,2,13,'Sazonarás con sal todas tus ofrendas de cereal. No permitas que falte en tu ofrenda la sal del pacto de tu Dios. En todas tus ofrendas debes presentar sal .',NULL),
(@vid,@bid,2,14,'“‘Si presentas a Yahvé una ofrenda de primicias, ofrecerás grano tierno tostado al fuego o grano desmenuzado de espigas frescas.',NULL),
(@vid,@bid,2,15,'Le añadirás aceite y le pondrás incienso . Es una ofrenda de cereal.',NULL),
(@vid,@bid,2,16,'El sacerdote quemará , como memorial, parte del grano desmenuzado y del aceite , junto con todo el incienso . Es una ofrenda quemada para Yahvé.',NULL),
(@vid,@bid,3,1,'“‘ Si su ofrenda es un sacrificio de paz, y la toma del ganado vacuno , ya sea macho o hembra , la presentará sin defecto delante de Yahvé.',NULL),
(@vid,@bid,3,2,'Pondrá su mano sobre la cabeza de la ofrenda y la degollará a la entrada de la Tienda del Encuentro. Los hijos de Aarón, los sacerdotes , rociarán la sangre por todos los lados del altar .',NULL),
(@vid,@bid,3,3,'Del sacrificio de paz, presentará como ofrenda quemada a Yahvé la grasa que cubre las entrañas y toda la grasa que está sobre ellas ,',NULL),
(@vid,@bid,3,4,'los dos riñones con la grasa que los cubre cerca de los lomos, y la parte superior del hígado , que quitará junto con los riñones .',NULL),
(@vid,@bid,3,5,'Los hijos de Aarón quemarán esto en el altar , sobre el holocausto que está sobre la leña en el fuego. Es una ofrenda quemada de aroma agradable para Yahvé.',NULL),
(@vid,@bid,3,6,'“‘Si su ofrenda para un sacrificio de paz a Yahvé es del rebaño de ovejas o cabras, ya sea macho o hembra , la presentará sin defecto.',NULL),
(@vid,@bid,3,7,'Si ofrece un cordero , lo presentará delante de Yahvé.',NULL),
(@vid,@bid,3,8,'Pondrá su mano sobre la cabeza de su ofrenda y la degollará ante la Tienda del Encuentro. Los hijos de Aarón rociarán la sangre por todos los lados del altar .',NULL),
(@vid,@bid,3,9,'Del sacrificio de paz presentará como ofrenda quemada a Yahvé la grasa: la cola entera , la cual cortará cerca del espinazo; la grasa que cubre las entrañas y toda la grasa que está sobre ellas ,',NULL),
(@vid,@bid,3,10,'los dos riñones con la grasa que los cubre cerca de los lomos, y la parte superior del hígado , que quitará junto con los riñones .',NULL),
(@vid,@bid,3,11,'El sacerdote quemará esto en el altar como alimento, una ofrenda quemada para Yahvé.',NULL),
(@vid,@bid,3,12,'“‘ Si su ofrenda es una cabra , la presentará delante de Yahvé.',NULL),
(@vid,@bid,3,13,'Pondrá su mano sobre la cabeza del animal y lo degollará ante la Tienda del Encuentro. Los hijos de Aarón rociarán la sangre por todos los lados del altar .',NULL),
(@vid,@bid,3,14,'De esa ofrenda presentará , como ofrenda quemada a Yahvé, la grasa que cubre las entrañas y toda la grasa que está sobre ellas ,',NULL),
(@vid,@bid,3,15,'los dos riñones con la grasa que los cubre cerca de los lomos, y la parte superior del hígado , que quitará junto con los riñones .',NULL),
(@vid,@bid,3,16,'El sacerdote quemará esto en el altar . Es alimento, una ofrenda quemada de aroma agradable. Toda la grasa le pertenece a Yahvé.',NULL),
(@vid,@bid,3,17,'“‘Este será un estatuto perpetuo para todas sus generaciones , dondequiera que vivan: No deberán comer ninguna grasa ni ninguna sangre ’”.',NULL),
(@vid,@bid,4,1,'Yahvé le dijo a Moisés :',NULL),
(@vid,@bid,4,2,'“ Diles a los hijos de Israel : ‘ Si alguien peca involuntariamente contra cualquiera de los mandamientos de Yahvé, haciendo algo que no está permitido hacer , se procederá así :',NULL),
(@vid,@bid,4,3,'Si el sacerdote ungido peca y con ello hace culpable al pueblo , ofrecerá a Yahvé un becerro sin defecto como ofrenda por su pecado .',NULL),
(@vid,@bid,4,4,'Llevará el becerro a la entrada de la Tienda del Encuentro, ante Yahvé, pondrá su mano sobre la cabeza del animal y lo degollará delante de Yahvé.',NULL),
(@vid,@bid,4,5,'Luego el sacerdote ungido tomará un poco de la sangre del becerro y la llevará a la Tienda del Encuentro.',NULL),
(@vid,@bid,4,6,'Mojará su dedo en la sangre y la rociará siete veces delante de Yahvé, frente al velo del santuario .',NULL),
(@vid,@bid,4,7,'El sacerdote pondrá también un poco de la sangre en los cuernos del altar del incienso aromático que está en la Tienda del Encuentro, delante de Yahvé, y derramará el resto de la sangre del becerro al pie del altar del holocausto , que está a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,4,8,'Le quitará toda la grasa al becerro de la ofrenda por el pecado : la grasa que cubre las entrañas y la que está sobre ellas ,',NULL),
(@vid,@bid,4,9,'los dos riñones con la grasa que los cubre cerca de los lomos, y la parte superior del hígado , que quitará junto con los riñones ,',NULL),
(@vid,@bid,4,10,'tal como se le quita al toro del sacrificio de paz. El sacerdote los quemará en el altar del holocausto .',NULL),
(@vid,@bid,4,11,'Pero la piel del becerro y toda su carne , con su cabeza , sus patas, sus entrañas y su excremento,',NULL),
(@vid,@bid,4,12,'es decir, todo el resto del becerro , lo sacará fuera del campamento a un lugar limpio , donde se echan las cenizas, y allí lo quemará sobre la leña . Lo quemará donde se echan las cenizas.',NULL),
(@vid,@bid,4,13,'“‘ Si es toda la comunidad de Israel la que peca por error, sin darse cuenta de que han hecho algo que Yahvé prohibió, son culpables.',NULL),
(@vid,@bid,4,14,'Cuando se den cuenta del pecado que cometieron , la comunidad ofrecerá un becerro como ofrenda por el pecado y lo llevará ante la Tienda del Encuentro.',NULL),
(@vid,@bid,4,15,'Los ancianos de la comunidad pondrán sus manos sobre la cabeza del becerro delante de Yahvé, y el animal será degollado delante de Yahvé.',NULL),
(@vid,@bid,4,16,'El sacerdote ungido llevará un poco de la sangre del becerro a la Tienda del Encuentro.',NULL),
(@vid,@bid,4,17,'Mojará su dedo en la sangre y la rociará siete veces delante de Yahvé, frente al velo.',NULL),
(@vid,@bid,4,18,'Pondrá un poco de la sangre en los cuernos del altar que está ante Yahvé, en la Tienda del Encuentro, y derramará el resto de la sangre al pie del altar del holocausto , a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,4,19,'Luego le quitará toda la grasa y la quemará en el altar .',NULL),
(@vid,@bid,4,20,'Hará con este becerro lo mismo que hizo con el becerro de la ofrenda por el pecado . Así el sacerdote hará expiación por ellos , y serán perdonados.',NULL),
(@vid,@bid,4,21,'Después sacará el becerro fuera del campamento y lo quemará como quemó el primer becerro . Es la ofrenda por el pecado de la comunidad.',NULL),
(@vid,@bid,4,22,'“‘Cuando un jefe peque y por error haga algo que Yahvé su Dios ha prohibido, será culpable.',NULL),
(@vid,@bid,4,23,'En cuanto se le haga saber el pecado que cometió , presentará como ofrenda un macho cabrío sin defecto.',NULL),
(@vid,@bid,4,24,'Pondrá su mano sobre la cabeza del macho cabrío y lo degollará en el lugar donde se degüellan los animales para el holocausto , delante de Yahvé. Es una ofrenda por el pecado .',NULL),
(@vid,@bid,4,25,'El sacerdote tomará con su dedo un poco de la sangre de la ofrenda y la pondrá en los cuernos del altar del holocausto . El resto de la sangre la derramará al pie del altar del holocausto .',NULL),
(@vid,@bid,4,26,'Quemará toda la grasa en el altar , como hizo con la grasa del sacrificio de paz. Así el sacerdote hará expiación por el pecado del jefe, y este será perdonado.',NULL),
(@vid,@bid,4,27,'“‘ Si alguien del pueblo peca por error, haciendo algo que Yahvé prohibió, será culpable.',NULL),
(@vid,@bid,4,28,'Cuando se le haga saber el pecado que cometió , presentará como ofrenda por su pecado una cabra sin defecto.',NULL),
(@vid,@bid,4,29,'Pondrá su mano sobre la cabeza de la ofrenda y la degollará en el lugar de los holocaustos .',NULL),
(@vid,@bid,4,30,'El sacerdote tomará con su dedo un poco de la sangre y la pondrá en los cuernos del altar del holocausto , y derramará el resto de la sangre al pie del altar .',NULL),
(@vid,@bid,4,31,'Le quitará toda la grasa, tal como se le quita al sacrificio de paz, y el sacerdote la quemará en el altar como aroma agradable para Yahvé. Así el sacerdote hará expiación por esa persona, y será perdonada.',NULL),
(@vid,@bid,4,32,'“‘Si ofrece un cordero como ofrenda por el pecado , debe ser una hembra sin defecto.',NULL),
(@vid,@bid,4,33,'Pondrá su mano sobre la cabeza de la ofrenda y la degollará como ofrenda por el pecado en el lugar donde se degüellan los animales para el holocausto .',NULL),
(@vid,@bid,4,34,'El sacerdote tomará con su dedo un poco de la sangre de la ofrenda y la pondrá en los cuernos del altar del holocausto , y derramará el resto de la sangre al pie del altar .',NULL),
(@vid,@bid,4,35,'Le quitará toda la grasa, tal como se le quita la grasa al cordero del sacrificio de paz. El sacerdote la quemará en el altar , sobre las ofrendas quemadas para Yahvé. Así el sacerdote hará expiación por el pecado que esa persona cometió , y será perdonada.',NULL),
(@vid,@bid,5,1,'“‘ Si alguien peca al escuchar un juramento público para testificar, siendo él testigo de lo que ha visto o sabido, y no lo denuncia, entonces cargará con su culpa.',NULL),
(@vid,@bid,5,2,'“‘ O si alguien toca algo impuro, ya sea el cadáver de un animal salvaje, o el cadáver de un animal doméstico, o el cadáver de un reptil impuro, aunque no se dé cuenta de ello , si se contamina, entonces será culpable.',NULL),
(@vid,@bid,5,3,'“‘ O si toca la impureza de un ser humano, cualquier impureza con la que pueda contaminarse, y no se da cuenta; cuando lo sepa , entonces será culpable.',NULL),
(@vid,@bid,5,4,'“‘ O si alguien jura a la ligera con sus labios para hacer el mal o para hacer el bien , cualquier cosa que una persona pueda decir sin pensar mediante un juramento , y le pasa inadvertido; cuando se dé cuenta, entonces será culpable de una de estas cosas .',NULL),
(@vid,@bid,5,5,'Cuando sea culpable de una de estas cosas, deberá confesar aquello en lo que ha pecado ;',NULL),
(@vid,@bid,5,6,'y le traerá a Yahvé su ofrenda por la culpa debido al pecado que cometió : una hembra del rebaño , oveja o cabra , como ofrenda por el pecado ; y el sacerdote hará expiación por él respecto a su pecado .',NULL),
(@vid,@bid,5,7,'“‘ Si no le alcanza para comprar un cordero , entonces traerá a Yahvé, como ofrenda por la culpa del pecado que cometió , dos tórtolas o dos pichones; uno para la ofrenda por el pecado y el otro para el holocausto .',NULL),
(@vid,@bid,5,8,'Los llevará al sacerdote , quien ofrecerá primero el que es para la ofrenda por el pecado . Le romperá el cuello a la altura de la cabeza , pero sin separar la cabeza por completo.',NULL),
(@vid,@bid,5,9,'Rociará un poco de la sangre de la ofrenda por el pecado a un lado del altar , y el resto de la sangre se exprimirá al pie del altar . Es una ofrenda por el pecado .',NULL),
(@vid,@bid,5,10,'Ofrecerá la segunda ave como holocausto , conforme al reglamento. Así el sacerdote hará expiación por el pecado que cometió , y la persona será perdonada.',NULL),
(@vid,@bid,5,11,'“‘ Pero si no tiene recursos para las dos tórtolas o los dos pichones, entonces traerá como ofrenda por su pecado la décima parte de un efa de harina fina como ofrenda por el pecado . No le pondrá aceite ni incienso , porque es una ofrenda por el pecado .',NULL),
(@vid,@bid,5,12,'La llevará al sacerdote , y el sacerdote tomará un puñado de la harina como porción memorial, y la quemará en el altar , sobre las ofrendas a Yahvé hechas por fuego. Es una ofrenda por el pecado .',NULL),
(@vid,@bid,5,13,'Así el sacerdote hará expiación por el pecado que esa persona haya cometido en cualquiera de estas cosas, y será perdonada. El resto de la harina será para el sacerdote , como en la ofrenda de cereal’”.',NULL),
(@vid,@bid,5,14,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,5,15,'“ Si alguien comete una falta y peca por error en contra de las cosas sagradas de Yahvé, traerá a Yahvé su ofrenda por la culpa: un carnero sin defecto del rebaño , tasado en siclos de plata según la medida del santuario , como ofrenda por la culpa.',NULL),
(@vid,@bid,5,16,'Deberá restituir lo que haya defraudado de las cosas sagradas , le añadirá una quinta parte y se lo dará al sacerdote . El sacerdote hará expiación por él con el carnero de la ofrenda por la culpa, y será perdonado.',NULL),
(@vid,@bid,5,17,'“ Si alguien peca haciendo algo que Yahvé ha prohibido, aunque no lo sepa , es culpable y cargará con su culpa.',NULL),
(@vid,@bid,5,18,'Llevará al sacerdote un carnero sin defecto del rebaño , tasado según tu valoración, como ofrenda por la culpa. El sacerdote hará expiación por el error que esa persona cometió sin saberlo , y será perdonada.',NULL),
(@vid,@bid,5,19,'Es una ofrenda por la culpa, pues verdaderamente resultó culpable ante Yahvé”.',NULL),
(@vid,@bid,6,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,6,2,'“ Si alguien peca y comete una falta contra Yahvé engañando a su prójimo en cuestión de un depósito, un objeto en custodia o un robo, o si ha extorsionado a su prójimo,',NULL),
(@vid,@bid,6,3,'o si encuentra algo perdido y miente al respecto, y jura en falso por cualquiera de estas cosas en las que suele pecar el ser humano,',NULL),
(@vid,@bid,6,4,'si ha pecado y es culpable, deberá devolver lo que robó, o lo que obtuvo por extorsión, o el depósito que se le confió, o la cosa perdida que encontró,',NULL),
(@vid,@bid,6,5,'o cualquier cosa sobre la cual haya jurado en falso. La restituirá por completo y le añadirá una quinta parte. Se lo devolverá al dueño el mismo día que presente su ofrenda por la culpa.',NULL),
(@vid,@bid,6,6,'Y como su ofrenda por la culpa a Yahvé, le llevará al sacerdote un carnero sin defecto del rebaño, tasado según tu valoración.',NULL),
(@vid,@bid,6,7,'El sacerdote hará expiación por él delante de Yahvé, y será perdonado por cualquier cosa que haya hecho y que lo haya hecho culpable”.',NULL),
(@vid,@bid,6,8,'Yahvé le habló a Moisés y le dijo:',NULL),
(@vid,@bid,6,9,'“Dales esta orden a Aarón y a sus hijos : ‘Esta es la ley del holocausto: el holocausto deberá quedarse sobre el hogar del altar toda la noche, hasta la mañana, y el fuego del altar debe mantenerse encendido.',NULL),
(@vid,@bid,6,10,'El sacerdote se pondrá su túnica de lino y su ropa interior de lino; luego recogerá las cenizas que queden en el altar cuando el fuego haya consumido el holocausto, y las pondrá a un lado del altar.',NULL),
(@vid,@bid,6,11,'Después se cambiará de ropa y llevará las cenizas fuera del campamento a un lugar ceremonialmente limpio.',NULL),
(@vid,@bid,6,12,'El fuego del altar debe mantenerse encendido; no se debe apagar. Cada mañana el sacerdote le pondrá más leña, acomodará el holocausto encima y quemará ahí la grasa de los sacrificios de paz.',NULL),
(@vid,@bid,6,13,'El fuego debe mantenerse encendido en el altar continuamente ; no debe apagarse.',NULL),
(@vid,@bid,6,14,'“‘ Esta es la ley para la ofrenda de cereal: los hijos de Aarón la presentarán ante Yahvé, frente al altar.',NULL),
(@vid,@bid,6,15,'El sacerdote tomará un puñado de la harina fina de la ofrenda, con su aceite y todo el incienso que está sobre ella, y lo quemará en el altar como aroma agradable, como su porción memorial para Yahvé.',NULL),
(@vid,@bid,6,16,'Lo que quede de la ofrenda lo comerán Aarón y sus hijos. Deberá comerse sin levadura en un lugar sagrado; lo comerán en el atrio de la Tienda del Encuentro.',NULL),
(@vid,@bid,6,17,'No se horneará con levadura. Se lo he dado a ellos como su porción de mis ofrendas hechas por fuego. Es una parte muy santa, igual que la ofrenda por el pecado y la ofrenda por la culpa.',NULL),
(@vid,@bid,6,18,'Cualquier varón de los descendientes de Aarón podrá comer de ella . Es un estatuto perpetuo para todas sus generaciones, en cuanto a las ofrendas hechas por fuego a Yahvé. Todo lo que toque estas ofrendas quedará consagrado ’”.',NULL),
(@vid,@bid,6,19,'Yahvé le habló a Moisés y le dijo:',NULL),
(@vid,@bid,6,20,'“ Esta es la ofrenda que Aarón y sus hijos presentarán a Yahvé el día en que sean ungidos: la décima parte de un efa de harina fina como ofrenda regular de cereal, la mitad por la mañana y la otra mitad por la tarde.',NULL),
(@vid,@bid,6,21,'Se preparará en una plancha con aceite. La llevarás bien mezclada, y presentarás la ofrenda de cereal en pedazos cocidos, como un aroma agradable a Yahvé.',NULL),
(@vid,@bid,6,22,'La ofrecerá el sacerdote ungido que tome el lugar de Aarón de entre sus hijos. Como un estatuto perpetuo, se quemará por completo para Yahvé.',NULL),
(@vid,@bid,6,23,'Toda ofrenda de cereal de un sacerdote debe quemarse por completo; no se comerá”.',NULL),
(@vid,@bid,6,24,'Yahvé le habló a Moisés y le dijo:',NULL),
(@vid,@bid,6,25,'“Diles a Aarón y a sus hijos: ‘Esta es la ley para el sacrificio por el pecado: la víctima por el pecado se degollará ante Yahvé en el mismo lugar donde se degüella el holocausto. Es una ofrenda muy santa.',NULL),
(@vid,@bid,6,26,'El sacerdote que la ofrezca por el pecado la comerá. Deberá comerse en un lugar sagrado, en el atrio de la Tienda del Encuentro.',NULL),
(@vid,@bid,6,27,'Todo lo que toque su carne quedará consagrado. Si la sangre salpica la ropa, lavarás la ropa manchada en un lugar santo.',NULL),
(@vid,@bid,6,28,'La olla de barro en la que se haya cocido la carne deberá romperse; pero si se coció en una olla de bronce, esta deberá fregarse y enjuagarse con agua.',NULL),
(@vid,@bid,6,29,'Cualquier varón de entre los sacerdotes podrá comer de esta carne. Es una ofrenda muy santa.',NULL),
(@vid,@bid,6,30,'Pero no se comerá ninguna ofrenda por el pecado si parte de su sangre se llevó al interior de la Tienda del Encuentro para hacer expiación en el Lugar Santo. Esa carne deberá quemarse en el fuego.',NULL),
(@vid,@bid,7,1,'“‘ Esta es la ley de la ofrenda por la culpa: es muy santa .',NULL),
(@vid,@bid,7,2,'La víctima de la ofrenda por la culpa se degollará en el lugar donde se degüella el holocausto , y su sangre se rociará por todos los lados del altar .',NULL),
(@vid,@bid,7,3,'Se ofrecerá toda su grasa: la cola gorda, la grasa que cubre las entrañas,',NULL),
(@vid,@bid,7,4,'los dos riñones con la grasa que los cubre cerca de los lomos, y la parte superior del hígado , que se quitará junto con los riñones .',NULL),
(@vid,@bid,7,5,'El sacerdote los quemará en el altar como ofrenda hecha por fuego a Yahvé. Es una ofrenda por la culpa.',NULL),
(@vid,@bid,7,6,'Cualquier varón de la familia sacerdotal podrá comer de ella . Deberá comerse en un lugar sagrado , pues es muy santa .',NULL),
(@vid,@bid,7,7,'“‘La ofrenda por el pecado y la ofrenda por la culpa tienen la misma ley . La carne será para el sacerdote que haga la expiación con ella.',NULL),
(@vid,@bid,7,8,'El sacerdote que ofrezca el holocausto por alguien se quedará con la piel del animal ofrecido.',NULL),
(@vid,@bid,7,9,'Toda ofrenda de cereal que se hornee, y toda la que se prepare en sartén o en plancha, será para el sacerdote que la ofrezca.',NULL),
(@vid,@bid,7,10,'Pero toda ofrenda de cereal, ya sea amasada con aceite o seca, se repartirá por igual entre todos los hijos de Aarón.',NULL),
(@vid,@bid,7,11,'“‘ Esta es la ley del sacrificio de paz que se presenta a Yahvé:',NULL),
(@vid,@bid,7,12,'Si se ofrece en acción de gracias, se presentarán con el sacrificio tortas sin levadura amasadas con aceite , hojuelas sin levadura untadas con aceite , y tortas de harina fina bien mezcladas con aceite .',NULL),
(@vid,@bid,7,13,'Además de las tortas sin levadura, se presentará pan con levadura como parte de su ofrenda , junto con su sacrificio de paz en acción de gracias.',NULL),
(@vid,@bid,7,14,'De cada clase de ofrenda se presentará una porción como ofrenda especial para Yahvé; será para el sacerdote que rocíe la sangre de los sacrificios de paz.',NULL),
(@vid,@bid,7,15,'La carne del sacrificio de paz en acción de gracias debe comerse el mismo día que se ofrezca. No se debe dejar nada para la mañana siguiente.',NULL),
(@vid,@bid,7,16,'“‘Pero si el sacrificio que ofrece es para cumplir una promesa o es una ofrenda voluntaria , la carne se comerá el día en que ofrezca el sacrificio , y lo que sobre se podrá comer al día siguiente .',NULL),
(@vid,@bid,7,17,'Sin embargo, si queda algo de carne del sacrificio para el tercer día , deberá quemarse en el fuego.',NULL),
(@vid,@bid,7,18,'Si alguien llega a comer la carne del sacrificio de paz al tercer día , la ofrenda no será aceptada ni se le tomará en cuenta al que la ofreció . Será considerada algo asqueroso, y el que la coma cargará con su culpa.',NULL),
(@vid,@bid,7,19,'“‘ La carne que toque cualquier cosa impura no deberá comerse; se quemará en el fuego. En cuanto a la demás carne , podrá comerla cualquiera que esté ceremonialmente limpio .',NULL),
(@vid,@bid,7,20,'Pero si alguien que está en estado de impureza come de la carne del sacrificio de paz que le pertenece a Yahvé, esa persona será eliminada de su pueblo .',NULL),
(@vid,@bid,7,21,'Si alguien toca cualquier cosa impura, ya sea impureza humana, un animal impuro o cualquier cosa repulsiva e impura, y luego come de la carne del sacrificio de paz que le pertenece a Yahvé, esa persona será eliminada de su pueblo ’”.',NULL),
(@vid,@bid,7,22,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,7,23,'“ Diles a los hijos de Israel : No deben comer nada de grasa de toros, ovejas o cabras .',NULL),
(@vid,@bid,7,24,'La grasa de un animal que muere por sí solo, o de uno despedazado por las fieras, podrá usarse para cualquier otro propósito, pero de ninguna manera deberán comerla.',NULL),
(@vid,@bid,7,25,'Todo el que coma la grasa de un animal del cual se presenta una ofrenda quemada a Yahvé, será eliminado de su pueblo .',NULL),
(@vid,@bid,7,26,'Y dondequiera que ustedes vivan, no deben comer la sangre de ningún ave ni de ningún animal.',NULL),
(@vid,@bid,7,27,'Cualquiera que coma sangre será eliminado de su pueblo ”.',NULL),
(@vid,@bid,7,28,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,7,29,'“ Diles a los hijos de Israel : ‘ El que presente a Yahvé su sacrificio de paz, debe llevarle a Yahvé una parte de ese sacrificio como ofrenda .',NULL),
(@vid,@bid,7,30,'Traerá con sus propias manos las ofrendas hechas por fuego a Yahvé. Traerá la grasa junto con el pecho, para presentar el pecho como ofrenda mecida delante de Yahvé.',NULL),
(@vid,@bid,7,31,'El sacerdote quemará la grasa en el altar , pero el pecho será para Aarón y sus hijos .',NULL),
(@vid,@bid,7,32,'Le darán al sacerdote el muslo derecho como ofrenda especial tomada de sus sacrificios de paz.',NULL),
(@vid,@bid,7,33,'El hijo de Aarón que ofrezca la sangre y la grasa de los sacrificios de paz recibirá el muslo derecho como su porción .',NULL),
(@vid,@bid,7,34,'Porque de los sacrificios de paz de los israelitas he tomado el pecho de la ofrenda mecida y el muslo de la ofrenda especial, y se los he dado al sacerdote Aarón y a sus hijos como un estatuto perpetuo para los hijos de Israel ’”.',NULL),
(@vid,@bid,7,35,'Esta es la porción de las ofrendas hechas por fuego a Yahvé que les corresponde a Aarón y a sus hijos desde el día en que fueron presentados para servir a Yahvé como sacerdotes.',NULL),
(@vid,@bid,7,36,'Yahvé ordenó que los israelitas les dieran estas porciones el día en que los ungió . Es un estatuto perpetuo para todas sus generaciones .',NULL),
(@vid,@bid,7,37,'Esta es la ley para el holocausto , la ofrenda de cereal, la ofrenda por el pecado , la ofrenda por la culpa, la ofrenda de consagración y el sacrificio de paz.',NULL),
(@vid,@bid,7,38,'Yahvé se la ordenó a Moisés en el monte Sinaí el día en que mandó a los israelitas que presentaran sus ofrendas a Yahvé en el desierto de Sinaí .',NULL),
(@vid,@bid,8,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,8,2,'“ Toma a Aarón y a sus hijos , junto con sus vestiduras, el aceite de la unción , el becerro de la ofrenda por el pecado , los dos carneros y la canasta de pan sin levadura;',NULL),
(@vid,@bid,8,3,'y reúne a toda la comunidad a la entrada de la Tienda del Encuentro”.',NULL),
(@vid,@bid,8,4,'Moisés hizo lo que Yahvé le ordenó , y la comunidad se reunió a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,8,5,'Moisés le dijo a la comunidad: “ Esto es lo que Yahvé ha mandado hacer ”.',NULL),
(@vid,@bid,8,6,'Moisés hizo acercarse a Aarón y a sus hijos , y los lavó con agua .',NULL),
(@vid,@bid,8,7,'Le puso la túnica a Aarón, le ató el cinturón, lo vistió con el manto y le puso el efod. Luego le amarró el cinturón tejido del efod para sujetarlo.',NULL),
(@vid,@bid,8,8,'Le puso también el pectoral, y dentro del pectoral colocó el Urim y el Tumim.',NULL),
(@vid,@bid,8,9,'Le puso el turbante en la cabeza , y en la parte delantera del turbante colocó la lámina de oro , la diadema sagrada, tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,8,10,'Después Moisés tomó el aceite de la unción , ungió el tabernáculo y todo lo que había en él , y los consagró.',NULL),
(@vid,@bid,8,11,'Roció un poco de aceite sobre el altar siete veces , y ungió el altar , todos sus utensilios, y el lavamanos con su base, para consagrarlos.',NULL),
(@vid,@bid,8,12,'Luego derramó parte del aceite de la unción sobre la cabeza de Aarón y lo ungió para consagrarlo.',NULL),
(@vid,@bid,8,13,'Moisés hizo acercarse a los hijos de Aarón, los vistió con túnicas , les puso cinturones y les ajustó los turbantes, tal como Yahvé se lo había ordenado .',NULL),
(@vid,@bid,8,14,'Luego hizo traer el becerro para la ofrenda por el pecado , y Aarón y sus hijos pusieron sus manos sobre la cabeza del becerro .',NULL),
(@vid,@bid,8,15,'Moisés degolló el becerro, tomó la sangre y , con su dedo, untó los cuernos del altar por todos lados para purificarlo. Derramó el resto de la sangre al pie del altar , consagrándolo así para hacer expiación por él .',NULL),
(@vid,@bid,8,16,'Moisés tomó toda la grasa que cubría las entrañas, la parte superior del hígado y los dos riñones con su grasa, y los quemó en el altar .',NULL),
(@vid,@bid,8,17,'Pero el resto del becerro , su piel , su carne y su excremento, los quemó en el fuego fuera del campamento , tal como Yahvé se lo había ordenado .',NULL),
(@vid,@bid,8,18,'Después presentó el carnero para el holocausto , y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero.',NULL),
(@vid,@bid,8,19,'Moisés lo degolló y roció la sangre por todos los lados del altar .',NULL),
(@vid,@bid,8,20,'Cortó el carnero en pedazos, y quemó la cabeza , los pedazos y la grasa.',NULL),
(@vid,@bid,8,21,'Lavó con agua las entrañas y las patas, y luego quemó todo el carnero en el altar . Fue un holocausto de aroma agradable, una ofrenda hecha por fuego a Yahvé, tal como Yahvé le había ordenado a Moisés .',NULL),
(@vid,@bid,8,22,'Luego presentó el otro carnero, el de la consagración, y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero.',NULL),
(@vid,@bid,8,23,'Moisés lo degolló , tomó un poco de la sangre y se la untó a Aarón en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho .',NULL),
(@vid,@bid,8,24,'Moisés hizo acercarse a los hijos de Aarón y les untó un poco de sangre en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho . Luego roció el resto de la sangre por todos los lados del altar .',NULL),
(@vid,@bid,8,25,'Tomó la grasa, la cola gorda, toda la grasa de las entrañas, la parte superior del hígado , los dos riñones con su grasa, y el muslo derecho .',NULL),
(@vid,@bid,8,26,'De la canasta de pan sin levadura que estaba ante Yahvé, sacó una torta sin levadura, una torta de pan hecha con aceite y una hojuela, y las puso sobre la grasa y sobre el muslo derecho .',NULL),
(@vid,@bid,8,27,'Puso todo esto en las manos de Aarón y de sus hijos , y se lo presentó a Yahvé como ofrenda mecida.',NULL),
(@vid,@bid,8,28,'Luego Moisés lo tomó de sus manos y lo quemó en el altar , sobre el holocausto . Esta fue una ofrenda de consagración, de aroma agradable, una ofrenda hecha por fuego a Yahvé.',NULL),
(@vid,@bid,8,29,'Moisés tomó el pecho y lo presentó ante Yahvé como ofrenda mecida; esa fue la porción del carnero de consagración que le correspondió a Moisés , tal como Yahvé se lo había ordenado .',NULL),
(@vid,@bid,8,30,'Luego Moisés tomó un poco del aceite de la unción y de la sangre que estaba en el altar , y roció a Aarón y su ropa, y también a sus hijos y la ropa de sus hijos . Así consagró a Aarón y su ropa, y a sus hijos y su ropa.',NULL),
(@vid,@bid,8,31,'Moisés les dijo a Aarón y a sus hijos : “Hiervan la carne a la entrada de la Tienda del Encuentro y cómanla allí , junto con el pan que está en la canasta de la consagración, tal como lo ordené cuando dije: ‘Aarón y sus hijos la comerán’.',NULL),
(@vid,@bid,8,32,'Lo que sobre de la carne y del pan deberán quemarlo en el fuego.',NULL),
(@vid,@bid,8,33,'Durante siete días no saldrán de la entrada de la Tienda del Encuentro, hasta que se cumpla el tiempo de su consagración, pues su consagración durará siete días .',NULL),
(@vid,@bid,8,34,'Lo que se ha hecho hoy , Yahvé mandó que se hiciera para hacer expiación por ustedes.',NULL),
(@vid,@bid,8,35,'Deberán quedarse a la entrada de la Tienda del Encuentro día y noche durante siete días , y cumplirán con las órdenes de Yahvé para que no mueran , pues así se me ha ordenado ”.',NULL),
(@vid,@bid,8,36,'Y Aarón y sus hijos hicieron todo lo que Yahvé ordenó por medio de Moisés .',NULL),
(@vid,@bid,9,1,'Al octavo día , Moisés llamó a Aarón, a sus hijos y a los ancianos de Israel ;',NULL),
(@vid,@bid,9,2,'y le dijo a Aarón: “ Toma un becerro de tu ganado para una ofrenda por el pecado , y un carnero para un holocausto , ambos sin defecto, y preséntalos ante Yahvé.',NULL),
(@vid,@bid,9,3,'Luego diles a los hijos de Israel : ‘ Tomen un macho cabrío para la ofrenda por el pecado , y un becerro y un cordero , ambos de un año y sin defecto, para el holocausto .',NULL),
(@vid,@bid,9,4,'Tomen también un toro y un carnero para los sacrificios de paz, para sacrificarlos ante Yahvé, junto con una ofrenda de cereal amasada con aceite , porque hoy Yahvé se les va a aparecer’”.',NULL),
(@vid,@bid,9,5,'Ellos llevaron a la entrada de la Tienda del Encuentro lo que Moisés había ordenado . Toda la comunidad se acercó y se quedó de pie ante Yahvé.',NULL),
(@vid,@bid,9,6,'Moisés les dijo: “ Esto es lo que Yahvé mandó que hicieran, para que la gloria de Yahvé se les aparezca ”.',NULL),
(@vid,@bid,9,7,'Luego Moisés le dijo a Aarón: “ Acércate al altar , presenta tu ofrenda por el pecado y tu holocausto , y haz la expiación por ti y por el pueblo . Presenta también la ofrenda del pueblo y haz la expiación por ellos, tal como Yahvé lo ha ordenado ”.',NULL),
(@vid,@bid,9,8,'Entonces Aarón se acercó al altar y degolló el becerro de la ofrenda por el pecado que era para él mismo.',NULL),
(@vid,@bid,9,9,'Sus hijos le acercaron la sangre ; él mojó su dedo en la sangre , untó los cuernos del altar y derramó el resto de la sangre al pie del altar .',NULL),
(@vid,@bid,9,10,'Pero la grasa, los riñones y la parte superior del hígado de la ofrenda por el pecado , los quemó en el altar , tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,9,11,'La carne y la piel las quemó en el fuego fuera del campamento .',NULL),
(@vid,@bid,9,12,'Después degolló el animal para el holocausto . Sus hijos le entregaron la sangre , y él la roció por todos los lados del altar .',NULL),
(@vid,@bid,9,13,'Le entregaron también el holocausto en pedazos, junto con la cabeza , y él los quemó en el altar .',NULL),
(@vid,@bid,9,14,'Lavó las entrañas y las patas, y las quemó sobre el holocausto en el altar .',NULL),
(@vid,@bid,9,15,'Luego presentó la ofrenda del pueblo . Tomó el macho cabrío de la ofrenda por el pecado del pueblo , lo degolló y lo ofreció por el pecado , igual que el primero .',NULL),
(@vid,@bid,9,16,'Presentó el holocausto y lo ofreció según el reglamento.',NULL),
(@vid,@bid,9,17,'Presentó también la ofrenda de cereal; tomó un puñado de ella y la quemó en el altar , además del holocausto de la mañana .',NULL),
(@vid,@bid,9,18,'Degolló el toro y el carnero para el sacrificio de paz del pueblo . Sus hijos le pasaron la sangre , y él la roció por todos los lados del altar .',NULL),
(@vid,@bid,9,19,'Tomaron las partes grasosas del toro y del carnero, la cola gorda, la grasa que cubre las entrañas, los riñones y la parte superior del hígado ,',NULL),
(@vid,@bid,9,20,'y pusieron toda esa grasa sobre los pechos de los animales. Entonces Aarón quemó la grasa en el altar .',NULL),
(@vid,@bid,9,21,'Aarón presentó los pechos y el muslo derecho como ofrenda mecida ante Yahvé, tal como Moisés lo había ordenado .',NULL),
(@vid,@bid,9,22,'Después Aarón levantó sus manos hacia el pueblo y lo bendijo . Una vez que terminó de presentar la ofrenda por el pecado , el holocausto y los sacrificios de paz, bajó del altar.',NULL),
(@vid,@bid,9,23,'Moisés y Aarón entraron en la Tienda del Encuentro. Cuando salieron , bendijeron al pueblo , y la gloria de Yahvé se le apareció a todo el pueblo .',NULL),
(@vid,@bid,9,24,'Salió fuego de la presencia de Yahvé y consumió el holocausto y la grasa que estaban en el altar . Al ver esto, todo el pueblo gritó de alegría y se postró rostro en tierra.',NULL),
(@vid,@bid,10,1,'Nadab y Abiú, hijos de Aarón, tomaron cada uno su incensario, le pusieron fuego, le echaron incienso encima y ofrecieron ante Yahvé un fuego no autorizado, algo que él no les había mandado .',NULL),
(@vid,@bid,10,2,'Entonces salió fuego de la presencia de Yahvé y los consumió, y murieron allí mismo, delante de Yahvé.',NULL),
(@vid,@bid,10,3,'Moisés le dijo a Aarón: “ Esto es lo que Yahvé quería decir cuando declaró: ‘ A los que se acercan a mí les mostraré mi santidad, y ante todo el pueblo revelaré mi gloria ’”. Y Aarón se quedó callado.',NULL),
(@vid,@bid,10,4,'Moisés llamó a Misael y a Elzafán, hijos de Uziel, tío de Aarón, y les dijo: “Acérquense y llévense a sus parientes de enfrente del santuario hacia afuera del campamento ”.',NULL),
(@vid,@bid,10,5,'Ellos se acercaron y se los llevaron agarrados de sus túnicas hacia afuera del campamento , tal como Moisés lo había ordenado.',NULL),
(@vid,@bid,10,6,'Luego Moisés les dijo a Aarón y a sus otros hijos , Eleazar e Itamar: “ No se despeinen ni se rasguen la ropa en señal de luto, para que no mueran y para que Yahvé no se enoje con toda la comunidad. Sus hermanos, toda la casa de Israel , son los que deben llorar por este fuego que Yahvé ha encendido.',NULL),
(@vid,@bid,10,7,'No se alejen de la entrada de la Tienda del Encuentro, no sea que mueran , porque el aceite de la unción de Yahvé está sobre ustedes”. Y ellos hicieron lo que Moisés les dijo.',NULL),
(@vid,@bid,10,8,'Entonces Yahvé le habló a Aarón y le dijo :',NULL),
(@vid,@bid,10,9,'“Tú y tus hijos no deben beber vino ni ninguna bebida alcohólica cuando entren a la Tienda del Encuentro, para que no mueran . Este será un estatuto perpetuo para todas sus generaciones .',NULL),
(@vid,@bid,10,10,'Ustedes deben hacer distinción entre lo santo y lo común, y entre lo impuro y lo puro .',NULL),
(@vid,@bid,10,11,'Además, deben enseñarles a los israelitas todas las leyes que Yahvé les ha dado por medio de Moisés ”.',NULL),
(@vid,@bid,10,12,'Moisés les dijo a Aarón y a los hijos que le quedaban, Eleazar e Itamar: “ Tomen la ofrenda de cereal que sobró de las ofrendas hechas por fuego a Yahvé, y cómanla sin levadura junto al altar , porque es una ofrenda muy santa .',NULL),
(@vid,@bid,10,13,'Deben comerla en un lugar sagrado, porque es la porción que les corresponde a ti y a tus hijos de las ofrendas hechas por fuego a Yahvé; así se me ha ordenado .',NULL),
(@vid,@bid,10,14,'Además , el pecho de la ofrenda mecida y el muslo de la ofrenda especial podrán comerlos tú, tus hijos y tus hijas en un lugar ceremonialmente limpio , porque se les han dado como su porción de los sacrificios de paz de los israelitas.',NULL),
(@vid,@bid,10,15,'Traerán el muslo de la ofrenda especial y el pecho de la ofrenda mecida junto con la grasa de las ofrendas hechas por fuego, para presentarlos como ofrenda mecida ante Yahvé. Esta será la porción perpetua para ti y para tus hijos , tal como Yahvé lo ha ordenado ”.',NULL),
(@vid,@bid,10,16,'Cuando Moisés preguntó qué había pasado con el macho cabrío de la ofrenda por el pecado , se dio cuenta de que ya lo habían quemado. Se enojó mucho con Eleazar e Itamar, los hijos que le quedaban a Aarón, y les reclamó:',NULL),
(@vid,@bid,10,17,'“¿ Por qué no se comieron la ofrenda por el pecado en el área del santuario ? Es una ofrenda muy santa , y se les dio a ustedes para quitar la culpa de la comunidad, haciendo expiación por ellos ante Yahvé.',NULL),
(@vid,@bid,10,18,'Como la sangre del animal no se llevó al interior del santuario , ustedes debieron haberse comido la carne en el área del santuario , tal como yo lo ordené ”.',NULL),
(@vid,@bid,10,19,'Aarón le respondió a Moisés : “ Mira , hoy ellos presentaron su ofrenda por el pecado y su holocausto ante Yahvé, ¡y a mí me han pasado estas tragedias! Si yo me hubiera comido hoy la ofrenda por el pecado , ¿ le habría agradado eso a Yahvé?”.',NULL),
(@vid,@bid,10,20,'Cuando Moisés escuchó esto, estuvo de acuerdo.',NULL),
(@vid,@bid,11,1,'Yahvé les habló a Moisés y a Aarón, y les dijo :',NULL),
(@vid,@bid,11,2,'“Díganles a los israelitas: ‘ De todos los animales que viven en la tierra, estos son los que ustedes pueden comer:',NULL),
(@vid,@bid,11,3,'Podrán comer cualquier animal que tenga la pezuña partida en dos y que además rumie.',NULL),
(@vid,@bid,11,4,'“‘ Sin embargo, de los animales que solo rumian o que solo tienen la pezuña partida, no podrán comer los siguientes: el camello , porque rumia pero no tiene la pezuña partida; lo considerarán impuro.',NULL),
(@vid,@bid,11,5,'El tejón, porque rumia pero no tiene la pezuña partida; lo considerarán impuro.',NULL),
(@vid,@bid,11,6,'La liebre, porque rumia pero no tiene la pezuña partida; la considerarán impura.',NULL),
(@vid,@bid,11,7,'Y el cerdo, porque tiene la pezuña partida en dos, pero no rumia ; lo considerarán impuro.',NULL),
(@vid,@bid,11,8,'No comerán la carne de estos animales ni tocarán sus cadáveres. Los considerarán impuros.',NULL),
(@vid,@bid,11,9,'“‘ De todas las criaturas que viven en el agua , en los mares y en los ríos, podrán comer todas las que tengan aletas y escamas.',NULL),
(@vid,@bid,11,10,'Pero todas las criaturas que viven en los mares y en los ríos que no tengan aletas ni escamas, ya sean las que se mueven en grupos o cualquier otra criatura del agua , las considerarán algo asqueroso.',NULL),
(@vid,@bid,11,11,'Las tendrán por cosas repugnantes: no comerán su carne y detestarán sus cadáveres.',NULL),
(@vid,@bid,11,12,'Cualquier criatura del agua que no tenga aletas ni escamas será algo asqueroso para ustedes.',NULL),
(@vid,@bid,11,13,'“‘ De las aves , detestarán las siguientes y no las comerán por ser asquerosas: el águila, el quebrantahuesos, el águila pescadora,',NULL),
(@vid,@bid,11,14,'el milano, cualquier especie de halcón,',NULL),
(@vid,@bid,11,15,'cualquier especie de cuervo ,',NULL),
(@vid,@bid,11,16,'el avestruz, la lechuza, la gaviota, cualquier especie de gavilán,',NULL),
(@vid,@bid,11,17,'el búho pequeño, el cormorán, el búho grande,',NULL),
(@vid,@bid,11,18,'la lechuza blanca, el pelícano, el buitre,',NULL),
(@vid,@bid,11,19,'la cigüeña, cualquier especie de garza, la abubilla y el murciélago.',NULL),
(@vid,@bid,11,20,'“‘ Cualquier insecto alado que camine en cuatro patas lo considerarán asqueroso.',NULL),
(@vid,@bid,11,21,'Sin embargo, podrán comer los insectos alados que caminan en cuatro patas y que además tienen patas traseras articuladas para saltar sobre el suelo.',NULL),
(@vid,@bid,11,22,'De estos podrán comer: cualquier especie de langosta, el grillo calvo, el grillo común y cualquier especie de saltamontes.',NULL),
(@vid,@bid,11,23,'Pero cualquier otro insecto alado de cuatro patas lo considerarán asqueroso.',NULL),
(@vid,@bid,11,24,'“‘ Con los siguientes animales ustedes quedarán impuros. Cualquiera que toque sus cadáveres quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,11,25,'Cualquiera que levante el cadáver de alguno de ellos deberá lavar su ropa y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,11,26,'“‘ Cualquier animal que tenga pezuñas pero no partidas en dos, o que no rumie, lo considerarán impuro. Cualquiera que lo toque quedará impuro.',NULL),
(@vid,@bid,11,27,'De todos los animales de cuatro patas, los que caminan sobre sus garras los considerarán impuros. Cualquiera que toque sus cadáveres quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,11,28,'El que recoja sus cadáveres deberá lavar su ropa y quedará impuro hasta el atardecer. Los considerarán impuros.',NULL),
(@vid,@bid,11,29,'“‘ De los animales que se arrastran por el suelo, considerarán impuros los siguientes: el topo, el ratón, cualquier especie de lagarto grande,',NULL),
(@vid,@bid,11,30,'el gecko, el lagarto monitor, la lagartija común, el eslizón y el camaleón.',NULL),
(@vid,@bid,11,31,'De todos los animales que se arrastran, estos los considerarán impuros. Cualquiera que los toque cuando estén muertos quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,11,32,'Cualquier cosa sobre la que caiga uno de estos animales muertos quedará impura, ya sea un artículo de madera , de tela, de cuero o un costal. Cualquier objeto que se use para trabajar deberá meterse en agua y quedará impuro hasta el atardecer; después de eso quedará limpio .',NULL),
(@vid,@bid,11,33,'Si uno de estos animales cae dentro de una olla de barro, todo lo que esté adentro quedará impuro, y deberán quebrar la olla.',NULL),
(@vid,@bid,11,34,'Cualquier alimento que se pueda comer quedará impuro si le cae agua de esa olla. Cualquier líquido que se pueda beber de esa olla quedará impuro.',NULL),
(@vid,@bid,11,35,'Cualquier cosa sobre la que caiga un pedazo de sus cadáveres quedará impura; si es un horno o un fogón de barro, deberán destruirlo. Son impuros y los considerarán impuros.',NULL),
(@vid,@bid,11,36,'Sin embargo, un manantial o una cisterna donde se junte agua seguirá siendo limpio , pero quien toque el cadáver del animal allí dentro quedará impuro.',NULL),
(@vid,@bid,11,37,'Si un pedazo del cadáver cae sobre semillas que se van a sembrar, las semillas seguirán estando limpias .',NULL),
(@vid,@bid,11,38,'Pero si se le ha echado agua a la semilla y luego le cae un pedazo del cadáver, considerarán la semilla como impura.',NULL),
(@vid,@bid,11,39,'“‘ Si muere un animal de los que a ustedes se les permite comer, el que toque su cadáver quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,11,40,'El que se coma parte del cadáver deberá lavar su ropa y quedará impuro hasta el atardecer. El que recoja el cadáver también deberá lavar su ropa y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,11,41,'“‘ Cualquier animal que se arrastre por el suelo es asqueroso; no se debe comer.',NULL),
(@vid,@bid,11,42,'No deben comer ningún animal que se arrastre por el suelo, ya sea que se mueva sobre su vientre, sobre cuatro patas o sobre muchas patas, porque son asquerosos.',NULL),
(@vid,@bid,11,43,'No se vuelvan asquerosos a ustedes mismos comiendo ninguno de estos animales que se arrastran. No se hagan impuros con ellos ni se contaminen por su culpa.',NULL),
(@vid,@bid,11,44,'Porque yo soy Yahvé, su Dios . Por lo tanto , conságrense y sean santos , porque yo soy santo . No se contaminen con ningún animal que se arrastre por el suelo.',NULL),
(@vid,@bid,11,45,'Yo soy Yahvé, el que los sacó de la tierra de Egipto para ser su Dios . Sean santos , porque yo soy santo .',NULL),
(@vid,@bid,11,46,'“‘ Este es el reglamento acerca de los animales , las aves , todas las criaturas que se mueven en el agua y todos los animales que se arrastran por el suelo.',NULL),
(@vid,@bid,11,47,'Sirve para distinguir entre lo impuro y lo limpio , y entre los animales que se pueden comer y los que no se deben comer’”.',NULL),
(@vid,@bid,12,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,12,2,'“ Diles a los israelitas: ‘ Si una mujer queda embarazada y da a luz a un niño, será ceremonialmente impura durante siete días ; será impura tal como lo es durante su período menstrual.',NULL),
(@vid,@bid,12,3,'Al octavo día , el niño deberá ser circuncidado .',NULL),
(@vid,@bid,12,4,'Después , la mujer deberá esperar treinta y tres días para purificarse del sangrado del parto. No debe tocar nada sagrado ni entrar al santuario hasta que se cumpla el tiempo de su purificación.',NULL),
(@vid,@bid,12,5,'Pero si da a luz a una niña, será impura durante dos semanas , tal como en su período menstrual, y deberá esperar sesenta y seis días para purificarse del sangrado.',NULL),
(@vid,@bid,12,6,'“‘ Cuando se cumpla el tiempo de su purificación, ya sea por un niño o por una niña, la mujer llevará a la entrada de la Tienda del Encuentro un cordero de un año para un holocausto , y un pichón o una tórtola para una ofrenda por el pecado , y se los entregará al sacerdote .',NULL),
(@vid,@bid,12,7,'El sacerdote los ofrecerá ante Yahvé y hará expiación por ella . De esta manera la mujer quedará purificada de su flujo de sangre . “‘ Este es el reglamento para la mujer que da a luz a un niño o a una niña.',NULL),
(@vid,@bid,12,8,'Si no le alcanza para comprar un cordero , podrá llevar dos tórtolas o dos pichones: uno para el holocausto y el otro para la ofrenda por el pecado . El sacerdote hará expiación por ella , y quedará purificada’”.',NULL),
(@vid,@bid,13,1,'Yahvé les habló a Moisés y a Aarón, y les dijo :',NULL),
(@vid,@bid,13,2,'“ Si a alguien le sale en la piel una hinchazón , una erupción o una mancha brillante que pueda convertirse en una infección de lepra , esa persona deberá ser llevada ante el sacerdote Aarón, o ante uno de sus hijos , los sacerdotes .',NULL),
(@vid,@bid,13,3,'El sacerdote examinará la infección en la piel . Si el vello en la zona infectada se ha vuelto blanco , y la infección parece haber penetrado más allá de la piel , se trata de una infección de lepra . Al examinar a la persona, el sacerdote la declarará impura.',NULL),
(@vid,@bid,13,4,'Pero si la mancha en la piel es blanca , y no parece ser más profunda que la piel ni el vello se ha vuelto blanco , entonces el sacerdote aislará a la persona infectada durante siete días .',NULL),
(@vid,@bid,13,5,'Al séptimo día , el sacerdote la examinará de nuevo. Si a su parecer la infección se ha detenido y no se ha extendido por la piel , el sacerdote la aislará durante siete días más .',NULL),
(@vid,@bid,13,6,'El sacerdote la examinará por segunda vez al séptimo día . Si la infección se ha desvanecido y no se ha extendido por la piel , el sacerdote la declarará pura; se trata solo de una erupción. La persona lavará su ropa y quedará pura.',NULL),
(@vid,@bid,13,7,'Sin embargo, si la erupción se extiende por la piel después de haberse presentado ante el sacerdote para ser declarada pura, deberá presentarse de nuevo ante él.',NULL),
(@vid,@bid,13,8,'El sacerdote la examinará, y si ve que la erupción se ha extendido, la declarará impura; es lepra .',NULL),
(@vid,@bid,13,9,'“ Cuando alguien tenga una infección de lepra , será llevado ante el sacerdote ,',NULL),
(@vid,@bid,13,10,'quien lo examinará. Si en la piel hay una hinchazón blanca que ha vuelto blanco el vello, y hay carne viva en la hinchazón ,',NULL),
(@vid,@bid,13,11,'se trata de lepra crónica en la piel . El sacerdote declarará impura a esa persona, pero no la aislará, porque ya es impura.',NULL),
(@vid,@bid,13,12,'“Si la lepra brota por todas partes y cubre toda la piel de la persona infectada, de la cabeza a los pies , hasta donde el sacerdote pueda ver,',NULL),
(@vid,@bid,13,13,'entonces el sacerdote la examinará. Si la lepra ha cubierto todo el cuerpo, el sacerdote declarará pura a la persona. Todo su cuerpo se ha vuelto blanco , así que está puro .',NULL),
(@vid,@bid,13,14,'Pero el día en que le aparezca carne viva , la persona será impura.',NULL),
(@vid,@bid,13,15,'El sacerdote examinará la carne viva y la declarará impura. La carne viva es impura; es lepra .',NULL),
(@vid,@bid,13,16,'Pero si la carne viva cambia y vuelve a ponerse blanca , la persona irá a ver al sacerdote .',NULL),
(@vid,@bid,13,17,'El sacerdote la examinará, y si la llaga se ha puesto blanca , el sacerdote declarará pura a la persona; está pura .',NULL),
(@vid,@bid,13,18,'“ Si a alguien le sale un forúnculo en la piel y se le cura ,',NULL),
(@vid,@bid,13,19,'pero en su lugar aparece una hinchazón blanca o una mancha brillante de color blanco rojizo, la persona deberá mostrarse al sacerdote .',NULL),
(@vid,@bid,13,20,'El sacerdote la examinará, y si la mancha parece más profunda que la piel y el vello se ha vuelto blanco , el sacerdote la declarará impura. Es una infección de lepra que ha brotado en el forúnculo.',NULL),
(@vid,@bid,13,21,'Pero si el sacerdote la examina y ve que no tiene vello blanco ni es más profunda que la piel , y que ha ido desapareciendo, entonces el sacerdote la aislará durante siete días .',NULL),
(@vid,@bid,13,22,'Si la mancha se extiende por la piel , el sacerdote la declarará impura; es una infección.',NULL),
(@vid,@bid,13,23,'Pero si la mancha brillante no cambia ni se extiende, es solo la cicatriz del forúnculo, y el sacerdote la declarará pura.',NULL),
(@vid,@bid,13,24,'“ Si alguien se hace una quemadura en la piel , y la carne viva de la quemadura se convierte en una mancha brillante de color blanco rojizo o blanco ,',NULL),
(@vid,@bid,13,25,'el sacerdote la examinará. Si el vello en la mancha se ha vuelto blanco y la mancha parece más profunda que la piel , es lepra que ha brotado en la quemadura . El sacerdote declarará impura a la persona; es una infección de lepra .',NULL),
(@vid,@bid,13,26,'Pero si el sacerdote la examina y ve que no tiene vello blanco ni es más profunda que la piel , y que ha ido desapareciendo, entonces el sacerdote la aislará durante siete días .',NULL),
(@vid,@bid,13,27,'Al séptimo día el sacerdote la examinará de nuevo. Si la mancha se ha extendido por la piel , el sacerdote la declarará impura; es una infección de lepra .',NULL),
(@vid,@bid,13,28,'Si la mancha brillante no cambia ni se extiende, sino que ha ido desapareciendo, es solo la hinchazón de la quemadura . El sacerdote declarará pura a la persona, pues es solo la cicatriz de la quemadura .',NULL),
(@vid,@bid,13,29,'“ Si a un hombre o a una mujer le sale una llaga en la cabeza o en la barba ,',NULL),
(@vid,@bid,13,30,'el sacerdote examinará la llaga . Si parece más profunda que la piel y el pelo en esa parte es amarillento y fino, el sacerdote declarará impura a la persona. Se trata de tiña , que es lepra en la cabeza o en la barba .',NULL),
(@vid,@bid,13,31,'Pero si el sacerdote examina la infección de la tiña y no parece ser más profunda que la piel , aunque no tenga pelo negro , aislará a la persona infectada durante siete días .',NULL),
(@vid,@bid,13,32,'Al séptimo día el sacerdote examinará la infección. Si la tiña no se ha extendido ni tiene pelo amarillento, y no parece ser más profunda que la piel ,',NULL),
(@vid,@bid,13,33,'la persona deberá rasurarse, pero no se rasurará la parte afectada por la tiña . Luego el sacerdote la aislará durante siete días más .',NULL),
(@vid,@bid,13,34,'Al séptimo día el sacerdote examinará la tiña . Si no se ha extendido por la piel ni parece ser más profunda , el sacerdote declarará pura a la persona. Esta deberá lavar su ropa y quedará pura.',NULL),
(@vid,@bid,13,35,'Pero si la tiña se extiende por la piel después de que la persona fue declarada pura,',NULL),
(@vid,@bid,13,36,'el sacerdote la examinará de nuevo. Si la tiña se ha extendido, el sacerdote ya no tendrá que buscar el pelo amarillento; la persona es impura.',NULL),
(@vid,@bid,13,37,'Pero si a su parecer la tiña ha dejado de extenderse y le ha salido pelo negro , la tiña está curada. La persona está pura , y el sacerdote así lo declarará.',NULL),
(@vid,@bid,13,38,'“ Si a un hombre o a una mujer le salen manchas brillantes y blancas en la piel ,',NULL),
(@vid,@bid,13,39,'el sacerdote deberá examinar a la persona. Si las manchas en la piel son de un blanco pálido, es una erupción inofensiva que ha brotado en la piel . La persona está pura .',NULL),
(@vid,@bid,13,40,'“ Si a un hombre se le cae el pelo de la cabeza y se queda calvo , está puro .',NULL),
(@vid,@bid,13,41,'Si se le cae el pelo de la parte de enfrente y se queda medio calvo, está puro .',NULL),
(@vid,@bid,13,42,'Pero si en la parte calva , ya sea atrás o adelante, le sale una llaga de color blanco rojizo, es lepra que está brotando.',NULL),
(@vid,@bid,13,43,'Entonces el sacerdote lo examinará. Si la hinchazón de la llaga es de color blanco rojizo, parecida a la lepra en el resto del cuerpo,',NULL),
(@vid,@bid,13,44,'el hombre está leproso . Es impuro, y el sacerdote sin duda lo declarará impuro; la infección la tiene en la cabeza .',NULL),
(@vid,@bid,13,45,'“ La persona enferma de lepra deberá andar con la ropa rasgada y el pelo despeinado. Deberá cubrirse la parte inferior de la cara y gritar: ‘¡Impuro! ¡Impuro!’.',NULL),
(@vid,@bid,13,46,'Mientras le dure la enfermedad, será impura. Como es impura, deberá vivir aislada; su lugar de residencia estará fuera del campamento .',NULL),
(@vid,@bid,13,47,'“ Si en una prenda de lana o de lino aparece una mancha de moho parecido a la lepra ,',NULL),
(@vid,@bid,13,48,'ya sea en el tejido o en el hilado del lino o de la lana , o en algún artículo de cuero,',NULL),
(@vid,@bid,13,49,'y si la mancha es verdosa o rojiza, se trata de una plaga de moho y deberá mostrarse al sacerdote .',NULL),
(@vid,@bid,13,50,'El sacerdote examinará la mancha y aislará el artículo afectado durante siete días .',NULL),
(@vid,@bid,13,51,'Al séptimo día lo examinará de nuevo. Si la mancha se ha extendido en el vestido, en el tejido, en el hilado o en el cuero, sin importar para qué se use el cuero, la plaga es un moho destructivo y el artículo es impuro.',NULL),
(@vid,@bid,13,52,'El sacerdote deberá quemar la prenda , el tejido o el hilado, ya sea de lana o de lino , o cualquier artículo de cuero que tenga la plaga , porque es un moho destructivo. Deberá quemarse por completo.',NULL),
(@vid,@bid,13,53,'“Pero si el sacerdote lo examina y ve que la mancha no se ha extendido,',NULL),
(@vid,@bid,13,54,'ordenará que laven el artículo afectado y lo aislará durante siete días más.',NULL),
(@vid,@bid,13,55,'Después de que el artículo haya sido lavado, el sacerdote lo examinará. Si la mancha no ha cambiado de aspecto, aunque no se haya extendido, el artículo es impuro y deberás quemarlo. Es una corrosión , sin importar de qué lado esté el desgaste.',NULL),
(@vid,@bid,13,56,'Si el sacerdote lo examina y ve que la mancha se ha desvanecido después de lavarlo, entonces recortará la parte manchada del vestido, del cuero, del tejido o del hilado.',NULL),
(@vid,@bid,13,57,'Pero si la mancha vuelve a aparecer, significa que la plaga se está extendiendo. Deberás quemar el artículo que tenga la plaga .',NULL),
(@vid,@bid,13,58,'En cambio, si al lavar la prenda , el tejido, el hilado o el artículo de cuero, la mancha desaparece, se lavará por segunda vez y el artículo quedará puro”.',NULL),
(@vid,@bid,13,59,'Este es el reglamento sobre la plaga de moho en una prenda de lana o de lino , en un tejido, en un hilado o en un artículo de cuero, para declararlos puros o impuros.',NULL),
(@vid,@bid,14,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,14,2,'“ Este será el reglamento para la persona con lepra en el día de su purificación. La persona será llevada ante el sacerdote ,',NULL),
(@vid,@bid,14,3,'quien saldrá fuera del campamento para examinarla. Si la infección de lepra se le ha curado,',NULL),
(@vid,@bid,14,4,'el sacerdote ordenará que traigan dos aves vivas y puras, madera de cedro, hilo escarlata y ramas de hisopo para la persona que se va a purificar.',NULL),
(@vid,@bid,14,5,'Luego el sacerdote ordenará que degüellen una de las aves sobre una olla de barro con agua de manantial.',NULL),
(@vid,@bid,14,6,'Tomará el ave viva junto con la madera de cedro, el hilo escarlata y el hisopo, y los mojará todos, incluida el ave viva , en la sangre del ave degollada sobre el agua de manantial.',NULL),
(@vid,@bid,14,7,'Rociará esa sangre siete veces sobre la persona que se está purificando de la lepra y la declarará pura. Después soltará el ave viva en campo abierto.',NULL),
(@vid,@bid,14,8,'“ La persona que se está purificando deberá lavar su ropa, rasurarse todo el pelo y bañarse; de este modo quedará pura. Después podrá entrar al campamento , pero tendrá que quedarse fuera de su propia tienda durante siete días .',NULL),
(@vid,@bid,14,9,'Al séptimo día volverá a rasurarse todo el pelo : la cabeza , la barba , las cejas y cualquier otro pelo que tenga . Lavará su ropa y se bañará, y entonces quedará pura.',NULL),
(@vid,@bid,14,10,'“Al octavo día , la persona tomará dos corderos sin defecto, una cordera de un año sin defecto, tres kilos de harina fina amasada con aceite como ofrenda de cereal, y un log de aceite .',NULL),
(@vid,@bid,14,11,'El sacerdote que realiza la purificación presentará a la persona , junto con sus ofrendas, ante Yahvé a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,14,12,'“El sacerdote tomará uno de los corderos y el log de aceite , y los presentará como ofrenda por la culpa; los presentará ante Yahvé como ofrenda mecida.',NULL),
(@vid,@bid,14,13,'Degollará el cordero en el área del santuario , en el mismo lugar donde se degüellan los animales para la ofrenda por el pecado y para el holocausto . El sacrificio por la culpa, al igual que el sacrificio por el pecado , le pertenece al sacerdote ; es una ofrenda muy santa .',NULL),
(@vid,@bid,14,14,'El sacerdote tomará un poco de la sangre de la ofrenda por la culpa y se la untará a la persona en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho .',NULL),
(@vid,@bid,14,15,'Luego el sacerdote echará un poco del log de aceite en la palma de su propia mano izquierda ,',NULL),
(@vid,@bid,14,16,'mojará el dedo derecho en el aceite y lo rociará con el dedo siete veces delante de Yahvé.',NULL),
(@vid,@bid,14,17,'Del aceite que le quede en la mano , le untará un poco a la persona en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho , exactamente encima de la sangre de la ofrenda por la culpa.',NULL),
(@vid,@bid,14,18,'Y el resto del aceite que le quede en la mano se lo untará a la persona en la cabeza . Así el sacerdote hará expiación por esa persona delante de Yahvé.',NULL),
(@vid,@bid,14,19,'“ Después el sacerdote presentará la ofrenda por el pecado para hacer expiación por la persona que se está purificando. Luego degollará el animal para el holocausto ,',NULL),
(@vid,@bid,14,20,'y ofrecerá en el altar tanto el holocausto como la ofrenda de cereal. Así el sacerdote hará expiación por la persona, y esta quedará pura.',NULL),
(@vid,@bid,14,21,'“Pero si la persona es pobre y no le alcanza para tanto , tomará solo un cordero como ofrenda por la culpa. El cordero se presentará como ofrenda mecida para hacer expiación por ella . Además , llevará un kilo de harina fina amasada con aceite como ofrenda de cereal, un log de aceite ,',NULL),
(@vid,@bid,14,22,'y dos tórtolas o dos pichones, según lo que pueda pagar. Una de las aves será para la ofrenda por el pecado y la otra para el holocausto .',NULL),
(@vid,@bid,14,23,'“Al octavo día llevará todo esto al sacerdote para su purificación, a la entrada de la Tienda del Encuentro, delante de Yahvé.',NULL),
(@vid,@bid,14,24,'El sacerdote tomará el cordero de la ofrenda por la culpa y el log de aceite , y los presentará ante Yahvé como ofrenda mecida.',NULL),
(@vid,@bid,14,25,'Luego degollará el cordero de la ofrenda por la culpa, tomará un poco de la sangre y se la untará a la persona en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho .',NULL),
(@vid,@bid,14,26,'El sacerdote echará un poco del aceite en la palma de su propia mano izquierda ,',NULL),
(@vid,@bid,14,27,'y con el dedo derecho rociará el aceite siete veces delante de Yahvé.',NULL),
(@vid,@bid,14,28,'Luego le untará un poco de ese aceite a la persona en el lóbulo de la oreja derecha , en el pulgar de la mano derecha y en el dedo gordo del pie derecho , exactamente en el mismo lugar donde le untó la sangre de la ofrenda por la culpa.',NULL),
(@vid,@bid,14,29,'El aceite que le sobre en la mano se lo untará a la persona en la cabeza , para hacer expiación por ella delante de Yahvé.',NULL),
(@vid,@bid,14,30,'Finalmente, el sacerdote ofrecerá las tórtolas o los pichones que la persona haya podido pagar.',NULL),
(@vid,@bid,14,31,'Presentará una de las aves como ofrenda por el pecado y la otra como holocausto , junto con la ofrenda de cereal. Así el sacerdote hará expiación delante de Yahvé por la persona que se está purificando”.',NULL),
(@vid,@bid,14,32,'Este es el reglamento para el que tiene una infección de lepra y no le alcanza para pagar las ofrendas normales para su purificación.',NULL),
(@vid,@bid,14,33,'Yahvé les habló a Moisés y a Aarón, y les dijo :',NULL),
(@vid,@bid,14,34,'“ Cuando ustedes entren en la tierra de Canaán , la cual les doy en posesión, y yo envíe una plaga de moho sobre alguna de las casas de su tierra,',NULL),
(@vid,@bid,14,35,'el dueño de la casa irá y le dirá al sacerdote : ‘Me parece que hay una plaga de moho en mi casa ’.',NULL),
(@vid,@bid,14,36,'El sacerdote ordenará que desocupen la casa antes de entrar a examinar la plaga , para que nada de lo que hay adentro sea declarado impuro. Después de eso , el sacerdote entrará a examinar la casa .',NULL),
(@vid,@bid,14,37,'Examinará la mancha, y si ve que en las paredes hay cavidades verdosas o rojizas que parecen penetrar más allá de la superficie,',NULL),
(@vid,@bid,14,38,'saldrá de la casa , cerrará la puerta y la dejará aislada durante siete días .',NULL),
(@vid,@bid,14,39,'Al séptimo día , el sacerdote regresará y la examinará. Si la mancha se ha extendido por las paredes,',NULL),
(@vid,@bid,14,40,'ordenará que quiten las piedras manchadas y las tiren en un lugar impuro fuera de la ciudad .',NULL),
(@vid,@bid,14,41,'Hará que raspen todo el interior de la casa , y el polvo raspado lo echarán en un lugar impuro fuera de la ciudad .',NULL),
(@vid,@bid,14,42,'Luego pondrán otras piedras en lugar de las primeras y revocarán la casa con mezcla nueva.',NULL),
(@vid,@bid,14,43,'“Si la plaga vuelve a aparecer en la casa después de que le quitaron las piedras, la rasparon y la revocaron,',NULL),
(@vid,@bid,14,44,'el sacerdote entrará a examinarla. Si la mancha se ha extendido, es un moho destructivo en la casa , y la casa es impura.',NULL),
(@vid,@bid,14,45,'Deberán derrumbar la casa por completo —las piedras, la madera y todo el revoco— y llevarán los escombros a un lugar impuro fuera de la ciudad .',NULL),
(@vid,@bid,14,46,'“ Cualquiera que entre en la casa mientras esté cerrada quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,14,47,'El que duerma o coma allí dentro deberá lavar su ropa.',NULL),
(@vid,@bid,14,48,'“ Pero si el sacerdote entra a examinar la casa después de haber sido revocada y ve que la mancha no se ha extendido, la declarará pura, pues la plaga se ha curado.',NULL),
(@vid,@bid,14,49,'Para purificar la casa , tomará dos aves, madera de cedro, hilo escarlata y ramas de hisopo.',NULL),
(@vid,@bid,14,50,'Degollará una de las aves sobre una olla de barro con agua de manantial.',NULL),
(@vid,@bid,14,51,'Luego tomará la madera de cedro, el hisopo, el hilo escarlata y el ave viva , los mojará en la sangre del ave degollada y en el agua de manantial, y rociará la casa siete veces .',NULL),
(@vid,@bid,14,52,'Purificará la casa con la sangre del ave , el agua de manantial, el ave viva , la madera de cedro, el hisopo y el hilo escarlata.',NULL),
(@vid,@bid,14,53,'Finalmente, soltará el ave viva fuera de la ciudad , en campo abierto. Así hará expiación por la casa y esta quedará pura”.',NULL),
(@vid,@bid,14,54,'Este es el reglamento para cualquier clase de infección de lepra o tiña ,',NULL),
(@vid,@bid,14,55,'para el moho en la ropa o en las casas ,',NULL),
(@vid,@bid,14,56,'y para las hinchazones, erupciones y manchas brillantes.',NULL),
(@vid,@bid,14,57,'Sirve para enseñar cuándo algo es impuro y cuándo es puro . Este es el reglamento sobre la lepra .',NULL),
(@vid,@bid,15,1,'Yahvé les habló a Moisés y a Aarón, y les dijo :',NULL),
(@vid,@bid,15,2,'“Díganles a los israelitas: ‘Cualquier hombre que tenga un flujo de su cuerpo es impuro a causa de ese flujo .',NULL),
(@vid,@bid,15,3,'Su impureza consiste en lo siguiente: ya sea que el flujo le salga del cuerpo o que se le retenga, el hombre es impuro.',NULL),
(@vid,@bid,15,4,'“‘ Cualquier cama donde se acueste y cualquier mueble donde se siente serán impuros.',NULL),
(@vid,@bid,15,5,'El que toque la cama del hombre impuro deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,6,'El que se siente en el mismo lugar donde se sentó el hombre impuro deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,7,'“‘El que toque el cuerpo de ese hombre deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,8,'“‘ Si el hombre del flujo le escupe a alguien que está puro , esa persona deberá lavar su ropa y bañarse, y quedará impura hasta el atardecer.',NULL),
(@vid,@bid,15,9,'“‘ Cualquier montura que use el hombre del flujo será impura.',NULL),
(@vid,@bid,15,10,'Cualquiera que toque lo que haya estado debajo de él quedará impuro hasta el atardecer. El que cargue con esas cosas deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,11,'“‘ Si el hombre del flujo toca a alguien sin haberse lavado primero las manos , esa persona deberá lavar su ropa y bañarse, y quedará impura hasta el atardecer.',NULL),
(@vid,@bid,15,12,'“‘ Cualquier olla de barro que toque el hombre del flujo deberá romperse, y cualquier utensilio de madera que toque deberá lavarse con agua .',NULL),
(@vid,@bid,15,13,'“‘ Cuando el hombre sane de su flujo , contará siete días para su purificación. Luego lavará su ropa y se bañará en agua de manantial, y quedará puro.',NULL),
(@vid,@bid,15,14,'“‘Al octavo día tomará dos tórtolas o dos pichones, se presentará ante Yahvé a la entrada de la Tienda del Encuentro y se los entregará al sacerdote .',NULL),
(@vid,@bid,15,15,'El sacerdote ofrecerá una de las aves como ofrenda por el pecado y la otra como holocausto . Así el sacerdote hará expiación por él delante de Yahvé a causa de su flujo .',NULL),
(@vid,@bid,15,16,'“‘ Si a un hombre le sale semen , deberá bañar todo su cuerpo en agua y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,17,'Cualquier ropa o cuero que se manche de semen deberá lavarse con agua y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,18,'Si un hombre y una mujer tienen relaciones sexuales y a él le sale semen , ambos deberán bañarse y quedarán impuros hasta el atardecer.',NULL),
(@vid,@bid,15,19,'“‘ Cuando una mujer tenga su período menstrual, su impureza durará siete días . Cualquiera que la toque quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,20,'“‘ Cualquier lugar donde ella se acueste o se siente durante su período será impuro.',NULL),
(@vid,@bid,15,21,'Cualquiera que toque la cama de ella deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,22,'Cualquiera que toque el mueble donde ella se sentó deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,23,'Ya sea que toque la cama o el mueble , quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,24,'“‘ Si un hombre se acuesta con ella y entra en contacto con la sangre de su menstruación, quedará impuro durante siete días , y cualquier cama donde él se acueste será impura.',NULL),
(@vid,@bid,15,25,'“‘ Si una mujer tiene un flujo de sangre durante muchos días fuera de su período normal, o si el sangrado le dura más tiempo de lo normal, será impura todo el tiempo que le dure el flujo , tal como en los días de su menstruación.',NULL),
(@vid,@bid,15,26,'Cualquier cama donde se acueste y cualquier mueble donde se siente durante esos días serán impuros, igual que en los días de su menstruación.',NULL),
(@vid,@bid,15,27,'Cualquiera que toque esas cosas quedará impuro, por lo que deberá lavar su ropa y bañarse, y quedará impuro hasta el atardecer.',NULL),
(@vid,@bid,15,28,'“‘ Cuando la mujer sane de su flujo , contará siete días , y después quedará pura.',NULL),
(@vid,@bid,15,29,'Al octavo día tomará dos tórtolas o dos pichones y se los llevará al sacerdote a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,15,30,'El sacerdote ofrecerá una de las aves como ofrenda por el pecado y la otra como holocausto . Así el sacerdote hará expiación por ella delante de Yahvé a causa de su flujo impuro.',NULL),
(@vid,@bid,15,31,'“‘ De esta manera ustedes mantendrán a los israelitas separados de sus cosas impuras, para que no mueran por contaminar mi santuario que está en medio de ellos’”.',NULL),
(@vid,@bid,15,32,'Este es el reglamento para el hombre que tiene un flujo o al que le sale semen y queda impuro;',NULL),
(@vid,@bid,15,33,'para la mujer que está en su período menstrual; para el hombre o la mujer que tenga un flujo , y para el hombre que se acueste con una mujer impura.',NULL),
(@vid,@bid,16,1,'Yahvé le habló a Moisés después de la muerte de los dos hijos de Aarón, quienes murieron al acercarse a la presencia de Yahvé.',NULL),
(@vid,@bid,16,2,'Le dijo : “Adviértele a tu hermano Aarón que no entre a cualquier hora en el Lugar Santísimo , que está detrás de la cortina, delante de la tapa del arca. Si lo hace, morirá , porque yo me apareceré en una nube por encima de esa tapa.',NULL),
(@vid,@bid,16,3,'“ Esta es la manera en que Aarón debe entrar al santuario : deberá llevar un becerro para la ofrenda por el pecado y un carnero para el holocausto .',NULL),
(@vid,@bid,16,4,'Deberá ponerse la túnica sagrada de lino y la ropa interior de lino. Además , se pondrá el cinturón de lino y el turbante de lino. Como es ropa sagrada, deberá bañarse primero y luego ponérsela.',NULL),
(@vid,@bid,16,5,'De parte de la comunidad de Israel , tomará dos machos cabríos para la ofrenda por el pecado y un carnero para el holocausto .',NULL),
(@vid,@bid,16,6,'“Aarón ofrecerá el becerro de la ofrenda por el pecado , el cual es para él mismo, y hará expiación por él y por su familia .',NULL),
(@vid,@bid,16,7,'Luego tomará los dos machos cabríos y los presentará delante de Yahvé a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,16,8,'Allí echará suertes para decidir cuál de los dos será para Yahvé y cuál será para soltarlo en el desierto.',NULL),
(@vid,@bid,16,9,'El macho cabrío que le toque a Yahvé, Aarón lo presentará como ofrenda por el pecado .',NULL),
(@vid,@bid,16,10,'Pero el macho cabrío que sea apartado para el desierto se presentará vivo delante de Yahvé para hacer expiación sobre él , y luego será soltado en el desierto .',NULL),
(@vid,@bid,16,11,'“Aarón presentará su propio becerro para la ofrenda por el pecado y hará expiación por él y por su familia . Después de degollar su becerro ,',NULL),
(@vid,@bid,16,12,'tomará un incensario lleno de brasas del altar que está delante de Yahvé, y lo llevará detrás de la cortina junto con dos puñados de incienso aromático en polvo.',NULL),
(@vid,@bid,16,13,'Allí, en la presencia de Yahvé, pondrá el incienso sobre el fuego para que el humo cubra la tapa que está sobre el arca del pacto; así no morirá .',NULL),
(@vid,@bid,16,14,'Luego tomará un poco de la sangre del becerro y con el dedo la rociará en la parte delantera de la tapa; también rociará la sangre con el dedo siete veces delante de la tapa.',NULL),
(@vid,@bid,16,15,'“ Después degollará el macho cabrío de la ofrenda por el pecado del pueblo , llevará la sangre detrás de la cortina y hará con ella lo mismo que hizo con la sangre del becerro : la rociará sobre la tapa y delante de ella .',NULL),
(@vid,@bid,16,16,'Así hará expiación por el Lugar Santísimo , purificándolo de las impurezas, rebeliones y pecados de los israelitas. Hará lo mismo por la Tienda del Encuentro, ya que está ubicada en medio de un pueblo impuro.',NULL),
(@vid,@bid,16,17,'Nadie más debe estar en la Tienda del Encuentro desde que Aarón entre a hacer la expiación en el Lugar Santísimo hasta que salga , después de haber hecho la expiación por sí mismo , por su familia y por toda la comunidad de Israel .',NULL),
(@vid,@bid,16,18,'“ Luego saldrá hacia el altar que está delante de Yahvé y hará expiación por él . Tomará un poco de la sangre del becerro y del macho cabrío, y la untará en todos los cuernos del altar .',NULL),
(@vid,@bid,16,19,'Con su dedo rociará la sangre sobre el altar siete veces para purificarlo y santificarlo de las impurezas de los israelitas.',NULL),
(@vid,@bid,16,20,'“Cuando Aarón termine de purificar el Lugar Santísimo , la Tienda del Encuentro y el altar , presentará el macho cabrío que quedó vivo .',NULL),
(@vid,@bid,16,21,'Le pondrá las dos manos en la cabeza y confesará sobre él todas las maldades , rebeliones y pecados de los israelitas. Así pondrá todos esos pecados sobre la cabeza del animal y lo enviará al desierto por medio de un hombre designado para esa tarea.',NULL),
(@vid,@bid,16,22,'El macho cabrío se llevará todos los pecados a un lugar solitario. Después de soltar al animal en el desierto ,',NULL),
(@vid,@bid,16,23,'“Aarón entrará de nuevo en la Tienda del Encuentro, se quitará la ropa de lino que se había puesto para entrar al Lugar Santísimo , y la dejará allí .',NULL),
(@vid,@bid,16,24,'Se bañará en un lugar sagrado, se pondrá su ropa normal y saldrá a presentar su propio holocausto y el holocausto del pueblo , para hacer expiación por sí mismo y por el pueblo .',NULL),
(@vid,@bid,16,25,'También quemará en el altar la grasa de la ofrenda por el pecado .',NULL),
(@vid,@bid,16,26,'“ El hombre que haya llevado el macho cabrío al desierto deberá lavar su ropa y bañarse antes de volver a entrar al campamento .',NULL),
(@vid,@bid,16,27,'El becerro y el macho cabrío de las ofrendas por el pecado , cuya sangre se llevó al Lugar Santísimo para hacer la expiación , deberán ser sacados del campamento , y quemarán en el fuego su piel , su carne y su excremento.',NULL),
(@vid,@bid,16,28,'El que los queme deberá lavar su ropa y bañarse antes de volver a entrar al campamento .',NULL),
(@vid,@bid,16,29,'“ Este será un reglamento perpetuo para ustedes: El día diez del mes séptimo , ayunarán y no harán ninguna clase de trabajo, ni los nacidos en el país ni los extranjeros que vivan entre ustedes.',NULL),
(@vid,@bid,16,30,'Porque en ese día se hará la expiación por ustedes para purificarlos, y quedarán limpios de todos sus pecados delante de Yahvé.',NULL),
(@vid,@bid,16,31,'Será para ustedes un día de descanso absoluto y de ayuno. Es un reglamento perpetuo .',NULL),
(@vid,@bid,16,32,'El sacerdote que haya sido ungido y consagrado para tomar el lugar de su padre hará la expiación . Se pondrá la ropa sagrada de lino',NULL),
(@vid,@bid,16,33,'y purificará el Lugar Santísimo , la Tienda del Encuentro y el altar . También hará la expiación por los sacerdotes y por toda la comunidad.',NULL),
(@vid,@bid,16,34,'“ Este será un reglamento perpetuo para ustedes: una vez al año se hará la expiación por todos los pecados de los israelitas”. Y Aarón hizo todo tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,17,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,17,2,'“ Diles a Aarón, a sus hijos y a todos los israelitas: ‘ Esto es lo que Yahvé ha ordenado :',NULL),
(@vid,@bid,17,3,'Cualquier hombre de la casa de Israel que degüelle un becerro, un cordero o una cabra dentro del campamento , o que lo degüelle fuera del campamento ,',NULL),
(@vid,@bid,17,4,'y no lo lleve a la entrada de la Tienda del Encuentro para presentarlo como ofrenda a Yahvé ante el santuario de Yahvé, será considerado culpable de derramar sangre . Ha derramado sangre , y ese hombre será eliminado de su pueblo .',NULL),
(@vid,@bid,17,5,'El propósito de esta ley es que los israelitas lleven a Yahvé los sacrificios que ahora ofrecen en el campo abierto. Deben llevarlos al sacerdote a la entrada de la Tienda del Encuentro, para ofrecerlos a Yahvé como sacrificios de paz.',NULL),
(@vid,@bid,17,6,'El sacerdote rociará la sangre sobre el altar de Yahvé a la entrada de la Tienda del Encuentro, y quemará la grasa como aroma agradable a Yahvé.',NULL),
(@vid,@bid,17,7,'Ya no ofrecerán más sus sacrificios a los ídolos en forma de chivo, con los cuales se han estado prostituyendo espiritualmente. Este será un reglamento perpetuo para todas sus generaciones ’.',NULL),
(@vid,@bid,17,8,'“También les dirás: ‘Cualquier hombre de la casa de Israel , o cualquier extranjero que viva entre ustedes, que ofrezca un holocausto o un sacrificio ,',NULL),
(@vid,@bid,17,9,'y no lo lleve a la entrada de la Tienda del Encuentro para ofrecerlo a Yahvé, ese hombre será eliminado de su pueblo .',NULL),
(@vid,@bid,17,10,'“‘ Si cualquier israelita , o cualquier extranjero que viva entre ustedes, come sangre de cualquier tipo, yo me pondré en contra de esa persona y la eliminaré de su pueblo .',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,17,11,'Porque la vida de toda criatura está en la sangre . Yo mismo se la he dado a ustedes sobre el altar para que hagan expiación por sus vidas , ya que es la sangre la que hace expiación por la vida .',NULL),
(@vid,@bid,17,12,'Por eso les he dicho a los israelitas: Ninguno de ustedes debe comer sangre , ni tampoco el extranjero que viva entre ustedes.',NULL),
(@vid,@bid,17,13,'“‘Cualquier israelita , o cualquier extranjero que viva entre ustedes, que cace un animal o un ave que esté permitido comer, deberá derramar su sangre y cubrirla con tierra .',NULL),
(@vid,@bid,17,14,'Porque la vida de toda criatura es su sangre . Por eso les he dicho a los israelitas: No coman la sangre de ninguna criatura, porque la vida de toda criatura es su sangre . Cualquiera que la coma será eliminado.',NULL),
(@vid,@bid,17,15,'“‘ Cualquier persona , sea israelita de nacimiento o extranjero , que coma carne de un animal que murió por sí solo o que fue despedazado por las fieras, deberá lavar su ropa y bañarse. Quedará impura hasta el atardecer y después quedará pura.',NULL),
(@vid,@bid,17,16,'Pero si no lava su ropa ni se baña, cargará con su culpa’”.',NULL),
(@vid,@bid,18,1,'Yahvé le dijo a Moisés :',NULL),
(@vid,@bid,18,2,'“ Háblales a los israelitas y diles : ‘Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,18,3,'No deben seguir las costumbres de la tierra de Egipto , donde ustedes vivieron. Tampoco sigan las costumbres de la tierra de Canaán , adonde los llevo. No se guíen por sus reglamentos.',NULL),
(@vid,@bid,18,4,'Ustedes deben cumplir mis leyes y obedecer mis reglamentos. Vivan de acuerdo con ellos . Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,18,5,'Obedezcan mis reglamentos y mis leyes, porque la persona que los cumpla, vivirá por ellos . Yo soy Yahvé.',NULL),
(@vid,@bid,18,6,'“‘ Ninguno de ustedes debe tener relaciones sexuales con un pariente cercano. Yo soy Yahvé.',NULL),
(@vid,@bid,18,7,'“‘ No deshonrarás a tu padre teniendo relaciones sexuales con tu madre. Ella es tu madre; no debes tener relaciones con ella .',NULL),
(@vid,@bid,18,8,'“‘ No tendrás relaciones sexuales con ninguna otra esposa de tu padre; eso deshonraría a tu padre.',NULL),
(@vid,@bid,18,9,'“‘ No tendrás relaciones sexuales con tu hermana, ya sea hija de tu padre o hija de tu madre, ya sea que haya nacido en la misma casa o en otra parte.',NULL),
(@vid,@bid,18,10,'“‘ No tendrás relaciones sexuales con tu nieta, ya sea la hija de tu hijo o la hija de tu hija , porque deshonrarla a ella es deshonrarte a ti mismo.',NULL),
(@vid,@bid,18,11,'“‘ No tendrás relaciones sexuales con la hija de una esposa de tu padre. Como ella es hija de tu padre, es tu media hermana.',NULL),
(@vid,@bid,18,12,'“‘ No tendrás relaciones sexuales con la hermana de tu padre, pues ella es pariente cercana de tu padre.',NULL),
(@vid,@bid,18,13,'“‘ No tendrás relaciones sexuales con la hermana de tu madre, pues ella es pariente cercana de tu madre.',NULL),
(@vid,@bid,18,14,'“‘ No deshonrarás al hermano de tu padre teniendo relaciones sexuales con su esposa. Ella es tu tía.',NULL),
(@vid,@bid,18,15,'“‘ No tendrás relaciones sexuales con tu nuera . Es la esposa de tu hijo ; no debes tener relaciones con ella .',NULL),
(@vid,@bid,18,16,'“‘ No tendrás relaciones sexuales con la esposa de tu hermano, pues eso deshonraría a tu hermano.',NULL),
(@vid,@bid,18,17,'“‘ No tendrás relaciones sexuales con una mujer y también con su hija . Tampoco te acostarás con su nieta, ya sea hija de su hijo o hija de su hija . Son parientes cercanas, y hacer eso es una perversidad.',NULL),
(@vid,@bid,18,18,'“‘Mientras tu esposa esté viva , no te casarás con su hermana para hacerla su rival y tener relaciones sexuales con ella .',NULL),
(@vid,@bid,18,19,'“‘ No te acercarás a una mujer para tener relaciones sexuales mientras ella esté en su período de impureza menstrual.',NULL),
(@vid,@bid,18,20,'“‘ No te acostarás con la esposa de tu prójimo, pues te contaminarías con ella.',NULL),
(@vid,@bid,18,21,'“‘ No entregarás a ninguno de tus hijos para que sea sacrificado en el fuego a Moloc. No profanes el nombre de tu Dios . Yo soy Yahvé.',NULL),
(@vid,@bid,18,22,'“‘ No te acostarás con un hombre como quien se acuesta con una mujer; es algo asqueroso.',NULL),
(@vid,@bid,18,23,'“‘ No tendrás relaciones sexuales con ningún animal, pues te contaminarías con él . Ninguna mujer debe presentarse ante un animal para aparearse con él ; es una perversión.',NULL),
(@vid,@bid,18,24,'“‘ No se contaminen con ninguna de estas cosas, porque las naciones que voy a expulsar de delante de ustedes se contaminaron haciendo todo esto.',NULL),
(@vid,@bid,18,25,'La tierra misma se contaminó . Por eso la castigué por sus pecados , y la tierra vomitó a sus habitantes .',NULL),
(@vid,@bid,18,26,'Por lo tanto, ustedes deben obedecer mis reglamentos y mis leyes, y no cometer ninguna de estas cosas asquerosas. Esto aplica tanto para los israelitas como para los extranjeros que viven entre ustedes.',NULL),
(@vid,@bid,18,27,'Los habitantes de esa tierra que vivieron antes que ustedes hicieron todas estas cosas asquerosas, y la tierra se contaminó .',NULL),
(@vid,@bid,18,28,'No permitan que la tierra los vomite a ustedes por haberla contaminado , tal como vomitó a la nación que vivía allí antes que ustedes.',NULL),
(@vid,@bid,18,29,'“‘ Cualquiera que haga alguna de estas cosas asquerosas, será eliminado de su pueblo .',NULL),
(@vid,@bid,18,30,'Cumplan mis mandamientos. No practiquen ninguna de las costumbres perversas que se practicaban antes de que ustedes llegaran, para que no se contaminen con ellas. Yo soy Yahvé, su Dios ’”.',NULL),
(@vid,@bid,19,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,19,2,'“ Háblales a todos los israelitas y diles : ‘ Sean santos , porque yo , Yahvé, su Dios , soy santo .',NULL),
(@vid,@bid,19,3,'“‘Cada uno de ustedes debe respetar a su madre y a su padre, y deben guardar mis días de descanso. Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,19,4,'“‘ No se vuelvan a los ídolos ni se hagan dioses de metal fundido. Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,19,5,'“‘ Cuando ofrezcan un sacrificio de paz a Yahvé, ofrézcanlo de la manera correcta para que sea aceptado.',NULL),
(@vid,@bid,19,6,'La carne debe comerse el mismo día que la ofrezcan o al día siguiente . Lo que quede para el tercer día deberá quemarse en el fuego.',NULL),
(@vid,@bid,19,7,'Si alguien come la carne al tercer día , el sacrificio será considerado asqueroso y no será aceptado.',NULL),
(@vid,@bid,19,8,'Cualquiera que lo coma cargará con su culpa por profanar lo que es sagrado para Yahvé, y esa persona será eliminada de su pueblo .',NULL),
(@vid,@bid,19,9,'“‘Cuando coseches los campos de tu tierra, no cortes hasta el último rincón del campo , ni recojas lo que se haya caído de la cosecha.',NULL),
(@vid,@bid,19,10,'Tampoco pases una segunda vez por tu viñedo ni recojas las uvas que se hayan caído. Déjalas para los pobres y para los extranjeros . Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,19,11,'“‘ No roben. “‘ No mientan. “‘ No se engañen unos a otros.',NULL),
(@vid,@bid,19,12,'“‘ No juren en mi nombre para decir una mentira , porque estarían profanando el nombre de su Dios . Yo soy Yahvé.',NULL),
(@vid,@bid,19,13,'“‘ No oprimas a tu prójimo ni le robes . “‘ No retengas el pago de un trabajador hasta la mañana siguiente.',NULL),
(@vid,@bid,19,14,'“‘ No maldigas al sordo , ni le pongas tropiezos al ciego . Más bien, teme a tu Dios . Yo soy Yahvé.',NULL),
(@vid,@bid,19,15,'“‘ No actúes con injusticia en un juicio . No favorezcas al pobre ni te dejes llevar por el poderoso; juzga a tu prójimo con justicia .',NULL),
(@vid,@bid,19,16,'“‘ No andes chismeando entre tu pueblo . “‘ No pongas en peligro la vida de tu prójimo . Yo soy Yahvé.',NULL),
(@vid,@bid,19,17,'“‘ No guardes odio en tu corazón contra tu hermano. Reprende a tu prójimo con franqueza, para que no te hagas cómplice de su pecado .',NULL),
(@vid,@bid,19,18,'“‘ No te vengues ni le guardes rencor a la gente de tu pueblo , sino ama a tu prójimo como a ti mismo. Yo soy Yahvé.',NULL),
(@vid,@bid,19,19,'“‘Obedezcan mis reglamentos. “‘ No cruces animales de distintas especies. “‘ No siembres tu campo con dos clases de semilla. “‘ No uses ropa hecha con hilos de dos clases de material.',NULL),
(@vid,@bid,19,20,'“‘ Si un hombre tiene relaciones sexuales con una esclava que está prometida en matrimonio a otro hombre, pero que no ha sido comprada ni liberada, ambos deberán ser castigados. Sin embargo, no se les condenará a muerte , porque ella no era libre.',NULL),
(@vid,@bid,19,21,'El hombre deberá llevar a la entrada de la Tienda del Encuentro un carnero como su ofrenda por la culpa ante Yahvé.',NULL),
(@vid,@bid,19,22,'Con el carnero de la ofrenda por la culpa, el sacerdote hará expiación por él delante de Yahvé por el pecado que cometió , y su pecado le será perdonado.',NULL),
(@vid,@bid,19,23,'“‘ Cuando entren a la tierra y planten cualquier clase de árbol frutal, considerarán que su fruto está prohibido durante los primeros tres años ; no deberán comerlo.',NULL),
(@vid,@bid,19,24,'Al cuarto año , todo el fruto será consagrado para alabar a Yahvé.',NULL),
(@vid,@bid,19,25,'Y en el quinto año ya podrán comer el fruto del árbol; de esa manera les dará una mayor cosecha. Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,19,26,'“‘ No coman carne que todavía tenga sangre . No practiquen la adivinación ni la hechicería.',NULL),
(@vid,@bid,19,27,'“‘ No se corten el pelo a los lados de la cabeza ni se recorten los bordes de la barba .',NULL),
(@vid,@bid,19,28,'“‘ No se hagan cortes en el cuerpo por los muertos, ni se hagan tatuajes. Yo soy Yahvé.',NULL),
(@vid,@bid,19,29,'“‘ No deshonres a tu hija haciéndola prostituta, para que el país no se llene de prostitución ni de perversidad.',NULL),
(@vid,@bid,19,30,'“‘ Guarden mis días de descanso y muestren respeto por mi santuario . Yo soy Yahvé.',NULL),
(@vid,@bid,19,31,'“‘No busquen el consejo de los médiums ni de los adivinos ; no se contaminen acudiendo a ellos. Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,19,32,'“‘Ponte de pie en presencia de las canas, muestra respeto por los ancianos y teme a tu Dios . Yo soy Yahvé.',NULL),
(@vid,@bid,19,33,'“‘ Cuando un extranjero viva entre ustedes en su país, no lo maltraten.',NULL),
(@vid,@bid,19,34,'Al extranjero que viva con ustedes lo tratarán como a uno de sus compatriotas. Ámalo como a ti mismo, porque también ustedes fueron extranjeros en Egipto . Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,19,35,'“‘ No usen medidas falsas para medir longitud, peso o capacidad.',NULL),
(@vid,@bid,19,36,'Usen balanzas exactas, pesas exactas y medidas exactas. Yo soy Yahvé, su Dios , quien los sacó de Egipto .',NULL),
(@vid,@bid,19,37,'“‘Obedezcan todos mis reglamentos y todas mis leyes, y pónganlos en práctica. Yo soy Yahvé’”.',NULL),
(@vid,@bid,20,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,20,2,'“Diles también a los israelitas: ‘Cualquier israelita , o cualquier extranjero que viva en Israel , que entregue a uno de sus hijos como sacrificio a Moloc, deberá ser condenado a muerte . El pueblo del país lo matará a pedradas.',NULL),
(@vid,@bid,20,3,'Yo mismo me pondré en contra de ese hombre y lo eliminaré de su pueblo , porque al entregarle su hijo a Moloc profanó mi santuario y deshonró mi santo nombre .',NULL),
(@vid,@bid,20,4,'Si la gente del país se hace de la vista gorda cuando ese hombre le entrega su hijo a Moloc y no lo matan,',NULL),
(@vid,@bid,20,5,'yo mismo me pondré en contra de él y de su familia , y lo eliminaré de su pueblo , junto con todos los que lo sigan en su prostitución espiritual para adorar a Moloc.',NULL),
(@vid,@bid,20,6,'“‘ Si alguien acude a médiums y adivinos , prostituyéndose al seguirlos, me pondré en contra de esa persona y la eliminaré de su pueblo .',NULL),
(@vid,@bid,20,7,'“‘ Por lo tanto, conságrense y sean santos , porque yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,20,8,'Obedezcan mis reglamentos y pónganlos en práctica. Yo soy Yahvé, el que los hace santos.',NULL),
(@vid,@bid,20,9,'“‘Cualquiera que maldiga a su padre o a su madre será condenado a muerte . Ha maldecido a sus padres, por lo que será el único responsable de su propia muerte .',NULL),
(@vid,@bid,20,10,'“‘Si un hombre comete adulterio con la esposa de otro hombre —es decir, con la esposa de su prójimo —, tanto el adúltero como la adúltera serán condenados a muerte .',NULL),
(@vid,@bid,20,11,'“‘Si un hombre tiene relaciones sexuales con la esposa de su padre, deshonra a su padre. Tanto el hombre como la mujer serán condenados a muerte ; serán los únicos responsables de su propia muerte .',NULL),
(@vid,@bid,20,12,'“‘Si un hombre tiene relaciones sexuales con su nuera , ambos serán condenados a muerte . Han cometido una perversidad; serán los únicos responsables de su propia muerte .',NULL),
(@vid,@bid,20,13,'“‘Si un hombre tiene relaciones sexuales con otro hombre como si fuera una mujer, ambos cometen un acto asqueroso y serán condenados a muerte ; serán los únicos responsables de su propia muerte .',NULL),
(@vid,@bid,20,14,'“‘ Si un hombre se casa con una mujer y también con la madre de ella , comete una gran perversidad. El hombre y las dos mujeres serán quemados en el fuego, para acabar con esa perversidad entre ustedes.',NULL),
(@vid,@bid,20,15,'“‘Si un hombre se aparea con un animal, será condenado a muerte , y el animal también será sacrificado.',NULL),
(@vid,@bid,20,16,'“‘Si una mujer se acerca a un animal para aparearse con él , deberán matar a la mujer y al animal. Serán condenados a muerte ; serán los únicos responsables de su propia muerte .',NULL),
(@vid,@bid,20,17,'“‘ Si un hombre se casa con su hermana, ya sea hija de su padre o de su madre, y tienen relaciones sexuales, cometen un acto vergonzoso. Serán eliminados a la vista de toda su gente . Ese hombre deshonró a su hermana, así que cargará con su culpa.',NULL),
(@vid,@bid,20,18,'“‘ Si un hombre tiene relaciones sexuales con una mujer durante su período menstrual, deshonra la fuente del flujo de la mujer, y ella queda descubierta . Ambos serán eliminados de su pueblo .',NULL),
(@vid,@bid,20,19,'“‘ No tendrás relaciones sexuales con la hermana de tu madre ni con la hermana de tu padre, porque sería deshonrar a un pariente cercano. Ambos cargarán con su culpa.',NULL),
(@vid,@bid,20,20,'Si un hombre tiene relaciones sexuales con la esposa de su tío , deshonra a su tío . Ambos cargarán con su pecado y morirán sin hijos.',NULL),
(@vid,@bid,20,21,'“‘ Si un hombre se casa con la esposa de su hermano, comete un acto impuro. Deshonró a su hermano y no tendrán hijos.',NULL),
(@vid,@bid,20,22,'“‘Obedezcan todos mis reglamentos y todas mis leyes, y pónganlos en práctica. Así no los vomitará la tierra a la que los llevo para vivir.',NULL),
(@vid,@bid,20,23,'No sigan las costumbres de las naciones que voy a expulsar de delante de ustedes. Ellas hicieron todas estas cosas asquerosas y por eso las detesto.',NULL),
(@vid,@bid,20,24,'A ustedes les he dicho: “Ustedes tomarán posesión de la tierra de ellos . Yo se la daré a ustedes como herencia, una tierra donde abundan la leche y la miel ”. Yo soy Yahvé, su Dios , que los ha separado de las demás naciones.',NULL),
(@vid,@bid,20,25,'“‘Por lo tanto, deben hacer una distinción entre los animales puros y los impuros, y entre las aves puras y las impuras. No se vuelvan asquerosos a ustedes mismos por comer algún animal , ave o criatura que se arrastra por el suelo, de los cuales les he dicho que son impuros.',NULL),
(@vid,@bid,20,26,'Sean santos para mí , porque yo , Yahvé, soy santo . Yo los he separado de las demás naciones para que sean míos.',NULL),
(@vid,@bid,20,27,'“‘Cualquier hombre o mujer que sea médium o adivino será condenado a muerte . Serán apedreados y serán los únicos responsables de su propia muerte ’”.',NULL),
(@vid,@bid,21,1,'Yahvé le dijo a Moisés : “Diles a los sacerdotes , los hijos de Aarón: ‘ Ningún sacerdote debe hacerse impuro por asistir al funeral de alguien de su pueblo ,',NULL),
(@vid,@bid,21,2,'a menos que se trate de un pariente muy cercano : su madre, su padre, su hijo , su hija o su hermano.',NULL),
(@vid,@bid,21,3,'También puede hacerse impuro por su hermana virgen que dependa de él y que no se haya casado; por ella sí puede hacerse impuro.',NULL),
(@vid,@bid,21,4,'Pero como líder de su pueblo , no debe hacerse impuro ni profanarse.',NULL),
(@vid,@bid,21,5,'“‘Los sacerdotes no deben raparse la cabeza , ni recortarse los bordes de la barba , ni hacerse cortes en el cuerpo.',NULL),
(@vid,@bid,21,6,'Deben ser santos para su Dios y no deshonrar el nombre de su Dios . Son ellos quienes presentan las ofrendas hechas por fuego a Yahvé, que son el alimento de su Dios ; por lo tanto, deben ser santos .',NULL),
(@vid,@bid,21,7,'“‘ No deben casarse con una mujer que se haya prostituido o deshonrado. El sacerdote tampoco debe casarse con una mujer divorciada, porque él está consagrado a su Dios.',NULL),
(@vid,@bid,21,8,'Por eso deben considerarlo santo , porque es él quien ofrece el alimento de su Dios . Será santo para ustedes, porque yo , Yahvé, que los hago santos , soy santo .',NULL),
(@vid,@bid,21,9,'“‘ Si la hija de un sacerdote se deshonra volviéndose prostituta, deshonra a su padre; deberá ser quemada en el fuego.',NULL),
(@vid,@bid,21,10,'“‘ El sumo sacerdote , el líder de sus hermanos, sobre cuya cabeza se derramó el aceite de la unción y que fue consagrado para llevar la ropa sacerdotal, no debe andar despeinado ni rasgarse la ropa en señal de luto.',NULL),
(@vid,@bid,21,11,'No debe acercarse a ningún cadáver; no debe hacerse impuro ni siquiera por la muerte de su padre o de su madre.',NULL),
(@vid,@bid,21,12,'Tampoco debe salir del área del santuario ni profanar el santuario de su Dios , porque lleva sobre sí la consagración del aceite de la unción de su Dios . Yo soy Yahvé.',NULL),
(@vid,@bid,21,13,'“‘Deberá casarse con una mujer virgen .',NULL),
(@vid,@bid,21,14,'No debe casarse con una viuda, ni con una divorciada, ni con una mujer deshonrada, ni con una prostituta. Se casará con una virgen de su propio pueblo .',NULL),
(@vid,@bid,21,15,'Así no deshonrará a su descendencia entre su pueblo , porque yo soy Yahvé, el que lo hace santo ’”.',NULL),
(@vid,@bid,21,16,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,21,17,'“Dile a Aarón: ‘ Ninguno de tus descendientes, de ninguna generación , que tenga algún defecto físico podrá acercarse a ofrecer el alimento de su Dios.',NULL),
(@vid,@bid,21,18,'Porque ningún hombre que tenga algún defecto podrá acercarse: ni el ciego , ni el cojo , ni el que tenga la cara deforme, ni el que tenga alguna otra deformidad,',NULL),
(@vid,@bid,21,19,'ni el que tenga fracturado el pie o la mano ,',NULL),
(@vid,@bid,21,20,'ni el jorobado, ni el enano, ni el que tenga un defecto en el ojo , ni el que tenga sarna o tiña, ni el que tenga los testículos aplastados.',NULL),
(@vid,@bid,21,21,'Ningún descendiente del sacerdote Aarón que tenga algún defecto físico podrá acercarse a presentar las ofrendas hechas por fuego a Yahvé. Ya que tiene un defecto, no podrá acercarse a ofrecer el alimento de su Dios .',NULL),
(@vid,@bid,21,22,'Sí podrá comer del alimento de su Dios, tanto de las ofrendas muy santas como de las ofrendas santas .',NULL),
(@vid,@bid,21,23,'Sin embargo, como tiene un defecto físico, no debe acercarse a la cortina del santuario ni acercarse al altar . Así no profanará mis cosas santas, porque yo soy Yahvé, el que las hace santas’”.',NULL),
(@vid,@bid,21,24,'Y Moisés le comunicó todo esto a Aarón, a sus hijos y a todos los israelitas.',NULL),
(@vid,@bid,22,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,22,2,'“ Diles a Aarón y a sus hijos que tengan cuidado con las ofrendas sagradas que los israelitas me consagran , para que no deshonren mi santo nombre . Yo soy Yahvé.',NULL),
(@vid,@bid,22,3,'“Diles: ‘ Cualquiera de sus descendientes, de cualquier generación , que estando en estado de impureza se acerque a las ofrendas sagradas que los israelitas consagran a Yahvé, será eliminado de mi presencia . Yo soy Yahvé.',NULL),
(@vid,@bid,22,4,'“‘ Ningún descendiente de Aarón que tenga una infección de lepra o que tenga un flujo, podrá comer de las ofrendas sagradas hasta que quede puro. El que toque algo que se haya vuelto impuro por causa de un cadáver, o el hombre que tenga un derrame de semen ,',NULL),
(@vid,@bid,22,5,'o el que toque cualquier animal que se arrastra que pueda hacerlo impuro, o el que toque a cualquier persona que lo haga impuro, cualquiera que sea su impureza,',NULL),
(@vid,@bid,22,6,'la persona que toque algo de esto quedará impura hasta el atardecer, y no podrá comer de las ofrendas sagradas a menos que se bañe.',NULL),
(@vid,@bid,22,7,'Cuando se ponga el sol , quedará puro, y entonces podrá comer de las ofrendas sagradas , porque son su alimento.',NULL),
(@vid,@bid,22,8,'No debe comer carne de ningún animal que muera por sí solo o que sea despedazado por las fieras, pues se volvería impuro por ello. Yo soy Yahvé.',NULL),
(@vid,@bid,22,9,'“‘ Los sacerdotes deberán cumplir mis requisitos; de lo contrario, serán culpables y morirán por haber profanado las ofrendas. Yo soy Yahvé, el que los hace santos.',NULL),
(@vid,@bid,22,10,'“‘ Ninguna persona que no sea de la familia del sacerdote podrá comer de la ofrenda sagrada; ni el huésped del sacerdote ni su empleado a sueldo podrán comer de ella .',NULL),
(@vid,@bid,22,11,'Pero si un sacerdote compra a un esclavo con su propio dinero , este sí podrá comer de la ofrenda. También los esclavos nacidos en su casa podrán comer de su alimento.',NULL),
(@vid,@bid,22,12,'Si la hija de un sacerdote se casa con alguien que no es sacerdote , ya no podrá comer de las ofrendas sagradas que se le presentan a Yahvé.',NULL),
(@vid,@bid,22,13,'Pero si ella queda viuda o se divorcia, no tiene hijos y regresa a vivir a la casa de su padre como cuando era joven, podrá comer del alimento de su padre. Sin embargo, nadie más fuera de la familia del sacerdote podrá comer de ese alimento.',NULL),
(@vid,@bid,22,14,'“‘ Si alguien come por error de una ofrenda sagrada, deberá pagarle al sacerdote el valor de la ofrenda sagrada más una quinta parte de su valor como multa.',NULL),
(@vid,@bid,22,15,'Los sacerdotes no deben profanar las ofrendas sagradas que los israelitas le presentan a Yahvé,',NULL),
(@vid,@bid,22,16,'al permitir que gente no autorizada se las coma y cargue así con la culpa. Porque yo soy Yahvé, el que las hace santas ’”.',NULL),
(@vid,@bid,22,17,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,22,18,'“ Háblales a Aarón, a sus hijos y a todos los israelitas, y diles : ‘ Cualquier israelita , o cualquier extranjero que viva en Israel , que presente un holocausto a Yahvé, ya sea para cumplir una promesa o como ofrenda voluntaria ,',NULL),
(@vid,@bid,22,19,'deberá ofrecer un macho sin defecto de entre las vacas , las ovejas o las cabras , para que la ofrenda le sea aceptada.',NULL),
(@vid,@bid,22,20,'No deben ofrecer ningún animal que tenga algún defecto, porque no les será aceptado.',NULL),
(@vid,@bid,22,21,'Cuando alguien le ofrezca a Yahvé un sacrificio de paz, ya sea del ganado o del rebaño , para cumplir una promesa o como ofrenda voluntaria , el animal deberá estar en perfectas condiciones para ser aceptado. No debe tener ningún defecto.',NULL),
(@vid,@bid,22,22,'No le ofrecerán a Yahvé ningún animal ciego , lastimado, mutilado, ni que tenga verrugas, sarna o tiña; no pondrán animales con estos defectos sobre el altar como ofrenda hecha por fuego a Yahvé.',NULL),
(@vid,@bid,22,23,'Podrán presentar como ofrenda voluntaria un toro joven o un cordero que tenga alguna parte del cuerpo más larga o más corta de lo normal, pero no será aceptado para cumplir una promesa.',NULL),
(@vid,@bid,22,24,'No le ofrecerán a Yahvé un animal que tenga los testículos lastimados, aplastados, desgarrados o cortados. Esto no lo deben hacer en el país de ustedes.',NULL),
(@vid,@bid,22,25,'Tampoco aceptarán de manos de un extranjero animales con estos defectos para ofrecerlos como el alimento de su Dios. Tienen defectos y están dañados, así que no les serán aceptados’”.',NULL),
(@vid,@bid,22,26,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,22,27,'“ Cuando nazca un ternero, un corderito o un cabrito, deberá quedarse con su madre durante siete días . A partir del octavo día podrá ser aceptado como ofrenda hecha por fuego a Yahvé.',NULL),
(@vid,@bid,22,28,'No degüellen una vaca ni una oveja el mismo día que degüellen a su cría.',NULL),
(@vid,@bid,22,29,'“ Cuando le ofrezcan a Yahvé un sacrificio de acción de gracias, háganlo de la manera correcta para que les sea aceptado.',NULL),
(@vid,@bid,22,30,'Deberán comérselo ese mismo día ; no dejen nada para la mañana siguiente. Yo soy Yahvé.',NULL),
(@vid,@bid,22,31,'“Por lo tanto, obedezcan mis mandamientos y pónganlos en práctica. Yo soy Yahvé.',NULL),
(@vid,@bid,22,32,'No deshonren mi santo nombre ; más bien, debo ser tratado como santo entre los israelitas. Yo soy Yahvé, el que los hace santos ,',NULL),
(@vid,@bid,22,33,'el que los sacó de Egipto para ser su Dios . Yo soy Yahvé”.',NULL),
(@vid,@bid,23,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,23,2,'“ Háblales a los israelitas y diles : ‘ Estas son las fiestas señaladas de Yahvé, las cuales ustedes proclamarán como asambleas santas .',NULL),
(@vid,@bid,23,3,'“‘Trabajarán durante seis días , pero el séptimo día será de descanso absoluto, un día de asamblea santa . No harán ninguna clase de trabajo. Dondequiera que ustedes vivan, será un día de descanso dedicado a Yahvé.',NULL),
(@vid,@bid,23,4,'“‘Las siguientes son las fiestas señaladas de Yahvé, las asambleas santas que deberán proclamar en las fechas establecidas:',NULL),
(@vid,@bid,23,5,'El día catorce del primer mes , al anochecer, se celebrará la Pascua de Yahvé.',NULL),
(@vid,@bid,23,6,'El día quince de ese mismo mes comienza la Fiesta de los Panes sin Levadura en honor a Yahvé. Durante siete días comerán pan hecho sin levadura.',NULL),
(@vid,@bid,23,7,'El primer día celebrarán una asamblea santa ; no harán ningún trabajo habitual.',NULL),
(@vid,@bid,23,8,'Durante siete días le presentarán a Yahvé ofrendas hechas por fuego. El séptimo día celebrarán otra asamblea santa y tampoco harán ningún trabajo habitual’”.',NULL),
(@vid,@bid,23,9,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,23,10,'“ Háblales a los israelitas y diles : ‘ Cuando entren a la tierra que les voy a dar y cosechen los primeros frutos, le llevarán al sacerdote un manojo de las primeras espigas de su cosecha.',NULL),
(@vid,@bid,23,11,'El sacerdote mecerá el manojo delante de Yahvé para que la ofrenda les sea aceptada; lo mecerá el día después del día de descanso.',NULL),
(@vid,@bid,23,12,'El mismo día que mezan el manojo, ofrecerán un cordero de un año y sin defecto como holocausto a Yahvé.',NULL),
(@vid,@bid,23,13,'Lo acompañarán con una ofrenda de cereal de dos kilos de harina fina amasada con aceite . Esta será una ofrenda hecha por fuego, de aroma agradable a Yahvé. La acompañarán también con una ofrenda de un litro y medio de vino .',NULL),
(@vid,@bid,23,14,'No deberán comer pan , ni grano tostado , ni grano nuevo, hasta el día en que le lleven esta ofrenda a su Dios. Este será un reglamento perpetuo para sus descendientes, dondequiera que vivan.',NULL),
(@vid,@bid,23,15,'“‘ A partir del día después del día de descanso, es decir, desde el día en que llevaron el manojo de espigas de la ofrenda mecida, contarán siete semanas completas.',NULL),
(@vid,@bid,23,16,'Contarán cincuenta días hasta el día después del séptimo día de descanso, y entonces le presentarán a Yahvé una ofrenda de grano nuevo .',NULL),
(@vid,@bid,23,17,'Desde los lugares donde vivan, llevarán dos panes para presentarlos como ofrenda mecida. Estarán hechos con dos kilos de harina fina y horneados con levadura, como los primeros frutos para Yahvé.',NULL),
(@vid,@bid,23,18,'Junto con el pan , ofrecerán siete corderos de un año y sin defecto, un toro joven y dos carneros. Todos estos se presentarán como un holocausto a Yahvé, junto con sus ofrendas de cereal y ofrendas líquidas; será una ofrenda hecha por fuego, de aroma agradable a Yahvé.',NULL),
(@vid,@bid,23,19,'También sacrificarán un macho cabrío como ofrenda por el pecado , y dos corderos de un año como sacrificio de paz.',NULL),
(@vid,@bid,23,20,'El sacerdote los mecerá delante de Yahvé junto con el pan de los primeros frutos y con los dos corderos . Estas ofrendas son sagradas para Yahvé y le pertenecerán al sacerdote .',NULL),
(@vid,@bid,23,21,'Ese mismo día convocarán una asamblea santa y no harán ningún trabajo habitual. Este será un reglamento perpetuo para sus descendientes, dondequiera que vivan.',NULL),
(@vid,@bid,23,22,'“‘Cuando cosechen los campos de su tierra, no corten hasta el último rincón del campo , ni recojan lo que se haya caído de la cosecha. Déjenlo para los pobres y para los extranjeros . Yo soy Yahvé, su Dios ’”.',NULL),
(@vid,@bid,23,23,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,23,24,'“ Diles a los israelitas: ‘ El primer día del séptimo mes será un día de descanso absoluto para ustedes. Será un día de conmemoración, anunciado con toques de trompeta, y celebrarán una asamblea santa .',NULL),
(@vid,@bid,23,25,'No harán ningún trabajo habitual, y le presentarán a Yahvé una ofrenda hecha por fuego’”.',NULL),
(@vid,@bid,23,26,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,23,27,'“ El día diez del séptimo mes será el Día de la Expiación. Celebrarán una asamblea santa , ayunarán y le presentarán a Yahvé una ofrenda hecha por fuego.',NULL),
(@vid,@bid,23,28,'No harán ningún trabajo en ese día , porque es el Día de la Expiación , cuando se hace expiación por ustedes delante de Yahvé su Dios .',NULL),
(@vid,@bid,23,29,'Cualquiera que no ayune en ese día será eliminado de su pueblo .',NULL),
(@vid,@bid,23,30,'Y a cualquiera que haga algún trabajo en ese día , yo lo destruiré de entre su pueblo .',NULL),
(@vid,@bid,23,31,'No harán ninguna clase de trabajo. Este será un reglamento perpetuo para sus descendientes, dondequiera que vivan.',NULL),
(@vid,@bid,23,32,'Será para ustedes un día de descanso absoluto en el que ayunarán. Comenzarán su descanso la tarde del día nueve del mes , y lo guardarán desde esa tarde hasta la tarde siguiente”.',NULL),
(@vid,@bid,23,33,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,23,34,'“ Diles a los israelitas: ‘ El día quince del séptimo mes comienza la Fiesta de las Enramadas, la cual durará siete días en honor a Yahvé.',NULL),
(@vid,@bid,23,35,'El primer día celebrarán una asamblea santa y no harán ningún trabajo habitual.',NULL),
(@vid,@bid,23,36,'Durante siete días le presentarán a Yahvé ofrendas hechas por fuego. El octavo día celebrarán otra asamblea santa y le presentarán a Yahvé ofrendas hechas por fuego. Será una asamblea solemne y no harán ningún trabajo habitual.',NULL),
(@vid,@bid,23,37,'“‘Estas son las fiestas señaladas de Yahvé, las cuales ustedes proclamarán como asambleas santas para presentar ofrendas hechas por fuego a Yahvé — holocaustos , ofrendas de cereal, sacrificios y ofrendas líquidas—, cada una en su día indicado.',NULL),
(@vid,@bid,23,38,'Estas fiestas son adicionales a los días de descanso de Yahvé, a los regalos que ustedes le den, a todas las promesas que le hagan y a todas las ofrendas voluntarias que le presenten a Yahvé.',NULL),
(@vid,@bid,23,39,'“‘Así que el día quince del séptimo mes , después de haber recogido las cosechas de la tierra, celebrarán la fiesta de Yahvé durante siete días . El primer día será de descanso absoluto, y el octavo día también será de descanso absoluto.',NULL),
(@vid,@bid,23,40,'El primer día tomarán frutos de los árboles más hermosos, ramas de palmeras , ramas de árboles frondosos y sauces de los arroyos , y se alegrarán delante de Yahvé su Dios durante siete días .',NULL),
(@vid,@bid,23,41,'Celebrarán esta fiesta en honor a Yahvé durante siete días cada año . Este será un reglamento perpetuo para sus descendientes; la celebrarán en el séptimo mes .',NULL),
(@vid,@bid,23,42,'Vivirán en enramadas durante siete días . Todos los israelitas de nacimiento vivirán en enramadas,',NULL),
(@vid,@bid,23,43,'para que sus descendientes sepan que yo hice que los israelitas vivieran en enramadas cuando los saqué de Egipto . Yo soy Yahvé, su Dios ’”.',NULL),
(@vid,@bid,23,44,'Y Moisés les anunció a los israelitas las fiestas señaladas de Yahvé.',NULL),
(@vid,@bid,24,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,24,2,'“Ordénales a los israelitas que te traigan aceite puro de olivas machacadas para el alumbrado, a fin de que las lámparas ardan continuamente .',NULL),
(@vid,@bid,24,3,'Aarón se encargará de mantener las lámparas encendidas delante de Yahvé desde la tarde hasta la mañana de manera continua . Las lámparas estarán fuera de la cortina que oculta el arca del pacto, en la Tienda del Encuentro. Este será un reglamento perpetuo para sus descendientes.',NULL),
(@vid,@bid,24,4,'Aarón deberá mantener siempre en orden las lámparas sobre el candelabro de oro puro , delante de Yahvé.',NULL),
(@vid,@bid,24,5,'“ Tomarás harina fina y hornearás doce panes, usando alrededor de dos kilos de harina para cada pan.',NULL),
(@vid,@bid,24,6,'Los colocarás en dos hileras, seis en cada hilera, sobre la mesa de oro puro que está delante de Yahvé.',NULL),
(@vid,@bid,24,7,'Pondrás incienso puro junto a cada hilera de pan . El incienso servirá como ofrenda memorial, una ofrenda hecha por fuego a Yahvé.',NULL),
(@vid,@bid,24,8,'Cada día de descanso, el sacerdote deberá colocar el pan en orden delante de Yahvé de manera continua . Es una ofrenda de parte de los israelitas como un pacto eterno .',NULL),
(@vid,@bid,24,9,'El pan le pertenecerá a Aarón y a sus hijos , quienes se lo comerán en un lugar sagrado . De las ofrendas hechas por fuego a Yahvé, esta será la porción más santa para ellos , por reglamento perpetuo ”.',NULL),
(@vid,@bid,24,10,'Hubo un pleito en el campamento entre un israelita y el hijo de una mujer israelita cuyo padre era egipcio .',NULL),
(@vid,@bid,24,11,'En medio del pleito, el hijo de la mujer israelita blasfemó el Nombre de Yahvé y lo maldijo , por lo que lo llevaron ante Moisés . La madre de este hombre se llamaba Selomit, hija de Dibri, de la tribu de Dan .',NULL),
(@vid,@bid,24,12,'Lo pusieron bajo vigilancia hasta que Yahvé les declarara qué debían hacer.',NULL),
(@vid,@bid,24,13,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,24,14,'“ Saca del campamento al hombre que maldijo mi nombre. Que todos los que lo escucharon pongan las manos sobre la cabeza de él , y que toda la comunidad lo mate a pedradas.',NULL),
(@vid,@bid,24,15,'Además , diles a los israelitas: ‘Cualquiera que maldiga a su Dios cargará con su culpa .',NULL),
(@vid,@bid,24,16,'Cualquiera que blasfeme el nombre de Yahvé será condenado a muerte ; toda la comunidad lo matará a pedradas. Ya sea extranjero o israelita de nacimiento, el que blasfeme el Nombre deberá morir .',NULL),
(@vid,@bid,24,17,'“‘ Cualquiera que le quite la vida a otra persona será condenado a muerte .',NULL),
(@vid,@bid,24,18,'Cualquiera que mate el animal de otra persona deberá pagarle un animal vivo para reemplazar el que mató .',NULL),
(@vid,@bid,24,19,'Si alguien lastima a su prójimo, se le hará a él lo mismo que él hizo :',NULL),
(@vid,@bid,24,20,'fractura por fractura, ojo por ojo , diente por diente . La misma lesión que le haya causado a la otra persona, se le causará a él.',NULL),
(@vid,@bid,24,21,'Así que, el que mate un animal deberá reponerlo, pero el que mate a una persona será condenado a muerte .',NULL),
(@vid,@bid,24,22,'Este reglamento aplicará por igual tanto para el extranjero como para el israelita de nacimiento, porque yo soy Yahvé, su Dios ’”.',NULL),
(@vid,@bid,24,23,'Moisés les comunicó todo esto a los israelitas, y ellos sacaron fuera del campamento al hombre que había maldecido el Nombre y lo mataron a pedradas. Así que los israelitas hicieron todo tal como Yahvé se lo había ordenado a Moisés .',NULL),
(@vid,@bid,25,1,'Yahvé le habló a Moisés en el monte Sinaí y le dijo :',NULL),
(@vid,@bid,25,2,'“ Háblales a los israelitas y diles : ‘ Cuando ustedes entren en la tierra que les doy , la tierra deberá tener un año de reposo dedicado a Yahvé.',NULL),
(@vid,@bid,25,3,'Durante seis años sembrarás tu campo , podarás tu viñedo y recogerás sus frutos ,',NULL),
(@vid,@bid,25,4,'pero el séptimo año será un año de reposo absoluto para la tierra, un año de reposo dedicado a Yahvé. No sembrarás tu campo ni podarás tu viñedo.',NULL),
(@vid,@bid,25,5,'Tampoco cosecharás lo que crezca por sí solo de tu cosecha, ni recogerás las uvas de tu viñedo sin podar. Será un año de descanso absoluto para la tierra.',NULL),
(@vid,@bid,25,6,'Lo que la tierra produzca por sí misma durante su reposo servirá de alimento para ti , para tus esclavos y esclavas, para tus jornaleros y para los extranjeros que vivan contigo .',NULL),
(@vid,@bid,25,7,'Todo lo que produzca la tierra también servirá de alimento para tu ganado y para los animales silvestres de tu tierra.',NULL),
(@vid,@bid,25,8,'“‘Contarás siete años de reposo, es decir, siete veces siete años . Ese período de siete años de reposo te dará un total de cuarenta y nueve años .',NULL),
(@vid,@bid,25,9,'Entonces , el día diez del séptimo mes , harás sonar la trompeta por todas partes. Ese día , que es el Día de la Expiación, tocarán la trompeta por toda su tierra.',NULL),
(@vid,@bid,25,10,'Consagrarán el año cincuenta y proclamarán libertad en todo el país para todos sus habitantes . Será un año de jubileo para ustedes, en el que cada uno volverá a su propiedad familiar y a su propia familia .',NULL),
(@vid,@bid,25,11,'Ese año cincuenta será un año de jubileo para ustedes. Durante ese año no sembrarán, ni cosecharán lo que crezca por sí solo , ni recogerán las uvas de los viñedos sin podar.',NULL),
(@vid,@bid,25,12,'Porque es el jubileo , y será sagrado para ustedes. Solo comerán lo que el campo produzca por sí mismo .',NULL),
(@vid,@bid,25,13,'“‘En este año de jubileo cada uno de ustedes volverá a su propiedad familiar.',NULL),
(@vid,@bid,25,14,'“‘ Si le vendes algo a tu prójimo o le compras algo , no se perjudiquen ni se engañen el uno al otro.',NULL),
(@vid,@bid,25,15,'Cuando le compres tierras a tu prójimo, el precio se fijará de acuerdo con el número de años que hayan pasado desde el último jubileo . El precio de venta se basará en el número de años de cosecha que falten para el próximo jubileo .',NULL),
(@vid,@bid,25,16,'Si faltan muchos años , el precio será mayor , pero si faltan pocos , el precio será menor , porque lo que en realidad te está vendiendo es el número de cosechas.',NULL),
(@vid,@bid,25,17,'No se opriman unos a otros, sino teman a su Dios . Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,25,18,'“‘ Por lo tanto , pongan en práctica mis reglamentos y cumplan mis leyes. Así vivirán seguros en su tierra.',NULL),
(@vid,@bid,25,19,'La tierra producirá sus frutos , ustedes comerán hasta quedar satisfechos y vivirán seguros en ella .',NULL),
(@vid,@bid,25,20,'Tal vez se pregunten: “¿ Qué comeremos el séptimo año si no sembramos ni recogemos nuestras cosechas?”.',NULL),
(@vid,@bid,25,21,'Pues bien, el sexto año les enviaré tal bendición que la tierra producirá cosechas suficientes para tres años .',NULL),
(@vid,@bid,25,22,'Cuando siembren en el octavo año , todavía estarán comiendo de la cosecha anterior, y seguirán comiendo de ella hasta el noveno año , cuando llegue la nueva cosecha.',NULL),
(@vid,@bid,25,23,'“‘ La tierra no se venderá de forma permanente, porque la tierra es mía; ustedes son solo extranjeros y huéspedes míos.',NULL),
(@vid,@bid,25,24,'Por lo tanto, en todo el país que ustedes posean deberán garantizar el derecho de rescatar la tierra.',NULL),
(@vid,@bid,25,25,'“‘ Si uno de tus hermanos se empobrece y tiene que vender parte de su propiedad, su pariente más cercano podrá venir y comprar lo que su hermano haya vendido, para que la propiedad vuelva a la familia.',NULL),
(@vid,@bid,25,26,'Si no hay nadie que pueda rescatar la propiedad, pero el hombre prospera y consigue dinero suficiente para comprarla de nuevo,',NULL),
(@vid,@bid,25,27,'calculará los años que han pasado desde la venta y le devolverá la diferencia al hombre a quien se la vendió . De esta manera recuperará su propiedad.',NULL),
(@vid,@bid,25,28,'Pero si no consigue dinero suficiente para recuperarla, la propiedad quedará en manos del comprador hasta el año de jubileo . En el jubileo la propiedad quedará libre, y el hombre recuperará su tierra.',NULL),
(@vid,@bid,25,29,'“‘ Si alguien vende una casa de vivienda en una ciudad rodeada de murallas, tendrá el derecho de rescatarla durante un año completo a partir de la fecha de venta. Solo tendrá derecho de rescate durante ese año .',NULL),
(@vid,@bid,25,30,'Si la casa en la ciudad amurallada no es rescatada antes de cumplirse el año , pasará a ser propiedad definitiva del comprador y de sus descendientes. No quedará libre en el año de jubileo .',NULL),
(@vid,@bid,25,31,'Sin embargo, las casas en las aldeas que no tienen murallas se considerarán igual que los campos abiertos; podrán ser rescatadas y quedarán libres en el año de jubileo .',NULL),
(@vid,@bid,25,32,'“‘En cuanto a las ciudades de los levitas , ellos tendrán siempre el derecho de rescatar las casas en las ciudades que les pertenecen.',NULL),
(@vid,@bid,25,33,'Si un levita no rescata la casa que vendió en su ciudad , de todas maneras la casa quedará libre en el año de jubileo , porque las casas en las ciudades levitas son su propiedad exclusiva entre los israelitas.',NULL),
(@vid,@bid,25,34,'Sin embargo, los campos de pastoreo que rodean sus ciudades no se podrán vender, porque son su posesión permanente.',NULL),
(@vid,@bid,25,35,'“‘ Si uno de tus hermanos se empobrece y no puede mantenerse por sí mismo entre ustedes, deberás ayudarlo, y vivirá contigo como si fuera un extranjero o un huésped.',NULL),
(@vid,@bid,25,36,'No le cobres intereses ni trates de sacarle provecho. Teme a tu Dios y permite que tu hermano siga viviendo entre ustedes.',NULL),
(@vid,@bid,25,37,'No le prestes dinero con intereses ni le des comida buscando ganancia.',NULL),
(@vid,@bid,25,38,'Yo soy Yahvé, su Dios , quien los sacó de Egipto para darles la tierra de Canaán y para ser su Dios .',NULL),
(@vid,@bid,25,39,'“‘ Si uno de tus hermanos se empobrece y tiene que venderse a ti , no lo hagas trabajar como esclavo.',NULL),
(@vid,@bid,25,40,'Lo tratarás como a un trabajador contratado o como a un huésped, y trabajará para ti hasta el año de jubileo .',NULL),
(@vid,@bid,25,41,'En ese año quedará libre de ti , él y sus hijos , y volverá a su propia familia y a la propiedad de sus antepasados.',NULL),
(@vid,@bid,25,42,'Porque los israelitas son mis siervos , los que saqué de la tierra de Egipto . No deben ser vendidos como esclavos comunes.',NULL),
(@vid,@bid,25,43,'No lo tratarás con dureza, sino que temerás a tu Dios.',NULL),
(@vid,@bid,25,44,'“‘Sin embargo, puedes comprar esclavos y esclavas de las naciones vecinas.',NULL),
(@vid,@bid,25,45,'También puedes comprar a los hijos de los extranjeros que vivan entre ustedes, y a los familiares de aquellos que hayan nacido en el país. Ellos pasarán a ser propiedad tuya.',NULL),
(@vid,@bid,25,46,'Podrán dejarlos como herencia para sus hijos , y serán sus esclavos para siempre . Pero ninguno de ustedes deberá tratar con dureza a sus compatriotas israelitas.',NULL),
(@vid,@bid,25,47,'“‘ Si un extranjero o huésped que vive entre ustedes se enriquece, y uno de tus compatriotas se empobrece y se vende a ese extranjero o a algún pariente de él ,',NULL),
(@vid,@bid,25,48,'el israelita conservará el derecho a ser rescatado después de haberse vendido. Cualquiera de sus hermanos podrá rescatarlo.',NULL),
(@vid,@bid,25,49,'También podrán rescatarlo su tío , su primo o cualquier otro pariente cercano de su familia . O si el hombre llega a prosperar, él mismo podrá pagar por su libertad.',NULL),
(@vid,@bid,25,50,'Él y su comprador calcularán el tiempo transcurrido desde el año en que se vendió hasta el año de jubileo . El precio de su libertad se basará en el número de años , y su tiempo de servicio se calculará como si hubiera sido un trabajador a sueldo.',NULL),
(@vid,@bid,25,51,'Si todavía faltan muchos años para el jubileo, el precio de su rescate será en proporción a esos años y devolverá una gran parte de lo que pagaron por él.',NULL),
(@vid,@bid,25,52,'Si faltan pocos años para el jubileo , harán el cálculo y pagará por su rescate en proporción a los años que le faltaban por servir.',NULL),
(@vid,@bid,25,53,'Deberá ser tratado como un trabajador contratado año tras año , y tú no permitirás que su amo extranjero lo trate con dureza.',NULL),
(@vid,@bid,25,54,'Si no es rescatado de ninguna de estas maneras, de todos modos quedará en libertad en el año de jubileo , junto con sus hijos .',NULL),
(@vid,@bid,25,55,'Porque los israelitas son mis siervos ; son los siervos que saqué de la tierra de Egipto . Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,26,1,'“‘ No se hagan ídolos, ni levanten imágenes talladas ni piedras sagradas. No pongan en su tierra piedras grabadas para inclinarse ante ellas , porque yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,26,2,'“‘ Guarden mis días de descanso y muestren respeto por mi santuario . Yo soy Yahvé.',NULL),
(@vid,@bid,26,3,'“‘Si ustedes viven de acuerdo con mis reglamentos, y obedecen y ponen en práctica mis mandamientos ,',NULL),
(@vid,@bid,26,4,'yo les enviaré las lluvias a su debido tiempo . La tierra dará sus cosechas y los árboles del campo darán su fruto .',NULL),
(@vid,@bid,26,5,'Tendrán tanto que trillar que seguirán trillando hasta el tiempo de la recolección de uvas, y la recolección de uvas durará hasta el tiempo de la siembra . Comerán hasta quedar satisfechos y vivirán seguros en su tierra.',NULL),
(@vid,@bid,26,6,'“‘ Yo traeré paz al país, y ustedes podrán dormir sin que nadie los asuste. Quitaré del país a los animales salvajes, y ninguna guerra pasará por la tierra de ustedes.',NULL),
(@vid,@bid,26,7,'Perseguirán a sus enemigos, y ellos caerán a filo de espada delante de ustedes.',NULL),
(@vid,@bid,26,8,'Cinco de ustedes perseguirán a cien , y cien de ustedes perseguirán a diez mil , y sus enemigos caerán a filo de espada delante de ustedes.',NULL),
(@vid,@bid,26,9,'“‘Yo los miraré con agrado, los haré muy fecundos, multiplicaré su descendencia y mantendré firme mi pacto con ustedes.',NULL),
(@vid,@bid,26,10,'Comerán de las cosechas del año anterior, y tendrán que sacar lo viejo para hacerle espacio a lo nuevo .',NULL),
(@vid,@bid,26,11,'Pondré mi santuario en medio de ustedes, y nunca los rechazaré.',NULL),
(@vid,@bid,26,12,'Caminaré en medio de ustedes; yo seré su Dios y ustedes serán mi pueblo .',NULL),
(@vid,@bid,26,13,'Yo soy Yahvé su Dios , quien los sacó de Egipto para que ya no fueran esclavos. Yo rompí el yugo que los oprimía y los hice caminar con la cabeza en alto.',NULL),
(@vid,@bid,26,14,'“‘Pero si no me escuchan y no obedecen todos estos mandamientos ,',NULL),
(@vid,@bid,26,15,'si rechazan mis reglamentos, desprecian mis leyes, desobedecen mis mandamientos y rompen mi pacto ,',NULL),
(@vid,@bid,26,16,'entonces yo haré lo siguiente con ustedes: Traeré sobre ustedes terror, tuberculosis y fiebre, males que les consumirán los ojos y les marchitarán la vida . Sembrarán sus semillas en vano, porque sus enemigos se comerán las cosechas.',NULL),
(@vid,@bid,26,17,'Me pondré en contra de ustedes, y sus enemigos los derrotarán. Los que los odian gobernarán sobre ustedes, y ustedes huirán aunque nadie los persiga .',NULL),
(@vid,@bid,26,18,'“‘ Si a pesar de esto no me obedecen , los castigaré siete veces más por sus pecados .',NULL),
(@vid,@bid,26,19,'Quebraré el orgullo que tienen de su poder, y haré que el cielo sea tan duro como el hierro y la tierra tan dura como el bronce.',NULL),
(@vid,@bid,26,20,'Ustedes gastarán sus fuerzas en vano, porque su tierra no les dará ninguna cosecha ni los árboles les darán su fruto .',NULL),
(@vid,@bid,26,21,'“‘ Si siguen rebelándose contra mí y no quieren escucharme, les enviaré siete veces más plagas por causa de sus pecados .',NULL),
(@vid,@bid,26,22,'Enviaré animales salvajes que los atacarán, les arrebatarán a sus hijos, destruirán su ganado y reducirán la población de ustedes hasta que los caminos queden desiertos.',NULL),
(@vid,@bid,26,23,'“‘ Si después de todos estos castigos ustedes no se vuelven a mí, sino que siguen rebelándose,',NULL),
(@vid,@bid,26,24,'yo también me rebelaré contra ustedes y los castigaré siete veces más por sus pecados .',NULL),
(@vid,@bid,26,25,'Traeré contra ustedes ejércitos enemigos que ejecutarán la venganza de mi pacto . Cuando ustedes se refugien en sus ciudades , enviaré plagas en medio de ustedes y caerán en manos del enemigo.',NULL),
(@vid,@bid,26,26,'Destruiré su suministro de alimentos . Habrá tanta escasez que diez mujeres podrán hornear el pan en un solo horno y se lo repartirán por peso . Ustedes comerán, pero no quedarán satisfechos.',NULL),
(@vid,@bid,26,27,'“‘ Si a pesar de todo esto todavía no me escuchan , sino que siguen rebelándose,',NULL),
(@vid,@bid,26,28,'entonces me enfrentaré a ustedes con mucha ira y los castigaré siete veces más por sus pecados .',NULL),
(@vid,@bid,26,29,'Llegarán a tal extremo que se comerán la carne de sus propios hijos e hijas .',NULL),
(@vid,@bid,26,30,'Destruiré sus santuarios paganos, derribaré sus altares de incienso y arrojaré sus cadáveres sobre los cuerpos sin vida de sus ídolos . Yo mismo los rechazaré por completo.',NULL),
(@vid,@bid,26,31,'Dejaré sus ciudades en ruinas y destruiré sus santuarios, y ya no aceptaré el aroma agradable de sus ofrendas.',NULL),
(@vid,@bid,26,32,'Yo mismo asolaré su tierra, a tal punto que sus enemigos que vengan a ocuparla se quedarán asombrados.',NULL),
(@vid,@bid,26,33,'Los esparciré a ustedes entre las naciones y los perseguiré con la espada desenvainada. Su tierra quedará desolada y sus ciudades en ruinas.',NULL),
(@vid,@bid,26,34,'Entonces la tierra disfrutará de sus años de reposo mientras esté desolada y ustedes estén en la tierra de sus enemigos. Por fin la tierra descansará y disfrutará de los años de reposo .',NULL),
(@vid,@bid,26,35,'Todo el tiempo que la tierra esté desolada tendrá el descanso que ustedes no le dieron durante los años de reposo cuando vivían allí.',NULL),
(@vid,@bid,26,36,'“‘ A los que sobrevivan en las tierras enemigas, les infundiré tal cobardía en el corazón que el simple ruido de una hoja arrastrada por el viento los hará huir. Huirán como si los persiguieran con una espada , y caerán aunque nadie los persiga .',NULL),
(@vid,@bid,26,37,'Tropezarán unos con otros como si huyeran de una batalla, aunque no haya nadie persiguiéndolos. No tendrán fuerzas para hacerles frente a sus enemigos.',NULL),
(@vid,@bid,26,38,'Morirán en las naciones extranjeras y la tierra de sus enemigos se los tragará.',NULL),
(@vid,@bid,26,39,'Los sobrevivientes se pudrirán en las tierras enemigas por causa de sus propios pecados y también por los pecados de sus antepasados.',NULL),
(@vid,@bid,26,40,'“‘Pero si confiesan sus propios pecados y los pecados de sus antepasados, si reconocen que fueron infieles y que se rebelaron contra mí,',NULL),
(@vid,@bid,26,41,'lo cual me obligó a rebelarme contra ellos y a enviarlos a la tierra de sus enemigos, y si por fin su terco corazón se humilla y aceptan el castigo por sus pecados ,',NULL),
(@vid,@bid,26,42,'entonces yo me acordaré de mi pacto con Jacob , de mi pacto con Isaac y de mi pacto con Abraham. También me acordaré de la tierra.',NULL),
(@vid,@bid,26,43,'Porque la tierra deberá ser abandonada por ellos para que pueda disfrutar de sus años de reposo mientras esté desolada. Ellos tendrán que pagar por sus pecados , porque despreciaron mis leyes y rechazaron mis reglamentos.',NULL),
(@vid,@bid,26,44,'A pesar de todo, mientras estén en el país de sus enemigos, no los rechazaré por completo ni los destruiré, porque eso anularía mi pacto con ellos . Yo soy Yahvé, su Dios .',NULL),
(@vid,@bid,26,45,'A favor de ellos, me acordaré del pacto que hice con sus antepasados, a quienes saqué de Egipto a la vista de todas las naciones , para ser su Dios . Yo soy Yahvé’”.',NULL),
(@vid,@bid,26,46,'Estos son los reglamentos, leyes e instrucciones que Yahvé estableció entre él y los israelitas en el monte Sinaí , por medio de Moisés .',NULL),
(@vid,@bid,27,1,'Yahvé le habló a Moisés y le dijo :',NULL),
(@vid,@bid,27,2,'“ Háblales a los israelitas y diles : ‘ Cuando alguien haga una promesa especial para dedicar a una persona a Yahvé, el valor de la persona se calculará de la siguiente manera:',NULL),
(@vid,@bid,27,3,'Si es un hombre de veinte a sesenta años , su valor se calculará en cincuenta monedas de plata , según el peso oficial del santuario .',NULL),
(@vid,@bid,27,4,'Si es una mujer de esa misma edad, el valor será de treinta monedas de plata.',NULL),
(@vid,@bid,27,5,'Si es un joven de cinco a veinte años , el valor será de veinte monedas de plata, y si es una joven, será de diez monedas.',NULL),
(@vid,@bid,27,6,'Si es un niño de un mes a cinco años , el valor será de cinco monedas de plata , y si es una niña, será de tres monedas .',NULL),
(@vid,@bid,27,7,'Si es un hombre de sesenta años o más, el valor será de quince monedas de plata, y si es una mujer, será de diez monedas.',NULL),
(@vid,@bid,27,8,'Pero si la persona es demasiado pobre para pagar la cantidad establecida, deberá presentarse ante el sacerdote , y el sacerdote fijará un valor diferente, dependiendo de lo que pueda pagar la persona que hizo la promesa .',NULL),
(@vid,@bid,27,9,'“‘ Si lo que se promete es un animal de los que se le pueden ofrecer a Yahvé, ese animal será considerado santo .',NULL),
(@vid,@bid,27,10,'No se podrá cambiar por otro animal, ni uno bueno por uno malo , ni uno malo por uno bueno . Si alguien llegara a cambiar un animal por otro, ambos animales quedarán consagrados a Yahvé.',NULL),
(@vid,@bid,27,11,'Si se trata de un animal impuro de los que no se pueden ofrecer a Yahvé, el dueño deberá llevarlo ante el sacerdote ,',NULL),
(@vid,@bid,27,12,'y el sacerdote calculará su valor, ya sea bueno o malo . El precio será el que fije el sacerdote .',NULL),
(@vid,@bid,27,13,'Si el dueño quiere recuperar el animal, tendrá que pagar el precio fijado más una quinta parte como recargo.',NULL),
(@vid,@bid,27,14,'“‘ Si alguien consagra su casa a Yahvé, el sacerdote calculará el valor de la casa , ya sea buena o mala . El precio será el que el sacerdote determine.',NULL),
(@vid,@bid,27,15,'Si el que la consagró desea recuperarla, tendrá que pagar el precio fijado más una quinta parte de recargo, y la casa volverá a ser suya.',NULL),
(@vid,@bid,27,16,'“‘ Si alguien dedica a Yahvé una parte de los campos de su propiedad familiar, el valor se calculará de acuerdo con la cantidad de semilla que se necesite para sembrarlo. La siembra de un costal grande de cebada se calculará en cincuenta monedas de plata .',NULL),
(@vid,@bid,27,17,'Si el hombre dedica su campo durante el año del jubileo , el precio completo de la valoración se mantendrá.',NULL),
(@vid,@bid,27,18,'Pero si dedica su campo después del jubileo , el sacerdote calculará el valor dependiendo de los años que falten para el próximo jubileo , y al precio total se le hará un descuento.',NULL),
(@vid,@bid,27,19,'Si el hombre desea recuperar su campo , tendrá que pagar el precio fijado más una quinta parte de recargo, y el campo seguirá siendo suyo.',NULL),
(@vid,@bid,27,20,'Si decide no recuperarlo, o si ya se lo ha vendido a otro , el campo jamás podrá ser recuperado.',NULL),
(@vid,@bid,27,21,'Cuando el campo quede libre en el año del jubileo , será considerado como un campo consagrado a Yahvé de manera permanente y pasará a ser propiedad de los sacerdotes .',NULL),
(@vid,@bid,27,22,'“‘ Si alguien consagra a Yahvé un campo que ha comprado , y que no es parte de su propiedad familiar,',NULL),
(@vid,@bid,27,23,'el sacerdote calculará el precio de la valoración en proporción a los años que falten para el jubileo . El hombre deberá pagar esa cantidad el mismo día como algo consagrado a Yahvé.',NULL),
(@vid,@bid,27,24,'En el año del jubileo , el campo volverá al que lo vendió originalmente, es decir, al dueño de la propiedad familiar.',NULL),
(@vid,@bid,27,25,'Todos los precios se calcularán según el peso oficial del santuario , donde cada moneda de plata equivale a veinte geras .',NULL),
(@vid,@bid,27,26,'“‘ Nadie podrá consagrar el primer hijo de un animal, porque las primeras crías, sean vacas u ovejas, ya le pertenecen a Yahvé.',NULL),
(@vid,@bid,27,27,'Si se trata de un animal impuro, el dueño podrá recuperarlo pagando el precio fijado más una quinta parte de recargo. Si no lo recupera, el animal podrá ser vendido por el precio fijado.',NULL),
(@vid,@bid,27,28,'“‘ Sin embargo, nada de lo que una persona consagre a Yahvé para destrucción total podrá ser vendido ni recuperado, ya sean personas, animales o campos de su propiedad familiar. Todo lo que se entrega para destrucción total es santísimo , pues le pertenece exclusivamente a Yahvé.',NULL),
(@vid,@bid,27,29,'“‘ Ninguna persona consagrada para destrucción total podrá ser rescatada. Deberá ser condenada a muerte sin falta.',NULL),
(@vid,@bid,27,30,'“‘ La décima parte de todos los productos de la tierra, ya sean cereales o frutas, le pertenece a Yahvé y es algo consagrado a él .',NULL),
(@vid,@bid,27,31,'Si alguien desea recuperar alguna parte de su diezmo, tendrá que pagar su valor más una quinta parte de recargo.',NULL),
(@vid,@bid,27,32,'Uno de cada diez animales del ganado o del rebaño que pasen bajo la vara del pastor para ser contados será consagrado a Yahvé.',NULL),
(@vid,@bid,27,33,'El dueño no debe ponerse a buscar si el animal es bueno o malo , ni debe cambiarlo. Si lo llega a cambiar, tanto el primer animal como su sustituto quedarán consagrados y no podrán ser recuperados’”.',NULL),
(@vid,@bid,27,34,'Estos son los mandamientos que Yahvé le entregó a Moisés en el monte Sinaí para los israelitas.',NULL);
REPLACE INTO verses (version_id, book_id, chapter, verse, text, wj) VALUES
(@vid,@bid,1,1,'Yahvé habló a Moisés en el desierto del Sinaí , en la Tienda del Encuentro, el primer día del segundo mes , en el segundo año después de haber salido de la tierra de Egipto , diciendo :',NULL),
(@vid,@bid,1,2,'“Haz un censo de toda la congregación de los hijos de Israel , por sus familias , por las casas de sus padres, según el número de los nombres , cada varón , uno por uno,',NULL),
(@vid,@bid,1,3,'de veinte años en adelante, todos los que puedan salir a la guerra en Israel . Tú y Aarón los contarán por sus divisiones.',NULL),
(@vid,@bid,1,4,'Con ustedes habrá un hombre de cada tribu , cada uno jefe de la casa de sus padres.',NULL),
(@vid,@bid,1,5,'Estos son los nombres de los hombres que estarán con ustedes: De Rubén : Elizur, hijo de Sedeur.',NULL),
(@vid,@bid,1,6,'De Simeón : Selumiel , hijo de Zurisadai.',NULL),
(@vid,@bid,1,7,'De Judá : Naasón , hijo de Aminadab .',NULL),
(@vid,@bid,1,8,'De Isacar: Netanel, hijo de Zuar.',NULL),
(@vid,@bid,1,9,'De Zabulón : Eliab, hijo de Helón.',NULL),
(@vid,@bid,1,10,'De los hijos de José : de Efraín, Elisama, hijo de Amiud; de Manasés , Gamaliel , hijo de Pedasur.',NULL),
(@vid,@bid,1,11,'De Benjamín : Abidán, hijo de Gideoni.',NULL),
(@vid,@bid,1,12,'De Dan : Ahiezer, hijo de Amisadai.',NULL),
(@vid,@bid,1,13,'De Aser: Pagiel , hijo de Ocrán.',NULL),
(@vid,@bid,1,14,'De Gad : Eliasaf, hijo de Deuel.',NULL),
(@vid,@bid,1,15,'De Neftalí: Ahira , hijo de Enán”.',NULL),
(@vid,@bid,1,16,'Estos son los que fueron llamados de la congregación, los líderes de las tribus de sus padres; eran los jefes de los millares de Israel .',NULL),
(@vid,@bid,1,17,'Moisés y Aarón tomaron a estos hombres mencionados por su nombre .',NULL),
(@vid,@bid,1,18,'Reunieron a toda la congregación el primer día del segundo mes , y registraron su descendencia por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años en adelante, uno por uno.',NULL),
(@vid,@bid,1,19,'Tal como Yahvé le ordenó a Moisés , así los contó en el desierto de Sinaí .',NULL),
(@vid,@bid,1,20,'Los hijos de Rubén , primogénito de Israel , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , uno por uno, todo varón de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,21,'los contados de ellos, de la tribu de Rubén , fueron cuarenta y seis mil quinientos .',NULL),
(@vid,@bid,1,22,'De los hijos de Simeón , sus generaciones, por sus familias , por las casas de sus padres, los que fueron contados de ella , según el número de los nombres , uno por uno, todo varón de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,23,'los que fueron contados de ellos, de la tribu de Simeón , fueron cincuenta y nueve mil trescientos .',NULL),
(@vid,@bid,1,24,'De los hijos de Gad , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,25,'los contados de ellos, de la tribu de Gad , fueron cuarenta y cinco mil seiscientos cincuenta .',NULL),
(@vid,@bid,1,26,'De los hijos de Judá , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,27,'los contados de ellos, de la tribu de Judá , fueron setenta y cuatro mil seiscientos .',NULL),
(@vid,@bid,1,28,'De los hijos de Isacar, sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,29,'los contados de ellos, de la tribu de Isacar, fueron cincuenta y cuatro mil cuatrocientos.',NULL),
(@vid,@bid,1,30,'De los hijos de Zabulón , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,31,'los contados de ellos, de la tribu de Zabulón , fueron cincuenta y siete mil cuatrocientos.',NULL),
(@vid,@bid,1,32,'De los hijos de José : de los hijos de Efraín, sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,33,'los contados de ellos, de la tribu de Efraín, fueron cuarenta mil quinientos .',NULL),
(@vid,@bid,1,34,'De los hijos de Manasés , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,35,'los contados de ellos, de la tribu de Manasés , fueron treinta y dos mil doscientos .',NULL),
(@vid,@bid,1,36,'De los hijos de Benjamín , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,37,'los contados de ellos, de la tribu de Benjamín , fueron treinta y cinco mil cuatrocientos.',NULL),
(@vid,@bid,1,38,'De los hijos de Dan , sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,39,'los contados de ellos, de la tribu de Dan , fueron sesenta y dos mil setecientos .',NULL),
(@vid,@bid,1,40,'De los hijos de Aser, sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,41,'los contados de ellos, de la tribu de Aser, fueron cuarenta y un mil quinientos .',NULL),
(@vid,@bid,1,42,'De los hijos de Neftalí, sus generaciones, por sus familias , por las casas de sus padres, según el número de los nombres , de veinte años para arriba , todos los que podían salir a la guerra :',NULL),
(@vid,@bid,1,43,'los contados de ellos, de la tribu de Neftalí, fueron cincuenta y tres mil cuatrocientos.',NULL),
(@vid,@bid,1,44,'Estos son los que fueron contados, los cuales contaron Moisés y Aarón, y los doce hombres que eran líderes de Israel , cada uno representando a la casa de su padre.',NULL),
(@vid,@bid,1,45,'Así que todos los que fueron contados de los hijos de Israel por las casas de sus padres, de veinte años para arriba , todos los que podían salir a la guerra en Israel ,',NULL),
(@vid,@bid,1,46,'todos los que fueron contados fueron seiscientos tres mil quinientos cincuenta .',NULL),
(@vid,@bid,1,47,'Pero los levitas , según la tribu de sus padres, no fueron contados entre ellos.',NULL),
(@vid,@bid,1,48,'Porque Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,1,49,'“Solo a la tribu de Leví no contarás , ni harás un censo de ellos entre los hijos de Israel ;',NULL),
(@vid,@bid,1,50,'sino que pondrás a los levitas a cargo del Tabernáculo del Testimonio , de todos sus utensilios y de todo lo que le pertenece. Ellos llevarán el tabernáculo y todo su mobiliario; lo cuidarán y acamparán alrededor de él .',NULL),
(@vid,@bid,1,51,'Cuando el tabernáculo deba trasladarse, los levitas lo desarmarán; y cuando el tabernáculo deba levantarse , los levitas lo armarán. El extranjero que se acerque morirá .',NULL),
(@vid,@bid,1,52,'Los hijos de Israel acamparán , cada uno en su campamento , y cada uno junto a su bandera, según sus divisiones.',NULL),
(@vid,@bid,1,53,'Pero los levitas acamparán alrededor del Tabernáculo del Testimonio , para que no caiga la ira sobre la congregación de los hijos de Israel . Los levitas serán responsables de cuidar el Tabernáculo del Testimonio ”.',NULL),
(@vid,@bid,1,54,'Así hicieron los hijos de Israel . Tal como Yahvé le ordenó a Moisés , así lo hicieron .',NULL),
(@vid,@bid,2,1,'Yahvé habló a Moisés y a Aarón, diciendo :',NULL),
(@vid,@bid,2,2,'“ Los hijos de Israel acamparán cada uno con su propia bandera, bajo los estandartes de las casas de sus padres. Acamparán alrededor de la Tienda del Encuentro, a cierta distancia de ella .',NULL),
(@vid,@bid,2,3,'“ Los que acampen en el lado este , hacia la salida del sol, serán los de la bandera del campamento de Judá , según sus divisiones. El líder de los hijos de Judá será Naasón , hijo de Aminadab .',NULL),
(@vid,@bid,2,4,'Su división, y los que fueron contados de ellos, fueron setenta y cuatro mil seiscientos .',NULL),
(@vid,@bid,2,5,'“ Los que acampen junto a él serán los de la tribu de Isacar. El líder de los hijos de Isacar será Netanel, hijo de Zuar.',NULL),
(@vid,@bid,2,6,'Su división, y los que fueron contados de ella, fueron cincuenta y cuatro mil cuatrocientos.',NULL),
(@vid,@bid,2,7,'“La tribu de Zabulón : el líder de los hijos de Zabulón será Eliab, hijo de Helón.',NULL),
(@vid,@bid,2,8,'Su división, y los contados de ella, fueron cincuenta y siete mil cuatrocientos.',NULL),
(@vid,@bid,2,9,'“ Todos los contados del campamento de Judá fueron ciento ochenta y seis mil cuatrocientos, según sus divisiones. Ellos marcharán primero .',NULL),
(@vid,@bid,2,10,'“En el lado sur estará la bandera del campamento de Rubén , según sus divisiones. El líder de los hijos de Rubén será Elizur, hijo de Sedeur.',NULL),
(@vid,@bid,2,11,'Su división, y los que se contaron de ella, fueron cuarenta y seis mil quinientos .',NULL),
(@vid,@bid,2,12,'“ Los que acampen junto a él serán los de la tribu de Simeón . El líder de los hijos de Simeón será Selumiel , hijo de Zurisadai.',NULL),
(@vid,@bid,2,13,'Su división, y los que fueron contados de ellos, fueron cincuenta y nueve mil trescientos .',NULL),
(@vid,@bid,2,14,'“La tribu de Gad : el líder de los hijos de Gad será Eliasaf, hijo de Deuel.',NULL),
(@vid,@bid,2,15,'Su división, y los contados de ellos, fueron cuarenta y cinco mil seiscientos cincuenta .',NULL),
(@vid,@bid,2,16,'“ Todos los contados del campamento de Rubén fueron ciento cincuenta y un mil cuatrocientos cincuenta , según sus ejércitos . Ellos marcharán en segundo lugar.',NULL),
(@vid,@bid,2,17,'“ Entonces saldrá la Tienda del Encuentro, con el campamento de los levitas en medio de los campamentos . Así como acampan, así avanzarán, cada uno en su lugar, bajo sus banderas.',NULL),
(@vid,@bid,2,18,'“En el lado oeste estará la bandera del campamento de Efraín, según sus divisiones. El líder de los hijos de Efraín será Elisama, hijo de Amiud.',NULL),
(@vid,@bid,2,19,'Su división, y los que fueron contados de ellos, fueron cuarenta mil quinientos .',NULL),
(@vid,@bid,2,20,'“ Junto a él estará la tribu de Manasés . El líder de los hijos de Manasés será Gamaliel , hijo de Pedasur.',NULL),
(@vid,@bid,2,21,'Su división, y los que fueron contados de ellos, fueron treinta y dos mil doscientos .',NULL),
(@vid,@bid,2,22,'“La tribu de Benjamín : el líder de los hijos de Benjamín será Abidán, hijo de Gideoni.',NULL),
(@vid,@bid,2,23,'Su ejército , y los contados de ellos, fueron treinta y cinco mil cuatrocientos.',NULL),
(@vid,@bid,2,24,'“ Todos los contados del campamento de Efraín fueron ciento ocho mil cien , según sus divisiones. Ellos marcharán en tercer lugar.',NULL),
(@vid,@bid,2,25,'“En el lado norte estará la bandera del campamento de Dan , según sus divisiones. El líder de los hijos de Dan será Ahiezer, hijo de Amisadai.',NULL),
(@vid,@bid,2,26,'Su división, y los que fueron contados de ellos, fueron sesenta y dos mil setecientos .',NULL),
(@vid,@bid,2,27,'“ Los que acampen junto a él serán los de la tribu de Aser. El líder de los hijos de Aser será Pagiel , hijo de Ocrán.',NULL),
(@vid,@bid,2,28,'Su división, y los que fueron contados de ellos, fueron cuarenta y un mil quinientos .',NULL),
(@vid,@bid,2,29,'“La tribu de Neftalí: el líder de los hijos de Neftalí será Ahira , hijo de Enán.',NULL),
(@vid,@bid,2,30,'Su división, y los que fueron contados de ellos, fueron cincuenta y tres mil cuatrocientos.',NULL),
(@vid,@bid,2,31,'“ Todos los contados del campamento de Dan fueron ciento cincuenta y siete mil seiscientos . Saldrán los últimos, bajo sus banderas”.',NULL),
(@vid,@bid,2,32,'Estos son los que fueron contados de los hijos de Israel por sus casas paternas. Todos los que fueron contados de los campamentos , según sus ejércitos , fueron seiscientos tres mil quinientos cincuenta .',NULL),
(@vid,@bid,2,33,'Pero los levitas no fueron contados entre los hijos de Israel , tal como Yahvé le ordenó a Moisés .',NULL),
(@vid,@bid,2,34,'Así lo hicieron los hijos de Israel . Conforme a todo lo que Yahvé ordenó a Moisés , acamparon por sus banderas, y así se pusieron en marcha, cada uno por su familia , según las casas de sus padres.',NULL),
(@vid,@bid,3,1,'Esta es la historia de las generaciones de Aarón y Moisés en el día en que Yahvé habló con Moisés en el monte Sinaí .',NULL),
(@vid,@bid,3,2,'Estos son los nombres de los hijos de Aarón: Nadab , el primogénito , y Abiú, Eleazar e Itamar.',NULL),
(@vid,@bid,3,3,'Estos son los nombres de los hijos de Aarón, los sacerdotes que fueron ungidos , a quienes él consagró para que ejercieran el ministerio sacerdotal.',NULL),
(@vid,@bid,3,4,'Nadab y Abiú murieron ante Yahvé cuando ofrecieron fuego extraño ante Yahvé en el desierto de Sinaí , y no tuvieron hijos . Eleazar e Itamar ejercieron el sacerdocio en presencia de su padre Aarón.',NULL),
(@vid,@bid,3,5,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,3,6,'“Haz que se acerque la tribu de Leví , y preséntalos delante del sacerdote Aarón, para que le sirvan.',NULL),
(@vid,@bid,3,7,'Ellos se encargarán de sus responsabilidades, y de las obligaciones de toda la congregación ante la Tienda del Encuentro, para realizar el servicio del tabernáculo .',NULL),
(@vid,@bid,3,8,'Estarán a cargo de todo el mobiliario de la Tienda del Encuentro y de las obligaciones de los hijos de Israel , para realizar el servicio del tabernáculo .',NULL),
(@vid,@bid,3,9,'Entregarás los levitas a Aarón y a sus hijos . Les serán dados por completo de parte de los hijos de Israel .',NULL),
(@vid,@bid,3,10,'Designarás a Aarón y a sus hijos , y ellos mantendrán su sacerdocio , pero el extranjero que se acerque será condenado a muerte ”.',NULL),
(@vid,@bid,3,11,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,3,12,'“Miren, yo he tomado a los levitas de entre los hijos de Israel en lugar de todos los primogénitos que abren el vientre entre los hijos de Israel ; los levitas serán míos,',NULL),
(@vid,@bid,3,13,'porque todos los primogénitos son míos. El día en que maté a todos los primogénitos en la tierra de Egipto , santifiqué para mí a todos los primogénitos de Israel , tanto de hombres como de animales. Serán míos. Yo soy Yahvé”.',NULL),
(@vid,@bid,3,14,'Yahvé habló a Moisés en el desierto del Sinaí , diciendo :',NULL),
(@vid,@bid,3,15,'“ Cuenta a los hijos de Leví por las casas de sus padres, por sus familias . Contarás a todos los varones de un mes de edad en adelante”.',NULL),
(@vid,@bid,3,16,'Moisés los contó según la palabra de Yahvé, como se le había ordenado .',NULL),
(@vid,@bid,3,17,'Estos fueron los hijos de Leví por sus nombres : Gersón , Coat y Merari .',NULL),
(@vid,@bid,3,18,'Estos son los nombres de los hijos de Gersón por sus familias : Libni y Simei.',NULL),
(@vid,@bid,3,19,'Los hijos de Coat por sus familias : Amram , Izhar, Hebrón y Uziel.',NULL),
(@vid,@bid,3,20,'Los hijos de Merari por sus familias : Mahli y Mushi. Estas son las familias de los levitas según las casas de sus padres.',NULL),
(@vid,@bid,3,21,'De Gersón era la familia de los libnitas y la familia de los simeítas. Estas son las familias de los gersonitas.',NULL),
(@vid,@bid,3,22,'Los que fueron contados de ellos , según el número de todos los varones de un mes para arriba , fueron siete mil quinientos .',NULL),
(@vid,@bid,3,23,'Las familias de los gersonitas acamparán detrás del tabernáculo , hacia el oeste.',NULL),
(@vid,@bid,3,24,'Eliasaf, hijo de Lael, será el líder de la casa paterna de los gersonitas.',NULL),
(@vid,@bid,3,25,'La tarea de los hijos de Gersón en la Tienda del Encuentro será cuidar el tabernáculo , la tienda, su cubierta, la cortina de la entrada de la Tienda del Encuentro,',NULL),
(@vid,@bid,3,26,'las cortinas del atrio , la cortina de la entrada del atrio que rodea el tabernáculo y el altar , y sus cuerdas para todo su servicio.',NULL),
(@vid,@bid,3,27,'De Coat era la familia de los amramitas, la familia de los izharitas, la familia de los hebronitas y la familia de los uzielitas. Estas son las familias de los coatitas.',NULL),
(@vid,@bid,3,28,'Según el número de todos los varones de un mes en adelante, había ocho mil seiscientos encargados de cuidar el santuario .',NULL),
(@vid,@bid,3,29,'Las familias de los hijos de Coat acamparán al lado sur de la tienda.',NULL),
(@vid,@bid,3,30,'El líder de la casa paterna de las familias de Coat será Elizafán, hijo de Uziel.',NULL),
(@vid,@bid,3,31,'Su tarea será cuidar el arca, la mesa , el candelabro, los altares , los utensilios sagrados con los que ministran , la cortina y todo su servicio.',NULL),
(@vid,@bid,3,32,'Eleazar, hijo del sacerdote Aarón, será el jefe de los líderes de los levitas , y supervisará a los encargados de cuidar el santuario .',NULL),
(@vid,@bid,3,33,'De Merari era la familia de los mahlitas y la familia de los mushitas. Estas son las familias de Merari .',NULL),
(@vid,@bid,3,34,'Los contados de ellos , según el número de todos los varones de un mes para arriba , fueron seis mil doscientos .',NULL),
(@vid,@bid,3,35,'El líder de la casa paterna de las familias de Merari era Zuriel, hijo de Abihail. Acamparán en el lado norte del tabernáculo .',NULL),
(@vid,@bid,3,36,'La tarea asignada a los hijos de Merari será cuidar las tablas del tabernáculo , sus travesaños, sus postes, sus bases, todos sus accesorios, todo su servicio,',NULL),
(@vid,@bid,3,37,'los postes que rodean el atrio , sus bases, sus estacas y sus cuerdas.',NULL),
(@vid,@bid,3,38,'Los que acamparán delante del tabernáculo hacia el este , frente a la Tienda del Encuentro hacia la salida del sol, serán Moisés , junto con Aarón y sus hijos , quienes tendrán a su cargo el cuidado del santuario en representación de los hijos de Israel . El extranjero que se acerque será condenado a muerte .',NULL),
(@vid,@bid,3,39,'Todos los contados de los levitas , que Moisés y Aarón contaron por orden de Yahvé, por sus familias , todos los varones de un mes en adelante, fueron veintidós mil.',NULL),
(@vid,@bid,3,40,'Yahvé le dijo a Moisés : “ Cuenta todos los primogénitos varones de los hijos de Israel de un mes en adelante, y registra sus nombres .',NULL),
(@vid,@bid,3,41,'Tomarás a los levitas para mí, yo soy Yahvé, en lugar de todos los primogénitos entre los hijos de Israel ; y el ganado de los levitas en lugar de todos los primogénitos del ganado de los hijos de Israel ”.',NULL),
(@vid,@bid,3,42,'Moisés contó a todos los primogénitos de los hijos de Israel , tal como Yahvé le había ordenado .',NULL),
(@vid,@bid,3,43,'Todos los primogénitos varones , según el número de nombres , de un mes para arriba , de los que fueron contados , fueron veintidós mil doscientos setenta y tres .',NULL),
(@vid,@bid,3,44,'Yahvé habló a Moisés diciendo :',NULL),
(@vid,@bid,3,45,'“ Toma a los levitas en lugar de todos los primogénitos de los hijos de Israel , y el ganado de los levitas en lugar de su ganado ; y los levitas serán míos. Yo soy Yahvé.',NULL),
(@vid,@bid,3,46,'Y para rescatar a los doscientos setenta y tres primogénitos de los hijos de Israel que sobrepasan el número de los levitas ,',NULL),
(@vid,@bid,3,47,'cobrarás cinco siclos por cada uno; los cobrarás según el peso oficial del santuario (un siclo equivale a veinte geras );',NULL),
(@vid,@bid,3,48,'y le darás a Aarón y a sus hijos el dinero con el que se rescata a los que sobran”.',NULL),
(@vid,@bid,3,49,'Moisés tomó el dinero del rescate de los que excedían el número de los rescatados por los levitas ;',NULL),
(@vid,@bid,3,50,'cobró el dinero de los primogénitos de los hijos de Israel : mil trescientos sesenta y cinco siclos , según el peso del santuario ;',NULL),
(@vid,@bid,3,51,'y Moisés le entregó el dinero del rescate a Aarón y a sus hijos , según la palabra de Yahvé, tal como Yahvé se lo ordenó a Moisés .',NULL),
(@vid,@bid,4,1,'Yahvé habló a Moisés y a Aarón, diciendo :',NULL),
(@vid,@bid,4,2,'“Hagan un censo de los hijos de Coat de entre los hijos de Leví , por sus familias y por las casas de sus padres,',NULL),
(@vid,@bid,4,3,'desde los treinta hasta los cincuenta años , todos los que puedan entrar al servicio para trabajar en la Tienda del Encuentro.',NULL),
(@vid,@bid,4,4,'“ Este es el servicio de los hijos de Coat en la Tienda del Encuentro, en cuanto a las cosas santísimas.',NULL),
(@vid,@bid,4,5,'Cuando el campamento deba avanzar, Aarón entrará con sus hijos ; bajarán el velo de la cortina, cubrirán con él el Arca del Testimonio ,',NULL),
(@vid,@bid,4,6,'le pondrán una cubierta de piel de tejón, extenderán sobre ella una tela totalmente azul y colocarán sus varas.',NULL),
(@vid,@bid,4,7,'“ Sobre la mesa del pan de la Presencia extenderán una tela azul, y pondrán sobre ella los platos , las cucharas , los tazones y las jarras para las ofrendas líquidas; y el pan continuo estará sobre ella .',NULL),
(@vid,@bid,4,8,'Extenderán sobre ellos una tela carmesí, la cubrirán con una cubierta de piel de tejón, y colocarán sus varas.',NULL),
(@vid,@bid,4,9,'“ Tomarán una tela azul y cubrirán el candelabro de la iluminación, sus lámparas , sus tenazas, sus platillos y todos sus recipientes de aceite , con los que lo atienden.',NULL),
(@vid,@bid,4,10,'Lo pondrán , junto con todos sus utensilios, dentro de una cubierta de piel de tejón, y lo colocarán sobre unas parihuelas.',NULL),
(@vid,@bid,4,11,'“ Sobre el altar de oro extenderán una tela azul, lo cubrirán con una cubierta de piel de tejón, y le colocarán sus varas.',NULL),
(@vid,@bid,4,12,'“ Tomarán todos los utensilios con los que sirven en el santuario , los pondrán en una tela azul, los cubrirán con una funda de piel de tejón y los colocarán sobre las parihuelas.',NULL),
(@vid,@bid,4,13,'“Limpiarán la ceniza del altar y extenderán sobre él una tela púrpura.',NULL),
(@vid,@bid,4,14,'Pondrán sobre él todos los utensilios con los que sirven en él : los braseros, los tenedores, las palas y los tazones , todos los utensilios del altar ; extenderán sobre él una cubierta de piel de tejón, y le colocarán sus varas.',NULL),
(@vid,@bid,4,15,'“Cuando Aarón y sus hijos hayan terminado de cubrir el santuario y todos los muebles del santuario , cuando el campamento esté por avanzar, entonces vendrán los hijos de Coat para cargarlos; pero no tocarán las cosas santas , para no morir . Estas son las cargas de los hijos de Coat en la Tienda del Encuentro.',NULL),
(@vid,@bid,4,16,'“Eleazar, hijo del sacerdote Aarón, estará a cargo del aceite para la lámpara, del incienso aromático , de la ofrenda continua y del aceite de la unción , teniendo la responsabilidad de todo el tabernáculo y de todo lo que hay en él , del santuario y de sus utensilios”.',NULL),
(@vid,@bid,4,17,'Yahvé habló a Moisés y a Aarón, diciendo :',NULL),
(@vid,@bid,4,18,'“No permitan que la tribu de las familias de los coatitas desaparezca de entre los levitas ;',NULL),
(@vid,@bid,4,19,'más bien, hagan esto con ellos , para que vivan y no mueran cuando se acerquen a las cosas santísimas: Aarón y sus hijos entrarán y le asignarán a cada uno su tarea y su carga ;',NULL),
(@vid,@bid,4,20,'pero ellos no entrarán a ver las cosas santas ni por un instante, para que no mueran ”.',NULL),
(@vid,@bid,4,21,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,4,22,'“Haz un censo también de los hijos de Gersón , por las casas de sus padres y por sus familias ;',NULL),
(@vid,@bid,4,23,'los contarás desde los treinta hasta los cincuenta años , todos los que entran a servir , para hacer el trabajo en la Tienda del Encuentro.',NULL),
(@vid,@bid,4,24,'“ Este es el servicio de las familias de los gersonitas, para servir y para cargar:',NULL),
(@vid,@bid,4,25,'llevarán las cortinas del tabernáculo y de la Tienda del Encuentro, su cubierta, la cubierta de piel de tejón que va por encima , la cortina de la entrada de la Tienda del Encuentro,',NULL),
(@vid,@bid,4,26,'las cortinas del atrio , la cortina de la entrada del atrio que rodea el tabernáculo y el altar , sus cuerdas y todos los accesorios de su servicio, y todo lo que se haga con ellos . Así servirán .',NULL),
(@vid,@bid,4,27,'Todo el servicio de los hijos de los gersonitas, tanto en sus cargas como en sus tareas, estará bajo las órdenes de Aarón y de sus hijos ; y ustedes les asignarán la responsabilidad de todo lo que deben cargar.',NULL),
(@vid,@bid,4,28,'Este es el servicio de las familias de los hijos de Gersón en la Tienda del Encuentro. Su trabajo estará bajo la dirección de Itamar, hijo del sacerdote Aarón.',NULL),
(@vid,@bid,4,29,'“En cuanto a los hijos de Merari , los contarás por sus familias y por las casas de sus padres;',NULL),
(@vid,@bid,4,30,'los contarás desde los treinta hasta los cincuenta años , todos los que entren en el servicio, para hacer la obra de la Tienda del Encuentro.',NULL),
(@vid,@bid,4,31,'Y esta es su responsabilidad respecto a lo que deben cargar, como parte de su servicio en la Tienda del Encuentro: las tablas del tabernáculo , sus travesaños, sus postes, sus bases,',NULL),
(@vid,@bid,4,32,'los postes que rodean el atrio , sus bases, sus estacas, sus cuerdas, con todos sus accesorios y con todo su servicio. Ustedes les asignarán por nombre los artículos de los que deben hacerse cargo .',NULL),
(@vid,@bid,4,33,'Este es el servicio de las familias de los hijos de Merari , según toda su labor en la Tienda del Encuentro, bajo la dirección de Itamar, hijo del sacerdote Aarón”.',NULL),
(@vid,@bid,4,34,'Moisés , Aarón y los líderes de la congregación contaron a los hijos de los coatitas por sus familias y por las casas de sus padres,',NULL),
(@vid,@bid,4,35,'desde los treinta hasta los cincuenta años , a todos los que entraban en el servicio para trabajar en la Tienda del Encuentro.',NULL),
(@vid,@bid,4,36,'Los contados de ellos por sus familias fueron dos mil setecientos cincuenta .',NULL),
(@vid,@bid,4,37,'Estos son los contados de las familias de los coatitas, todos los que servían en la Tienda del Encuentro, los cuales fueron contados por Moisés y Aarón según el mandato que Yahvé dio por medio de Moisés .',NULL),
(@vid,@bid,4,38,'Los que fueron contados de los hijos de Gersón , por sus familias y por las casas de sus padres,',NULL),
(@vid,@bid,4,39,'desde los treinta hasta los cincuenta años , todos los que entraron en el servicio para trabajar en la Tienda del Encuentro;',NULL),
(@vid,@bid,4,40,'los contados de ellos, por sus familias y por las casas de sus padres, fueron dos mil seiscientos treinta .',NULL),
(@vid,@bid,4,41,'Estos son los contados de las familias de los hijos de Gersón , todos los que servían en la Tienda del Encuentro, los cuales fueron contados por Moisés y Aarón según la orden de Yahvé.',NULL),
(@vid,@bid,4,42,'Los que fueron contados de las familias de los hijos de Merari , por sus familias y por las casas de sus padres,',NULL),
(@vid,@bid,4,43,'desde los treinta hasta los cincuenta años , todos los que entraron en el servicio para trabajar en la Tienda del Encuentro;',NULL),
(@vid,@bid,4,44,'los contados de ellos por sus familias , fueron tres mil doscientos .',NULL),
(@vid,@bid,4,45,'Estos son los contados de las familias de los hijos de Merari , que Moisés y Aarón registraron según el mandato de Yahvé por medio de Moisés .',NULL),
(@vid,@bid,4,46,'Todos los contados de los levitas que Moisés , Aarón y los líderes de Israel registraron, por sus familias y por las casas de sus padres,',NULL),
(@vid,@bid,4,47,'desde los treinta hasta los cincuenta años , todos los que entraron a hacer el trabajo de servicio y a cargar en la Tienda del Encuentro;',NULL),
(@vid,@bid,4,48,'los contados de ellos, fueron ocho mil quinientos ochenta .',NULL),
(@vid,@bid,4,49,'Según el mandato de Yahvé fueron contados por Moisés , asignando a cada uno su servicio y su carga . Así fueron contados por él , tal como Yahvé le ordenó a Moisés .',NULL),
(@vid,@bid,5,1,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,5,2,'“ Manda a los hijos de Israel que saquen del campamento a todo leproso , a todo el que tenga un flujo y a todo el que esté impuro por tocar un cadáver.',NULL),
(@vid,@bid,5,3,'Sacarán del campamento tanto a los hombres como a las mujeres , para que no contaminen su campamento , en medio del cual yo habito ”.',NULL),
(@vid,@bid,5,4,'Los hijos de Israel lo hicieron así , y los sacaron del campamento ; tal como Yahvé le habló a Moisés , así lo hicieron los hijos de Israel .',NULL),
(@vid,@bid,5,5,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,5,6,'“ Habla a los hijos de Israel : ‘ Cuando un hombre o una mujer cometa cualquier pecado que cometen los hombres , ofendiendo así a Yahvé, y esa persona resulte culpable,',NULL),
(@vid,@bid,5,7,'entonces confesará el pecado que ha cometido; y pagará la restitución por su culpa en su totalidad, añadiendo además la quinta parte, y se la dará a la persona contra la cual pecó.',NULL),
(@vid,@bid,5,8,'Pero si la persona no tiene un pariente cercano a quien hacerle la restitución, la restitución por la culpa que se le haga a Yahvé será del sacerdote , además del carnero de la expiación , con el cual se hará la expiación por el culpable.',NULL),
(@vid,@bid,5,9,'Toda ofrenda de las cosas sagradas de los hijos de Israel que le presenten al sacerdote , será suya.',NULL),
(@vid,@bid,5,10,'Las cosas sagradas de cada persona serán del sacerdote ; todo lo que alguien le entregue al sacerdote será suyo’”.',NULL),
(@vid,@bid,5,11,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,5,12,'“ Habla a los hijos de Israel y diles : ‘ Si la mujer de un hombre se desvía y le es infiel,',NULL),
(@vid,@bid,5,13,'y un hombre tiene relaciones sexuales con ella , y esto se oculta a los ojos de su esposo y se mantiene en secreto, y ella se contamina, sin que haya testigos contra ella ni sea sorprendida en el acto;',NULL),
(@vid,@bid,5,14,'y el espíritu de celos se apodera del esposo, y siente celos de su mujer, estando ella contaminada ; o si el espíritu de celos se apodera de él , y siente celos de su mujer, aunque ella no esté contaminada ;',NULL),
(@vid,@bid,5,15,'entonces el hombre llevará a su mujer ante el sacerdote , y presentará su ofrenda por ella : la décima parte de un efa de harina de cebada . No derramará aceite ni le pondrá incienso encima , porque es una ofrenda de celos, una ofrenda de recordatorio, que trae a la memoria el pecado .',NULL),
(@vid,@bid,5,16,'El sacerdote la acercará y la pondrá delante de Yahvé.',NULL),
(@vid,@bid,5,17,'El sacerdote tomará agua santa en una vasija de barro ; y tomará un poco del polvo que está en el piso del tabernáculo y lo echará en el agua .',NULL),
(@vid,@bid,5,18,'El sacerdote pondrá a la mujer delante de Yahvé, soltará el cabello de la mujer, y pondrá en sus manos la ofrenda de recordatorio, que es la ofrenda de celos. El sacerdote tendrá en su mano el agua amarga que trae maldición.',NULL),
(@vid,@bid,5,19,'El sacerdote le hará un juramento y le dirá a la mujer: “ Si ningún hombre se ha acostado contigo y si no te has desviado a la impureza, estando bajo la autoridad de tu esposo, queda libre de esta agua amarga que trae maldición.',NULL),
(@vid,@bid,5,20,'Pero si te has desviado, estando bajo la autoridad de tu esposo, y si te has contaminado , y algún hombre se ha acostado contigo además de tu esposo,”',NULL),
(@vid,@bid,5,21,'entonces el sacerdote hará que la mujer haga un juramento de maldición, y le dirá: “ Que Yahvé te ponga como ejemplo de maldición y juramento en medio de tu pueblo , cuando Yahvé haga que tu muslo decaiga y tu vientre se hinche;',NULL),
(@vid,@bid,5,22,'y que esta agua que trae maldición entre en tus entrañas para hacer que tu vientre se hinche y tu muslo decaiga”. Y la mujer dirá: “Amén, amén”.',NULL),
(@vid,@bid,5,23,'“‘El sacerdote escribirá estas maldiciones en un documento, y las lavará en el agua amarga .',NULL),
(@vid,@bid,5,24,'Hará que la mujer beba el agua amarga que trae maldición; y el agua que trae la maldición entrará en ella y se volverá amarga .',NULL),
(@vid,@bid,5,25,'El sacerdote tomará de las manos de la mujer la ofrenda de celos, mecerá la ofrenda delante de Yahvé y la llevará al altar .',NULL),
(@vid,@bid,5,26,'El sacerdote tomará un puñado de la ofrenda como porción de recordatorio, la quemará sobre el altar , y después hará que la mujer beba el agua .',NULL),
(@vid,@bid,5,27,'Cuando le haya dado a beber el agua , sucederá que si ella se ha contaminado y ha sido infiel a su esposo, el agua que trae la maldición entrará en ella causando amargura , su vientre se hinchará y su muslo decaerá; y la mujer se convertirá en una maldición en medio de su pueblo .',NULL),
(@vid,@bid,5,28,'Pero si la mujer no se ha contaminado y está limpia , entonces quedará libre y podrá tener hijos .',NULL),
(@vid,@bid,5,29,'“‘ Esta es la ley sobre los celos, cuando una mujer que está bajo la autoridad de su esposo se desvía y se contamina,',NULL),
(@vid,@bid,5,30,'o cuando un espíritu de celos se apodera de un hombre y este siente celos de su mujer; entonces pondrá a la mujer delante de Yahvé, y el sacerdote aplicará en ella toda esta ley .',NULL),
(@vid,@bid,5,31,'El hombre quedará libre de culpa , y la mujer cargará con su propio pecado ’”.',NULL),
(@vid,@bid,6,1,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,6,2,'“ Habla a los hijos de Israel y diles : ‘ Cuando un hombre o una mujer haga un voto especial, el voto de nazareo , para consagrarse a Yahvé,',NULL),
(@vid,@bid,6,3,'se apartará del vino y de las bebidas fermentadas. No beberá vinagre de vino , ni vinagre de bebida fermentada, ni beberá jugo de uva, ni comerá uvas frescas o secas .',NULL),
(@vid,@bid,6,4,'Durante todos los días de su nazareato , no comerá nada que provenga de la vid , desde las semillas hasta la cáscara.',NULL),
(@vid,@bid,6,5,'“‘Durante todos los días de su voto de consagración , ninguna navaja pasará por su cabeza , hasta que se cumpla el tiempo de su consagración a Yahvé. Será santo . Dejará crecer los mechones de su cabello .',NULL),
(@vid,@bid,6,6,'“‘ Todos los días que esté consagrado a Yahvé no se acercará a un cadáver.',NULL),
(@vid,@bid,6,7,'No se contaminará ni siquiera por su padre, su madre, su hermano o su hermana cuando ellos mueran, porque lleva sobre su cabeza la consagración a su Dios.',NULL),
(@vid,@bid,6,8,'Todos los días de su nazareato él es santo para Yahvé.',NULL),
(@vid,@bid,6,9,'“‘ Si alguien muere de repente junto a él , y se contamina la cabeza de su consagración , entonces se rapará la cabeza el día de su purificación. Al séptimo día se la rapará.',NULL),
(@vid,@bid,6,10,'Al octavo día llevará dos tórtolas o dos pichones al sacerdote , a la entrada de la Tienda del Encuentro.',NULL),
(@vid,@bid,6,11,'El sacerdote ofrecerá uno como ofrenda por el pecado y el otro como holocausto , y hará expiación por él , porque pecó a causa del muerto, y consagrará su cabeza ese mismo día .',NULL),
(@vid,@bid,6,12,'Dedicará nuevamente a Yahvé los días de su nazareato , y traerá un cordero de un año como ofrenda por la culpa; los días anteriores quedarán anulados, porque su consagración fue profanada.',NULL),
(@vid,@bid,6,13,'“‘ Esta es la ley del nazareo : cuando se cumpla el tiempo de su consagración , será llevado a la entrada de la Tienda del Encuentro,',NULL),
(@vid,@bid,6,14,'y presentará su ofrenda a Yahvé: un cordero de un año sin defecto para el holocausto , una cordera de un año sin defecto para la ofrenda por el pecado , un carnero sin defecto para el sacrificio de comunión,',NULL),
(@vid,@bid,6,15,'una canasta de panes sin levadura, tortas de harina fina amasadas con aceite , y obleas sin levadura untadas con aceite , junto con su ofrenda de grano y sus libaciones .',NULL),
(@vid,@bid,6,16,'El sacerdote los presentará delante de Yahvé, y ofrecerá su ofrenda por el pecado y su holocausto .',NULL),
(@vid,@bid,6,17,'Ofrecerá el carnero como sacrificio de comunión a Yahvé, junto con la canasta de los panes sin levadura. El sacerdote ofrecerá también su ofrenda de grano y su libación .',NULL),
(@vid,@bid,6,18,'El nazareo se rapará la cabeza de su consagración a la entrada de la Tienda del Encuentro, tomará el cabello de su consagración y lo echará al fuego que está debajo del sacrificio de comunión.',NULL),
(@vid,@bid,6,19,'El sacerdote tomará la pierna cocida del carnero, una torta sin levadura de la canasta y una oblea sin levadura, y las pondrá en las manos del nazareo después de que se haya rapado la cabeza de su consagración ;',NULL),
(@vid,@bid,6,20,'y el sacerdote las mecerá como ofrenda especial delante de Yahvé. Son porción sagrada para el sacerdote , además del pecho mecido y la pierna ofrecida. Después de eso , el nazareo podrá beber vino .',NULL),
(@vid,@bid,6,21,'“‘ Esta es la ley del nazareo que hace un voto y de su ofrenda a Yahvé por su consagración , sin contar lo que él voluntariamente pueda dar. Según el voto que haya hecho , así lo cumplirá conforme a la ley de su consagración ’”.',NULL),
(@vid,@bid,6,22,'Yahvé habló a Moisés , diciendo :',NULL),
(@vid,@bid,6,23,'“ Habla a Aarón y a sus hijos , y diles : ‘ Así bendecirán a los hijos de Israel . Les dirán:',NULL),
(@vid,@bid,6,24,'Que Yahvé te bendiga y te proteja;',NULL),
(@vid,@bid,6,25,'Que Yahvé haga brillar su rostro sobre ti, y te muestre su favor;',NULL),
(@vid,@bid,6,26,'Que Yahvé levante su rostro hacia ti, y te conceda la paz ’.',NULL),
(@vid,@bid,6,27,'“Así pondrán mi nombre sobre los hijos de Israel , y yo los bendeciré ”.',NULL),
(@vid,@bid,7,1,'El día en que Moisés terminó de levantar el tabernáculo , lo ungió y lo consagró con todo su mobiliario; ungió y consagró también el altar con todos sus utensilios;',NULL),
(@vid,@bid,7,2,'los líderes de Israel , los jefes de las casas de sus padres, presentaron ofrendas. Estos eran los líderes de las tribus , los que estaban a cargo del censo;',NULL),
(@vid,@bid,7,3,'y trajeron su ofrenda delante de Yahvé: seis carretas cubiertas y doce bueyes ; una carreta por cada dos líderes, y un buey por cada uno. Los presentaron delante del tabernáculo .',NULL),
(@vid,@bid,7,4,'Yahvé habló a Moisés , diciendo:',NULL),
(@vid,@bid,7,5,'“Recíbelos de ellos, para que se utilicen en el servicio de la Tienda del Encuentro; y entrégaselos a los levitas , a cada uno según sus responsabilidades”.',NULL),
(@vid,@bid,7,6,'Moisés tomó las carretas y los bueyes y se los entregó a los levitas .',NULL),
(@vid,@bid,7,7,'Les dio dos carretas y cuatro bueyes a los hijos de Gersón , según sus responsabilidades.',NULL),
(@vid,@bid,7,8,'Y a los hijos de Merari les dio cuatro carretas y ocho bueyes , según sus responsabilidades, bajo la dirección de Itamar, hijo del sacerdote Aarón.',NULL),
(@vid,@bid,7,9,'Pero a los hijos de Coat no les dio nada , porque el servicio del santuario estaba a su cargo y debían llevar las cosas santas sobre sus hombros .',NULL),
(@vid,@bid,7,10,'Los líderes presentaron ofrendas para la dedicación del altar el día en que fue ungido . Los líderes presentaron sus ofrendas delante del altar .',NULL),
(@vid,@bid,7,11,'Yahvé le dijo a Moisés : “Presentarán su ofrenda , un líder cada día , para la dedicación del altar ”.',NULL),
(@vid,@bid,7,12,'El que presentó su ofrenda el primer día fue Naasón , hijo de Aminadab , de la tribu de Judá ,',NULL),
(@vid,@bid,7,13,'y su ofrenda fue: una bandeja de plata , con un peso de ciento treinta siclos , un tazón de plata de setenta siclos , según el peso del santuario , ambos llenos de harina fina amasada con aceite para una ofrenda de grano;',NULL),
(@vid,@bid,7,14,'un cazo de oro de diez siclos, lleno de incienso;',NULL),
(@vid,@bid,7,15,'un becerro , un carnero, un cordero de un año , para el holocausto ;',NULL),
(@vid,@bid,7,16,'un macho cabrío como ofrenda por el pecado ;',NULL),
(@vid,@bid,7,17,'y para el sacrificio de comunión, dos bueyes , cinco carneros, cinco machos cabríos y cinco corderos de un año . Esta fue la ofrenda de Naasón , hijo de Aminadab .',NULL),
(@vid,@bid,7,18,'El segundo día , Netanel, hijo de Zuar, líder de Isacar, presentó su ofrenda.',NULL),
(@vid,@bid,7,19,'Presentó por su ofrenda : una bandeja de plata , con un peso de ciento treinta siclos , un tazón de plata de setenta siclos , según el peso del santuario , ambos llenos de harina fina amasada con aceite para una ofrenda de grano;',NULL),
(@vid,@bid,7,20,'un cazo de oro de diez siclos, lleno de incienso;',NULL),
(@vid,@bid,7,21,'un becerro , un carnero, un cordero de un año , para el holocausto ;',NULL),
(@vid,@bid,7,22,'un macho cabrío como ofrenda por el pecado ;',NULL),
(@vid,@bid,7,23,'y para el sacrificio de comunión, dos bueyes , cinco carneros, cinco machos cabríos y cinco corderos de un año . Esta fue la ofrenda de Netanel, hijo de Zuar.',NULL),
(@vid,@bid,7,24,'Al tercer día Eliab, hijo de Helón, líder de los hijos de Zabulón ,',NULL),
(@vid,@bid,7,25,'presentó su ofrenda : una bandeja de plata , con un peso de ciento treinta siclos , un tazón de plata de setenta siclos , según el peso del santuario , ambos llenos de harina fina amasada con aceite para una ofrenda de grano;',NULL),
(@vid,@bid,7,26,'un cazo de oro de diez siclos, lleno de incienso;',NULL),
(@vid,@bid,7,27,'un becerro , un carnero, un cordero de un año , para el holocausto ;',NULL),
(@vid,@bid,7,28,'un macho cabrío como ofrenda por el pecado ;',NULL),
(@vid,@bid,7,29,'y para el sacrificio de comunión, dos bueyes , cinco carneros, cinco machos cabríos y cinco corderos de un año . Esta fue la ofrenda de Eliab, hijo de Helón.',NULL),
(@vid,@bid,7,30,'El cuarto día Elizur, hijo de Sedeur, líder de los hijos de Rubén ,',NULL),
(@vid,@bid,7,31,'presentó su ofrenda : una bandeja de plata , con un peso de ciento treinta siclos , un tazón de plata de setenta siclos , según el peso del santuario , ambos llenos de harina fina amasada con aceite para una ofrenda de grano;',NULL),
(@vid,@bid,7,32,'un cazo de oro de diez siclos, lleno de incienso;',NULL),
(@vid,@bid,7,33,'un becerro , un carnero, un cordero de un año , para el holocausto ;',NULL),
(@vid,@bid,7,34,'un macho cabrío como ofrenda por el pecado ;',NULL),
(@vid,@bid,7,35,'y para el sacrificio de comunión, dos bueyes , cinco carneros, cinco machos cabríos y cinco corderos de un año . Esta fue la ofrenda de Elizur, hijo de Sedeur.',NULL),
(@vid,@bid,7,36,'El quinto día , Selumiel , hijo de Zurisadai, líder de los hijos de Simeón ,',NULL),
(@vid,@bid,7,37,'presentó su ofrenda : una bandeja de plata , con un peso de ciento treinta siclos , un tazón de plata de setenta siclos , según el peso del santuario , ambos llenos de harina fina amasada con aceite para una ofrenda de grano;',NULL),
(@vid,@bid,7,38,'un cazo de oro de diez siclos, lleno de incienso;',NULL),
(@vid,@bid,7,39,'un becerro , un carnero, un cordero de un año , para el holocausto ;',NULL),
(@vid,@bid,7,40,'un macho cabrío como ofrenda por el pecado ;',NULL),
